-- ==================================================================
-- Frameworks aus dem Tool entfernen (Nutzer-Entscheidung 2026-07-05):
-- ISO27017, ISO27018, TR03183 werden NICHT mehr angeboten. Idempotent.
-- Reihenfolge child->parent (FK-sicher).
-- ==================================================================
DELETE FROM public.answers     WHERE framework IN ('ISO27017','ISO27018','TR03183');
DELETE FROM public.control_iso WHERE framework IN ('ISO27017','ISO27018','TR03183');
DELETE FROM public.controls    WHERE framework IN ('ISO27017','ISO27018','TR03183');
DELETE FROM public.frameworks  WHERE code      IN ('ISO27017','ISO27018','TR03183');
UPDATE public.company_profiles
   SET enabled_frameworks = array_remove(array_remove(array_remove(enabled_frameworks,'ISO27017'),'ISO27018'),'TR03183')
 WHERE enabled_frameworks && ARRAY['ISO27017','ISO27018','TR03183'];


-- ==================================================================
-- Fehlende Kontrollen ergaenzt (Audit Fable5 + Opus-Verifikation, autoritative Quelle):
-- NIS2 3 (Art. 21(2) f/i/g) + ISO 42001 9 (Annex A). Idempotent, neue Rows (kein FK-Konflikt).
-- ==================================================================
INSERT INTO public.controls (framework, id, req_de, req_en, meta)
SELECT v.framework, v.id, v.req_de, v.req_en, v.meta
FROM (VALUES
  ('NIS2','f-08','Das Sicherheitsniveau wird regelmaessig durch Benchmarks mit Branchenstandards verglichen, um Abweichungen zu erkennen und die Wirksamkeit der Massnahmen zu bewerten. (NIS2 Art. 21(2)f)','The security level is regularly benchmarked against industry standards to detect deviations and assess the effectiveness of measures. (NIS2 Art. 21(2)(f))','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('NIS2','org-21','Es wird ausschliesslich lizenzierte Software eingesetzt; die Einhaltung der Lizenzbedingungen wird regelmaessig geprueft (Lizenz- und Software-Compliance). (NIS2 Art. 21(2)i)','Only licensed software is used; compliance with license terms is reviewed regularly (license and software compliance). (NIS2 Art. 21(2)(i))','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('NIS2','org-05','Relevantes Personal nimmt aktiv an Fachgruppen, Sicherheitsforen und Informationsaustausch (z. B. ISAC) teil, um fruehzeitig ueber neue Bedrohungen informiert zu sein. (NIS2 Art. 21(2)g, Art. 29)','Relevant staff actively participate in professional groups, security forums and information sharing (e.g. ISAC) to receive early warning of new threats. (NIS2 Art. 21(2)(g), Art. 29)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.4.4','Werkzeuge (Tooling) fuer Entwicklung, Betrieb und Ueberwachung von KI-Systemen sind dokumentiert und werden verwaltet. (ISO/IEC 42001 A.4.4)','Tooling resources for AI development, operation and monitoring are documented and managed. (ISO/IEC 42001 A.4.4)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.4.5','System- und Rechenressourcen (Compute/Infrastruktur) fuer KI-Systeme sind dokumentiert und werden verwaltet. (ISO/IEC 42001 A.4.5)','System and computing resources for AI systems are documented and managed. (ISO/IEC 42001 A.4.5)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.6.2.2','Anforderungen und Spezifikationen fuer KI-Systeme werden dokumentiert festgelegt. (ISO/IEC 42001 A.6.2.2)','Requirements and specification for AI systems are documented. (ISO/IEC 42001 A.6.2.2)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.6.2.3','Entwurf und Entwicklung von KI-Systemen werden dokumentiert. (ISO/IEC 42001 A.6.2.3)','Design and development of AI systems are documented. (ISO/IEC 42001 A.6.2.3)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.6.2.7','Technische Dokumentation der KI-Systeme wird erstellt und aktuell gehalten. (ISO/IEC 42001 A.6.2.7)','Technical documentation for AI systems is created and maintained. (ISO/IEC 42001 A.6.2.7)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.6.2.8','Ereignisprotokolle (Event Logs) von KI-Systemen werden aufgezeichnet. (ISO/IEC 42001 A.6.2.8)','Event logs of AI systems are recorded. (ISO/IEC 42001 A.6.2.8)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.7.3','Die Beschaffung und Auswahl von Daten fuer KI-Systeme ist geregelt. (ISO/IEC 42001 A.7.3)','Acquisition and selection of data for AI systems is governed. (ISO/IEC 42001 A.7.3)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.7.6','Die Datenaufbereitung (Data Preparation) fuer KI-Systeme folgt definierten Kriterien. (ISO/IEC 42001 A.7.6)','Data preparation for AI systems follows defined criteria. (ISO/IEC 42001 A.7.6)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('ISO42001','ISO42001-A.10.4','Erwartungen und Informationspflichten gegenueber Kunden bei KI-Systemen sind geregelt. (ISO/IEC 42001 A.10.4)','Customer expectations and information obligations for AI systems are addressed. (ISO/IEC 42001 A.10.4)','{"coverage":"neu","iso_ids":[]}'::jsonb)
) AS v(framework, id, req_de, req_en, meta)
WHERE NOT EXISTS (SELECT 1 FROM public.controls c WHERE c.framework = v.framework AND c.id = v.id);


-- ==================================================================
-- Fehlende Kontrollen Welle 2 (Fable-Audit + Opus-Verifikation 9/9 bestaetigt,
-- autoritative Quelle Recht/Norm): KRITIS 3, BSI200_4 1, GDPR 3, AIACT 1, CRA 1.
-- Idempotent, neue Rows (kein FK-Konflikt).
-- ==================================================================
INSERT INTO public.controls (framework, id, req_de, req_en, meta)
SELECT v.framework, v.id, v.req_de, v.req_en, v.meta
FROM (VALUES
  ('KRITIS','ITK-3.1.1','Ist ein verbindliches Verfahren zur Erkennung, Dokumentation und Kontrolle von Risiken für Netze, Dienste und die Verarbeitung personenbezogener Daten festgelegt (Organisations- und Risikomanagement)?','Is a binding procedure established to identify, document and control risks to networks, services and the processing of personal data (organisation and risk management)?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','ITK-3.7.4','Werden die getroffenen Sicherheitsmaßnahmen regelmäßig anhand einer festgelegten Strategie (Risikoanalysen, Kennzahlen, Stresstests) auf Angemessenheit gegenüber dem Stand der Technik beurteilt?','Are the implemented security measures regularly reassessed for adequacy against the state of the art using a defined strategy (risk analyses, metrics, stress tests)?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','ITK-3.7.5','Ist die Einhaltung gesetzlicher, vertraglicher und freiwilliger Anforderungen durch ein in die Betriebsabläufe integriertes Überwachungssystem und eine benannte zuständige Stelle sichergestellt?','Is compliance with legal, contractual and voluntary requirements ensured through a monitoring system embedded in operations and a designated responsible unit?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('BSI200_4','BSI2004-24.1','Werden nach Übungen/Tests die tatsächlich erreichten Werte (RTA/RPA) den geplanten Vorgaben (RTO/WAZ und RPO) im Soll-Ist-Vergleich gegenübergestellt und Abweichungen als Verbesserungsmaßnahmen behandelt?','After exercises/tests, are the achieved recovery values (RTA/RPA) compared against planned targets (RTO and RPO), and are gaps handled as improvement actions?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('GDPR','GDPR-36','Werden personenbezogene Daten über strafrechtliche Verurteilungen und Straftaten nur unter behördlicher Aufsicht oder auf Grundlage einer geeigneten Rechtsvorschrift verarbeitet (Art. 10 DSGVO)?','Are personal data relating to criminal convictions and offences processed only under the control of official authority or on an authorised legal basis (Art. 10 GDPR)?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('GDPR','GDPR-37','Werden alle Empfänger, denen Daten offengelegt wurden, über jede Berichtigung/Löschung/Einschränkung unterrichtet (sofern nicht unmöglich/unverhältnismäßig), und wird die betroffene Person auf Verlangen informiert (Art. 19 DSGVO)?','Are all recipients informed of any rectification/erasure/restriction (unless impossible/disproportionate), and is the data subject informed on request (Art. 19 GDPR)?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('GDPR','GDPR-38','Ist ein Prozess etabliert, der die Zusammenarbeit mit der Aufsichtsbehörde auf deren Anfrage sicherstellt (Art. 31 DSGVO)?','Is a process established to ensure cooperation with the supervisory authority on request (Art. 31 GDPR)?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('AIACT','AIACT-A-50.1','Werden Personen darüber informiert, dass sie mit einem KI-System interagieren (Chatbot), sofern nicht offensichtlich, und werden KI-erzeugte oder -manipulierte Inhalte (inkl. Deepfakes) maschinenlesbar als künstlich gekennzeichnet und offengelegt? (EU AI Act Art. 50)','Are persons informed that they interact with an AI system (chatbot) unless obvious, and are AI-generated or manipulated contents (incl. deepfakes) marked machine-readable as artificial and disclosed? (EU AI Act Art. 50)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('CRA','CRA-13.6','Werden in integrierten Komponenten (inkl. Open-Source) festgestellte Schwachstellen der herstellenden/betreuenden Stelle gemeldet und ein entwickelter Fix (Code/Doku, wo angebracht maschinenlesbar) mit dem Maintainer geteilt? (CRA Art. 13 Abs. 6)','Are vulnerabilities found in integrated components (incl. open source) reported to the manufacturing/maintaining entity, and is a developed fix (code/docs, where appropriate machine-readable) shared with the maintainer? (CRA Art. 13(6))','{"coverage":"neu","iso_ids":[]}'::jsonb)
) AS v(framework, id, req_de, req_en, meta)
WHERE NOT EXISTS (SELECT 1 FROM public.controls c WHERE c.framework = v.framework AND c.id = v.id);


-- ==================================================================
-- Fehlende Kontrollen Welle 3 (KRITIS-Sektorpakete SZA/KRN/ENE gegen
-- AUTORITATIVE oeffentliche Quellen verifiziert: BSI OH-SzA v1.1,
-- BSIG n.F. (NIS2UmsuCG), KRITIS-DachG (i.K. 17.03.2026), IT-Sicherheitskatalog
-- §11 Abs.1b EnWG. Fable5-Audit + Opus-Verifikation. Idempotent, neue Rows.
-- ==================================================================
INSERT INTO public.controls (framework, id, req_de, req_en, meta)
SELECT v.framework, v.id, v.req_de, v.req_en, v.meta
FROM (VALUES
  ('KRITIS','SZA-O06','Werden alle zur Angriffserkennung erforderlichen Hard- und Softwarekomponenten sowie die Signaturen der Detektionssysteme durchgaengig auf aktuellem Stand gehalten? (BSI OH-SzA v1.1, Kap. 3)','Are all hardware and software components required for attack detection, and the signatures of detection systems, kept continuously up to date? (BSI OH-SzA v1.1, ch. 3)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','SZA-P03.2','Existiert ein Prozess, der die Protokollierung bei Veraenderungen im Anwendungsbereich (Changes) entsprechend anpasst? (BSI OH-SzA v1.1, Kap. 3.1.1)','Is there a process that adapts logging when changes occur in the scope of application? (BSI OH-SzA v1.1, ch. 3.1.1)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','SZA-D01.2','Werden bereits ueberpruefte Protokoll- und Protokollierungsdaten regelmaessig automatisch erneut hinsichtlich sicherheitsrelevanter Ereignisse untersucht (retrospektive Analyse)? (BSI OH-SzA v1.1, Kap. 3.2.2)','Are already-reviewed log data regularly re-examined automatically for security-relevant events (retrospective analysis)? (BSI OH-SzA v1.1, ch. 3.2.2)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','KRN-06.2','Sind Systeme zur Angriffserkennung im Einsatz, die geeignete Parameter aus dem laufenden Betrieb kontinuierlich und automatisch erfassen und auswerten? (§31 Abs. 2 BSIG)','Are attack detection systems in place that continuously and automatically collect and evaluate suitable parameters from live operations? (Sec. 31(2) BSIG)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','KRN-08','Sind die Nachweis- und Mitwirkungspflichten nach §16 KRITIS-DachG organisiert (Vorlage Resilienzplan und Audit-Ergebnisse inkl. Maengel auf Verlangen, Zutritt/Auskunft bei Vor-Ort-Pruefungen, Maengelbeseitigungsplan mit Frist, ggf. Zertifikat)?','Are the evidence and cooperation duties under Sec. 16 KRITIS umbrella act organized (submission of resilience plan and audit results incl. defects on request, access/information during on-site inspections, defect remediation plan with deadline, certificate if required)?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','KRN-11.4','Werden die gesetzlichen Meldestufen eingehalten: Fruehmeldung binnen 24h, Meldung binnen 72h, Zwischenmeldung auf Ersuchen, Abschluss- bzw. Fortschrittsmeldung binnen 1 Monat? (§32 Abs. 1-2 BSIG)','Are the statutory reporting stages met: early warning within 24h, notification within 72h, interim report on request, final or progress report within 1 month? (Sec. 32(1)-(2) BSIG)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','KRN-11.5','Sind die Meldungsinhalte je Stufe vorbereitet, inkl. der Betreiber-Zusatzangaben zu Art der betroffenen Anlage, kritischer Dienstleistung und Auswirkungen? (§32 Abs. 3 BSIG)','Is the reporting content per stage prepared, incl. operator-specific details on affected installation type, critical service and impact? (Sec. 32(3) BSIG)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','KRN-13','Ist der Meldeprozess fuer Vorfaelle nach §18 KRITIS-DachG an das BBK etabliert (24h-Erstmeldung ueber die gemeinsame Meldestelle, Aktualisierung bei andauerndem Vorfall, ausfuehrlicher Bericht spaetestens 1 Monat, Angaben zu Betroffenenzahl/-anteil, Dauer und geografischem Gebiet)?','Is the incident reporting process under Sec. 18 KRITIS umbrella act to the BBK established (24h initial report via the joint reporting office, updates for ongoing incidents, detailed report within 1 month, details on number/share of affected persons, duration, geographic area)?','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','KRN-15.2','Wird die Risikoanalyse und Risikobewertung im Bedarfsfall, mindestens jedoch alle vier Jahre wiederholt? (§12 Abs. 1 KRITIS-DachG)','Is the risk analysis and assessment repeated as needed, but at least every four years? (Sec. 12(1) KRITIS umbrella act)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','ENE-16','Erzeugungs- und Speicheranlagen: Sind die besonderen Schutzziele - Bereitstellung elektrischer Leistung gemaess kommunizierten Fahrplaenen und vertraglichen Verpflichtungen (§13 Abs. 1 EnWG), gemaess Anforderung des UEbertragungsnetzbetreibers (§13 Abs. 2 EnWG) bzw. Verteilnetzbetreibers (§13 Abs. 2 i.V.m. §14 Abs. 1 EnWG) sowie gemaess Verfuegungen des Lastverteilers - im ISMS und in der Schutzbedarfs-/Risikoeinschaetzung beruecksichtigt? (IT-SiKat §11 Abs.1b EnWG, Kap. B.II.1)','Generation and storage installations: are the special protection goals - provision of electrical power per communicated schedules and contractual obligations (Sec. 13(1) EnWG), per TSO request (Sec. 13(2) EnWG) or DSO request (Sec. 13(2) i.c.w. Sec. 14(1) EnWG), and per load-dispatcher orders - reflected in the ISMS and protection-needs/risk assessment? (IT security catalogue Sec. 11(1b) EnWG, ch. B.II.1)','{"coverage":"neu","iso_ids":[]}'::jsonb),
  ('KRITIS','ENE-17','Gasfoerderanlagen und Gasspeicher: Sind die besonderen Schutzziele - Bereitstellung von Ausspeiseleistung bzw. Speicherkapazitaet gemaess Fahrplaenen der Speichernutzer und vertraglichen Verpflichtungen (§16 Abs. 1 EnWG), Ein-/Ausspeisung gemaess Anforderungen des Fernleitungsnetzbetreibers (§16 Abs. 2 EnWG) bzw. Verteilernetzbetreibers (§16 Abs. 2 i.V.m. §16a EnWG) sowie zur Deckung des lebenswichtigen Gasbedarfs gemaess Verfuegungen des Lastverteilers - im ISMS und in der Schutzbedarfs-/Risikoeinschaetzung beruecksichtigt? (IT-SiKat §11 Abs.1b EnWG, Kap. B.II.2)','Gas production facilities and gas storage: are the special protection goals - provision of withdrawal/storage capacity per storage users schedules and contractual obligations (Sec. 16(1) EnWG), injection/withdrawal per TSO requirements (Sec. 16(2) EnWG) or DSO requirements (Sec. 16(2) i.c.w. Sec. 16a EnWG), and covering vital gas demand per load-dispatcher orders - reflected in the ISMS and protection-needs/risk assessment? (IT security catalogue Sec. 11(1b) EnWG, ch. B.II.2)','{"coverage":"neu","iso_ids":[]}'::jsonb)
) AS v(framework, id, req_de, req_en, meta)
WHERE NOT EXISTS (SELECT 1 FROM public.controls c WHERE c.framework = v.framework AND c.id = v.id);

-- Textkorrektur SZA-O04 (BSI OH-SzA v1.1, Kap. 4.1: etablierter KVP ist ab Umsetzungsgrad 4 zwingend, nicht Grad 5)
UPDATE public.controls
SET req_de = 'KVP etabliert (ab Umsetzungsgrad 4 zwingend; fuer Grad 3 mindestens in Planung)?',
    req_en = 'Is a continual improvement process established (mandatory from implementation level 4; at least planned for level 3)?'
WHERE framework = 'KRITIS' AND id = 'SZA-O04';


-- ==================================================================
-- Vorfall-Werkzeug (Sprint 1): Assessment + generierte Meldungen als JSONB
-- am bestehenden incidents-Register (D83). Idempotent, keine neuen Tabellen.
-- assessment = die 6-8 Bewertungsantworten (+ Begruendung, versionierbar);
-- meldungen  = automatisch aufgeloeste Melde-Instanzen mit Frist/Status.
-- ==================================================================
ALTER TABLE public.incidents
  ADD COLUMN IF NOT EXISTS assessment jsonb NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS meldungen jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS assessment_updated_at timestamptz;
-- ==================================================================
-- Placeholder-Risikotexte (text_de==risk_id) aus den ZUGEORDNETEN Kontrollen
-- autoritativ abgeleitet (control_risk-Link = 'diese Kontrolle mindert dieses Risiko').
