UPDATE public.controls SET req_de='Wird die Unternehmensführung regelmäßig und ggf. ad-hoc über den Status und Tendenzen im Notfallmanagement sowie über die Risikosituation informiert (gemäß AT 7.3 Tz. 1 MaRisk)? (MUSS)', muss='true' WHERE framework='MaRisk' AND id='MR-132';
UPDATE public.controls SET req_de='Sind Bedingungen für die Aktivierung oder Deaktivierung der IKT-Reaktions- und Wiederherstellungspläne festgelegt (gemäß Art. 26 Abs. 1 a RTS RMF)? (MUSS)', muss='true' WHERE framework='MaRisk' AND id='MR-133';
