UPDATE public.controls SET req_de='Werden bei Einkäufen die erforderlichen Informationssicherheits-Kontrollmechanismen (z. B. Sicherheitsanforderungen und Schutzmaßnahmen) verbindlich mit dem Lieferanten vereinbart? (SOLLTE)' WHERE framework='BSI' AND id='BES.5.4';
UPDATE public.controls SET req_de='Ist ein geregeltes Meldeverfahren eingerichtet und verbindlich verankert, über das Sicherheitsvorfälle strukturiert gemeldet werden können? (SOLLTE)' WHERE framework='BSI' AND id='DET.2.1';
UPDATE public.controls SET req_de='Stehen den Mitarbeitenden vorbereitete Meldeformulare für die Meldung von Sicherheitsvorfällen zur Verfügung und sind diese eingeführt? (SOLLTE)' WHERE framework='BSI' AND id='DET.2.1.2';
