UPDATE public.controls SET req_de='Ist ein zeitnahes Patchmanagement eingerichtet und verankert, sodass verfügbare Sicherheitsupdates schnell erkannt und eingespielt werden? (SOLLTE)' WHERE framework='BSI' AND id='DET.5.10';
UPDATE public.controls SET req_de='Werden die Bezugsquellen für Patches und Updates vorab autorisiert, sodass nur Updates aus geprüften, vertrauenswürdigen Quellen bezogen werden? (SOLLTE)' WHERE framework='BSI' AND id='DET.5.10.1';
