UPDATE public.controls SET req_de='Werden bei der Entwicklung von Anwendungen Schutzmaßnahmen gegen Replay-Angriffe (unbefugtes Wiedereinspielen abgefangener Nachrichten) umgesetzt, sodass solche Angriffe blockiert werden? (SOLLTE)' WHERE framework='BSI' AND id='DEV.3.1';
UPDATE public.controls SET req_de='Sind für die Standorte aktuelle Strukturpläne (z. B. Gebäude-, Raum- und Infrastrukturpläne) dokumentiert und verfügbar? (SOLLTE)' WHERE framework='BSI' AND id='GEB.1.5';
