UPDATE public.controls SET req_de='Sind in den Serverräumen Brandunterdrückungssysteme (z. B. Löschanlagen) installiert, um Brände im Serverraum automatisch zu bekämpfen? (KANN)' WHERE framework='BSI' AND id='GEB.10.2.6';
