UPDATE public.controls SET req_de='Werden in Konfigurationen hinterlegte Geheimnisse (z. B. Passwörter, Schlüssel und Zugangsdaten) verschlüsselt gespeichert, sodass sie nicht im Klartext vorliegen? (SOLLTE)' WHERE framework='BSI' AND id='KONF.1.5';
