UPDATE public.controls SET req_de='Ist auf den IT-Systemen die Code-Signierung im Betriebssystemkern aktiviert, sodass nur digital signierter und damit vertrauenswürdiger Kernel-Code (z. B. Treiber, Kernelmodule) ausgeführt wird? (SOLLTE)' WHERE framework='BSI' AND id='KONF.7.14';
UPDATE public.controls SET req_de='Ist auf den IT-Systemen eine Host-basierte Angriffserkennung (HIDS) aktiviert, die verdächtige Aktivitäten direkt auf dem jeweiligen System erkennt? (KANN)' WHERE framework='BSI' AND id='KONF.7.3';
