UPDATE public.controls SET req_de='Ist im Rahmen der Notfallplanung ein Datenträgerarchiv (gesicherte Aufbewahrung von Sicherungs-Datenträgern für den Wiederanlauf) eingerichtet? (SOLLTE)' WHERE framework='BSI' AND id='NOT.4.11';
UPDATE public.controls SET req_de='Werden im Rahmen des Monitorings und der Auswertung Sicherheitsvorfälle laufend überwacht, sodass sicherheitsrelevante Ereignisse erkannt werden? (MUSS)' WHERE framework='BSI' AND id='PERF.6.1.1';
UPDATE public.controls SET req_de='Wird bei der Behandlung von Sicherheitsvorfällen jeder eingehenden Meldung eine Priorität (Dringlichkeit/Schwere) zugewiesen? (SOLLTE)' WHERE framework='BSI' AND id='REA.2.1';
