INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0029','Werden die Schutzziele des ISMS und die betrieblichen Kontinuitätsanforderungen des BCMS klar voneinander abgegrenzt, und wurden die Schnittstellen zwischen BCMS und ISMS bereits in der Planungs- und Konzeptionsphase festgelegt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
