INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0031','Gibt das BCM Wiederanlaufzeiten vor und ist sichergestellt, dass die BCM-Anforderungen (Wiederanlaufzeiten, maximale Ausfallzeiten, zugesichertes Mindestniveau) auch im Schadensfall garantiert sind?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0032','Werden die Maßnahmen zur Wiederherstellung mit den Maßnahmen zum Wiederanlauf und zum Notbetrieb zwischen den beteiligten Zuständigen abgestimmt?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
