INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BSI200_4','BSI2004-A0152','Dokumentiert die Geschäftsordnung des Stabes die personelle Besetzung, besonderen Befugnisse, Konstituierung und Auflösung, das Zusammenarbeitsmodell, die Arbeitsbedingungen, die Protokollierung, die Compliance-Rahmenbedingungen und den Verhaltenskodex?',NULL,'false','{"quelle": "BSI 200-4 Standardtext (extrahiert)", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de;
