INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.1.2.c','Setzt die Organisation alle erforderlichen Maßnahmen zur Behebung der Nichtkonformität um?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.1.2.c", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.1.2.d','Überprüft die Organisation die Wirksamkeit der ergriffenen Korrekturmaßnahmen?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.1.2.d", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.1.2.e','Nimmt die Organisation bei Bedarf Änderungen am BCMS vor, um die Nichtkonformität zu beheben?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.1.2.e", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.1.2.f','Sind die ergriffenen Korrekturmaßnahmen den Auswirkungen der aufgetretenen Nichtkonformitäten angemessen?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.1.2.f", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.1.3.a','Bewahrt die Organisation dokumentierte Information als Nachweis über die Art der Nichtkonformitäten und alle daraufhin ergriffenen Maßnahmen auf?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.1.3.a", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.1.3.b','Bewahrt die Organisation dokumentierte Information als Nachweis über die Ergebnisse aller Korrekturmaßnahmen auf?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.1.3.b", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.2.1','Verbessert die Organisation fortlaufend die Eignung, Angemessenheit und Wirksamkeit des BCMS auf Basis qualitativer und quantitativer Kennzahlen?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.2.1", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';
INSERT INTO public.controls(framework,id,req_de,req_en,muss,meta) VALUES ('BCM22301','BCM22301-10.2.2','Berücksichtigt die Organisation die Ergebnisse aus Analyse und Bewertung sowie die Ergebnisse der Managementbewertung, um Bedarf oder Möglichkeiten zur fortlaufenden Verbesserung zu ermitteln?',NULL,'true','{"quelle": "ISO 22301:2019", "clause": "10.2.2", "tags": ["bcm"], "scored": true}'::jsonb) ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, muss='true';


-- ============================================================
-- R3: Risiken für die neu geladenen Kontrollen (BCM22301/BSI200_4/TISAX). 2026-07-15
-- Je Kontrolle ein passendes erklärendes Fließtext-Risiko + Verknüpfung. Idempotent.
-- ============================================================
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0001','R3-2026-07','Wenn Sie Verbesserungsmöglichkeiten nicht systematisch bestimmen und umsetzen, bleibt Ihr BCMS auf dem Stand von gestern und verfehlt seine beabsichtigten Ergebnisse. Schwachstellen bleiben unentdeckt, sodass Ihre Organisation im Ernstfall nicht so schnell und wirksam reagiert wie nötig und einen längeren Ausfall kritischer Leistungen riskiert.','BCM22301','BCM22301-10.1.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.1','R-R3-0001','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0002','R3-2026-07','Reagieren Sie bei einer Nichtkonformität nicht mit steuernden und korrigierenden Maßnahmen, weitet sich die Abweichung ungebremst aus. Der zugrunde liegende Mangel wirkt fort, gefährdet die Betriebskontinuität und kann bei einem Notfall zu erheblichen Schäden sowie zum Verlust Ihrer Zertifizierung führen.','BCM22301','BCM22301-10.1.2.a.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.a.1','R-R3-0002','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0003','R3-2026-07','Gehen Sie mit den Konsequenzen einer Nichtkonformität nicht angemessen um, bleiben Folgeschäden unbeherrscht und können sich auf Prozesse, Kunden und Dritte übertragen. Ohne aktive Bewältigung drohen finanzielle Verluste, Vertrauensverlust und im schlimmsten Fall die Haftung Ihrer Organisation für vermeidbare Folgen.','BCM22301','BCM22301-10.1.2.a.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.a.2','R-R3-0003','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0004','R3-2026-07','Wenn Sie den Bedarf an Maßnahmen zur Ursachenbeseitigung nicht durch Überprüfung der Abweichung bewerten, behandeln Sie nur Symptome statt Ursachen. Dieselbe Nichtkonformität tritt dann immer wieder auf, bindet Ressourcen und untergräbt nachhaltig die Wirksamkeit und Verlässlichkeit Ihres BCMS.','BCM22301','BCM22301-10.1.2.b.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.b.1','R-R3-0004','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0005','R3-2026-07','Bestimmen Sie die eigentlichen Ursachen einer Nichtkonformität nicht, kann diese jederzeit erneut oder an anderer Stelle auftreten. Die Störung wiederholt sich, kritische Prozesse fallen wiederholt aus und Ihre Organisation verliert Zeit, Geld und die Fähigkeit, im Ernstfall verlässlich weiterzuarbeiten.','BCM22301','BCM22301-10.1.2.b.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.b.2','R-R3-0005','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0006','R3-2026-07','Prüfen Sie nicht, ob ähnliche Nichtkonformitäten bereits bestehen oder auftreten können, übersehen Sie systemische Schwachstellen. Verborgene Mängel wirken parallel in anderen Bereichen fort und können im Notfall gleichzeitig versagen, wodurch sich ein Einzelfehler zu einem großflächigen Ausfall Ihrer Betriebskontinuität auswächst.','BCM22301','BCM22301-10.1.2.b.3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.b.3','R-R3-0006','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0007','R3-2026-07','Setzen Sie nicht alle erforderlichen Maßnahmen zur Behebung einer Nichtkonformität um, bleibt der Mangel ganz oder teilweise bestehen. Halbe Korrekturen erzeugen ein trügerisches Sicherheitsgefühl, sodass Ihre Organisation im Ernstfall an genau der Stelle scheitert, die vermeintlich schon behoben war.','BCM22301','BCM22301-10.1.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.c','R-R3-0007','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0008','R3-2026-07','Überprüfen Sie die Wirksamkeit Ihrer Korrekturmaßnahmen nicht, wissen Sie nicht, ob das Problem wirklich gelöst ist. Unwirksame Maßnahmen bleiben unbemerkt, die Abweichung besteht faktisch fort und Ihre Organisation verlässt sich auf einen Schutz, der im Notfall nicht trägt.','BCM22301','BCM22301-10.1.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.d','R-R3-0008','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0009','R3-2026-07','Nehmen Sie bei Bedarf keine Änderungen am BCMS vor, um eine Nichtkonformität zu beheben, bleiben strukturelle Schwächen im System verankert. Der Fehler ist damit vorprogrammiert, dieselben Störungen wiederholen sich und Ihr Managementsystem verliert seine Fähigkeit, kritische Abläufe verlässlich abzusichern.','BCM22301','BCM22301-10.1.2.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.e','R-R3-0009','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0010','R3-2026-07','Stehen Ihre Korrekturmaßnahmen nicht im Verhältnis zu den Auswirkungen der Nichtkonformität, riskieren Sie zwei Fehler. Zu schwache Maßnahmen lassen ernste Risiken bestehen, überzogene binden unnötig Ressourcen; beides schwächt die Wirksamkeit Ihres BCMS und die Verteidigungsfähigkeit gegenüber Auditoren.','BCM22301','BCM22301-10.1.2.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.2.f','R-R3-0010','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0011','R3-2026-07','Bewahren Sie keine dokumentierten Nachweise über Art und Behandlung von Nichtkonformitäten auf, fehlt Ihnen die Beweisgrundlage. Sie können weder Wiederholungen nachvollziehen noch gegenüber Auditoren belegen, dass Sie angemessen gehandelt haben, was zu Abweichungen im Audit und zum Verlust der Zertifizierung führen kann.','BCM22301','BCM22301-10.1.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.3.a','R-R3-0011','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0012','R3-2026-07','Dokumentieren Sie die Ergebnisse Ihrer Korrekturmaßnahmen nicht, lässt sich deren Wirksamkeit später nicht belegen. Ohne diesen Nachweis fehlt der Beleg für kontinuierliche Verbesserung, Auditoren beanstanden die Lücke und Ihre Organisation kann die ordnungsgemäße Behebung von Abweichungen nicht rechtssicher darstellen.','BCM22301','BCM22301-10.1.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.1.3.b','R-R3-0012','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0013','R3-2026-07','Verbessern Sie die Eignung, Angemessenheit und Wirksamkeit des BCMS nicht fortlaufend anhand von Kennzahlen, veraltet Ihr System schleichend. Es passt sich weder neuen Bedrohungen noch geänderten Prozessen an, sodass die Reaktionsfähigkeit sinkt und kritische Leistungen im Ernstfall länger als tolerierbar ausfallen.','BCM22301','BCM22301-10.2.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.2.1','R-R3-0013','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0014','R3-2026-07','Berücksichtigen Sie die Ergebnisse aus Analyse, Bewertung und Managementbewertung nicht, verschenken Sie wertvolle Erkenntnisse. Verbesserungsbedarf bleibt ungenutzt, dieselben Schwachstellen bestehen fort und Ihr BCMS entwickelt sich nicht weiter, wodurch es hinter den tatsächlichen Kontinuitätsanforderungen Ihrer Organisation zurückbleibt.','BCM22301','BCM22301-10.2.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-10.2.2','R-R3-0014','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0015','R3-2026-07','Ermitteln Sie die für Ihr BCMS relevanten interessierten Parteien nicht, übersehen Sie wichtige Stakeholder wie Aufsichtsbehörden, Kunden oder Lieferanten. Deren Erwartungen und Vorgaben fließen dann nicht in Ihr System ein, was zu Fehlplanungen, unerfüllten Pflichten und im Ernstfall zu Konflikten und Reputationsschäden führt.','BCM22301','BCM22301-4.2.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.2.1.a','R-R3-0015','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0016','R3-2026-07','Bestimmen Sie die Anforderungen der interessierten Parteien an das BCMS nicht, bauen Sie Ihr System an den tatsächlichen Erwartungen vorbei. Rechtliche, vertragliche oder behördliche Vorgaben bleiben unerfüllt, wodurch Vertragsstrafen, der Verlust von Aufträgen und Beanstandungen bei Prüfungen drohen.','BCM22301','BCM22301-4.2.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.2.1.b','R-R3-0016','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0017','R3-2026-07','Führen Sie keinen Prozess zur Ermittlung anwendbarer rechtlicher und regulatorischer Anforderungen ein und pflegen ihn, übersehen Sie geltende Pflichten. Ihre Organisation verstößt unbemerkt gegen Vorgaben, was Bußgelder, behördliche Auflagen und die persönliche Haftung der Leitung nach sich ziehen kann.','BCM22301','BCM22301-4.2.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.2.2.a','R-R3-0017','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0018','R3-2026-07','Stellen Sie nicht sicher, dass die anwendbaren rechtlichen und regulatorischen Anforderungen bei Umsetzung und Betrieb des BCMS berücksichtigt werden, bleibt Ihr System formal wirkungslos. Die Vorgaben existieren nur auf dem Papier, sodass Ihre Organisation trotz vorhandener Dokumente rechtlich angreifbar bleibt und Sanktionen riskiert.','BCM22301','BCM22301-4.2.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.2.2.b','R-R3-0018','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0019','R3-2026-07','Dokumentieren Sie Ihre rechtlichen und regulatorischen Anforderungen nicht und halten sie nicht aktuell, arbeiten Sie mit veralteten Vorgaben. Gesetzesänderungen entgehen Ihnen, Sie erfüllen überholte Pflichten und riskieren bei Prüfungen Beanstandungen sowie Sanktionen wegen nicht eingehaltener aktueller Rechtslage.','BCM22301','BCM22301-4.2.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.2.2.c','R-R3-0019','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0020','R3-2026-07','Bestimmen Sie die Grenzen und die Anwendbarkeit des BCMS nicht, bleibt der Anwendungsbereich unklar. Wichtige Bereiche fallen unbemerkt durch das Raster, sind im Notfall nicht abgesichert und Ihre Organisation entdeckt erst in der Krise, dass kritische Prozesse gar nicht vom Managementsystem erfasst waren.','BCM22301','BCM22301-4.3.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.1','R-R3-0020','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0021','R3-2026-07','Berücksichtigen Sie bei der Festlegung des Anwendungsbereichs die externen und internen Themen nicht, passt der Scope nicht zur Realität Ihrer Organisation. Relevante Rahmenbedingungen bleiben ausgeblendet, sodass Ihr BCMS an den tatsächlichen Risiken vorbeigeht und im Ernstfall entscheidende Bereiche ungeschützt lässt.','BCM22301','BCM22301-4.3.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.1.a','R-R3-0021','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0022','R3-2026-07','Lassen Sie bei der Festlegung des Anwendungsbereichs die Anforderungen der interessierten Parteien außer Acht, deckt Ihr Scope deren Erwartungen nicht ab. Wichtige Leistungen für Kunden oder Behörden fallen aus dem BCMS heraus und sind im Notfall nicht abgesichert, was zu Vertragsverletzungen und Vertrauensverlust führt.','BCM22301','BCM22301-4.3.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.1.b','R-R3-0022','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0023','R3-2026-07','Berücksichtigen Sie Ihre Mission, Ziele sowie internen und externen Verpflichtungen bei der Scope-Festlegung nicht, verliert Ihr BCMS den Bezug zum Kerngeschäft. Es schützt dann möglicherweise Nebensächliches und lässt geschäftskritische Verpflichtungen ungesichert, wodurch im Ernstfall gerade die wichtigsten Zusagen nicht eingehalten werden können.','BCM22301','BCM22301-4.3.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.1.c','R-R3-0023','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0024','R3-2026-07','Ist der Anwendungsbereich des BCMS nicht als dokumentierte Information verfügbar, bleibt der Geltungsbereich unverbindlich und auslegbar. Mitarbeitende und Auditoren wissen nicht, was abgedeckt ist, es entstehen Lücken und Missverständnisse und Sie können den Scope bei Prüfungen nicht belegen, was zu Audit-Abweichungen führt.','BCM22301','BCM22301-4.3.1.doc') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.1.doc','R-R3-0024','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0025','R3-2026-07','Legen Sie die in das BCMS einzubeziehenden Teile der Organisation nicht unter Berücksichtigung von Standorten, Größe, Art und Komplexität fest, entstehen blinde Flecken. Ganze Standorte oder Einheiten bleiben ungeschützt und fallen im Notfall aus, ohne dass Notfallpläne greifen, was die Betriebskontinuität ernsthaft gefährdet.','BCM22301','BCM22301-4.3.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.2.a','R-R3-0025','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0026','R3-2026-07','Identifizieren Sie die in das BCMS einzubeziehenden Produkte und Dienstleistungen nicht, bleibt unklar, was im Ernstfall aufrechterhalten werden muss. Kritische Leistungen werden womöglich nicht priorisiert und fallen bei einer Störung ungeschützt aus, wodurch Kunden, Umsatz und die Reputation Ihrer Organisation erheblichen Schaden nehmen.','BCM22301','BCM22301-4.3.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.2.b','R-R3-0026','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0027','R3-2026-07','Dokumentieren und begründen Sie Ausschlüsse aus dem Anwendungsbereich nicht, bleiben Lücken im BCMS unsichtbar und unkontrolliert. Ausgeschlossene Bereiche gelten fälschlich als abgesichert, im Notfall zeigt sich die Schutzlücke unvorbereitet und Auditoren beanstanden die fehlende Rechtfertigung, was Ihre Zertifizierung gefährdet.','BCM22301','BCM22301-4.3.2.excl') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.2.excl','R-R3-0027','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0028','R3-2026-07','Stellen Sie nicht sicher, dass Ausschlüsse die Fähigkeit zur Gewährleistung der Betriebskontinuität nicht beeinträchtigen, können Sie kritische Prozesse unbemerkt aus dem Schutz herausnehmen. Ein durch BIA und Risikobewertung eigentlich als wesentlich erkannter Bereich fällt im Notfall aus und Ihre Organisation kann ihre Leistungen nicht mehr erbringen.','BCM22301','BCM22301-4.3.2.excl2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-4.3.2.excl2','R-R3-0028','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0029','R3-2026-07','Stellt die oberste Leitung nicht sicher, dass Business-Continuity-Politik und -Ziele festgelegt und mit der strategischen Ausrichtung vereinbar sind, fehlt dem BCMS die Richtung. Es läuft ohne klaren Auftrag, verfehlt geschäftliche Prioritäten und wird von Auditoren als nicht wirksam geführt beanstandet, was die Zertifizierung gefährdet.','BCM22301','BCM22301-5.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.a','R-R3-0029','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0030','R3-2026-07','Stellt die oberste Leitung die Integration der BCMS-Anforderungen in die Geschäftsprozesse nicht sicher, bleibt Business Continuity ein isoliertes Papierkonstrukt. Im Tagesgeschäft wird sie nicht gelebt, sodass im Ernstfall die eingeübten Abläufe fehlen und Ihre Organisation deutlich langsamer und fehleranfälliger auf Störungen reagiert.','BCM22301','BCM22301-5.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.b','R-R3-0030','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0031','R3-2026-07','Stellt die oberste Leitung die für das BCMS erforderlichen Ressourcen nicht bereit, bleibt das System unterfinanziert und unterbesetzt. Notwendige Maßnahmen, Übungen und Technik unterbleiben, sodass Ihre Notfallvorsorge auf dem Papier existiert, im Ernstfall jedoch mangels Mitteln und Personal nicht funktioniert.','BCM22301','BCM22301-5.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.c','R-R3-0031','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0032','R3-2026-07','Kommuniziert die oberste Leitung die Bedeutung eines wirksamen Business-Continuity-Managements nicht, fehlt den Beschäftigten das Bewusstsein für dessen Wichtigkeit. Vorgaben werden nachlässig behandelt, Verantwortung nicht wahrgenommen und im Ernstfall handeln Mitarbeitende unkoordiniert, was die Wiederherstellung kritischer Prozesse erheblich verzögert.','BCM22301','BCM22301-5.1.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.d','R-R3-0032','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0033','R3-2026-07','Stellt die oberste Leitung nicht sicher, dass das BCMS seine beabsichtigten Ergebnisse erreicht, läuft das System ohne Erfolgskontrolle ins Leere. Abweichungen zwischen Anspruch und Wirklichkeit bleiben unbemerkt, sodass Ihre Organisation sich in falscher Sicherheit wiegt und im Notfall die erwartete Kontinuität nicht erhält.','BCM22301','BCM22301-5.1.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.e','R-R3-0033','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0034','R3-2026-07','Leitet und unterstützt die oberste Leitung die Personen nicht, die zur Wirksamkeit des BCMS beitragen, fehlt es an Rückhalt und Orientierung. Verantwortliche werden allein gelassen, verlieren Motivation und Durchsetzungskraft, sodass wichtige Maßnahmen liegen bleiben und die Widerstandsfähigkeit Ihrer Organisation gegenüber Störungen sinkt.','BCM22301','BCM22301-5.1.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.f','R-R3-0034','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0035','R3-2026-07','Fördert die oberste Leitung die fortlaufende Verbesserung des BCMS nicht, stagniert das System. Es reagiert nicht auf neue Risiken, Erkenntnisse aus Vorfällen verpuffen und der Reifegrad Ihrer Notfallvorsorge bleibt zurück, wodurch Ihre Organisation künftigen Bedrohungen zunehmend schlechter gewachsen ist.','BCM22301','BCM22301-5.1.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.g','R-R3-0035','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0036','R3-2026-07','Unterstützt die oberste Leitung andere Führungsrollen nicht dabei, ihre Führung im BCMS zu demonstrieren, bleibt Verantwortung an der Spitze hängen. Mittleren Führungsebenen fehlt das Mandat, Business Continuity in ihren Bereichen durchzusetzen, sodass Vorgaben im Tagesgeschäft versanden und die Umsetzung flächendeckend lückenhaft bleibt.','BCM22301','BCM22301-5.1.h') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.1.h','R-R3-0036','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0037','R3-2026-07','Legt die oberste Leitung keine dem Zweck der Organisation angemessene Business-Continuity-Politik fest, fehlt dem BCMS das verbindliche Fundament. Ohne klaren Rahmen handeln Bereiche uneinheitlich, Prioritäten bleiben ungeklärt und Auditoren beanstanden die fehlende Grundsatzverpflichtung, was Ihre Zertifizierung und die Steuerbarkeit des Systems gefährdet.','BCM22301','BCM22301-5.2.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.2.1.a','R-R3-0037','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0038','R3-2026-07','Bietet Ihre Business-Continuity-Politik keinen Rahmen für die Festlegung von Zielen, bleiben die Bemühungen richtungslos. Ohne ableitbare, messbare Ziele lässt sich der Erfolg des BCMS weder planen noch überprüfen, sodass Maßnahmen beliebig werden und die Wirksamkeit Ihrer Notfallvorsorge nicht nachweisbar ist.','BCM22301','BCM22301-5.2.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.2.1.b','R-R3-0038','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0039','R3-2026-07','Enthält Ihre Business-Continuity-Politik keine Verpflichtung zur Erfüllung anwendbarer Anforderungen, fehlt das klare Bekenntnis zur Einhaltung von Recht und Vorgaben. Compliance wird unverbindlich, Pflichten werden übersehen und Ihre Organisation riskiert Rechtsverstöße, Sanktionen sowie Beanstandungen bei internen und externen Prüfungen.','BCM22301','BCM22301-5.2.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.2.1.c','R-R3-0039','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0040','R3-2026-07','Enthält Ihre Business-Continuity-Politik keine Verpflichtung zur fortlaufenden Verbesserung, fehlt der grundsätzliche Auftrag zur Weiterentwicklung. Das BCMS verharrt auf seinem Stand, passt sich neuen Bedrohungen nicht an und verliert über die Zeit an Wirksamkeit, wodurch Ihre Organisation gegenüber wachsenden Risiken zurückfällt.','BCM22301','BCM22301-5.2.1.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.2.1.d','R-R3-0040','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0041','R3-2026-07','Ist Ihre Business-Continuity-Politik nicht als dokumentierte Information verfügbar, bleibt sie unverbindlich und nicht nachweisbar. Beschäftigte können sich nicht darauf berufen, die Ausrichtung bleibt auslegbar und bei Audits fehlt der Beleg für ein grundlegendes Element, was zu Abweichungen und zum Verlust der Zertifizierung führen kann.','BCM22301','BCM22301-5.2.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.2.2.a','R-R3-0041','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0042','R3-2026-07','Wird Ihre Business-Continuity-Politik innerhalb der Organisation nicht kommuniziert, kennen die Beschäftigten die geltenden Grundsätze nicht. Sie können danach weder handeln noch Prioritäten richtig setzen, sodass die Politik wirkungslos bleibt und im Ernstfall das gemeinsame Verständnis für das notwendige Vorgehen fehlt.','BCM22301','BCM22301-5.2.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.2.2.b','R-R3-0042','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0043','R3-2026-07','Ist Ihre Business-Continuity-Politik für interessierte Parteien nicht, soweit angemessen, verfügbar, fehlt außenwirksam der Nachweis Ihres Engagements. Kunden, Behörden oder Partner können Ihre Verlässlichkeit nicht einschätzen, was Vertrauen kostet, Ausschreibungschancen mindert und bei vertraglich geforderter Transparenz zu Beanstandungen führen kann.','BCM22301','BCM22301-5.2.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.2.2.c','R-R3-0043','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0044','R3-2026-07','Weist die oberste Leitung keine Verantwortung und Befugnis zu, die Erfüllung der Anforderungen dieses Dokuments sicherzustellen, fehlt eine klare Zuständigkeit. Aufgaben bleiben liegen, weil sich niemand verantwortlich fühlt, das BCMS wird nicht wirksam gesteuert und Ihre Organisation riskiert Umsetzungslücken sowie Beanstandungen im Audit.','BCM22301','BCM22301-5.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.3.a','R-R3-0044','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0045','R3-2026-07','Wenn die oberste Leitung niemandem die Verantwortung und Befugnis zur Berichterstattung über die Leistung des BCMS zuweist, erfahren die Entscheidungsträger nicht, ob Ihr Notfallmanagement wirksam ist. Schwachstellen und Fehlentwicklungen bleiben verborgen, notwendige Korrekturen unterbleiben, und im Ernstfall stehen Sie einer Störung mit einem ungeprüften, möglicherweise untauglichen System gegenüber.','BCM22301','BCM22301-5.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-5.3.b','R-R3-0045','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0046','R3-2026-07','Wenn Sie bei der Planung des BCMS die relevanten Risiken und Chancen nicht bestimmen, bleiben Bedrohungen für Ihre kritischen Prozesse unerkannt. Ihre Vorsorge greift dann ins Leere, weil sie nicht auf die tatsächlichen Gefährdungen ausgerichtet ist. Im Störfall erreichen Sie die beabsichtigten Ergebnisse nicht und riskieren vermeidbare Ausfälle.','BCM22301','BCM22301-6.1.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.1.1.a','R-R3-0046','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0047','R3-2026-07','Wenn Sie die Risiken und Chancen nicht bestimmen, um unerwünschte Auswirkungen zu verhindern oder zu verringern, treffen Störungen Ihre Organisation unvorbereitet. Ohne diese Analyse können Sie keine gezielten Gegenmaßnahmen planen, sodass Schäden ungebremst eintreten und sich Betriebsunterbrechungen, finanzielle Verluste und Reputationsschäden vermeidbar ausweiten.','BCM22301','BCM22301-6.1.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.1.1.b','R-R3-0047','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0048','R3-2026-07','Wenn Sie die Risiken und Chancen für eine fortlaufende Verbesserung des BCMS nicht bestimmen, bleibt Ihr Managementsystem statisch und veraltet. Veränderte Bedrohungslagen und neue Anforderungen werden nicht aufgegriffen, sodass Ihre Vorsorge mit der Zeit an Wirksamkeit verliert und im Ernstfall nicht mehr zu Ihrer aktuellen Situation passt.','BCM22301','BCM22301-6.1.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.1.1.c','R-R3-0048','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0049','R3-2026-07','Wenn Sie keine konkreten Maßnahmen zur Behandlung der ermittelten Risiken und Chancen planen, bleibt Ihre Risikoanalyse folgenlos. Erkannte Gefährdungen werden nicht adressiert, sodass die identifizierten Schwachstellen bestehen bleiben. Im Störfall stehen Sie ohne vorbereitete Reaktion da und tragen vermeidbare Schäden.','BCM22301','BCM22301-6.1.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.1.2.a','R-R3-0049','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0050','R3-2026-07','Wenn Sie nicht planen, wie Sie die Maßnahmen zur Risikobehandlung in Ihre BCMS-Prozesse integrieren und umsetzen, bleiben gute Vorsätze auf dem Papier. Die Maßnahmen entfalten im Arbeitsalltag keine Wirkung, weil unklar ist, wer sie wie umsetzt. Ihr BCMS schützt Sie dann nur scheinbar.','BCM22301','BCM22301-6.1.2.b.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.1.2.b.1','R-R3-0050','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0051','R3-2026-07','Wenn Sie nicht planen, wie Sie die Wirksamkeit der ergriffenen Maßnahmen bewerten, erfahren Sie nie, ob Ihre Risikobehandlung tatsächlich schützt. Unwirksame Maßnahmen bleiben unentdeckt und wiegen Sie in falscher Sicherheit. So verlassen Sie sich im Ernstfall auf Vorkehrungen, die der Belastung möglicherweise nicht standhalten.','BCM22301','BCM22301-6.1.2.b.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.1.2.b.2','R-R3-0051','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0052','R3-2026-07','Wenn Ihre Business-Continuity-Ziele nicht mit der Business-Continuity-Politik übereinstimmen, ziehen Leitlinie und operative Ziele in unterschiedliche Richtungen. Ihre Mitarbeitenden erhalten widersprüchliche Vorgaben, Ressourcen werden fehlgeleitet, und das BCMS verliert an Glaubwürdigkeit und Steuerungskraft. Im Ergebnis erreichen Sie weder die strategischen noch die operativen Vorgaben zuverlässig.','BCM22301','BCM22301-6.2.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.1.a','R-R3-0052','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0053','R3-2026-07','Wenn Ihre Business-Continuity-Ziele nicht messbar formuliert sind, können Sie deren Erreichung nicht überprüfen. Fortschritte und Defizite bleiben unklar, und Diskussionen über den Zielerreichungsgrad enden ergebnislos. Ohne messbare Ziele fehlt Ihnen die Grundlage, um Ihr BCMS gezielt zu steuern und nachweisbar zu verbessern.','BCM22301','BCM22301-6.2.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.1.b','R-R3-0053','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0054','R3-2026-07','Wenn Ihre Business-Continuity-Ziele die anwendbaren internen und externen Anforderungen nicht berücksichtigen, gehen sie an den tatsächlichen Bedürfnissen vorbei. Rechtliche Vorgaben und Erwartungen wichtiger Interessengruppen bleiben unerfüllt, was zu Beanstandungen, Vertrauensverlust und rechtlichen Konsequenzen führen kann. Ihre Vorsorge passt dann nicht zu Ihrem realen Umfeld.','BCM22301','BCM22301-6.2.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.1.c','R-R3-0054','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0055','R3-2026-07','Wenn Sie Ihre Business-Continuity-Ziele nicht überwachen, bemerken Sie Abweichungen und Rückstände zu spät. Fehlentwicklungen setzen sich unbemerkt fort, und Sie können nicht rechtzeitig gegensteuern. Dadurch verfehlen Sie Ihre Ziele womöglich, ohne es zu wissen, und stehen im Ernstfall schlechter vorbereitet da als angenommen.','BCM22301','BCM22301-6.2.1.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.1.d','R-R3-0055','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0056','R3-2026-07','Wenn Sie Ihre Business-Continuity-Ziele nicht innerhalb der Organisation kommunizieren, kennen Ihre Mitarbeitenden die gemeinsamen Prioritäten nicht. Jeder handelt nach eigenem Verständnis, wichtige Beiträge unterbleiben, und die Ziele werden nicht getragen. So bleibt Ihr BCMS ein abstraktes Konzept, das im Ernstfall keine gelebte Wirkung entfaltet.','BCM22301','BCM22301-6.2.1.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.1.e','R-R3-0056','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0057','R3-2026-07','Wenn Sie Ihre Business-Continuity-Ziele nicht bei Bedarf aktualisieren, veralten sie und verlieren den Bezug zu Ihrer tatsächlichen Lage. Neue Risiken, veränderte Prozesse oder gestiegene Anforderungen bleiben unberücksichtigt. Sie steuern Ihr BCMS dann nach überholten Vorgaben und schützen sich nicht mehr gegen die heute relevanten Bedrohungen.','BCM22301','BCM22301-6.2.1.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.1.f','R-R3-0057','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0058','R3-2026-07','Wenn Sie keine dokumentierte Information über Ihre Business-Continuity-Ziele aufbewahren, fehlt der verbindliche Bezugspunkt für Steuerung und Nachweis. Ziele geraten in Vergessenheit oder werden unterschiedlich ausgelegt, und bei Audits oder Prüfungen können Sie Ihre Zielsetzung nicht belegen. Nachvollziehbarkeit und Kontinuität Ihrer Vorsorge gehen verloren.','BCM22301','BCM22301-6.2.1.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.1.g','R-R3-0058','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0059','R3-2026-07','Wenn Sie bei der Planung nicht festlegen, was konkret zur Erreichung Ihrer Business-Continuity-Ziele getan wird, bleiben die Ziele bloße Absichtserklärungen. Ohne konkrete Handlungen kommt die Umsetzung nicht voran, Verantwortliche wissen nicht, was von ihnen erwartet wird, und die angestrebten Ergebnisse bleiben aus.','BCM22301','BCM22301-6.2.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.2.a','R-R3-0059','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0060','R3-2026-07','Wenn Sie nicht festlegen, welche Ressourcen zur Erreichung Ihrer Business-Continuity-Ziele erforderlich sind, fehlt es im entscheidenden Moment an Personal, Mitteln oder Technik. Maßnahmen bleiben stecken oder scheitern an fehlender Ausstattung. So verzögert sich die Zielerreichung, und im Ernstfall stehen Ihnen die benötigten Mittel nicht zur Verfügung.','BCM22301','BCM22301-6.2.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.2.b','R-R3-0060','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0061','R3-2026-07','Wenn Sie nicht festlegen, wer für die Erreichung der Business-Continuity-Ziele verantwortlich ist, fühlt sich niemand zuständig. Aufgaben bleiben liegen, weil jeder annimmt, ein anderer kümmere sich darum. Ohne klare Verantwortlichkeit versanden Ihre Vorhaben, und die Ziele werden nicht erreicht.','BCM22301','BCM22301-6.2.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.2.c','R-R3-0061','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0062','R3-2026-07','Wenn Sie nicht festlegen, bis wann die Maßnahmen abgeschlossen sein sollen, fehlt jede Verbindlichkeit. Ohne Termine werden Aufgaben immer wieder verschoben und geraten aus dem Blick. Ihre Business-Continuity-Ziele bleiben so auf unbestimmte Zeit unerfüllt, während die zugrunde liegenden Risiken fortbestehen.','BCM22301','BCM22301-6.2.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.2.d','R-R3-0062','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0063','R3-2026-07','Wenn Sie nicht festlegen, wie die Ergebnisse zur Erreichung Ihrer Business-Continuity-Ziele bewertet werden, können Sie den Erfolg Ihrer Maßnahmen nicht beurteilen. Sie erkennen nicht, ob die Ziele wirklich erreicht wurden, und steuern im Blindflug. Fehlentwicklungen bleiben unbemerkt, und eine gezielte Verbesserung wird unmöglich.','BCM22301','BCM22301-6.2.2.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.2.2.e','R-R3-0063','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0064','R3-2026-07','Wenn Sie bei Änderungen am BCMS den Zweck und die möglichen Auswirkungen nicht berücksichtigen, führen Anpassungen zu unbeabsichtigten Nebenwirkungen. Neue Lücken entstehen, während bestehende Schutzvorkehrungen ungewollt geschwächt werden. So verschlechtern gut gemeinte Änderungen Ihre Notfallvorsorge, ohne dass Sie es rechtzeitig bemerken.','BCM22301','BCM22301-6.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.3.a','R-R3-0064','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0065','R3-2026-07','Wenn Sie bei Änderungen am BCMS die Integrität des Managementsystems nicht wahren, geraten dessen Bestandteile aus dem Gleichgewicht. Einzelne Anpassungen passen nicht mehr zusammen, Prozesse und Dokumente widersprechen sich, und das System verliert seine Stimmigkeit. Im Ernstfall greifen die Vorkehrungen dann nicht mehr zuverlässig ineinander.','BCM22301','BCM22301-6.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.3.b','R-R3-0065','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0066','R3-2026-07','Wenn Sie bei Änderungen am BCMS die Verfügbarkeit der benötigten Ressourcen nicht berücksichtigen, planen Sie Anpassungen ohne die Mittel zu ihrer Umsetzung. Die Änderungen bleiben unvollständig oder überlasten vorhandene Kapazitäten. So entstehen halbfertige Zustände, in denen Ihr BCMS weder im alten noch im neuen Stand voll funktionsfähig ist.','BCM22301','BCM22301-6.3.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.3.c','R-R3-0066','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0067','R3-2026-07','Wenn Sie bei Änderungen am BCMS die Zuweisung oder Neuzuweisung von Verantwortlichkeiten und Befugnissen nicht berücksichtigen, entstehen Zuständigkeitslücken. Aufgaben fallen zwischen den Beteiligten durch, weil unklar bleibt, wer sie nach der Änderung übernimmt. Im Störfall handelt dann niemand oder mehrere gegeneinander, was die Reaktion verzögert.','BCM22301','BCM22301-6.3.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-6.3.d','R-R3-0067','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0068','R3-2026-07','Wenn Sie die erforderliche Kompetenz der Personen, die business-continuity-relevante Tätigkeiten ausführen, nicht bestimmen, wissen Sie nicht, welche Fähigkeiten überhaupt nötig sind. Aufgaben werden dann von unzureichend qualifizierten Personen wahrgenommen, Fehler häufen sich, und im Ernstfall fehlt Ihnen das Können, um Störungen wirksam zu bewältigen.','BCM22301','BCM22301-7.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.2.a','R-R3-0068','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0069','R3-2026-07','Wenn Sie nicht sicherstellen, dass die betreffenden Personen durch Ausbildung, Schulung oder Erfahrung kompetent sind, führen unzureichend qualifizierte Mitarbeitende kritische Aufgaben aus. Im Störfall treffen sie falsche Entscheidungen oder handeln zu zögerlich. Dadurch verlängern sich Ausfälle, und Ihre Business-Continuity-Leistung leidet erheblich.','BCM22301','BCM22301-7.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.2.b','R-R3-0069','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0070','R3-2026-07','Wenn Sie keine Maßnahmen zum Erwerb der notwendigen Kompetenz ergreifen und deren Wirksamkeit nicht bewerten, bleiben erkannte Qualifikationslücken bestehen. Schulungen verpuffen wirkungslos, ohne dass Sie es merken. So verlassen Sie sich im Ernstfall auf Personen, die den Anforderungen der Krisenbewältigung möglicherweise nicht gewachsen sind.','BCM22301','BCM22301-7.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.2.c','R-R3-0070','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0071','R3-2026-07','Wenn Sie keine dokumentierte Information als Nachweis der Kompetenz aufbewahren, können Sie die Qualifikation Ihrer Mitarbeitenden nicht belegen. Bei Audits und Prüfungen fehlt der Nachweis, und Sie verlieren den Überblick über Schulungsstände und Auffrischungsbedarfe. So bleiben Kompetenzlücken unbemerkt, bis sie sich im Ernstfall auswirken.','BCM22301','BCM22301-7.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.2.d','R-R3-0071','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0072','R3-2026-07','Wenn Ihre Mitarbeitenden die Business-Continuity-Politik nicht kennen und sich ihrer nicht bewusst sind, fehlt ihnen die gemeinsame Orientierung. Sie handeln ohne Verständnis für die Ziele der Notfallvorsorge und treffen Entscheidungen, die der Leitlinie zuwiderlaufen. Im Ernstfall reagiert Ihre Organisation dann uneinheitlich und ohne klare Richtung.','BCM22301','BCM22301-7.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.3.a','R-R3-0072','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0073','R3-2026-07','Wenn Ihre Mitarbeitenden sich ihres Beitrags zur Wirksamkeit des BCMS und der Vorteile einer besseren Business-Continuity-Leistung nicht bewusst sind, nehmen sie ihre Rolle nicht ernst. Vorsorgemaßnahmen werden als lästige Pflicht abgetan und nachlässig umgesetzt. So bleibt Ihr BCMS in der Praxis wirkungslos, weil die Beteiligten es nicht mittragen.','BCM22301','BCM22301-7.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.3.b','R-R3-0073','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0074','R3-2026-07','Wenn Ihre Mitarbeitenden sich der Folgen einer Nichterfüllung der BCMS-Anforderungen nicht bewusst sind, unterschätzen sie die Bedeutung ihres Handelns. Vorgaben werden umgangen oder ignoriert, ohne dass die Tragweite erkannt wird. Dadurch entstehen vermeidbare Schwachstellen, die im Störfall zu ernsten Ausfällen und Schäden führen können.','BCM22301','BCM22301-7.3.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.3.c','R-R3-0074','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0075','R3-2026-07','Wenn Ihre Mitarbeitenden ihre eigene Rolle und Verantwortung vor, während und nach Störungen nicht kennen, entsteht im Ernstfall Chaos. Niemand weiß, was zu tun ist, Zuständigkeiten überschneiden sich oder bleiben ungenutzt, und wertvolle Zeit verstreicht. So verzögert sich Ihre Reaktion, und der Schaden vergrößert sich unnötig.','BCM22301','BCM22301-7.3.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.3.d','R-R3-0075','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0076','R3-2026-07','Wenn Sie für die BCMS-relevante Kommunikation nicht bestimmen, worüber kommuniziert werden soll, bleiben wichtige Inhalte ungeklärt. Im Ernstfall werden entscheidende Informationen vergessen oder unvollständig weitergegeben. Empfänger treffen dann Entscheidungen auf lückenhafter Grundlage, was Ihre Störungsbewältigung erschwert und Fehlreaktionen begünstigt.','BCM22301','BCM22301-7.4.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.4.a','R-R3-0076','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0077','R3-2026-07','Wenn Sie nicht bestimmen, wann kommuniziert werden soll, erreichen Informationen die Beteiligten zu spät oder zur Unzeit. Im Störfall verzögern sich Warnungen und Abstimmungen, sodass notwendige Maßnahmen nicht rechtzeitig anlaufen. Fehlende zeitliche Vorgaben führen zu Lücken in der Informationskette und verschlechtern Ihre Reaktionsfähigkeit.','BCM22301','BCM22301-7.4.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.4.b','R-R3-0077','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0078','R3-2026-07','Wenn Sie nicht bestimmen, mit wem kommuniziert werden soll, bleiben wichtige interne und externe Ansprechpartner außen vor. Entscheidungsträger, Behörden oder Dienstleister werden im Ernstfall nicht oder zu spät einbezogen. So entstehen Informationslücken, die eine abgestimmte Störungsbewältigung verhindern und das Vertrauen der Beteiligten beschädigen.','BCM22301','BCM22301-7.4.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.4.c','R-R3-0078','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0079','R3-2026-07','Wenn Sie nicht bestimmen, wie kommuniziert werden soll, fehlen im Ernstfall verlässliche Kommunikationswege. Fällt der übliche Kanal aus, wissen die Beteiligten nicht, wie sie sich erreichen. Wichtige Nachrichten kommen dann verspätet oder gar nicht an, und Ihre Krisenkommunikation bricht im entscheidenden Moment zusammen.','BCM22301','BCM22301-7.4.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.4.d','R-R3-0079','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0080','R3-2026-07','Wenn Sie nicht bestimmen, wer kommunizieren soll, ist im Störfall unklar, wer welche Botschaften verantwortet. Es entsteht entweder Schweigen oder ein Durcheinander widersprüchlicher Aussagen. Ungeprüfte oder falsche Informationen gelangen nach außen, was Verwirrung stiftet und den Ruf Ihrer Organisation ernsthaft gefährdet.','BCM22301','BCM22301-7.4.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.4.e','R-R3-0080','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0081','R3-2026-07','Wenn Ihr BCMS die von der Norm geforderte dokumentierte Information nicht umfasst, fehlt die verbindliche Grundlage für ein nachweisbares Managementsystem. Prozesse sind nicht belegt, und bei Audits oder Zertifizierungen können Sie die Konformität nicht nachweisen. Ohne diese Dokumentation bleibt Ihr BCMS unvollständig und rechtlich angreifbar.','BCM22301','BCM22301-7.5.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.1.a','R-R3-0081','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0082','R3-2026-07','Wenn Ihr BCMS die für seine Wirksamkeit notwendige dokumentierte Information nicht umfasst, fehlt Ihren Mitarbeitenden die verlässliche Handlungsgrundlage. Wichtiges Wissen bleibt an einzelne Personen gebunden und geht bei deren Ausfall verloren. Im Ernstfall fehlen dann die Vorgaben, die eine schnelle und geordnete Reaktion ermöglichen.','BCM22301','BCM22301-7.5.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.1.b','R-R3-0082','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0083','R3-2026-07','Wenn Sie beim Erstellen und Aktualisieren dokumentierter Information keine angemessene Kennzeichnung wie Titel, Datum oder Autor sicherstellen, verlieren Sie die Übersicht über Ihre Dokumente. Veraltete und aktuelle Fassungen sind nicht unterscheidbar, und niemand weiß, welche Version gilt. Im Ernstfall arbeiten Beteiligte mit falschen oder überholten Unterlagen.','BCM22301','BCM22301-7.5.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.2.a','R-R3-0083','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0084','R3-2026-07','Wenn Sie kein angemessenes Format und Medium der dokumentierten Information sicherstellen, sind wichtige Unterlagen im Ernstfall nicht nutzbar. Dokumente lassen sich nicht öffnen, sind unverständlich oder auf ausgefallenen Systemen gespeichert. So stehen Ihnen gerade dann keine verwertbaren Informationen zur Verfügung, wenn Sie sie am dringendsten benötigen.','BCM22301','BCM22301-7.5.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.2.b','R-R3-0084','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0085','R3-2026-07','Wenn Sie beim Erstellen und Aktualisieren dokumentierter Information keine angemessene Überprüfung und Genehmigung sicherstellen, gelangen fehlerhafte oder ungeeignete Vorgaben in Umlauf. Ihre Mitarbeitenden verlassen sich auf ungeprüfte Informationen und handeln womöglich falsch. Im Störfall führen solche Fehler in den Unterlagen zu Fehlentscheidungen und vermeidbaren Schäden.','BCM22301','BCM22301-7.5.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.2.c','R-R3-0085','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0086','R3-2026-07','Wenn Ihre dokumentierte Information nicht so gelenkt wird, dass sie dort und dann verfügbar ist, wo und wann sie gebraucht wird, fehlen im Ernstfall die entscheidenden Unterlagen. Notfallpläne sind unauffindbar oder unzugänglich, und Ihre Mitarbeitenden handeln aus dem Gedächtnis. So verzögert sich die Reaktion, und Fehler häufen sich.','BCM22301','BCM22301-7.5.3.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.3.1.a','R-R3-0086','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0087','R3-2026-07','Wenn Ihre dokumentierte Information nicht angemessen vor Verlust der Vertraulichkeit, unsachgemäßer Nutzung oder Integritätsverlust geschützt wird, geraten sensible Notfallunterlagen in falsche Hände oder werden verfälscht. Vertrauliche Informationen werden offengelegt, und Sie verlassen sich womöglich auf manipulierte Dokumente. Das gefährdet sowohl Ihre Sicherheit als auch die Verlässlichkeit Ihrer Vorsorge.','BCM22301','BCM22301-7.5.3.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.3.1.b','R-R3-0087','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0088','R3-2026-07','Wenn Sie bei der Lenkung dokumentierter Information Verteilung, Zugriff, Auffinden und Nutzung nicht regeln, herrscht Unordnung in Ihren Unterlagen. Berechtigte finden benötigte Dokumente nicht, während Unbefugte womöglich Zugriff erhalten. Im Ernstfall kosten Sie das Suchen und die fehlende Zugriffssteuerung wertvolle Zeit und gefährden eine geordnete Reaktion.','BCM22301','BCM22301-7.5.3.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.3.2.a','R-R3-0088','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0089','R3-2026-07','Wenn Sie Ablage und Erhaltung dokumentierter Informationen nicht steuern, verlieren gelenkte Unterlagen mit der Zeit ihre Lesbarkeit oder Auffindbarkeit. Im Ernstfall greifen Sie dann auf unbrauchbare oder veraltete Notfallpläne zurück, verzögern die Wiederanlaufmaßnahmen und können die Funktionsfähigkeit Ihres BCMS im Audit nicht mehr belegen.','BCM22301','BCM22301-7.5.3.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.3.2.b','R-R3-0089','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0090','R3-2026-07','Ohne geregelte Änderungslenkung und Versionskontrolle kursieren mehrere Fassungen desselben Dokuments nebeneinander. Ihre Mitarbeitenden handeln im Notfall nach überholten Anweisungen, Zuständigkeiten und Kontaktdaten stimmen nicht mehr, und Fehlentscheidungen verlängern die Störung und untergraben das Vertrauen in Ihre Notfalldokumentation.','BCM22301','BCM22301-7.5.3.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.3.2.c','R-R3-0090','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0091','R3-2026-07','Fehlt eine Regelung zu Aufbewahrung und geordneter Vernichtung, bewahren Sie Unterlagen entweder zu kurz oder unnötig lange auf. Dadurch verletzen Sie gesetzliche Aufbewahrungsfristen oder Datenschutzvorgaben, riskieren Bußgelder und geben durch unkontrollierte Entsorgung sensible Informationen an Unbefugte preis.','BCM22301','BCM22301-7.5.3.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.3.2.d','R-R3-0091','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0092','R3-2026-07','Wenn Sie dokumentierte Informationen externen Ursprungs nicht kennzeichnen und lenken, arbeiten Sie mit veralteten Normen, Verträgen oder Lieferantenvorgaben. Fehler und Inkonsistenzen fließen unbemerkt in Ihre Planung ein, sodass Ihr BCMS auf falschen Grundlagen aufbaut und im Ernstfall nicht wie vorgesehen funktioniert.','BCM22301','BCM22301-7.5.3.2.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-7.5.3.2.e','R-R3-0092','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0093','R3-2026-07','Ohne festgelegte Kriterien für Ihre Prozesse steuern Sie den Betrieb nach Bauchgefühl statt nach nachvollziehbaren Vorgaben. Ergebnisse werden uneinheitlich, Abweichungen bleiben unerkannt, und Sie können im Ernstfall weder die Wirksamkeit noch die Angemessenheit Ihrer Business-Continuity-Maßnahmen belegen.','BCM22301','BCM22301-8.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.1.a','R-R3-0093','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0094','R3-2026-07','Wenn Sie Ihre Prozesse nicht gemäß den festgelegten Kriterien steuern, klaffen Vorgaben und gelebte Praxis auseinander. Maßnahmen werden uneinheitlich oder gar nicht umgesetzt, Schwachstellen bleiben unentdeckt, und im Störungsfall reagiert Ihre Organisation unkoordiniert und langsamer als geplant.','BCM22301','BCM22301-8.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.1.b','R-R3-0094','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0095','R3-2026-07','Halten Sie keine ausreichende dokumentierte Information vor, fehlt Ihnen der Nachweis, dass Prozesse tatsächlich wie geplant durchgeführt wurden. Sie können weder gegenüber Auditoren noch intern Vertrauen belegen, verlieren die Nachvollziehbarkeit von Entscheidungen und erschweren jede Ursachenanalyse nach einer Störung.','BCM22301','BCM22301-8.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.1.c','R-R3-0095','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0096','R3-2026-07','Wenn Sie geplante Änderungen nicht steuern und Folgen unbeabsichtigter Änderungen nicht prüfen, entstehen unkontrollierte Wechselwirkungen in Ihren Continuity-Prozessen. Neue Risiken bleiben unbemerkt, bestehende Maßnahmen verlieren ihre Wirkung, und Sie bemerken die entstandene Lücke erst, wenn die Störung bereits eingetreten ist.','BCM22301','BCM22301-8.1.changes') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.1.changes','R-R3-0096','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0097','R3-2026-07','Steuern Sie ausgelagerte Prozesse und Ihre Lieferkette nicht, verlagern Sie kritische Abhängigkeiten in einen Bereich ohne Kontrolle. Fällt ein Dienstleister aus oder hält Vorgaben nicht ein, bricht ein Teil Ihrer Leistungserbringung weg, und Sie können weder gegensteuern noch die Verantwortung wirksam nachhalten.','BCM22301','BCM22301-8.1.outsourced') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.1.outsourced','R-R3-0097','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0098','R3-2026-07','Ohne systematische Prozesse zur Analyse geschäftlicher Auswirkungen und zur Bewertung von Störungsrisiken kennen Sie Ihre kritischen Aktivitäten nur ungefähr. Sie priorisieren falsch, investieren Ressourcen an den falschen Stellen und stehen im Ernstfall ohne belastbare Grundlage für Ihre Wiederanlaufentscheidungen da.','BCM22301','BCM22301-8.2.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.1.a','R-R3-0098','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0099','R3-2026-07','Wenn Sie Business-Impact-Analyse und Risikobewertung nicht in geplanten Abständen und bei wesentlichen Änderungen überprüfen, veralten Ihre Annahmen unbemerkt. Neue Aktivitäten, Abhängigkeiten oder Bedrohungen bleiben unberücksichtigt, sodass Ihre Notfallplanung auf einem überholten Bild beruht und im Ernstfall an der Realität vorbeigeht.','BCM22301','BCM22301-8.2.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.1.b','R-R3-0099','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0100','R3-2026-07','Nutzen Sie die Analyse der geschäftlichen Auswirkungen nicht zur Bestimmung Ihrer Continuity-Prioritäten und -Anforderungen, planen Sie ohne klare Rangfolge. Sie schützen im Zweifel das Falsche, verzögern die Wiederaufnahme wirklich kritischer Aktivitäten und gefährden die Lieferung Ihrer wichtigsten Produkte und Dienstleistungen.','BCM22301','BCM22301-8.2.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2','R-R3-0100','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0101','R3-2026-07','Wenn Ihr Prozess die relevanten Auswirkungsarten und -kriterien nicht definiert, bewerten Sie Störungsfolgen ohne einheitlichen Maßstab. Unterschiedliche Beteiligte kommen zu widersprüchlichen Einschätzungen, wichtige Auswirkungen werden übersehen, und Ihre gesamte Priorisierung steht auf einer unbelastbaren Grundlage.','BCM22301','BCM22301-8.2.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.a','R-R3-0101','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0102','R3-2026-07','Identifiziert Ihr Prozess die Aktivitäten zur Bereitstellung von Produkten und Dienstleistungen nicht, kennen Sie Ihre eigenen Leistungsketten nur lückenhaft. Verborgene, aber kritische Tätigkeiten bleiben ungeschützt, und ihr Ausfall trifft Sie unvorbereitet und legt die Leistungserbringung unerwartet lahm.','BCM22301','BCM22301-8.2.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.b','R-R3-0102','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0103','R3-2026-07','Wenn Ihr Prozess die zeitliche Entwicklung der Störungsauswirkungen nicht bewertet, unterschätzen Sie, wie schnell ein Ausfall eskaliert. Sie setzen Wiederanlauffristen zu großzügig an, reagieren zu spät und lassen zu, dass ein anfangs beherrschbarer Vorfall zu einem existenzbedrohenden Schaden anwächst.','BCM22301','BCM22301-8.2.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.c','R-R3-0103','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0104','R3-2026-07','Identifiziert Ihr Prozess nicht den Zeitrahmen, ab dem Auswirkungen untragbar werden, fehlt Ihnen die entscheidende Zielgröße für den Wiederanlauf. Sie priorisieren Maßnahmen ohne verbindliche Frist, verpassen den kritischen Punkt und riskieren, dass die Störung irreversible Schäden verursacht.','BCM22301','BCM22301-8.2.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.d','R-R3-0104','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0105','R3-2026-07','Wenn Sie innerhalb des kritischen Zeitrahmens keine priorisierten Wiederanlauffristen mit minimal akzeptabler Kapazität festlegen, bleibt Ihr Notfallbetrieb ungeplant. Im Ernstfall fehlt ein klares Ziel, wie viel Leistung bis wann verfügbar sein muss, sodass Wiederanlauf und Ressourceneinsatz unkoordiniert und zu langsam erfolgen.','BCM22301','BCM22301-8.2.2.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.e','R-R3-0105','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0106','R3-2026-07','Nutzen Sie die Analyse nicht zur Identifikation priorisierter Aktivitäten, behandeln Sie alle Tätigkeiten gleich. Im Notfall verzetteln sich Ihre begrenzten Kräfte an nachrangigen Aufgaben, während die wirklich geschäftskritischen Aktivitäten liegen bleiben und die Wiederaufnahme Ihrer Kernleistungen sich verzögert.','BCM22301','BCM22301-8.2.2.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.f','R-R3-0106','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0107','R3-2026-07','Wenn Ihr Prozess nicht bestimmt, welche Ressourcen die priorisierten Aktivitäten benötigen, planen Sie den Wiederanlauf ohne Kenntnis der notwendigen Mittel. Im Ernstfall fehlen Personal, Technik oder Material an entscheidender Stelle, und Ihre Continuity-Lösungen lassen sich nicht wie vorgesehen aktivieren.','BCM22301','BCM22301-8.2.2.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.g','R-R3-0107','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0108','R3-2026-07','Bestimmt Ihr Prozess die Abhängigkeiten von Partnern und Lieferanten sowie die wechselseitigen Abhängigkeiten nicht, übersehen Sie versteckte Schwachstellen. Der Ausfall eines einzelnen Zulieferers oder einer verketteten Aktivität kann dann unerwartet eine ganze priorisierte Leistung zum Erliegen bringen.','BCM22301','BCM22301-8.2.2.h') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.2.h','R-R3-0108','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0109','R3-2026-07','Wenn Sie die Risiken einer Störung Ihrer priorisierten Aktivitäten und der erforderlichen Ressourcen nicht identifizieren, bleiben Bedrohungen im Verborgenen. Sie treffen keine Vorsorge gegen konkrete Ausfallszenarien und werden von Ereignissen überrascht, die Sie bei systematischer Betrachtung hätten erkennen und abmildern können.','BCM22301','BCM22301-8.2.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.3.a','R-R3-0109','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0110','R3-2026-07','Analysieren und bewerten Sie die identifizierten Risiken nicht, kennen Sie zwar mögliche Gefahren, aber nicht deren Bedeutung. Ohne Einschätzung von Eintrittswahrscheinlichkeit und Schadenshöhe priorisieren Sie falsch, verschwenden Mittel an Nebensächliches und lassen wesentliche Risiken unbehandelt.','BCM22301','BCM22301-8.2.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.3.b','R-R3-0110','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0111','R3-2026-07','Wenn Sie nicht bestimmen, welche Risiken eine Behandlung erfordern, bleiben kritische Gefährdungen ohne Maßnahmen. Sie akzeptieren unbewusst ein zu hohes Restrisiko, sodass eine vermeidbare Störung eintritt und Ihre priorisierten Aktivitäten ungeschützt und mit erheblichen Folgen ausfallen.','BCM22301','BCM22301-8.2.3.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.2.3.c','R-R3-0111','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0112','R3-2026-07','Bestehen Ihre Business-Continuity-Strategien nicht aus konkreten Lösungen, bleibt die Planung auf der Ebene guter Absichten stehen. Im Ernstfall fehlt Ihnen ein umsetzbarer Weg zur Wiederaufnahme, und Sie improvisieren unter Druck, statt auf vorbereitete und erprobte Maßnahmen zurückzugreifen.','BCM22301','BCM22301-8.3.1.solutions') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.1.solutions','R-R3-0112','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0113','R3-2026-07','Wenn Sie bei der Identifikation nicht berücksichtigen, ob Strategien und Lösungen die priorisierten Aktivitäten innerhalb der festgelegten Zeitrahmen wiederherstellen, wählen Sie ungeeignete Ansätze. Im Ernstfall stellt sich heraus, dass Ihre Lösung zu langsam greift und die kritische Wiederanlauffrist reißt.','BCM22301','BCM22301-8.3.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.2.a','R-R3-0113','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0114','R3-2026-07','Berücksichtigen Sie bei der Identifikation nicht, inwieweit Strategien und Lösungen Ihre priorisierten Aktivitäten schützen, setzen Sie möglicherweise auf Maßnahmen ohne Schutzwirkung. Die kritischen Tätigkeiten bleiben verwundbar, und Ihre Continuity-Planung erzeugt trügerische Sicherheit statt echter Widerstandsfähigkeit.','BCM22301','BCM22301-8.3.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.2.b','R-R3-0114','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0115','R3-2026-07','Wenn Sie nicht betrachten, inwieweit Strategien und Lösungen die Wahrscheinlichkeit einer Störung verringern, vernachlässigen Sie die Vorbeugung. Sie konzentrieren sich allein auf die Reaktion, sodass vermeidbare Störungen häufiger eintreten und Ihre Organisation unnötig oft in den Notfallbetrieb wechseln muss.','BCM22301','BCM22301-8.3.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.2.c','R-R3-0115','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0116','R3-2026-07','Berücksichtigen Sie bei der Identifikation nicht, inwieweit Lösungen die Dauer einer Störung verkürzen, drohen unnötig lange Ausfälle. Selbst bei grundsätzlich wirksamen Maßnahmen zieht sich die Wiederherstellung hin, wodurch Schäden, Kosten und der Vertrauensverlust bei Kunden und Bürgern deutlich anwachsen.','BCM22301','BCM22301-8.3.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.2.d','R-R3-0116','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0117','R3-2026-07','Wenn Sie nicht prüfen, inwieweit Strategien und Lösungen die Auswirkung einer Störung auf Ihre Produkte und Dienstleistungen begrenzen, bleibt der Schaden unkontrolliert. Eine Störung schlägt dann ungefiltert bis zum Kunden durch und gefährdet Leistungsversprechen, Reputation und Vertragsbeziehungen.','BCM22301','BCM22301-8.3.2.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.2.e','R-R3-0117','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0118','R3-2026-07','Berücksichtigen Sie bei der Identifikation nicht, inwieweit Lösungen für die Verfügbarkeit angemessener Ressourcen sorgen, planen Sie Maßnahmen ohne gesicherte Mittel. Im Ernstfall fehlen Personal, Technik oder Material, und Ihre gewählte Strategie lässt sich mangels Ressourcen gar nicht erst umsetzen.','BCM22301','BCM22301-8.3.2.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.2.f','R-R3-0118','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0119','R3-2026-07','Wenn Ihre Auswahl nicht berücksichtigt, ob Strategien und Lösungen die priorisierten Aktivitäten innerhalb der festgelegten Zeitrahmen erfüllen, entscheiden Sie sich womöglich für den falschen Ansatz. Die gewählte Lösung greift dann zu spät, und Sie verfehlen im Ernstfall Ihre vereinbarten Wiederanlaufziele.','BCM22301','BCM22301-8.3.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.3.a','R-R3-0119','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0120','R3-2026-07','Berücksichtigt Ihre Auswahl nicht Art und Umfang des vertretbaren Risikos, entscheiden Sie ohne Bezug zur Risikobereitschaft Ihrer Organisation. Sie wählen entweder eine unzureichende Lösung, die zu viel Restrisiko lässt, oder eine überzogene, die Ressourcen bindet, welche Sie an anderer Stelle dringender benötigen.','BCM22301','BCM22301-8.3.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.3.b','R-R3-0120','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0121','R3-2026-07','Wenn Sie bei der Auswahl Kosten und Nutzen nicht abwägen, treffen Sie unwirtschaftliche Entscheidungen. Sie investieren entweder zu viel in wenig wirksame Lösungen oder sparen an entscheidender Stelle, sodass Ihre Business-Continuity-Maßnahmen entweder unbezahlbar oder im Ernstfall wirkungslos sind.','BCM22301','BCM22301-8.3.3.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.3.c','R-R3-0121','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0122','R3-2026-07','Bestimmen Sie die Ressourcenanforderungen zur Umsetzung der ausgewählten Continuity-Lösungen nicht, bleibt die Planung eine leere Hülle. Im Ernstfall stellen Sie fest, dass die nötigen Mittel nie beschafft oder bereitgestellt wurden, und Ihre Lösung lässt sich nicht wie vorgesehen aktivieren.','BCM22301','BCM22301-8.3.4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4','R-R3-0122','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0123','R3-2026-07','Wenn Sie bei den Ressourcenanforderungen das benötigte Personal nicht berücksichtigen, fehlen im Ernstfall qualifizierte Kräfte für den Wiederanlauf. Schlüsselaufgaben bleiben unbesetzt, verbleibende Mitarbeitende sind überlastet, und die Wiederaufnahme Ihrer priorisierten Aktivitäten verzögert sich erheblich.','BCM22301','BCM22301-8.3.4.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.a','R-R3-0123','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0124','R3-2026-07','Berücksichtigen Sie bei den Ressourcenanforderungen die benötigten Informationen und Daten nicht, kann der Wiederanlauf an fehlenden Grundlagen scheitern. Ohne aktuelle, verfügbare Daten arbeiten Ihre Teams blind oder mit veraltetem Stand, was Fehlentscheidungen begünstigt und die Wiederherstellung blockiert.','BCM22301','BCM22301-8.3.4.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.b','R-R3-0124','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0125','R3-2026-07','Wenn Sie die benötigte physische Infrastruktur wie Gebäude, Arbeitsplätze und Versorgungseinrichtungen nicht berücksichtigen, steht Ihren Teams im Ernstfall kein funktionsfähiger Ort zum Arbeiten zur Verfügung. Der Wiederanlauf scheitert an fehlenden Räumen, Strom oder Versorgung, obwohl Personal und Technik bereitstehen.','BCM22301','BCM22301-8.3.4.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.c','R-R3-0125','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0126','R3-2026-07','Berücksichtigen Sie bei den Ressourcenanforderungen die benötigte Ausrüstung und Verbrauchsmaterialien nicht, fehlen im Notfall Werkzeuge und Nachschub. Selbst gut geplante Abläufe kommen zum Stillstand, wenn ein einfaches, aber unverzichtbares Material nicht verfügbar ist und die priorisierten Aktivitäten unterbricht.','BCM22301','BCM22301-8.3.4.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.d','R-R3-0126','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0127','R3-2026-07','Wenn Sie die benötigten IKT-Systeme nicht berücksichtigen, fehlt Ihren priorisierten Aktivitäten die technische Grundlage. Fallen Anwendungen, Netze oder Daten aus, ohne dass Ersatz oder Wiederanlauf eingeplant ist, steht ein Großteil Ihrer Leistungserbringung still und lässt sich nicht rechtzeitig wiederherstellen.','BCM22301','BCM22301-8.3.4.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.e','R-R3-0127','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0128','R3-2026-07','Berücksichtigen Sie bei den Ressourcenanforderungen Transport und Logistik nicht, unterbrechen Sie versteckte, aber wesentliche Ketten. Können Personal, Material oder Ausrüstung im Ernstfall nicht dorthin gelangen, wo sie gebraucht werden, verzögert sich der Wiederanlauf trotz ansonsten vollständiger Vorbereitung.','BCM22301','BCM22301-8.3.4.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.f','R-R3-0128','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0129','R3-2026-07','Wenn Sie bei den Ressourcenanforderungen die benötigten Finanzmittel nicht berücksichtigen, fehlt im Ernstfall das Geld für Sofortmaßnahmen. Beschaffungen, Dienstleister und Überstunden lassen sich nicht kurzfristig finanzieren, sodass Ihre Continuity-Lösungen an fehlender Liquidität scheitern und der Wiederanlauf stockt.','BCM22301','BCM22301-8.3.4.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.g','R-R3-0129','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0130','R3-2026-07','Berücksichtigen Sie die benötigten Partner und Lieferanten nicht, verlassen Sie sich im Ernstfall auf externe Beiträge, die nicht abgesichert sind. Fällt ein Schlüssellieferant aus oder ist nicht verfügbar, fehlt ein unverzichtbarer Baustein Ihrer Lösung, und die Wiederaufnahme Ihrer Aktivitäten gerät ins Stocken.','BCM22301','BCM22301-8.3.4.h') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.4.h','R-R3-0130','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0131','R3-2026-07','Wenn Sie die ausgewählten Continuity-Lösungen nicht implementieren und pflegen, sodass sie bei Bedarf aktivierbar sind, existieren sie nur auf dem Papier. Im Ernstfall stellen Sie fest, dass Lösungen veraltet, nicht eingerichtet oder untauglich sind, und stehen ohne einsatzbereite Wiederanlaufmaßnahmen da.','BCM22301','BCM22301-8.3.5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.3.5','R-R3-0131','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0132','R3-2026-07','Sind Ihre Verfahren hinsichtlich der unmittelbaren Sofortschritte während einer Störung nicht konkret, verlieren Ihre Teams in der kritischen Anfangsphase wertvolle Zeit. Unklare oder fehlende Handlungsanweisungen führen zu Zögern, Fehlentscheidungen und unkoordiniertem Vorgehen, wodurch sich der Schaden ausweitet, bevor die Reaktion überhaupt greift.','BCM22301','BCM22301-8.4.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.a','R-R3-0132','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0133','R3-2026-07','Werden die Pläne im Ernstfall nicht aktiv genutzt, um die Business-Continuity-Lösungen tatsächlich in Gang zu setzen, verpuffen alle Vorbereitungen im entscheidenden Moment. Ihre Organisation reagiert dann ungeordnet und verzögert, wodurch sich Ausfallzeiten verlängern und die Erfüllung Ihrer kommunalen Pflichtaufgaben gegenüber den Bürgern gefährdet wird.','BCM22301','BCM22301-8.4.1.activate') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.activate','R-R3-0133','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0134','R3-2026-07','Sind Ihre Verfahren zu starr und nicht an wechselnde interne wie externe Störungsbedingungen anpassbar, laufen sie bei realen, unvorhergesehenen Lagen ins Leere. Sie werden gezwungen, unter Druck zu improvisieren, was Fehlentscheidungen begünstigt und die Wiederherstellung kritischer Dienste erheblich verzögert.','BCM22301','BCM22301-8.4.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.b','R-R3-0134','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0135','R3-2026-07','Konzentrieren sich Ihre Verfahren nicht auf die Auswirkungen von Vorfällen, die zu einer Störung führen können, bekämpfen Sie Symptome statt Folgen. Dadurch priorisieren Sie falsch, binden Ressourcen an Nebenschauplätzen und lassen die wirklich geschäftskritischen Ausfälle ungesteuert eskalieren.','BCM22301','BCM22301-8.4.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.c','R-R3-0135','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0136','R3-2026-07','Sind Ihre Verfahren nicht wirksam, um Auswirkungen durch geeignete Lösungen zu minimieren, bleibt der Schaden trotz vorhandener Pläne unverändert hoch. Sie tragen dann Kosten, Reputationsverluste und Dienstunterbrechungen, obwohl der Aufwand für das Business-Continuity-Management eigentlich genau dies verhindern sollte.','BCM22301','BCM22301-8.4.1.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.d','R-R3-0136','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0137','R3-2026-07','Identifizieren und dokumentieren Sie Ihre Business-Continuity-Pläne nicht auf Basis der gewählten Strategien und Lösungen, bleibt Wissen nur in einzelnen Köpfen. Fallen diese Personen aus, fehlt jede belastbare Handlungsgrundlage, und Ihre Reaktion auf eine Störung wird unkoordiniert und nicht nachvollziehbar.','BCM22301','BCM22301-8.4.1.document') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.document','R-R3-0137','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0138','R3-2026-07','Weisen Ihre Verfahren den enthaltenen Aufgaben keine klaren Rollen und Verantwortlichkeiten zu, fühlt sich im Ernstfall niemand zuständig oder mehrere handeln widersprüchlich. Wichtige Schritte bleiben liegen, die Reaktion verzögert sich, und die geordnete Bewältigung der Störung gerät ernsthaft ins Wanken.','BCM22301','BCM22301-8.4.1.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.e','R-R3-0138','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0139','R3-2026-07','Stellen Sie keine Pläne und Verfahren bereit, um Ihre Organisation während einer Störung zu steuern, fehlt in der Krise jeder verbindliche Handlungsrahmen. Entscheidungen werden dann ad hoc und uneinheitlich getroffen, wodurch sich Schäden ausweiten und die Fortführung Ihrer kritischen Leistungen ernsthaft gefährdet ist.','BCM22301','BCM22301-8.4.1.plans') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.1.plans','R-R3-0139','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0140','R3-2026-07','Implementieren und pflegen Sie keine Struktur mit klar benannten Teams für die Störungsreaktion, ist im Ernstfall unklar, wer die Bewältigung übernimmt. Die Reaktion startet verspätet und unkoordiniert, wodurch wertvolle Zeit verloren geht und sich die Auswirkungen der Störung unnötig verschärfen.','BCM22301','BCM22301-8.4.2.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.1','R-R3-0140','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0141','R3-2026-07','Sind die Rollen, Verantwortlichkeiten und Beziehungen zwischen Ihren Teams nicht klar festgelegt, entstehen im Krisenfall Zuständigkeitslücken und Doppelarbeit. Aufgaben bleiben unerledigt oder werden mehrfach ausgeführt, Abstimmung scheitert, und die gemeinsame Reaktion auf die Störung verliert an Schlagkraft und Tempo.','BCM22301','BCM22301-8.4.2.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.2','R-R3-0141','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0142','R3-2026-07','Sind Ihre Teams nicht gemeinsam kompetent, Art, Ausmaß und potenzielle Auswirkung einer Störung zu beurteilen, fehlt die Grundlage für richtige Entscheidungen. Sie schätzen die Lage falsch ein, reagieren über- oder untertrieben und riskieren, dass geschäftskritische Folgen zu spät erkannt werden.','BCM22301','BCM22301-8.4.2.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.a','R-R3-0142','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0143','R3-2026-07','Können Ihre Teams die Auswirkung nicht gegen vordefinierte Schwellenwerte beurteilen, fehlt ein objektiver Auslöser für die formale Reaktion. Sie eskalieren dann entweder zu früh und binden unnötig Ressourcen oder zu spät, sodass sich die Störung ungebremst zu einer echten Krise ausweitet.','BCM22301','BCM22301-8.4.2.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.b','R-R3-0143','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0144','R3-2026-07','Sind Ihre Teams nicht in der Lage, eine angemessene Business-Continuity-Reaktion zu aktivieren, bleiben vorhandene Lösungen im Ernstfall ungenutzt. Die Wiederherstellung Ihrer priorisierten Aktivitäten verzögert sich erheblich, und die Vorbereitungen entfalten trotz Investition keinerlei schützende Wirkung für Ihren Betrieb.','BCM22301','BCM22301-8.4.2.3.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.c','R-R3-0144','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0145','R3-2026-07','Sind Ihre Teams nicht kompetent, die zu ergreifenden Maßnahmen zu planen, handeln sie in der Krise planlos und reaktiv. Schritte werden ohne Reihenfolge und Ziel ausgeführt, Ressourcen falsch eingesetzt und die Bewältigung der Störung zieht sich unnötig in die Länge.','BCM22301','BCM22301-8.4.2.3.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.d','R-R3-0145','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0146','R3-2026-07','Können Ihre Teams keine Prioritäten mit dem Schutz von Leben an erster Stelle setzen, drohen im Ernstfall gravierende Fehlentscheidungen. Sie riskieren, dass Menschen gefährdet werden, während zweitrangige Aufgaben Ressourcen binden, was neben dem Schaden auch erhebliche rechtliche Verantwortung nach sich zieht.','BCM22301','BCM22301-8.4.2.3.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.e','R-R3-0146','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0147','R3-2026-07','Sind Ihre Teams nicht in der Lage, Auswirkungen der Störung und die eigene Reaktion zu überwachen, agieren sie blind. Fehlentwicklungen und wirkungslose Maßnahmen bleiben unbemerkt, Sie können nicht rechtzeitig nachsteuern, und die Störung entwickelt sich unkontrolliert zu Ihrem Nachteil weiter.','BCM22301','BCM22301-8.4.2.3.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.f','R-R3-0147','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0148','R3-2026-07','Sind Ihre Teams nicht kompetent, die Business-Continuity-Lösungen zu aktivieren, bleiben Ausweichverfahren und Notbetrieb im Ernstfall untätig. Ihre priorisierten Aktivitäten kommen zum Erliegen, die Ausfallzeiten überschreiten die tolerierbaren Grenzen, und der eigentliche Zweck Ihrer Vorsorge verfehlt sein Ziel.','BCM22301','BCM22301-8.4.2.3.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.g','R-R3-0148','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0149','R3-2026-07','Sind Ihre Teams nicht kompetent, mit interessierten Parteien, Behörden und Medien zu kommunizieren, entsteht in der Krise ein Informationsvakuum. Gerüchte, Fehlinformationen und Verunsicherung breiten sich aus, Ihre Reputation leidet, und die Zusammenarbeit mit Aufsichts- und Einsatzstellen wird empfindlich gestört.','BCM22301','BCM22301-8.4.2.3.h') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.3.h','R-R3-0149','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0150','R3-2026-07','Gibt es für Ihre Teams kein benanntes Personal samt Vertretern mit ausreichender Verantwortung, Befugnis und Kompetenz, fällt die Reaktion bei Abwesenheit oder Ausfall Einzelner zusammen. Entscheidungen können nicht getroffen werden, Handlungsketten reißen ab und die Störungsbewältigung stockt genau dann, wenn sie am dringendsten gebraucht wird.','BCM22301','BCM22301-8.4.2.4.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.4.a','R-R3-0150','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0151','R3-2026-07','Fehlen Ihren Teams dokumentierte Verfahren zur Anleitung ihres Handelns bei Aktivierung, Betrieb, Koordination und Kommunikation, bleibt die Reaktion vom Erfahrungswissen Einzelner abhängig. Unter Stress werden Schritte vergessen oder falsch ausgeführt, was die Reaktion inkonsistent, fehleranfällig und schwer nachvollziehbar macht.','BCM22301','BCM22301-8.4.2.4.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.2.4.b','R-R3-0151','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0152','R3-2026-07','Dokumentieren und pflegen Sie keine Verfahren für die interne und externe Kommunikation mit klaren Angaben zu Was, Wann, mit Wem und Wie, kommuniziert im Ernstfall jeder anders oder gar nicht. Wichtige Adressaten werden übersehen, Botschaften widersprechen sich und das Vertrauen in Ihre Organisation nimmt Schaden.','BCM22301','BCM22301-8.4.3.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.1.a','R-R3-0152','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0153','R3-2026-07','Fehlen Verfahren zum Empfangen, Dokumentieren und Beantworten von Kommunikation interessierter Parteien einschließlich nationaler oder regionaler Stellen, gehen Anfragen und Warnungen unter. Sie verpassen behördliche Hinweise, verletzen möglicherweise Meldepflichten und wirken nach außen unorganisiert und wenig verlässlich.','BCM22301','BCM22301-8.4.3.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.1.b','R-R3-0153','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0154','R3-2026-07','Stellen Sie die Verfügbarkeit der Kommunikationsmittel während einer Störung nicht sicher, brechen genau dann die Verbindungen weg, wenn Sie sie am dringendsten brauchen. Teams können sich nicht abstimmen, Warnungen erreichen niemanden, und die gesamte Reaktion zerfällt in unkoordinierte Einzelmaßnahmen.','BCM22301','BCM22301-8.4.3.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.1.c','R-R3-0154','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0155','R3-2026-07','Fehlen Verfahren für eine strukturierte Kommunikation mit Notfallhelfern, verläuft die Zusammenarbeit mit Feuerwehr, Rettungsdiensten und Katastrophenschutz im Ernstfall chaotisch. Informationen gehen verloren oder verzögern sich, Einsätze werden behindert und die Sicherheit von Menschen sowie Ihrer Einrichtungen ist gefährdet.','BCM22301','BCM22301-8.4.3.1.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.1.d','R-R3-0155','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0156','R3-2026-07','Fehlen Verfahren zur Medienreaktion nach einem Vorfall einschließlich einer Kommunikationsstrategie, überlassen Sie die öffentliche Deutung anderen. Unabgestimmte oder ausbleibende Aussagen befeuern Spekulationen und Kritik, und ein anfangs beherrschbarer Vorfall entwickelt sich zu einem nachhaltigen Reputationsschaden für Ihre Kommune.','BCM22301','BCM22301-8.4.3.1.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.1.e','R-R3-0156','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0157','R3-2026-07','Zeichnen Sie Details der Störung, der ergriffenen Maßnahmen und getroffenen Entscheidungen nicht auf, fehlt später jeder belastbare Nachweis. Sie können den Verlauf nicht rekonstruieren, nicht aus Fehlern lernen und geraten bei Prüfungen, Haftungsfragen oder Aufsichtsverfahren in erhebliche Beweisnot.','BCM22301','BCM22301-8.4.3.1.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.1.f','R-R3-0157','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0158','R3-2026-07','Alarmieren Sie interessierte Parteien nicht, die von einer tatsächlichen oder bevorstehenden Störung betroffen sein können, bleiben diese ahnungslos und ungeschützt. Sie können keine Vorkehrungen treffen, erleiden vermeidbare Schäden und verlieren das Vertrauen in Ihre Organisation, weil Warnungen ausblieben.','BCM22301','BCM22301-8.4.3.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.2.a','R-R3-0158','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0159','R3-2026-07','Stellen Sie bei mehreren reagierenden Organisationen keine angemessene Koordination und Kommunikation sicher, arbeiten die Beteiligten gegeneinander statt miteinander. Maßnahmen überschneiden sich oder widersprechen sich, Ressourcen werden verschwendet und die gemeinsame Bewältigung der Störung wird deutlich langsamer und wirkungsärmer.','BCM22301','BCM22301-8.4.3.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.2.b','R-R3-0159','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0160','R3-2026-07','Üben Sie Ihre Warn- und Kommunikationsverfahren nicht als Teil des Übungsprogramms, zeigen sich deren Schwächen erst im echten Ernstfall. Kontaktlisten sind veraltet, Zuständigkeiten unklar und Abläufe ungeübt, sodass die Kommunikation genau dann versagt, wenn schnelle und korrekte Information entscheidend ist.','BCM22301','BCM22301-8.4.3.2.exercise') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.3.2.exercise','R-R3-0160','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0161','R3-2026-07','Dokumentieren und pflegen Sie Ihre Business-Continuity-Pläne und -Verfahren nicht, veralten die Inhalte unbemerkt und spiegeln nicht mehr die reale Organisation wider. Im Ernstfall greifen Sie auf falsche Kontakte, überholte Abläufe und ungültige Annahmen zurück, was die Reaktion untergräbt.','BCM22301','BCM22301-8.4.4.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.1','R-R3-0161','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0162','R3-2026-07','Liefern Ihre Business-Continuity-Pläne keine klare Anleitung und Information für Reaktion und Wiederherstellung, stehen Ihre Teams im Ernstfall ohne Orientierung da. Sie müssen unter Zeitdruck raten, treffen inkonsistente Entscheidungen und verzögern die Rückkehr zum Normalbetrieb erheblich.','BCM22301','BCM22301-8.4.4.1.guidance') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.1.guidance','R-R3-0162','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0163','R3-2026-07','Enthalten Ihre Pläne keine Details zu den Maßnahmen, mit denen die Teams priorisierte Aktivitäten innerhalb vorbestimmter Zeitrahmen fortführen, bleibt unklar, was bis wann zu leisten ist. Kritische Leistungen fallen länger aus als tolerierbar, und die vereinbarten Wiederanlaufziele werden regelmäßig verfehlt.','BCM22301','BCM22301-8.4.4.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.2.a','R-R3-0163','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0164','R3-2026-07','Fehlt in Ihren Plänen der Verweis auf die vordefinierten Schwellenwerte und der Prozess zur Aktivierung der Reaktion, bleibt der Auslösemoment unklar. Sie starten die Reaktion zu spät oder gar nicht, wodurch sich eine anfangs beherrschbare Störung ungebremst zu einer schweren Krise entwickeln kann.','BCM22301','BCM22301-8.4.4.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.2.b','R-R3-0164','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0165','R3-2026-07','Enthalten Ihre Pläne keine Verfahren, die die Lieferung von Produkten und Dienstleistungen mit der vereinbarten Kapazität ermöglichen, können Sie im Notbetrieb die zugesagten Mindestleistungen nicht halten. Bürger und Partner erhalten keine ausreichende Versorgung, und vertragliche wie gesetzliche Verpflichtungen werden verletzt.','BCM22301','BCM22301-8.4.4.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.2.c','R-R3-0165','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0166','R3-2026-07','Regeln Ihre Pläne den Umgang mit den unmittelbaren Folgen einer Störung nicht, bleiben Wohlergehen von Personen und Schadensbegrenzung dem Zufall überlassen. In den kritischen ersten Minuten fehlt jede Orientierung, wodurch sich Schäden ausweiten und Menschen unnötig gefährdet werden können.','BCM22301','BCM22301-8.4.4.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.2.d','R-R3-0166','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0167','R3-2026-07','Enthält ein Plan nicht seinen Zweck, Umfang und seine Ziele, wissen die Anwender nicht, wofür er gilt und wann er greift. Der Plan wird falsch oder gar nicht eingesetzt, deckt Lücken auf oder überschneidet sich mit anderen und stiftet im Ernstfall Verwirrung statt Klarheit.','BCM22301','BCM22301-8.4.4.3.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.a','R-R3-0167','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0168','R3-2026-07','Ist ein Plan nicht zu der Zeit und an dem Ort nutzbar und verfügbar, an dem er gebraucht wird, nützt selbst der beste Inhalt nichts. Fällt bei einem IT-Ausfall auch der Zugriff auf den Plan aus, stehen Ihre Teams im entscheidenden Moment ohne jede Handlungsgrundlage da.','BCM22301','BCM22301-8.4.4.3.available') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.available','R-R3-0168','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0169','R3-2026-07','Enthält ein Plan nicht die Rollen und Verantwortlichkeiten des umsetzenden Teams, ist im Ernstfall unklar, wer welche Aufgabe übernimmt. Wichtige Schritte bleiben liegen oder werden doppelt ausgeführt, die Umsetzung stockt und die Wirksamkeit des gesamten Plans steht damit auf dem Spiel.','BCM22301','BCM22301-8.4.4.3.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.b','R-R3-0169','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0170','R3-2026-07','Enthält ein Plan nicht die konkreten Maßnahmen zur Umsetzung der Lösungen, bleibt er eine wirkungslose Absichtserklärung. Ihre Teams wissen nicht, welche Schritte tatsächlich auszuführen sind, verlieren wertvolle Zeit mit Rückfragen und Improvisation und bringen die vorgesehenen Lösungen nicht rechtzeitig zum Tragen.','BCM22301','BCM22301-8.4.4.3.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.c','R-R3-0170','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0171','R3-2026-07','Fehlen einem Plan die unterstützenden Informationen zu Aktivierung, Betrieb, Koordination und Kommunikation der Reaktion, stockt die Umsetzung an entscheidenden Stellen. Aktivierungskriterien sind unklar, Kontaktdaten fehlen und Abläufe hängen in der Luft, sodass sich die gesamte Reaktion verzögert und lückenhaft bleibt.','BCM22301','BCM22301-8.4.4.3.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.d','R-R3-0171','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0172','R3-2026-07','Enthält ein Plan nicht die internen und externen wechselseitigen Abhängigkeiten, übersehen Sie im Ernstfall kritische Verbindungen. Der Ausfall eines Dienstleisters oder eines vorgelagerten Prozesses trifft Sie unvorbereitet, und Ihre Wiederherstellung scheitert an nicht bedachten Abhängigkeiten, die Sie hätten einplanen müssen.','BCM22301','BCM22301-8.4.4.3.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.e','R-R3-0172','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0173','R3-2026-07','Enthält ein Plan nicht die Ressourcenanforderungen, ist im Ernstfall unklar, welches Personal, welche Technik und welche Mittel benötigt werden. Sie stellen fest, dass Entscheidendes fehlt, wenn es bereits zu spät ist, und die Umsetzung der Lösungen scheitert an nicht vorgehaltenen Ressourcen.','BCM22301','BCM22301-8.4.4.3.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.f','R-R3-0173','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0174','R3-2026-07','Enthält ein Plan nicht die Berichtsanforderungen, fließen im Krisenfall keine strukturierten Informationen an Leitung und interessierte Parteien. Entscheidungen werden auf unvollständiger Grundlage getroffen, gesetzliche Meldepflichten möglicherweise verletzt und die Nachvollziehbarkeit des Krisenverlaufs geht verloren.','BCM22301','BCM22301-8.4.4.3.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.g','R-R3-0174','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0175','R3-2026-07','Enthält ein Plan keinen Prozess zur geordneten Beendigung, bleibt nach der Störung unklar, wann und wie in den Normalbetrieb zurückgekehrt wird. Notmaßnahmen laufen unnötig weiter, Ressourcen bleiben gebunden und ungelöste Restrisiken werden übersehen, wodurch neue Störungen begünstigt werden.','BCM22301','BCM22301-8.4.4.3.h') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.4.4.3.h','R-R3-0175','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0176','R3-2026-07','Implementieren und pflegen Sie kein Programm zum Üben und Testen, bleibt die Wirksamkeit Ihrer Business-Continuity-Strategien und -Lösungen ungeprüft. Verborgene Lücken, veraltete Annahmen und untrainierte Abläufe zeigen sich erst im echten Ernstfall, wenn ein Scheitern die schwerwiegendsten Folgen für Ihre Organisation hat.','BCM22301','BCM22301-8.5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5','R-R3-0176','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0177','R3-2026-07','Wenn Sie Übungen und Tests nicht an Ihren Business-Continuity-Zielen ausrichten, prüfen Sie letztlich Dinge, die im Ernstfall nicht entscheidend sind. Sie gewinnen ein trügerisches Sicherheitsgefühl, während zentrale Wiederherstellungsziele ungeprüft bleiben. Im tatsächlichen Störfall stellen Sie dann fest, dass Ihre Fähigkeiten die geforderten Zeit- und Leistungsvorgaben nicht erfüllen.','BCM22301','BCM22301-8.5.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.a','R-R3-0177','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0178','R3-2026-07','Wenn Sie aus den Ergebnissen Ihrer Übungen und Tests keine Änderungen und Verbesserungen ableiten, bleiben erkannte Schwachstellen dauerhaft bestehen. Sie wiederholen dieselben Fehler im nächsten Ernstfall und verschwenden den gesamten Aufwand des Testens. So verpasst Ihre Organisation die Chance, ihre Widerstandsfähigkeit gezielt und nachweisbar zu stärken.','BCM22301','BCM22301-8.5.act') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.act','R-R3-0178','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0179','R3-2026-07','Wenn Ihre Übungen nicht auf durchdachten Szenarien mit klaren Zielen beruhen, liefern sie beliebige und wenig aussagekräftige Ergebnisse. Sie können nicht belastbar beurteilen, ob Ihre Pläne wirklich tragfähig sind. Realistische Störungsverläufe bleiben ungeprüft, sodass gefährliche Lücken erst im echten Notfall sichtbar werden.','BCM22301','BCM22301-8.5.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.b','R-R3-0179','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0180','R3-2026-07','Wenn Ihre Übungen bei den beteiligten Personen kein Teamwork, keine Kompetenz und kein Selbstvertrauen aufbauen, agieren diese im Ernstfall unsicher und unkoordiniert. Rollen und Abläufe sind ungeübt, sodass wertvolle Zeit durch Zögern und Missverständnisse verloren geht. Die Bewältigung der Störung verzögert sich und der Schaden für Ihre Organisation wächst.','BCM22301','BCM22301-8.5.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.c','R-R3-0180','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0181','R3-2026-07','Wenn Sie Ihre Strategien und Lösungen nicht über die Zeit hinweg durch Übungen validieren, verlassen Sie sich auf Annahmen, die längst überholt sein können. Veränderte Prozesse, Systeme oder Abhängigkeiten machen Ihre Notfallkonzepte womöglich unwirksam. Im Ernstfall greifen Ihre Maßnahmen dann nicht wie erwartet und die Fortführung kritischer Tätigkeiten ist gefährdet.','BCM22301','BCM22301-8.5.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.d','R-R3-0181','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0182','R3-2026-07','Wenn Ihre Übungen keine formalisierten Nachberichte mit Ergebnissen, Empfehlungen und Maßnahmen erzeugen, gehen wichtige Erkenntnisse verloren. Verbesserungen werden nicht nachvollziehbar dokumentiert und niemand ist für ihre Umsetzung verantwortlich. So bleibt Ihr Business-Continuity-System statisch und Sie können gegenüber Prüfern keinen belastbaren Nachweis erbringen.','BCM22301','BCM22301-8.5.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.e','R-R3-0182','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0183','R3-2026-07','Wenn Sie Ihre Übungen und Tests nicht im Sinne kontinuierlicher Verbesserung überprüfen, verkommen sie zu reiner Routine ohne Lerneffekt. Sie erkennen nicht, ob Ihr Übungsprogramm selbst noch geeignet und wirksam ist. Ihr Business-Continuity-Management entwickelt sich nicht weiter und verliert im Laufe der Zeit an Aussagekraft und Wirksamkeit.','BCM22301','BCM22301-8.5.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.f','R-R3-0183','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0184','R3-2026-07','Wenn Sie Übungen nicht in geplanten Abständen und bei wesentlichen Änderungen durchführen, veralten Ihre Notfallfähigkeiten unbemerkt. Neue Risiken, Systeme oder Organisationsstrukturen bleiben ungetestet und Ihr Personal verliert die Routine. Im Ernstfall stellen Sie fest, dass Ihre Pläne nicht mehr zur aktuellen Realität passen.','BCM22301','BCM22301-8.5.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.5.g','R-R3-0184','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0185','R3-2026-07','Wenn Sie die Eignung, Angemessenheit und Wirksamkeit Ihrer Analysen, Strategien und Pläne nicht bewerten, erkennen Sie deren Schwächen nicht. Veraltete oder fehlerhafte Annahmen bleiben unentdeckt und untergraben Ihr gesamtes Business-Continuity-System. Im Krisenfall verlassen Sie sich dann auf Konzepte, die den tatsächlichen Anforderungen nicht standhalten.','BCM22301','BCM22301-8.6.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.6.a','R-R3-0185','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0186','R3-2026-07','Wenn Sie Bewertungen nicht durch Reviews, Analysen, Übungen, Tests und Nachberichte absichern, beruhen Ihre Einschätzungen auf bloßen Vermutungen. Ihnen fehlt die belastbare Grundlage, um über die Tauglichkeit Ihrer Vorkehrungen zu urteilen. Fehlentscheidungen bleiben unbemerkt und Ihre Widerstandsfähigkeit wird systematisch überschätzt.','BCM22301','BCM22301-8.6.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.6.b','R-R3-0186','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0187','R3-2026-07','Wenn Sie die Business-Continuity-Fähigkeiten Ihrer Partner und Lieferanten nicht bewerten, entstehen unkontrollierte Abhängigkeiten in Ihrer Lieferkette. Ein Ausfall eines kritischen Dienstleisters kann Ihre eigenen Leistungen zum Erliegen bringen, obwohl Ihre internen Pläne intakt sind. So gefährden fremde Schwachstellen Ihre gesamte Fortführungsfähigkeit.','BCM22301','BCM22301-8.6.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.6.c','R-R3-0187','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0188','R3-2026-07','Wenn Sie Bewertungen nicht in geplanten Abständen, nach Vorfällen und bei wesentlichen Änderungen durchführen, arbeiten Sie mit einem überholten Lagebild. Neue Risiken und veränderte Rahmenbedingungen fließen nicht in Ihre Vorkehrungen ein. Dadurch verlassen Sie sich im Ernstfall auf Erkenntnisse, die die aktuelle Realität nicht mehr abbilden.','BCM22301','BCM22301-8.6.conducted') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.6.conducted','R-R3-0188','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0189','R3-2026-07','Wenn Sie die Einhaltung gesetzlicher, behördlicher und branchenüblicher Anforderungen sowie Ihrer eigenen Vorgaben nicht bewerten, riskieren Sie unbemerkte Compliance-Verstöße. Es drohen Bußgelder, Haftungsfolgen und Reputationsschäden. Zudem können sich Abweichungen von bewährten Praktiken zu ernsten Schwachstellen in Ihrer Notfallvorsorge auswachsen.','BCM22301','BCM22301-8.6.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.6.d','R-R3-0189','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0190','R3-2026-07','Wenn Sie Dokumentation und Verfahren nicht zeitnah aktualisieren, arbeiten Ihre Mitarbeitenden im Ernstfall mit veralteten Anweisungen. Falsche Kontaktdaten, überholte Abläufe oder ungültige Zuständigkeiten führen zu Verzögerungen und Fehlern. So untergraben Sie die Wirksamkeit Ihrer gesamten Notfallplanung genau im entscheidenden Moment.','BCM22301','BCM22301-8.6.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-8.6.e','R-R3-0190','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0191','R3-2026-07','Wenn Sie nicht festlegen, was im BCMS überwacht und gemessen werden muss, können Sie dessen Leistung und Wirksamkeit nicht beurteilen. Sie steuern Ihr System im Blindflug und erkennen Fehlentwicklungen zu spät. Ohne klare Messgrößen fehlt Ihnen die Grundlage für fundierte Entscheidungen und nachweisbare Verbesserungen.','BCM22301','BCM22301-9.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.1.a','R-R3-0191','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0192','R3-2026-07','Wenn Sie keine geeigneten Methoden für Überwachung, Messung, Analyse und Bewertung festlegen, sind Ihre Ergebnisse weder gültig noch nachvollziehbar. Sie ziehen möglicherweise falsche Schlüsse aus verzerrten oder nicht vergleichbaren Daten. So gefährden Sie die Verlässlichkeit Ihrer gesamten Leistungsbewertung und treffen Entscheidungen auf unsicherer Basis.','BCM22301','BCM22301-9.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.1.b','R-R3-0192','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0193','R3-2026-07','Wenn nicht festgelegt ist, wann und durch wen Überwachung und Messung erfolgen, unterbleiben diese Tätigkeiten in der Praxis oder geschehen zufällig. Verantwortlichkeiten sind unklar und niemand fühlt sich zuständig. So entstehen Lücken in der Überwachung, wodurch Schwachstellen Ihres BCMS unentdeckt bleiben.','BCM22301','BCM22301-9.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.1.c','R-R3-0193','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0194','R3-2026-07','Wenn nicht festgelegt ist, wann und durch wen Ergebnisse analysiert und bewertet werden, bleiben erhobene Daten ungenutzt liegen. Erkenntnisse werden nicht in Maßnahmen übersetzt und wichtige Warnsignale übersehen. So verpufft der Aufwand der Datenerhebung, ohne dass Ihr Business-Continuity-System davon profitiert.','BCM22301','BCM22301-9.1.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.1.d','R-R3-0194','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0195','R3-2026-07','Wenn Sie keine angemessene dokumentierte Information als Nachweis über Ihre Überwachungs- und Messergebnisse aufbewahren, können Sie Ihre Bemühungen nicht belegen. Bei Audits, Vorfällen oder rechtlichen Auseinandersetzungen fehlt Ihnen die Beweisgrundlage. Zudem gehen wertvolle Vergleichsdaten verloren, die Sie für Trendanalysen und Verbesserungen benötigen.','BCM22301','BCM22301-9.1.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.1.e','R-R3-0195','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0196','R3-2026-07','Wenn Sie die Leistung und Gesamtwirksamkeit Ihres BCMS nicht bewerten, wissen Sie nicht, ob Ihr System die gesetzten Ziele tatsächlich erreicht. Schwächen und Fehlentwicklungen bleiben verborgen, bis ein realer Vorfall sie schmerzhaft offenlegt. So fehlt Ihnen die Grundlage, um Ressourcen gezielt und wirksam einzusetzen.','BCM22301','BCM22301-9.1.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.1.f','R-R3-0196','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0197','R3-2026-07','Wenn Sie keine internen Audits in geplanten Abständen durchführen, fehlt Ihnen eine unabhängige Rückmeldung über Konformität und Wirksamkeit Ihres BCMS. Abweichungen und Schwachstellen bleiben unentdeckt und verfestigen sich mit der Zeit. So erkennen Sie erst im Ernstfall, dass Ihr System nicht wie vorgesehen umgesetzt und aufrechterhalten wird.','BCM22301','BCM22301-9.2.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.1','R-R3-0197','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0198','R3-2026-07','Wenn Ihre internen Audits nicht prüfen, ob das BCMS Ihre eigenen Anforderungen erfüllt, kann Ihr System unbemerkt von den selbst gesetzten Vorgaben abweichen. Interne Vorgaben verlieren an Verbindlichkeit und werden nicht durchgängig gelebt. So entsteht eine Kluft zwischen Anspruch und Wirklichkeit, die Ihre Notfallvorsorge schwächt.','BCM22301','BCM22301-9.2.1.a.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.1.a.1','R-R3-0198','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0199','R3-2026-07','Wenn Ihre internen Audits nicht prüfen, ob das BCMS die Anforderungen der ISO 22301 erfüllt, riskieren Sie unbemerkte Normabweichungen. Diese gefährden Ihre Zertifizierung und führen bei externen Prüfungen zu Beanstandungen. Zudem können strukturelle Lücken im System unentdeckt bleiben, die im Ernstfall Ihre Handlungsfähigkeit einschränken.','BCM22301','BCM22301-9.2.1.a.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.1.a.2','R-R3-0199','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0200','R3-2026-07','Wenn Ihre internen Audits nicht prüfen, ob das BCMS wirksam umgesetzt und aufrechterhalten wird, verlassen Sie sich auf ein System, das nur auf dem Papier existiert. Dokumentierte Verfahren werden in der Praxis womöglich gar nicht gelebt. Erst im Ernstfall zeigt sich dann, dass Ihre Vorkehrungen ins Leere greifen.','BCM22301','BCM22301-9.2.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.1.b','R-R3-0200','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0201','R3-2026-07','Wenn Sie kein Auditprogramm mit Häufigkeit, Methoden, Verantwortlichkeiten und Berichtswegen etablieren, verlaufen Ihre Audits planlos und lückenhaft. Wichtige Bereiche werden übersehen und Ergebnisse nicht systematisch verfolgt. So verlieren Ihre Prüfungen an Aussagekraft und Sie können deren ordnungsgemäße Durchführung nicht belegen.','BCM22301','BCM22301-9.2.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.2.a','R-R3-0201','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0202','R3-2026-07','Wenn Sie für einzelne Audits keine eindeutigen Kriterien und keinen klaren Umfang festlegen, bleibt unklar, wogegen und wie umfassend geprüft wird. Die Ergebnisse werden beliebig und schwer vergleichbar. So können relevante Bereiche unbeabsichtigt aus der Prüfung fallen und Schwachstellen unentdeckt bleiben.','BCM22301','BCM22301-9.2.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.2.b','R-R3-0202','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0203','R3-2026-07','Wenn Sie Auditoren nicht so auswählen, dass Objektivität und Unparteilichkeit gewährleistet sind, prüfen Personen womöglich ihre eigene Arbeit. Befangenheit führt zu geschönten Ergebnissen und verschwiegenen Mängeln. So verlieren Ihre Audits ihre Glaubwürdigkeit und liefern kein verlässliches Bild vom Zustand Ihres BCMS.','BCM22301','BCM22301-9.2.2.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.2.c','R-R3-0203','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0204','R3-2026-07','Wenn Auditergebnisse nicht an die zuständigen Führungskräfte berichtet werden, bleibt das Management über Schwachstellen im Unklaren. Notwendige Entscheidungen und Ressourcen zur Behebung unterbleiben. So versanden erkannte Mängel auf der Arbeitsebene, ohne dass wirksame Korrekturen eingeleitet werden.','BCM22301','BCM22301-9.2.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.2.d','R-R3-0204','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0205','R3-2026-07','Wenn Sie keine dokumentierte Information über die Umsetzung des Auditprogramms und die Auditergebnisse aufbewahren, können Sie Ihre Prüftätigkeit nicht nachweisen. Bei Zertifizierungen und Aufsichtskontrollen fehlt Ihnen der Beleg. Zudem geht die Nachverfolgbarkeit früherer Feststellungen verloren, sodass Sie wiederkehrende Probleme nicht erkennen.','BCM22301','BCM22301-9.2.2.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.2.e','R-R3-0205','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0206','R3-2026-07','Wenn Sie notwendige Korrekturmaßnahmen nicht ohne unangemessene Verzögerung ergreifen, bestehen festgestellte Nichtkonformitäten und ihre Ursachen unnötig lange fort. Bekannte Schwachstellen können in dieser Zeit zu realen Störungen führen. So untergraben Sie den Zweck des Audits, das gerade auf zeitnahe Verbesserung abzielt.','BCM22301','BCM22301-9.2.2.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.2.f','R-R3-0206','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0207','R3-2026-07','Wenn Folgemaßnahmen des Audits die Verifizierung der ergriffenen Maßnahmen und deren Berichterstattung nicht umfassen, wissen Sie nie, ob Korrekturen tatsächlich gewirkt haben. Vermeintlich behobene Mängel bestehen möglicherweise fort. So schließt sich der Verbesserungskreislauf nicht und dieselben Schwachstellen tauchen bei künftigen Prüfungen erneut auf.','BCM22301','BCM22301-9.2.2.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.2.2.g','R-R3-0207','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0208','R3-2026-07','Wenn die oberste Leitung das BCMS nicht in geplanten Abständen überprüft, fehlt dem System die strategische Steuerung von höchster Stelle. Fortdauernde Eignung, Angemessenheit und Wirksamkeit werden nicht sichergestellt. So driftet Ihr Business-Continuity-Management ab und verliert den Rückhalt und die Ressourcen, die nur das Top-Management sichern kann.','BCM22301','BCM22301-9.3.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.1','R-R3-0208','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0209','R3-2026-07','Wenn Ihre Managementbewertung den Status von Maßnahmen aus früheren Bewertungen nicht berücksichtigt, verlieren Sie die Kontrolle über deren Umsetzung. Beschlossene Verbesserungen versanden unbemerkt und offene Punkte bleiben liegen. So wiederholen sich Diskussionen ergebnislos und Ihr System entwickelt sich trotz erkannten Handlungsbedarfs nicht weiter.','BCM22301','BCM22301-9.3.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.a','R-R3-0209','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0210','R3-2026-07','Wenn Ihre Managementbewertung Änderungen bei externen und internen Themen nicht berücksichtigt, bleibt Ihr BCMS auf einem überholten Kontext stehen. Neue rechtliche, technische oder organisatorische Entwicklungen fließen nicht ein. So passen Ihre Vorkehrungen nicht mehr zur tatsächlichen Risikolage und werden im Ernstfall wirkungslos.','BCM22301','BCM22301-9.3.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.b','R-R3-0210','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0211','R3-2026-07','Wenn Ihre Managementbewertung Informationen zur BCMS-Leistung samt Trends bei Nichtkonformitäten und Korrekturmaßnahmen nicht berücksichtigt, erkennt die Leitung keine systematischen Schwächen. Wiederkehrende Probleme bleiben unadressiert. So treffen Sie strategische Entscheidungen ohne fundiertes Bild vom tatsächlichen Zustand Ihres Systems.','BCM22301','BCM22301-9.3.2.c.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.c.1','R-R3-0211','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0212','R3-2026-07','Wenn Ihre Managementbewertung Trends aus Überwachung und Messung nicht berücksichtigt, entgeht der Leitung die Entwicklung wichtiger Kennzahlen über die Zeit. Schleichende Verschlechterungen bleiben unbemerkt, bis sie kritisch werden. So verlieren Sie die Möglichkeit, frühzeitig und vorausschauend gegenzusteuern.','BCM22301','BCM22301-9.3.2.c.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.c.2','R-R3-0212','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0213','R3-2026-07','Wenn Ihre Managementbewertung die Trends aus internen Audits nicht berücksichtigt, bleiben systematische Prüffeststellungen ohne Konsequenz auf Leitungsebene. Wiederkehrende Abweichungen werden nicht strategisch aufgegriffen. So verpufft der Wert Ihrer Audits und dieselben Schwachstellen bestehen über Jahre hinweg fort.','BCM22301','BCM22301-9.3.2.c.3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.c.3','R-R3-0213','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0214','R3-2026-07','Wenn Ihre Managementbewertung Rückmeldungen interessierter Parteien nicht berücksichtigt, entgehen Ihnen wichtige Erwartungen von Kunden, Behörden, Partnern und Mitarbeitenden. Ihr BCMS orientiert sich dann an internen Annahmen statt an realen Anforderungen. So riskieren Sie, an den Bedürfnissen zentraler Stakeholder vorbeizuplanen und deren Vertrauen zu verlieren.','BCM22301','BCM22301-9.3.2.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.d','R-R3-0214','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0215','R3-2026-07','Wenn Ihre Managementbewertung den Bedarf an Änderungen an Leitlinie und Zielen nicht berücksichtigt, bleiben Politik und Zielsetzung Ihres BCMS statisch. Sie passen sich nicht an veränderte Bedingungen und Erkenntnisse an. So steuert Ihr System auf Basis überholter Vorgaben und verliert an Relevanz und Wirksamkeit.','BCM22301','BCM22301-9.3.2.e') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.e','R-R3-0215','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0216','R3-2026-07','Wenn Ihre Managementbewertung Verfahren und Ressourcen zur Leistungssteigerung nicht berücksichtigt, verpassen Sie Gelegenheiten, Ihr BCMS gezielt zu verbessern. Notwendige Investitionen und Optimierungen unterbleiben. So stagniert Ihr System, während Anforderungen und Bedrohungen sich weiterentwickeln und der Abstand zwischen Soll und Ist wächst.','BCM22301','BCM22301-9.3.2.f') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.f','R-R3-0216','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0217','R3-2026-07','Wenn Ihre Managementbewertung die Informationen aus Business-Impact-Analyse und Risikobeurteilung nicht berücksichtigt, entkoppelt sich die strategische Steuerung von der tatsächlichen Risikolage. Prioritäten und Ressourcen werden falsch gesetzt. So schützen Sie womöglich unkritische Bereiche, während zeitkritische Prozesse unzureichend abgesichert bleiben.','BCM22301','BCM22301-9.3.2.g') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.g','R-R3-0217','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0218','R3-2026-07','Wenn Ihre Managementbewertung die Ergebnisse aus der Bewertung von Dokumentation und Fähigkeiten nach 8.6 nicht berücksichtigt, bleiben dort erkannte Lücken auf Leitungsebene unbekannt. Notwendige Verbesserungen werden nicht angestoßen. So klafft eine Lücke zwischen der Prüfung Ihrer Fähigkeiten und der strategischen Entscheidung über deren Ausbau.','BCM22301','BCM22301-9.3.2.h') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.h','R-R3-0218','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0219','R3-2026-07','Wenn Ihre Managementbewertung Risiken und Themen, die in einer früheren Risikobeurteilung nicht angemessen behandelt wurden, nicht berücksichtigt, bleiben bekannte blinde Flecken dauerhaft offen. Diese ungelösten Risiken können sich unbemerkt zu realen Bedrohungen entwickeln. So verpassen Sie die Chance, frühere Versäumnisse gezielt zu korrigieren.','BCM22301','BCM22301-9.3.2.i') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.i','R-R3-0219','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0220','R3-2026-07','Wenn Ihre Managementbewertung Erkenntnisse aus Beinahe-Vorfällen und tatsächlichen Störungen nicht berücksichtigt, lernt Ihre Organisation nicht aus realen Ereignissen. Wertvolle Warnsignale bleiben ungenutzt und dieselben Ursachen führen erneut zu Schäden. So vergeben Sie die wirkungsvollste Grundlage für die Verbesserung Ihrer Widerstandsfähigkeit.','BCM22301','BCM22301-9.3.2.j') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.j','R-R3-0220','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0221','R3-2026-07','Wenn Ihre Managementbewertung keine Möglichkeiten zur fortlaufenden Verbesserung berücksichtigt, verharrt Ihr BCMS auf einem einmal erreichten Stand. Sie erkennen Schwachstellen und veränderte Rahmenbedingungen nicht rechtzeitig, sodass Ihr System veraltet und im Ernstfall nicht die erwartete Widerstandsfähigkeit liefert.','BCM22301','BCM22301-9.3.2.k') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.2.k','R-R3-0221','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0222','R3-2026-07','Fehlen in den Ergebnissen der Managementbewertung konkrete Entscheidungen zu Verbesserungen und notwendigen Änderungen, bleibt die Bewertung folgenlos. Erkannte Defizite werden nicht behoben, die Wirksamkeit Ihres BCMS sinkt schleichend, und Sie riskieren, dass Ihr System im Notfall den tatsächlichen Anforderungen nicht mehr gerecht wird.','BCM22301','BCM22301-9.3.3.1') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.1','R-R3-0222','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0223','R3-2026-07','Wenn Ihre Managementbewertung keine Entscheidungen über Änderungen am Anwendungsbereich trifft, kann der Scope des BCMS von der realen Organisation abweichen. Neu hinzugekommene oder weggefallene Prozesse bleiben unberücksichtigt, sodass kritische Bereiche ungeschützt bleiben und Ihre Kontinuitätsplanung ins Leere läuft.','BCM22301','BCM22301-9.3.3.1.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.1.a','R-R3-0223','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0224','R3-2026-07','Aktualisieren Sie Business Impact Analyse, Risikobeurteilung, Strategien und Pläne nicht auf Basis der Managementbewertung, arbeiten Sie mit überholten Annahmen. Veränderte Bedrohungen und Prozesse werden nicht abgebildet, wodurch Ihre Notfallmaßnahmen im Ernstfall unpassend dimensioniert sind und versagen können.','BCM22301','BCM22301-9.3.3.1.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.1.b','R-R3-0224','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0225','R3-2026-07','Passen Sie Verfahren und Controls nicht an interne oder externe Themen an, reagiert Ihr BCMS nicht auf veränderte Umstände. Neue Risiken und geänderte Rahmenbedingungen bleiben unbeantwortet, sodass Ihre Schutzmaßnahmen an Wirksamkeit verlieren und die Organisation im Störfall unzureichend abgesichert ist.','BCM22301','BCM22301-9.3.3.1.c') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.1.c','R-R3-0225','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0226','R3-2026-07','Legen Sie nicht fest, wie die Wirksamkeit der Controls künftig gemessen wird, fehlt Ihnen die Grundlage für eine objektive Steuerung. Sie können nicht belegen, ob Maßnahmen tatsächlich wirken, treffen Entscheidungen im Blindflug und riskieren, unwirksame Controls unbemerkt weiterzuführen.','BCM22301','BCM22301-9.3.3.1.d') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.1.d','R-R3-0226','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0227','R3-2026-07','Bewahren Sie keine dokumentierten Informationen über die Ergebnisse der Managementbewertungen auf, fehlt Ihnen der Nachweis, dass die Leitung ihrer Steuerungspflicht nachkommt. Bei Audits und im Schadensfall können Sie getroffene Entscheidungen nicht belegen, was Ihre Nachvollziehbarkeit und Zertifizierungsfähigkeit gefährdet.','BCM22301','BCM22301-9.3.3.2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.2','R-R3-0227','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0228','R3-2026-07','Werden die Ergebnisse der Managementbewertung nicht an die relevanten interessierten Parteien kommuniziert, bleiben Entscheidungen im Führungskreis stecken. Die für die Umsetzung Zuständigen kennen die Vorgaben nicht, sodass Verbesserungen nicht umgesetzt werden und Ihr BCMS trotz Bewertung stagniert.','BCM22301','BCM22301-9.3.3.2.a') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.2.a','R-R3-0228','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0229','R3-2026-07','Ergreifen Sie auf Grundlage der Managementbewertung keine angemessenen Maßnahmen, verpufft der gesamte Bewertungsaufwand. Erkannte Verbesserungspotenziale bleiben ungenutzt, Defizite bestehen fort, und Ihr BCMS entwickelt sich nicht weiter, wodurch es im Ernstfall hinter den Anforderungen zurückbleibt.','BCM22301','BCM22301-9.3.3.2.b') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BCM22301','BCM22301-9.3.3.2.b','R-R3-0229','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0230','R3-2026-07','Nimmt Ihre Institutionsleitung ihre Gesamtverantwortung für das BCM nicht wahr, fehlt dem gesamten System die tragende Grundlage. Ohne klare Ziele, benannten BCB und bereitgestellte Ressourcen bleibt das BCM unverbindlich und ineffektiv, sodass Ihre Institution auf Notfälle nicht vorbereitet ist.','BSI200_4','BSI2004-A0001') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0001','R-R3-0230','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0231','R3-2026-07','Bekennen sich Leitung und Führungskräfte nicht sichtbar zu ihrer Verantwortung für das BCM, fehlt die Vorbildwirkung. Die Beschäftigten nehmen das Thema nicht ernst, Vorgaben werden nachlässig umgesetzt, und Ihre Notfallvorsorge bleibt in der gelebten Praxis wirkungslos.','BSI200_4','BSI2004-A0002') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0002','R-R3-0231','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0232','R3-2026-07','Unterstützt Ihre Institutionsleitung die Führungskräfte nicht dabei, in ihren Bereichen zum BCMS beizutragen, entsteht kein flächendeckendes Engagement. Das BCM bleibt auf einzelne Zuständige beschränkt, wichtige Bereiche werden vernachlässigt, und die Widerstandsfähigkeit Ihrer Institution weist gefährliche Lücken auf.','BSI200_4','BSI2004-A0003') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0003','R-R3-0232','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0233','R3-2026-07','Fordert Ihre Leitung keine Informationen über den Status des BCM ein und steuert nicht durch Entscheidungen, verliert das BCMS an Richtung. Fehlentwicklungen bleiben unerkannt, das System wird weder wirksam noch angemessen gehalten, und Ihre Institution ist im Notfall schlecht aufgestellt.','BSI200_4','BSI2004-A0004') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0004','R-R3-0233','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0234','R3-2026-07','Verpflichtet sich Ihre Institutionsleitung nicht, das BCMS nach BSI-Standard 200-4 zu etablieren und zu verbessern, fehlt die verbindliche Grundlage. Das BCM bleibt beliebig und wird bei konkurrierenden Interessen zurückgestellt, sodass Ihre Notfallvorsorge weder verlässlich aufgebaut noch dauerhaft gepflegt wird.','BSI200_4','BSI2004-A0005') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0005','R-R3-0234','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0235','R3-2026-07','Stellt Ihre Leitungsebene nicht die erforderlichen finanziellen, personellen und zeitlichen Ressourcen bereit, kann das BCM nicht wirksam arbeiten. Notwendige Maßnahmen unterbleiben, Zuständige sind überlastet, und Ihr BCMS bleibt Stückwerk, das im Ernstfall die zugesagte Handlungsfähigkeit nicht sicherstellt.','BSI200_4','BSI2004-A0006') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0006','R-R3-0235','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0236','R3-2026-07','Haben Sie die Gründe und strategischen Ziele für das BCM nicht festgelegt, fehlt dem System eine klare Ausrichtung. Maßnahmen werden ohne roten Faden umgesetzt, passen nicht zur Institution, und Sie investieren Aufwand, ohne die für Ihre Kontinuität entscheidenden Prozesse gezielt abzusichern.','BSI200_4','BSI2004-A0007') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0007','R-R3-0236','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0237','R3-2026-07','Haben Sie den Geltungsbereich des BCMS nicht passend zu Zielsetzung und regulatorischen Anforderungen festgelegt, bleibt unklar, was geschützt wird. Zeitkritische Prozesse können außerhalb des Scopes liegen und ungeschützt bleiben, sodass Ihre Institution im Notfall gerade an den wichtigsten Stellen verwundbar ist.','BSI200_4','BSI2004-A0008') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0008','R-R3-0237','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0238','R3-2026-07','Ist Ihr Geltungsbereich nicht anhand nachvollziehbarer Kriterien in sich abgeschlossen und ohne klar definierte Grenzen, entstehen Grauzonen. Zuständigkeiten bleiben unklar, Prozesse fallen durch das Raster, und Sie riskieren, dass wesentliche Bereiche im Ernstfall ohne Notfallvorsorge dastehen.','BSI200_4','BSI2004-A0009') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0009','R-R3-0238','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0239','R3-2026-07','Dokumentieren und begründen Sie Einschränkungen und Abgrenzungen des Geltungsbereichs nicht, bleiben bewusste Ausklammerungen intransparent. Weder Prüfer noch Leitung können nachvollziehen, welche Risiken bewusst in Kauf genommen wurden, sodass ungeschützte Bereiche unbemerkt bleiben und im Notfall überraschen.','BSI200_4','BSI2004-A0010') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0010','R-R3-0239','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0240','R3-2026-07','Legen Sie den abzusichernden Zeitraum nicht individuell fest und überprüfen ihn nicht regelmäßig, passt Ihre Notfallvorsorge nicht zum tatsächlichen Bedarf. Sie planen für falsche Zeithorizonte, sodass Maßnahmen entweder zu kurz greifen oder unnötig aufwendig sind und die reale Belastung im Ernstfall verfehlen.','BSI200_4','BSI2004-A0011') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0011','R-R3-0240','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0241','R3-2026-07','Hat Ihre Leitung keine geeignete BCMS-Stufe ausgewählt und dokumentiert, fehlt dem Aufbau ein klarer Rahmen. Umfang und Tempo bleiben ungeklärt, Erwartungen und Realität klaffen auseinander, und Sie riskieren, dass Ihr BCMS weder zum Reifegrad noch zu den Anforderungen Ihrer Institution passt.','BSI200_4','BSI2004-A0012') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0012','R-R3-0241','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0242','R3-2026-07','Begründen Sie die Entscheidung für ein Reaktiv- oder Aufbau-BCMS nicht nachvollziehbar und zeigen keinen Entwicklungspfad auf, verfestigt sich ein bewusst reduziertes Schutzniveau ohne Perspektive. Die verbleibenden Lücken bleiben unbewusst bestehen, und Ihr BCMS entwickelt sich nicht zum angemessenen Zielzustand weiter.','BSI200_4','BSI2004-A0013') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0013','R-R3-0242','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0243','R3-2026-07','Verfolgt Ihre Institution nicht das Ziel, ein Standard-BCMS zu erreichen, bleiben Ihre zeitkritischen Geschäftsprozesse dauerhaft nur unzureichend abgesichert. Sie verharren auf einem reduzierten Schutzniveau, und im Ernstfall reichen die vorhandenen Vorkehrungen nicht aus, um den Betrieb verlässlich aufrechtzuerhalten.','BSI200_4','BSI2004-A0014') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0014','R-R3-0243','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0244','R3-2026-07','Entwickeln Sie ein Reaktiv-BCMS nach dem ersten Zyklus nicht gezielt weiter und planen den Übergang nicht in der Act-Phase, verharrt Ihr System auf einer Behelfslösung. Die vorgesehene Reifung unterbleibt, und Ihre Institution bleibt dauerhaft nur notdürftig gegen Ausfälle abgesichert.','BSI200_4','BSI2004-A0015') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0015','R-R3-0244','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0245','R3-2026-07','Beginnen Sie im Reaktiv-BCMS nicht zuerst mit dem Aufbau der BAO, fehlt Ihnen die handlungsfähige Organisation für den Not- und Krisenfall. Ohne diese Struktur bleibt die Reaktion auf Schadensereignisse unkoordiniert, wertvolle Zeit geht verloren, und der Schaden weitet sich unnötig aus.','BSI200_4','BSI2004-A0016') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0016','R-R3-0245','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0246','R3-2026-07','Hat Ihre Institutionsleitung nicht entschieden, wie die weiteren Schritte zum Aufbau des BCMS aussehen, fehlt dem Vorhaben eine belastbare Planung. Der Aufbau verläuft unstrukturiert und stockt, Ressourcen werden ineffizient eingesetzt, und Ihr BCMS erreicht die angestrebte Handlungsfähigkeit nur verzögert oder gar nicht.','BSI200_4','BSI2004-A0017') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0017','R-R3-0246','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0247','R3-2026-07','Dokumentieren Sie die wesentlichen Inhalte von Initiierung und Konzeption nicht in der Leitlinie BCMS, fehlt der verbindliche Bezugsrahmen. Selbstverpflichtung und Rahmenbedingungen bleiben ungreifbar, sodass das BCM beliebig interpretiert wird und Ihnen bei Audits sowie im Ernstfall die nachvollziehbare Grundlage fehlt.','BSI200_4','BSI2004-A0018') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0018','R-R3-0247','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0248','R3-2026-07','Haben Sie keinen BCB mit qualifizierter Vertretung für alle Aspekte des BCM benannt, bleibt die operative Steuerung ohne festen Verantwortlichen. Aufgaben versanden, niemand treibt das BCMS voran, und bei Ausfall der zuständigen Person steht Ihre Notfallorganisation im entscheidenden Moment führungslos da.','BSI200_4','BSI2004-A0019') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0019','R-R3-0248','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0249','R3-2026-07','Ist die Rolle des BCB nicht mit direktem Vorspracherecht bei der Leitung verankert, gehen kritische Themen im Instanzenweg verloren. Dringende Risiken erreichen die Entscheidungsebene zu spät oder gar nicht, sodass notwendige Weichenstellungen unterbleiben und Ihr BCM an Durchsetzungskraft verliert.','BSI200_4','BSI2004-A0020') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0020','R-R3-0249','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0250','R3-2026-07','Wird Ihr BCB nicht umfassend und frühzeitig über BCM-relevantes Geschehen unterrichtet, arbeitet er mit unvollständigem Lagebild. Änderungen und neue Risiken werden zu spät berücksichtigt, sodass das BCMS hinter der Realität zurückbleibt und im Ernstfall nicht auf dem aktuellen Stand ist.','BSI200_4','BSI2004-A0021') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0021','R-R3-0250','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0251','R3-2026-07','Verfügt Ihr BCB nicht über ausreichende zeitliche Ressourcen, kann er die BCM-Aufgaben nur oberflächlich erfüllen. Wichtige Tätigkeiten bleiben liegen, das BCMS wird vernachlässigt, und Ihre Notfallvorsorge veraltet, weil die verantwortliche Person schlicht nicht die Zeit zur sorgfältigen Pflege hat.','BSI200_4','BSI2004-A0022') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0022','R-R3-0251','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0252','R3-2026-07','Verfügt Ihr BCB nicht über die erforderliche fachliche und persönliche Qualifikation und werden Lücken nicht durch Schulung geschlossen, leidet die Qualität des gesamten BCMS. Methodische Fehler und Fehleinschätzungen bleiben unbemerkt, sodass Ihre Notfallvorsorge auf unsicherem Fundament steht und im Ernstfall versagt.','BSI200_4','BSI2004-A0023') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0023','R-R3-0252','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0253','R3-2026-07','Nimmt Ihr BCB die Aufgaben für Aufbau, Betrieb und Verbesserung des BCMS nicht wahr, fehlt dem System der operative Motor. Methoden werden nicht definiert, die Umsetzung nicht überwacht und die Leitung nicht informiert, sodass Ihr BCMS stillsteht und seine Wirksamkeit einbüßt.','BSI200_4','BSI2004-A0024') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0024','R-R3-0253','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0254','R3-2026-07','Behandeln Sie die für zeitkritische Prozesse benötigten Unterstützungsprozesse und Ressourcen nicht selbst als zeitkritisch, entsteht eine trügerische Sicherheit. Fällt eine unbeachtete Abhängigkeit wie IT oder ein Dienstleister aus, steht auch der Kernprozess still, und Ihre Kontinuitätsplanung greift ins Leere.','BSI200_4','BSI2004-A0025') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0025','R-R3-0254','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0255','R3-2026-07','Etablieren Sie das BCMS nicht im Rahmen einer übergreifenden Gesamtsicherheitsstrategie, bleibt es eine isolierte Insel. Schnittstellen zu anderen Sicherheitsdisziplinen werden nicht genutzt, Maßnahmen widersprechen sich oder überschneiden sich, und Ihre Institution schützt sich uneinheitlich und mit vermeidbaren Lücken.','BSI200_4','BSI2004-A0026') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0026','R-R3-0255','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0256','R3-2026-07','Ist nicht sichergestellt, dass Ihr BCM in einen kontinuierlich verbessernden PDCA-Zyklus übergeht, bleibt das System ein einmaliges Projekt. Ohne regelmäßige Überprüfung und Anpassung veraltet es, verliert an Wirksamkeit und schützt Ihre Institution schon bald nicht mehr gegen die tatsächlichen Risiken.','BSI200_4','BSI2004-A0027') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0027','R-R3-0256','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0257','R3-2026-07','Achten Ihre BC-Strategien und Ausweichverfahren nicht auch auf Vertraulichkeit und Integrität, erkaufen Sie Verfügbarkeit auf Kosten anderer Schutzziele. Im Ausweichbetrieb können Daten offengelegt oder verfälscht werden, sodass Sie ein Ausfallrisiko durch ein ebenso schwerwiegendes Datenschutz- oder Manipulationsrisiko ersetzen.','BSI200_4','BSI2004-A0028') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0028','R-R3-0257','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0258','R3-2026-07','Grenzen Sie die Schutzziele des ISMS und die Kontinuitätsanforderungen des BCMS nicht klar ab und klären die Schnittstellen nicht, entstehen Zuständigkeitslücken und Doppelarbeit. Risiken fallen zwischen beide Systeme, Maßnahmen widersprechen sich, und Ihre Sicherheits- und Notfallvorsorge wirkt weniger verlässlich als angenommen.','BSI200_4','BSI2004-A0029') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0029','R-R3-0258','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0259','R3-2026-07','Stimmen Sie die Methoden zur Identifikation, Analyse, Bewertung und Behandlung von Risiken nicht mit dem Risikomanagement ab, arbeiten beide Bereiche mit unterschiedlichen Maßstäben. Risiken werden widersprüchlich bewertet, Ergebnisse sind nicht vergleichbar, und Ihre Steuerungsentscheidungen beruhen auf einer inkonsistenten Grundlage.','BSI200_4','BSI2004-A0030') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0030','R-R3-0259','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0260','R3-2026-07','Gibt Ihr BCM keine Wiederanlaufzeiten vor und ist nicht sichergestellt, dass die Anforderungen auch im Betrieb eingehalten werden, bleibt die Notfallplanung unverbindlich. Im Ernstfall dauert die Wiederherstellung länger als tragbar, das zugesagte Mindestniveau wird verfehlt, und kritische Leistungen fallen zu lange aus.','BSI200_4','BSI2004-A0031') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0031','R-R3-0260','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0261','R3-2026-07','Stimmen Sie die Maßnahmen zur Wiederherstellung nicht mit denen zum Wiederanlauf und zum Notbetrieb ab, greifen die Schritte im Ernstfall nicht ineinander. Es entstehen Lücken oder Doppelungen, wertvolle Zeit geht verloren, und der Übergang vom Notbetrieb zurück in den Normalbetrieb verläuft chaotisch und fehleranfällig.','BSI200_4','BSI2004-A0032') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0032','R-R3-0261','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0262','R3-2026-07','Ist Ihre BAO nicht funktionierend aufgebaut und im Not- und Krisenfall sofort erreichbar und arbeitsfähig, fehlt die handlungsfähige Struktur im entscheidenden Moment. Die Reaktion auf ein Schadensereignis verzögert sich, Zuständigkeiten sind unklar, und der Schaden weitet sich aus, bevor überhaupt gegengesteuert wird.','BSI200_4','BSI2004-A0033') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0033','R-R3-0262','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0263','R3-2026-07','Stellt Ihre Entscheidungsinstanz nach Bestätigung eines Notfalls nicht sicher, dass die BAO alarmiert wird, verstreicht wertvolle Reaktionszeit ungenutzt. Die Notfallorganisation tritt zu spät oder gar nicht zusammen, sodass Sofortmaßnahmen unterbleiben und sich ein beherrschbares Ereignis zu einer ausgewachsenen Krise entwickelt.','BSI200_4','BSI2004-A0034') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0034','R-R3-0263','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0264','R3-2026-07','Sind die Rollen Ihrer BC-Organisation nicht mit Aufgaben, Rechten und Pflichten definiert und auf qualifizierte Mitarbeitende übertragen, bleibt im Ernstfall unklar, wer was tun darf. Entscheidungen verzögern sich, Zuständigkeiten überschneiden sich, und Ihre Notfallbewältigung verliert genau dann an Schlagkraft, wenn schnelles Handeln zählt.','BSI200_4','BSI2004-A0035') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0035','R-R3-0264','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0265','R3-2026-07','Wenn Sie die dauerhaften BCM-Aufgaben nicht in den Aufgaben- und Stellenprofilen verankern und Rollenabweichungen nicht absichern, bleiben Verantwortlichkeiten unklar. Im Ernstfall fühlt sich niemand zuständig, Aufgaben bleiben liegen und die Notfallbewältigung verzögert sich. So drohen Ihnen längere Ausfälle, Kompetenzstreitigkeiten und ein Wiederanlauf, der die kritischen Fristen reißt.','BSI200_4','BSI2004-A0036') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0036','R-R3-0265','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0266','R3-2026-07','Wenn die Detektion und Behandlung von Major Incidents nicht nahtlos in Alarmierung, Eskalation und Notfallbewältigung übergeht, entstehen Brüche in der Reaktionskette. Ein erkannter Vorfall wird dann zu spät hochgestuft oder gar nicht als Notfall behandelt. Dadurch verlieren Sie wertvolle Zeit, der Schaden wächst und aus einer beherrschbaren Störung wird ein ausgewachsener Notfall.','BSI200_4','BSI2004-A0037') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0037','R-R3-0266','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0267','R3-2026-07','Fehlen abgestimmte Schnittstellen und Verfahren zwischen ITSCM und BCM, arbeiten beide Disziplinen im Ernstfall aneinander vorbei. Technischer Wiederanlauf und geschäftliche Notfallbewältigung greifen dann nicht ineinander, Maßnahmen werden doppelt oder gar nicht ergriffen. So riskieren Sie widersprüchliche Entscheidungen, verlorene Zeit und einen Wiederanlauf, der die zeitkritischen Prozesse nicht rechtzeitig stützt.','BSI200_4','BSI2004-A0038') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0038','R-R3-0267','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0268','R3-2026-07','Wenn Sie Störung, Notfall und Krise nicht eindeutig und mit klaren Abgrenzungskriterien definieren, ordnen Ihre Mitarbeitenden Ereignisse unterschiedlich ein. Ein Notfall wird dann als bloße Störung abgetan oder umgekehrt überzogen eskaliert. Dadurch reagieren Sie mit den falschen Strukturen, verlieren wertvolle Zeit und die passenden Bewältigungsprozesse laufen nicht oder zu spät an.','BSI200_4','BSI2004-A0039') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0039','R-R3-0268','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0269','R3-2026-07','Sind die Zuständigkeiten für Störungen, Notfälle und Krisen sowie die Kriterien für die Eskalation nicht klar geregelt, entsteht im Ernstfall ein Kompetenzvakuum. Niemand übernimmt die Führung oder mehrere Stellen entscheiden widersprüchlich. So verzögert sich die Reaktion, wichtige Maßnahmen bleiben aus und aus einem beherrschbaren Ereignis kann sich eine ausgewachsene Krise entwickeln.','BSI200_4','BSI2004-A0040') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0040','R-R3-0269','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0270','R3-2026-07','Prüfen Sie nicht, inwiefern vorhandene Managementsysteme bereits BCM-Aspekte abdecken, bauen Sie Strukturen doppelt auf oder übersehen gefährliche Lücken. Ressourcen werden verschwendet, während geschäftskritische Schadensereignisse ungeregelt bleiben. Dadurch investieren Sie in Redundanzen, verlassen sich auf vermeintlich abgedeckte Bereiche und stehen im Ernstfall doch ohne wirksame Vorsorge da.','BSI200_4','BSI2004-A0041') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0041','R-R3-0270','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0271','R3-2026-07','Ist das Outsourcing zeitkritischer Dienstleistungen nicht im BCMS verankert und fehlen BCM-Anforderungen an die Dienstleister, bleibt deren Ausfallrisiko unkontrolliert. Fällt ein Dienstleister aus, haben Sie weder abgestimmte Schnittstellen noch durchsetzbare Wiederanlaufzusagen. So gefährden externe Ausfälle Ihre eigenen zeitkritischen Prozesse, ohne dass Sie darauf steuernd Einfluss nehmen können.','BSI200_4','BSI2004-A0042') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0042','R-R3-0271','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0272','R3-2026-07','Ohne etablierte Dokumentenlenkung, die Gestaltung, Überarbeitung und Freigabe regelt, geraten Ihre BCM-Dokumente außer Kontrolle. Es kursieren unklare Verantwortlichkeiten und ungeprüfte Fassungen. Im Notfall greifen Ihre Mitarbeitenden dann auf unvollständige oder nicht freigegebene Unterlagen zurück, treffen falsche Entscheidungen und die Notfallbewältigung verliert an Verlässlichkeit und Tempo.','BSI200_4','BSI2004-A0043') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0043','R-R3-0272','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0273','R3-2026-07','Schützen Sie BCM-Dokumente nicht angemessen hinsichtlich Verfügbarkeit, Vertraulichkeit und Integrität, sind Ihre Notfallpläne im entscheidenden Moment unbrauchbar. Sensible Alarmierungs- und Ablaufinformationen können in falsche Hände geraten oder unbemerkt verfälscht werden. So stehen Sie im Ernstfall ohne verlässliche Unterlagen da oder handeln nach manipulierten Vorgaben.','BSI200_4','BSI2004-A0044') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0044','R-R3-0273','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0274','R3-2026-07','Führen Sie keine Interessengruppenanalyse durch, kennen Sie die formalen und impliziten Anforderungen Ihrer internen und externen Stakeholder nicht. Wichtige Erwartungen und Einflussfaktoren bleiben unentdeckt. Dadurch richten Sie Ihr BCMS an falschen Annahmen aus, verletzen ungewollt regulatorische oder vertragliche Pflichten und verlieren im Ernstfall die Unterstützung entscheidender Beteiligter.','BSI200_4','BSI2004-A0045') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0045','R-R3-0274','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0275','R3-2026-07','Leiten Sie aus der Interessengruppenanalyse keine Maßnahmen ab und schätzen Sie den Einfluss der Gruppen nicht ein, bleibt die Analyse folgenlos. Erkannte Anforderungen werden nicht umgesetzt und mächtige Stakeholder nicht angemessen eingebunden. So bleibt Ihr BCMS auf dem Papier, während zentrale Erwartungen unerfüllt bleiben und einflussreiche Gruppen sich im Ernstfall gegen Sie stellen.','BSI200_4','BSI2004-A0046') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0046','R-R3-0275','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0276','R3-2026-07','Halten Sie die Interessengruppen sowie deren Anforderungen und Einflussfaktoren nicht regelmäßig aktuell, arbeiten Sie mit einem veralteten Bild Ihres Umfelds. Neue Beteiligte, geänderte Erwartungen oder weggefallene Ansprechpartner bleiben unberücksichtigt. Dadurch trifft Ihr BCMS im Ernstfall falsche Annahmen, verfehlt reale Bedürfnisse und verliert an Wirksamkeit und Akzeptanz.','BSI200_4','BSI2004-A0047') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0047','R-R3-0276','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0277','R3-2026-07','Legen Sie nicht fest, wer welche Informationen über welches Medium wie häufig mit den Interessengruppen austauscht, verläuft die Kommunikation im Ernstfall planlos. Wichtige Empfänger werden vergessen oder erhalten widersprüchliche Botschaften. So entstehen Informationslücken, Verunsicherung und Reputationsschäden, während sich Ihre Notfallbewältigung durch improvisierte und unkoordinierte Abstimmung unnötig verzögert.','BSI200_4','BSI2004-A0048') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0048','R-R3-0277','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0278','R3-2026-07','Dokumentieren Sie nicht, wo die Originale regulatorischer und sonstiger Anforderungen zu finden sind, verlieren Sie den verlässlichen Bezug zur maßgeblichen Quelle. Im Zweifel arbeiten Sie mit veralteten Auszügen oder Interpretationen. Dadurch übersehen Sie Änderungen, verletzen unbemerkt Vorgaben und können bei Prüfungen oder im Ernstfall die Rechtskonformität Ihres BCMS nicht belegen.','BSI200_4','BSI2004-A0049') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0049','R-R3-0278','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0279','R3-2026-07','Ermitteln und dokumentieren Sie die für das BCMS relevanten Schnittstellen nicht klar, bleiben ausgetauschte Informationen und Leistungen sowie Verantwortlichkeiten unklar. An den Nahtstellen entstehen Lücken, die niemand bemerkt. Im Notfall greifen die beteiligten Stellen dann nicht sauber ineinander, Aufgaben fallen zwischen die Zuständigkeiten und Ihre Notfallbewältigung stockt.','BSI200_4','BSI2004-A0050') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0050','R-R3-0279','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0280','R3-2026-07','Ohne Business-Impact-Analyse wissen Sie nicht, welche Geschäftsprozesse zeitkritisch sind, wie lange sie ausfallen dürfen und welche Ressourcen sie im Notbetrieb brauchen. Ihre Vorsorge beruht dann auf Vermutungen statt auf Fakten. So schützen Sie womöglich die falschen Prozesse, unterschätzen Ausfallzeiten und stehen im Ernstfall ohne die tatsächlich benötigten Ressourcen da.','BSI200_4','BSI2004-A0051') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0051','R-R3-0280','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0281','R3-2026-07','Stellen Sie der Business-Impact-Analyse im Reaktiv- und Aufbau-BCMS keinen BIA-Vorfilter voran, betrachten Sie von Beginn an eine unüberschaubare Menge an Prozessen. Die Analyse wird aufwendig, langwierig und verliert den Fokus. Dadurch binden Sie unnötig Ressourcen, verzögern erste Schutzmaßnahmen und verlieren wertvolle Zeit, in der Ihre wirklich kritischen Prozesse noch ungeschützt bleiben.','BSI200_4','BSI2004-A0052') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0052','R-R3-0281','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0282','R3-2026-07','Führen Sie keinen Soll-Ist-Vergleich durch, wissen Sie nicht, ob die benötigten Ressourcen bereits ausreichend abgesichert sind. Vorhandene Lücken zwischen Bedarf und tatsächlicher Absicherung bleiben verborgen. So wiegen Sie sich in falscher Sicherheit und stellen erst im Ernstfall fest, dass zentrale Ressourcen für den Notbetrieb fehlen und der Wiederanlauf scheitert.','BSI200_4','BSI2004-A0053') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0053','R-R3-0282','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0283','R3-2026-07','Untersuchen Sie im Aufbau- und Standard-BCMS nicht in einer Risikoanalyse, gegen welche Gefährdungen Ihre zeitkritischen Prozesse und Ressourcen abzusichern sind, treffen Sie Schutzentscheidungen ohne Grundlage. Relevante Bedrohungen bleiben unbewertet. Dadurch investieren Sie in falsche Maßnahmen, lassen echte Schwachstellen offen und werden von genau den Gefährdungen getroffen, die Sie nie betrachtet haben.','BSI200_4','BSI2004-A0054') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0054','R-R3-0283','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0284','R3-2026-07','Legen Sie keine geeigneten BC-Strategien und -Lösungen fest und setzen sie um, bleibt Ihr BCMS eine reine Analyse ohne Wirkung. Sie kennen dann zwar Ihre Risiken, haben aber keine erprobten Vorkehrungen zur Fortführung. Im Ernstfall fehlen Ihnen die Mittel zum Notbetrieb, kritische Prozesse fallen aus und der Schaden übersteigt schnell Ihre Belastbarkeit.','BSI200_4','BSI2004-A0055') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0055','R-R3-0284','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0285','R3-2026-07','Dokumentieren Ihre Geschäftsfortführungs- und Wiederanlaufpläne die im Notfall nötigen Handlungsschritte nicht, muss Ihr Personal unter Druck improvisieren. Wichtige Schritte werden vergessen oder in falscher Reihenfolge ausgeführt. So verlieren Sie wertvolle Zeit, die zeitkritischen Prozesse laufen nicht innerhalb der tolerierten Ausfallzeiten wieder an und der Schaden eskaliert.','BSI200_4','BSI2004-A0056') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0056','R-R3-0285','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0286','R3-2026-07','Geben Ihre Wiederherstellungspläne keine Hilfestellung, welche Schritte für ausreichend Ressourcen im Normalbetrieb nötig sind, verlängert sich die Rückkehr aus dem Notbetrieb unnötig. Ihre Institution verharrt dann im ressourcenschwachen Übergangszustand. Dadurch bleiben Leistungseinschränkungen bestehen, Kosten steigen und die vollständige Handlungsfähigkeit stellt sich erst spät und unkoordiniert wieder ein.','BSI200_4','BSI2004-A0057') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0057','R-R3-0286','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0287','R3-2026-07','Überprüfen Sie Strukturen, Notfallpläne und reaktive Maßnahmen nicht durch Übungen und Tests, kennen Sie deren praktische Wirksamkeit nicht. Schwachstellen und Lücken zeigen sich dann erst im Ernstfall. So verlassen Sie sich auf ungeprüfte Pläne, die unter realen Bedingungen versagen, und verlieren im entscheidenden Moment die Fähigkeit zur geordneten Notfallbewältigung.','BSI200_4','BSI2004-A0058') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0058','R-R3-0287','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0288','R3-2026-07','Führen Sie im Aufbau- und Standard-BCMS keine Leistungsüberprüfungen durch, erfahren Sie nicht, ob Ihr BCMS die gesetzten Anforderungen und Ziele erfüllt. Fehlentwicklungen und Wirkungslücken bleiben unentdeckt. Dadurch pflegen Sie ein Managementsystem im Blindflug, das im Ernstfall womöglich versagt, und können weder Fortschritt noch Konformität gegenüber Leitung und Prüfern belegen.','BSI200_4','BSI2004-A0059') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0059','R-R3-0288','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0289','R3-2026-07','Dokumentieren Sie Korrekturbedarfe und Verbesserungsmöglichkeiten nicht in einem Maßnahmenplan und setzen sie um, versanden erkannte Schwächen folgenlos. Dieselben Mängel treten immer wieder auf, ohne behoben zu werden. So bleibt der kontinuierliche Verbesserungsprozess aus, Ihr BCMS stagniert und bekannte Lücken gefährden im Ernstfall genau die Prozesse, die Sie eigentlich schützen wollten.','BSI200_4','BSI2004-A0060') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0060','R-R3-0289','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0290','R3-2026-07','Stellen Sie bei geografisch verteilten Standorten nicht sicher, dass globale und lokale BCM-Vorgaben einander nicht widersprechen, entstehen widersprüchliche Regelungen. Ihre Mitarbeitenden wissen dann nicht, welche Vorgabe im Ernstfall gilt. Dadurch treffen einzelne Standorte unkoordinierte Entscheidungen, die Notfallbewältigung zerfällt und einheitliches, standortübergreifendes Handeln wird unmöglich.','BSI200_4','BSI2004-A0061') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0061','R-R3-0290','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0291','R3-2026-07','Sind die im Notfall benötigten Dokumente nicht stets aktuell und für die jeweiligen Zielgruppen verfügbar, fehlen Ihrem Personal im entscheidenden Moment die richtigen Informationen. Alarmierungslisten oder Ablaufpläne sind dann veraltet oder unauffindbar. So handeln Ihre Teams nach falschen Vorgaben oder gar nicht, und die Notfallbewältigung gerät ins Stocken.','BSI200_4','BSI2004-A0062') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0062','R-R3-0291','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0292','R3-2026-07','Stellen Sie nicht sicher, dass veraltete Dokumentenversionen an allen Ablageorten durch die aktuellen ersetzt werden, kursieren im Ernstfall überholte Fassungen. Ihre Mitarbeitenden folgen dann Kontaktdaten oder Abläufen, die nicht mehr stimmen. Dadurch laufen Alarmierungen ins Leere, Maßnahmen greifen nicht und die Notfallbewältigung leidet unter falschen und widersprüchlichen Anweisungen.','BSI200_4','BSI2004-A0063') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0063','R-R3-0292','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0293','R3-2026-07','Legen Sie nicht für jede Dokumentenart fest, wie sie gestaltet, versioniert, überarbeitet und freigegeben wird, entsteht ein uneinheitlicher und lückenhafter Dokumentenbestand. Zuständigkeiten und Aktualisierungszyklen bleiben unklar. So altern wichtige Notfallunterlagen unbemerkt, niemand fühlt sich für ihre Pflege verantwortlich und im Ernstfall verlassen Sie sich auf ungeprüfte, überholte Dokumente.','BSI200_4','BSI2004-A0064') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0064','R-R3-0293','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0294','R3-2026-07','Versehen Sie BCMS-Dokumente nicht mit den geforderten Kennzeichnungen wie Titel, Version, Autor, Freigabe- und Überarbeitungsdatum, lässt sich ihre Aktualität und Verbindlichkeit nicht mehr nachvollziehen. Im Ernstfall wissen Ihre Mitarbeitenden nicht, ob ein Dokument gültig ist. Dadurch entstehen Verwechslungen, überholte Fassungen werden genutzt und die Verlässlichkeit Ihrer Notfalldokumentation geht verloren.','BSI200_4','BSI2004-A0065') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0065','R-R3-0294','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0295','R3-2026-07','Können die jeweiligen Zielgruppen die für sie bestimmten Dokumente nicht verstehen, nützen selbst inhaltlich korrekte Notfallpläne im Ernstfall wenig. Zu komplexe oder unklare Anweisungen werden falsch ausgelegt oder ignoriert. So handeln Ihre Mitarbeitenden unter Stress fehlerhaft oder zögerlich, wichtige Schritte unterbleiben und die Wirksamkeit Ihrer gesamten Notfalldokumentation ist gefährdet.','BSI200_4','BSI2004-A0066') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0066','R-R3-0295','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0296','R3-2026-07','Überprüfen Sie nicht, ob sich über- und untergeordnete Dokumente widersprechen, entstehen inkonsistente Vorgaben über die Dokumentenhierarchie hinweg. Leitlinie, Konzepte und Pläne weisen dann in unterschiedliche Richtungen. Dadurch verunsichern Sie Ihre Mitarbeitenden, die im Ernstfall nicht wissen, welche Anweisung gilt, und die widersprüchlichen Vorgaben untergraben ein geordnetes Notfallhandeln.','BSI200_4','BSI2004-A0067') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0067','R-R3-0296','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0297','R3-2026-07','Stellen Sie nicht fest, ob Dokumente entsprechend ihrem Aktualisierungszyklus geprüft und bei Bedarf aktualisiert wurden, altern Ihre Notfallunterlagen unbemerkt. Überholte Kontakte, Abläufe und Annahmen bleiben unentdeckt bestehen. So verlassen Sie sich im Ernstfall auf Dokumente, die nicht mehr zur Realität passen, und Ihre Notfallbewältigung baut auf einer veralteten Grundlage auf.','BSI200_4','BSI2004-A0068') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0068','R-R3-0297','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0298','R3-2026-07','Überprüfen Sie BCM-Dokumente nicht anlassbezogen, sobald sich Rahmenbedingungen, Regelungen, Ziele oder Strategien ändern, laufen Ihre Pläne der Wirklichkeit hinterher. Wichtige Änderungen schlagen sich erst mit großer Verzögerung nieder. Dadurch beruhen Ihre Notfallvorkehrungen auf überholten Voraussetzungen, greifen im Ernstfall nicht und lassen neue Gefährdungen oder Anforderungen unberücksichtigt.','BSI200_4','BSI2004-A0069') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0069','R-R3-0298','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0299','R3-2026-07','Stellt die Institutionsleitung keine angemessenen personellen, zeitlichen und finanziellen Ressourcen bereit und entscheidet nicht über die Ressourcenbedarfe, bleibt Ihr BCMS unterfinanziert und unterbesetzt. Notwendige Maßnahmen werden nicht umgesetzt. So verkümmert das BCMS zur Alibiübung, zentrale Schutzlücken bleiben offen und im Ernstfall fehlen Ihnen die Mittel für eine wirksame Notfallbewältigung.','BSI200_4','BSI2004-A0070') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0070','R-R3-0299','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0300','R3-2026-07','Benennen Sie nach Verabschiedung der Organisationsstruktur die Rolleninhabenden nicht und geben sie nicht bekannt, bleiben die BCM-Rollen unbesetzt oder unbekannt. Im Ernstfall weiß niemand, wer welche Aufgabe übernimmt oder wen er ansprechen muss. Dadurch verzögert sich die Reaktion, Verantwortlichkeiten bleiben ungeklärt und Ihre Notfallorganisation existiert nur auf dem Papier.','BSI200_4','BSI2004-A0071') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0071','R-R3-0300','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0301','R3-2026-07','Überprüfen Sie die Ressourcenplanung nicht regelmäßig auf Angemessenheit und passen sie nicht an, driftet die Ausstattung von den tatsächlichen Bedarfen ab. Gewachsene Anforderungen bleiben unterfinanziert und unterbesetzt. So stellen Sie erst im Ernstfall fest, dass Personal, Zeit oder Mittel nicht ausreichen, und Ihr BCMS kann seine Aufgaben nicht mehr wirksam erfüllen.','BSI200_4','BSI2004-A0072') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0072','R-R3-0301','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0302','R3-2026-07','Stellen Sie nicht sicher, dass alle Rolleninhabenden die benötigten Fähigkeiten und Kenntnisse besitzen oder erlangen, sind Ihre BCM-Rollen zwar besetzt, aber nicht handlungsfähig. Im Ernstfall fehlt den Verantwortlichen das nötige Können. Dadurch werden falsche Entscheidungen getroffen, Notfallpläne mangelhaft umgesetzt und die Bewältigung eines Ereignisses scheitert an unzureichend qualifiziertem Personal.','BSI200_4','BSI2004-A0073') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0073','R-R3-0302','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0303','R3-2026-07','Überprüfen Sie nach Schulungsmaßnahmen nicht, ob die Schulungsziele erreicht wurden, wissen Sie nicht, ob Ihre Mitarbeitenden das Gelernte tatsächlich beherrschen. Wissenslücken bleiben unentdeckt. So gehen Sie von einer Handlungsfähigkeit aus, die gar nicht besteht, und stellen erst im Ernstfall fest, dass zentrale Rollen mit unzureichend vorbereitetem Personal besetzt sind.','BSI200_4','BSI2004-A0074') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0074','R-R3-0303','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0304','R3-2026-07','Dokumentieren Sie nicht erreichte Schulungsziele nicht im Maßnahmenplan und behandeln sie nicht über korrektive Maßnahmen, bleiben Qualifikationslücken dauerhaft bestehen. Erkannte Defizite versanden ohne Nachsteuerung. Dadurch bleiben BCM-Rollen mit unzureichend geschultem Personal besetzt, und im Ernstfall handeln genau die Verantwortlichen fehlerhaft, deren Wissenslücken Sie bereits kannten, aber nicht geschlossen haben.','BSI200_4','BSI2004-A0075') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0075','R-R3-0304','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0305','R3-2026-07','Stellen Sie nicht durch geeignete Maßnahmen sicher, dass sich die BCM-Rolleninhabenden ihrer Aufgaben und Verantwortung bewusst werden, kennen diese ihre Pflichten im Ernstfall nicht ausreichend. Zuständigkeiten werden unterschätzt oder übersehen. So zögern Verantwortliche im entscheidenden Moment, nehmen ihre Rolle nicht an und wichtige Aufgaben der Notfallbewältigung bleiben unerledigt.','BSI200_4','BSI2004-A0076') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0076','R-R3-0305','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0306','R3-2026-07','Sensibilisieren Sie nicht alle Mitarbeitenden zielgruppenorientiert und bedarfsgerecht für das BCM, fehlt der Belegschaft das Bewusstsein für Notfälle und ihr Verhalten darin. Warnsignale werden übersehen und Vorgaben nicht ernst genommen. Dadurch reagiert Ihr Personal im Ernstfall falsch oder gar nicht, und selbst gute Notfallpläne scheitern am mangelnden Mitwirken der Mitarbeitenden.','BSI200_4','BSI2004-A0077') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0077','R-R3-0306','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0307','R3-2026-07','Ist Ihren Mitarbeitenden nicht bewusst, wo sie die relevanten Informationen zur Notfallbewältigung finden und wie sie sich im Notfall verhalten sollen, herrscht im Ernstfall Orientierungslosigkeit. Statt zu handeln, suchen Ihre Beschäftigten nach Anweisungen. So verlieren Sie in der kritischen Anfangsphase wertvolle Zeit, Fehlreaktionen häufen sich und der Schaden vergrößert sich unnötig.','BSI200_4','BSI2004-A0078') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0078','R-R3-0307','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0308','R3-2026-07','Enthält die Leitlinie BCMS nicht die geforderten Inhalte wie Motivation, Ziele, abzusichernden Zeitraum, Geltungsbereich sowie Gesamtverantwortung und Selbstverpflichtung der Leitung, fehlt Ihrem BCMS die verbindliche Grundlage. Rahmen und Auftrag bleiben unklar. Dadurch lässt sich das BCMS weder einheitlich ausrichten noch gegenüber Mitarbeitenden und Prüfern legitimieren, und ihm fehlt der nötige Rückhalt der Leitung.','BSI200_4','BSI2004-A0079') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0079','R-R3-0308','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0309','R3-2026-07','Wenn Sie die Anforderungen der relevanten Interessengruppen in der BCMS-Leitlinie nicht berücksichtigen, verfehlt Ihr Notfallmanagement die tatsächlichen Erwartungen von Aufsicht, Kunden und Partnern. Die Leitlinie bleibt praxisfern und wird nicht gelebt, wodurch im Ernstfall wichtige Vorgaben unbeachtet bleiben und Ihre Reaktionsfähigkeit sowie Ihre Reputation Schaden nehmen.','BSI200_4','BSI2004-A0080') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0080','R-R3-0309','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0310','R3-2026-07','Wenn die Institutionsleitung die BCMS-Leitlinie nicht prüft, freigibt und bekannt macht, fehlt dem Notfallmanagement das sichtbare Mandat der obersten Ebene. Die Mitarbeitenden kennen die Vorgaben nicht und fühlen sich nicht verpflichtet, wodurch im Notfall abgestimmtes Handeln ausbleibt und wertvolle Zeit sowie Durchsetzungskraft verloren gehen.','BSI200_4','BSI2004-A0081') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0081','R-R3-0310','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0311','R3-2026-07','Wenn die BCMS-Leitlinie nicht für alle berechtigten Interessengruppen verfügbar ist, können sich betroffene Stellen nicht an den festgelegten Grundsätzen orientieren. Im Notfall handeln Beteiligte uneinheitlich oder unwissend, wodurch Verantwortlichkeiten unklar bleiben, Reaktionen sich verzögern und die Wirksamkeit Ihres gesamten Notfallmanagements erheblich sinkt.','BSI200_4','BSI2004-A0082') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0082','R-R3-0311','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0312','R3-2026-07','Wenn Sie die BCMS-Leitlinie bei wesentlichen Änderungen von Rahmenbedingungen, Zielen oder Strategien nicht aktualisieren, veraltet sie und spiegelt Ihre tatsächliche Lage nicht mehr wider. Im Ernstfall stützen Sie sich auf überholte Annahmen, treffen falsche Prioritäten und gefährden so die Fortführung Ihrer kritischen Geschäftsprozesse.','BSI200_4','BSI2004-A0083') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0083','R-R3-0312','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0313','R3-2026-07','Wenn Sie Bewältigungsmaßnahmen nicht institutionsspezifisch anpassen und in einem Notfallhandbuch dokumentieren, fehlen im Ernstfall konkrete, umsetzbare Handlungsanweisungen. Die Verantwortlichen improvisieren unter Druck, übersehen wichtige Schritte und verlieren wertvolle Zeit, wodurch sich Ausfälle verlängern und Schäden für Ihre Institution vermeidbar wachsen.','BSI200_4','BSI2004-A0084') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0084','R-R3-0313','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0314','R3-2026-07','Wenn Sie zur Bewältigung von Notfällen und Krisen keine besondere Aufbauorganisation einrichten, fehlt Ihnen im Ernstfall eine handlungsfähige Struktur. Entscheidungen werden verzögert, Zuständigkeiten überschneiden sich und die Reaktion verläuft chaotisch, wodurch sich Schäden ausweiten und die Wiederherstellung Ihrer kritischen Prozesse gefährdet ist.','BSI200_4','BSI2004-A0085') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0085','R-R3-0314','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0315','R3-2026-07','Wenn die Rollen der besonderen Aufbauorganisation samt Aufgaben, Rechten und Pflichten nicht im Vorfeld festgelegt sind, herrscht im Notfall Unklarheit darüber, wer was entscheiden und tun darf. Diese Lücke führt zu Doppelarbeit, Verzögerungen und Lähmung, sodass Ihre Bewältigung ineffektiv bleibt und Schäden anwachsen.','BSI200_4','BSI2004-A0086') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0086','R-R3-0315','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0316','R3-2026-07','Wenn in der besonderen Aufbauorganisation kein Stab als zentrales Führungsgremium definiert ist, fehlt die lenkende und koordinierende Instanz der Bewältigung. Die einzelnen Teams handeln ohne gemeinsame Ausrichtung, Informationen laufen nicht zusammen und Maßnahmen widersprechen sich, wodurch Ihre Krisenreaktion unkoordiniert und deutlich weniger wirksam ausfällt.','BSI200_4','BSI2004-A0087') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0087','R-R3-0316','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0317','R3-2026-07','Wenn der Stab den Fortschritt der Notfallbewältigung nicht an die relevanten Parteien kommuniziert, entstehen Informationslücken bei Leitung, Teams und externen Stellen. Entscheidungen beruhen auf veraltetem Wissen, Maßnahmen werden doppelt oder gar nicht ergriffen, und Vertrauen sowie Steuerbarkeit Ihrer Bewältigung gehen verloren.','BSI200_4','BSI2004-A0088') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0088','R-R3-0317','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0318','R3-2026-07','Wenn die Institutionsleitung dem Stab keine angemessenen Entscheidungsbefugnisse überträgt, kann dieser im Notfall nicht schnell und verbindlich handeln. Jede Maßnahme erfordert Rückfragen und Freigaben, wodurch wertvolle Zeit verstreicht, sich Schäden ausweiten und die zügige Bewältigung von Notfällen und Krisen ernsthaft behindert wird.','BSI200_4','BSI2004-A0089') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0089','R-R3-0318','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0319','R3-2026-07','Wenn der Stab nicht mindestens aus einem Kernteam besteht, das die Schlüsselpositionen wie IT, Personal, Gebäudeverwaltung und Kommunikation abdeckt, fehlt im Notfall entscheidende Fachkompetenz. Wichtige Aspekte der Lage bleiben unbearbeitet, Entscheidungen sind lückenhaft und Ihre Bewältigung greift zu kurz, wodurch sich Auswirkungen unnötig verschärfen.','BSI200_4','BSI2004-A0090') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0090','R-R3-0319','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0320','R3-2026-07','Wenn für die stabsleitende Person die Verantwortung im Not- und Krisenfall nicht zusätzlich zu Aufgabe und Zuständigkeit definiert ist, bleibt unklar, wer die Bewältigung tatsächlich führt und verantwortet. Diese Lücke führt zu zögerlichem Handeln und Verantwortungsdiffusion, sodass Ihre Krisensteuerung im entscheidenden Moment ins Stocken gerät.','BSI200_4','BSI2004-A0091') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0091','R-R3-0320','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0321','R3-2026-07','Wenn für die stabsleitende Person keine mehreren Stellvertretenden benannt sind, ist Ihr Krisenstab bei deren Ausfall führungslos. Gerade in Notfällen sind Personen oft nicht verfügbar, und ohne Nachfolge bricht die Leitung weg, wodurch Entscheidungen ausbleiben und die Handlungsfähigkeit Ihrer gesamten Bewältigungsorganisation gefährdet ist.','BSI200_4','BSI2004-A0092') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0092','R-R3-0321','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0322','R3-2026-07','Wenn Sie bei der Aufnahme externer Mitglieder in den Stab Vertraulichkeit sowie Handlungs- und Entscheidungsbefugnisse nicht explizit regeln, riskieren Sie den Abfluss sensibler Krisendetails und unklare Kompetenzen. Externe könnten überschreiten oder blockieren, während vertrauliche Informationen nach außen gelangen, wodurch Ihre Institution zusätzlichen rechtlichen und reputativen Schaden erleidet.','BSI200_4','BSI2004-A0093') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0093','R-R3-0322','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0323','R3-2026-07','Wenn der Stab nicht durch eine Stabsassistenz mit mindestens Protokollierung und Backoffice ergänzt ist, fehlen im Notfall geordnete Dokumentation und Unterstützung. Entscheidungen bleiben unnachvollziehbar, Aufgaben werden vergessen und die Stabsleitung wird mit Nebentätigkeiten überlastet, wodurch die Qualität und Nachweisbarkeit Ihrer Bewältigung erheblich leidet.','BSI200_4','BSI2004-A0094') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0094','R-R3-0323','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0324','R3-2026-07','Wenn keine Bewältigungsteams zur operativen Notfallbewältigung aufgebaut sind, die ihre Aufträge vom Stab erhalten und an ihn berichten, fehlt die ausführende Ebene der Krisenreaktion. Beschlüsse des Stabes werden nicht umgesetzt, die Rückmeldung zur Lage bleibt aus, und Ihre Bewältigung verharrt in der Planung statt in der Wirkung.','BSI200_4','BSI2004-A0095') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0095','R-R3-0324','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0325','R3-2026-07','Wenn die Institutionsleitung bei der Vorbereitung der besonderen Aufbauorganisation nicht eingebunden ist und deren Aufbau nicht freigibt, fehlt der Struktur die verbindliche Legitimation. Rollen und Besetzungen könnten im Ernstfall angezweifelt werden, Entscheidungen verlieren an Durchsetzungskraft, und Ihre Krisenorganisation steht ohne den nötigen Rückhalt der obersten Ebene da.','BSI200_4','BSI2004-A0096') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0096','R-R3-0325','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0326','R3-2026-07','Wenn nicht jede Rolle der besonderen Aufbauorganisation mit einer hauptzuständigen und mindestens einer stellvertretenden Person besetzt ist, bricht bei Ausfall einer Person die Handlungsfähigkeit an dieser Stelle weg. Gerade im Notfall sind Personen häufig nicht erreichbar, wodurch Ihre Bewältigungsorganisation Lücken aufweist und ihre Aufgaben nicht durchgängig erfüllen kann.','BSI200_4','BSI2004-A0097') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0097','R-R3-0326','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0327','R3-2026-07','Wenn Sie nicht durch Schulungen sicherstellen, dass die BAO-Rolleninhabenden fachlich geeignet sind, treffen im Ernstfall unvorbereitete Personen folgenschwere Entscheidungen. Sie kennen Abläufe und Werkzeuge nicht, handeln fehlerhaft und verlieren wertvolle Zeit, wodurch sich die Krise verschärft und die Wirksamkeit Ihrer gesamten Bewältigung ernsthaft in Frage steht.','BSI200_4','BSI2004-A0098') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0098','R-R3-0327','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0328','R3-2026-07','Wenn nicht geklärt ist, ob die vorgesehenen Personen mental in der Lage sind, in besonderen Stresssituationen zu arbeiten, riskieren Sie deren Überforderung im entscheidenden Moment. Betroffene treffen unter Druck fehlerhafte Entscheidungen oder fallen aus, wodurch die Führung Ihrer Bewältigung wegbricht und sich die Krise unkontrolliert ausweiten kann.','BSI200_4','BSI2004-A0099') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0099','R-R3-0328','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0329','R3-2026-07','Wenn die Rollenbesetzung nach Freigabe nicht in der Geschäftsordnung des Stabes mit Stabsform, Rollen und namentlicher Besetzung dokumentiert ist, fehlt im Ernstfall eine verbindliche Referenz. Es bleibt unklar, wer welche Funktion innehat, Zuständigkeiten werden bestritten und die schnelle, geordnete Aktivierung Ihres Krisenstabes gerät ins Stocken.','BSI200_4','BSI2004-A0100') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0100','R-R3-0329','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0330','R3-2026-07','Wenn die Bewältigungsteams nicht mit fachlich qualifiziertem Personal und hinreichenden Vertretungen besetzt sind, können sie die operativen Aufgaben im Notfall nicht zuverlässig erfüllen. Fehlt Kompetenz oder fällt eine Schlüsselperson aus, stockt die Umsetzung der Maßnahmen, wodurch sich die Wiederherstellung Ihrer kritischen Prozesse verzögert und Schäden anwachsen.','BSI200_4','BSI2004-A0101') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0101','R-R3-0330','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0331','R3-2026-07','Wenn Sie bei der Besetzung der Bewältigungsteams die Mitarbeitenden und die Personalvertretung nicht beteiligen, riskieren Sie mangelnde Akzeptanz und mögliche arbeitsrechtliche Konflikte. Betroffene fühlen sich übergangen und tragen die Aufgaben nur widerwillig mit, wodurch die Einsatzbereitschaft im Ernstfall leidet und Ihre Bewältigung an innerem Rückhalt verliert.','BSI200_4','BSI2004-A0102') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0102','R-R3-0331','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0332','R3-2026-07','Wenn kein Alarmierungs- und Eskalationsprozess definiert, visualisiert und im Notfallhandbuch dokumentiert ist, bleibt im Ernstfall unklar, wie ein Ereignis gemeldet und hochgestuft wird. Meldungen versanden oder erreichen die falschen Stellen, die Aktivierung der Bewältigungsorganisation verzögert sich, und wertvolle Reaktionszeit geht für Ihre Institution verloren.','BSI200_4','BSI2004-A0103') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0103','R-R3-0332','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0333','R3-2026-07','Wenn vorab nicht festgelegt ist, wie und über welche Kanäle Schadensereignisse mit Notfallpotenzial gemeldet werden und ob es sich um Information oder Alarmierung handelt, entsteht im Ernstfall Verwirrung. Meldungen erreichen die zuständigen Stellen nicht rechtzeitig oder werden falsch eingeordnet, wodurch die Reaktion Ihrer Institution gefährlich verzögert wird.','BSI200_4','BSI2004-A0104') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0104','R-R3-0333','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0334','R3-2026-07','Wenn der Alarmierungs- und Eskalationsprozess vorhandene Prozesse zur Detektion und Behandlung von Störungen und Sicherheitsvorfällen nicht berücksichtigt, entstehen Brüche und Doppelstrukturen. Ereignisse werden mehrfach oder gar nicht weitergegeben, Übergänge stocken, und Ihre Institution verliert im Ernstfall wertvolle Zeit, weil bestehende und neue Meldewege nicht zusammenwirken.','BSI200_4','BSI2004-A0105') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0105','R-R3-0334','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0335','R3-2026-07','Wenn der Alarmierungsprozess samt Reaktionszeiten und Meldewegen nicht mit den beteiligten Stellen und Schnittstellen abgestimmt und dokumentiert ist, greifen die Übergänge im Ernstfall nicht ineinander. Meldungen bleiben an Schnittstellen liegen, Fristen werden verpasst und die Alarmierung Ihrer Bewältigungsorganisation verzögert sich, wodurch Schäden vermeidbar anwachsen.','BSI200_4','BSI2004-A0106') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0106','R-R3-0335','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0336','R3-2026-07','Wenn technisch nicht sichergestellt ist, dass Kommunikations- und Alarmierungstechnik einschließlich Alarmierungssoftware auch im Not- oder Krisenfall verfügbar ist, kann gerade dann keine Alarmierung erfolgen, wenn sie am dringendsten benötigt wird. Ihre Bewältigungsorganisation bleibt uninformiert und inaktiv, wodurch sich Schäden ungebremst ausweiten und die Reaktion ausbleibt.','BSI200_4','BSI2004-A0107') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0107','R-R3-0336','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0337','R3-2026-07','Wenn keine Kommunikationskanäle zur Verfügung stehen, die unabhängig von der IT der Institution funktionieren, bricht bei einem IT-Ausfall gerade die Verständigung im Krisenfall weg. Der Stab kann nicht alarmieren, koordinieren oder informieren, wodurch Ihre Bewältigung genau in der kritischsten Lage handlungsunfähig wird und sich Schäden ungehindert ausbreiten.','BSI200_4','BSI2004-A0108') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0108','R-R3-0337','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0338','R3-2026-07','Wenn auch für Ereignisse, die nicht aus einer Störung eskalieren oder als Sicherheitsvorfall gelten, keine Kriterien festgelegt sind, was durch wen an eine Meldestelle gemeldet wird, bleiben relevante Vorfälle unbemerkt. Sie erkennen aufkommende Notlagen zu spät, verlieren wertvolle Reaktionszeit und geraten leichter in eine unkontrollierte Krisensituation.','BSI200_4','BSI2004-A0109') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0109','R-R3-0338','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0339','R3-2026-07','Wenn die relevanten Meldequellen der Institution nicht identifiziert und samt zuständigen Meldestellen im Notfallhandbuch dokumentiert sind, gehen wichtige Hinweise auf drohende Notfälle verloren. Meldungen wissen nicht, wohin sie gerichtet werden sollen, bleiben unbearbeitet, und Ihre Institution erkennt kritische Ereignisse zu spät, um noch wirksam gegensteuern zu können.','BSI200_4','BSI2004-A0110') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0110','R-R3-0339','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0340','R3-2026-07','Wenn nicht sichergestellt ist, dass Meldungen die zuständigen Meldestellen erreichen und nicht verloren gehen, versickern Hinweise auf Schadensereignisse unbemerkt. Ein potenzieller Notfall bleibt unerkannt, die Alarmierung unterbleibt, und Ihre Bewältigungsorganisation wird nicht aktiviert, wodurch sich Schäden ausweiten, die bei rechtzeitiger Meldung beherrschbar gewesen wären.','BSI200_4','BSI2004-A0111') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0111','R-R3-0340','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0341','R3-2026-07','Wenn nicht durch Schulungen und Sensibilisierung sichergestellt ist, dass der Alarmierungs- und Eskalationsprozess allen Mitarbeitenden und ggf. Externen bekannt ist und korrekt angewendet wird, melden Betroffene falsch, zu spät oder gar nicht. Der Prozess läuft ins Leere, kritische Ereignisse bleiben unbemerkt, und Ihre Institution reagiert im Notfall verspätet und ungeordnet.','BSI200_4','BSI2004-A0112') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0112','R-R3-0341','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0342','R3-2026-07','Wenn nicht jede Meldestelle die Meldungen in einem einheitlichen Format mit Mindestinhalten wie Zeitpunkt, Ort, meldender Person und betroffenen Bereichen erfasst, fehlen zur Lagebeurteilung entscheidende Angaben. Die Einschätzung wird unvollständig und uneinheitlich, wodurch Entscheidungen auf lückenhafter Grundlage ergehen und Ihre Bewältigung an Geschwindigkeit und Treffsicherheit verliert.','BSI200_4','BSI2004-A0113') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0113','R-R3-0342','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0343','R3-2026-07','Wenn nicht definiert und dokumentiert ist, wie die Meldestellen während und außerhalb der Geschäftszeiten erreicht werden, bleiben Notfälle in Rand- und Nachtzeiten unbearbeitet. Gerade dann meldet niemand weiter, die Alarmierung verzögert sich um Stunden, und Ihre Institution verliert wertvolle Reaktionszeit, während sich der Schaden ungehindert ausbreitet.','BSI200_4','BSI2004-A0114') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0114','R-R3-0343','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0344','R3-2026-07','Wenn eine nur eingeschränkte Erreichbarkeit einzelner Meldestellen nicht im Notfallhandbuch dokumentiert ist und keine Risikoübernahme durch die Institutionsleitung erfolgt, bleibt die Lücke unerkannt und unverantwortet. Im Ernstfall verlassen sich Beteiligte auf eine nicht erreichbare Stelle, Meldungen bleiben liegen, und die Verantwortung für die entstehenden Schäden ist ungeklärt.','BSI200_4','BSI2004-A0115') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0115','R-R3-0344','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0345','R3-2026-07','Wenn bei gesetzlichen oder regulatorischen kurzfristigen Meldepflichten nicht durch Rufbereitschaft oder durchgängige Besetzung sichergestellt ist, dass diese eingehalten werden, verpassen Sie verbindliche Meldefristen. Die Folge sind Bußgelder, aufsichtsrechtliche Maßnahmen und Reputationsschäden, während Ihre Institution zugleich als unzuverlässig gegenüber Aufsicht und betroffenen Personen wahrgenommen wird.','BSI200_4','BSI2004-A0116') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0116','R-R3-0345','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0346','R3-2026-07','Wenn nicht jede Meldestelle anhand klarer, verständlicher und individuell festgelegter Kriterien befähigt ist, initial einzuschätzen, ob ein Ereignis Notfallpotenzial hat, werden Vorfälle falsch bewertet. Ernste Ereignisse werden unterschätzt und nicht eskaliert oder harmlose überbewertet, wodurch Ihre Bewältigungsorganisation entweder zu spät oder unnötig aktiviert wird.','BSI200_4','BSI2004-A0117') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0117','R-R3-0346','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0347','R3-2026-07','Wenn nicht sichergestellt ist, dass die zuständige Stelle Schadensereignisse mit Notfallpotenzial unverzüglich an eine zentrale Entscheidungsinstanz meldet und dabei bekannte Details übermittelt, bleibt die entscheidende Ebene uninformiert. Die Einstufung und Alarmierung verzögern sich, wertvolle Zeit verstreicht, und Ihre Institution reagiert auf einen Notfall zu spät, um ihn noch einzudämmen.','BSI200_4','BSI2004-A0118') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0118','R-R3-0347','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0348','R3-2026-07','Wenn nicht festgelegt ist, wie Alarmmeldungen übermittelt werden, etwa per Telefon, Alarm-SMS mit Lesebestätigung oder Alarmierungstool, kann im Ernstfall unklar bleiben, ob eine Alarmierung tatsächlich angekommen ist. Empfänger werden nicht erreicht oder reagieren nicht, wodurch die Aktivierung Ihrer Bewältigungsorganisation scheitert und wertvolle Reaktionszeit ungenutzt verstreicht.','BSI200_4','BSI2004-A0119') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0119','R-R3-0348','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0349','R3-2026-07','Wenn die Einstufung, ob eine Störung, ein Notfall oder eine Krise vorliegt, nicht durch eine geschulte, erfahrene und befugte zentrale Entscheidungsinstanz erfolgt, wird die Lage falsch bewertet. Notfälle werden als bloße Störungen behandelt und zu spät eskaliert oder unnötig hochgestuft, wodurch Ihre Bewältigung fehlgeleitet und ihre Wirksamkeit untergraben wird.','BSI200_4','BSI2004-A0120') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0120','R-R3-0349','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0350','R3-2026-07','Wenn der zentralen Entscheidungsinstanz keine Checkliste mit Kriterien zur nachvollziehbaren und dokumentierten Einstufung zur Verfügung steht, beruht die Bewertung eines Schadensereignisses allein auf Bauchgefühl. Die Einstufung wird uneinheitlich und schwer nachvollziehbar, wodurch Entscheidungen anfechtbar bleiben und Ihre Institution im Ernstfall wertvolle Zeit mit unsicheren Beurteilungen verliert.','BSI200_4','BSI2004-A0121') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0121','R-R3-0350','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0351','R3-2026-07','Wenn als Störung eingestufte Ereignisse nicht durch die zuständige Fachabteilung innerhalb der allgemeinen Aufbauorganisation behoben werden und sich die zentrale Entscheidungsinstanz nicht über den Verlauf informieren lässt, verliert diese den Überblick. Eine sich zuspitzende Störung wird nicht rechtzeitig als Notfall erkannt und eskaliert, wodurch Ihre Institution wertvolle Reaktionszeit einbüßt.','BSI200_4','BSI2004-A0122') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0122','R-R3-0351','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0352','R3-2026-07','Wenn die besondere Aufbauorganisation bei Einstufung eines Ereignisses als Notfall oder Krise durch die zentrale Entscheidungsinstanz nicht unverzüglich alarmiert wird, verstreicht zwischen Erkennung und Reaktion kostbare Zeit. Ihre Bewältigungsorganisation tritt zu spät zusammen, erste entscheidende Maßnahmen unterbleiben, und der Schaden weitet sich aus, bevor überhaupt gegengesteuert wird.','BSI200_4','BSI2004-A0123') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0123','R-R3-0352','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0353','R3-2026-07','Wenn Sie die Einstufungsentscheidung nicht nachvollziehbar mit Zeitpunkt, Auswirkung, Begründung und Beteiligten dokumentieren, lässt sich im Nachhinein nicht belegen, warum ein Ereignis als Notfall oder Störung bewertet wurde. Sie verlieren die Grundlage für Lessons Learned, riskieren Fehlentscheidungen unter Zeitdruck und können gegenüber Aufsicht, Versicherung und Leitung Ihre Reaktion nicht rechtssicher rechtfertigen.','BSI200_4','BSI2004-A0124') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0124','R-R3-0353','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0354','R3-2026-07','Überprüft und bestätigt der Stab die Einstufung bei Konstituierung der BAO nicht anhand weiterer Kriterien, arbeiten Sie möglicherweise auf einer veralteten oder falschen Lagebeurteilung weiter. Sie eskalieren harmlose Ereignisse unnötig oder unterschätzen echte Notfälle, binden Ressourcen falsch und verlieren wertvolle Zeit, die für die Bewältigung des tatsächlichen Schadens fehlt.','BSI200_4','BSI2004-A0125') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0125','R-R3-0354','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0355','R3-2026-07','Fehlen die organisatorischen und technischen Voraussetzungen für eine unverzügliche Alarmierung der BAO oder sind sie nicht dokumentiert, verzögert sich im Ernstfall der Aufbau der Notfallorganisation. Sie verlieren in der kritischen Anfangsphase entscheidende Zeit, der Schaden weitet sich unkontrolliert aus und die Wiederanlaufzeiten Ihrer Geschäftsprozesse überschreiten die tolerierbaren Grenzen.','BSI200_4','BSI2004-A0126') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0126','R-R3-0355','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0356','R3-2026-07','Ist die Erreichbarkeit der BAO innerhalb und außerhalb der Geschäftszeiten nicht mit den Rolleninhabenden und der Leitung abgestimmt, laufen Alarmierungen im Notfall ins Leere. Sie können entscheidende Personen nachts oder am Wochenende nicht erreichen, der Krisenstab bleibt handlungsunfähig und Ihre Reaktion beginnt mit gefährlicher Verzögerung.','BSI200_4','BSI2004-A0127') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0127','R-R3-0356','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0357','R3-2026-07','Werden für Zeiten ohne garantierte Erreichbarkeit der BAO keine Risikoübernahmen durch die Institutionsleitung herbeigeführt, tragen Sie ein bewusstes Reaktionsrisiko, ohne dass es entschieden und verantwortet ist. Tritt in einer solchen Lücke ein Notfall ein, fehlt die Handlungsfähigkeit, und die Leitung haftet für einen ungeregelten, nicht abgesicherten Zustand.','BSI200_4','BSI2004-A0128') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0128','R-R3-0357','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0358','R3-2026-07','Regelt der Alarmierungs- und Eskalationsprozess nicht, wie die BAO innerhalb und außerhalb der Geschäftszeiten erreicht wird und wer alarmiert und nachalarmiert wird, entstehen im Ernstfall Lücken in der Meldekette. Sie riskieren, dass Schlüsselpersonen unbenachrichtigt bleiben, sich niemand verantwortlich fühlt und die Krisenreaktion verspätet oder gar nicht anläuft.','BSI200_4','BSI2004-A0129') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0129','R-R3-0358','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0359','R3-2026-07','Ist die Benachrichtigung der BAO-Rolleninhabenden im Ernstfall nicht kurz, präzise und mit klaren nächsten Schritten formuliert, entstehen Missverständnisse und Rückfragen in der kritischsten Phase. Die alarmierte Person weiß nicht, was zu tun ist, reagiert falsch oder zögerlich, und Sie verlieren wertvolle Zeit beim Aufbau der Notfallorganisation.','BSI200_4','BSI2004-A0130') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0130','R-R3-0359','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0360','R3-2026-07','Ist nicht sichergestellt, dass die alarmierte Person dem Aufruf zeitnah folgt, bleibt Ihre Alarmierung wirkungslos. Wird ein Alarm ignoriert, übersehen oder verzögert bearbeitet, bleibt der Krisenstab unterbesetzt und handlungsunfähig, während sich der Schaden ungebremst ausbreitet und tolerierbare Ausfallzeiten überschritten werden.','BSI200_4','BSI2004-A0131') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0131','R-R3-0360','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0361','R3-2026-07','Werden weitere Personen wie Haushaltsmitglieder, die Alarmmeldungen entgegennehmen könnten, nicht für den Umgang damit sensibilisiert, gehen dringende Meldungen verloren oder werden nicht weitergegeben. Sie riskieren, dass eine nächtliche Alarmierung nicht ankommt, die zuständige Person nicht erreicht wird und die Notfallreaktion mit gefährlicher Verzögerung startet.','BSI200_4','BSI2004-A0132') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0132','R-R3-0361','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0362','R3-2026-07','Sind die Sofortmaßnahmen im Notfallhandbuch nicht als Checklisten dokumentiert, müssen Ihre Mitarbeitenden unter Stress und Zeitdruck aus dem Gedächtnis handeln. Sie riskieren, dass wichtige Schritte vergessen, falsch ausgeführt oder in falscher Reihenfolge erledigt werden, wodurch sich der Schaden vergrößert und die Bewältigung unnötig chaotisch verläuft.','BSI200_4','BSI2004-A0133') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0133','R-R3-0362','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0363','R3-2026-07','Beinhalten die Sofortmaßnahmen keine mit der Fachkraft für Arbeitssicherheit abgestimmten Regelungen zum Schutz von Leib und Leben, gefährden Sie im Notfall Menschen. Sie riskieren, dass der Schutz von Personen hinter dem Schutz von Sachwerten zurücksteht, Verletzungen oder schlimmere Folgen eintreten und Sie zudem arbeitsschutzrechtliche Pflichten verletzen.','BSI200_4','BSI2004-A0134') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0134','R-R3-0363','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0364','R3-2026-07','Sind konkrete Anweisungen und Zuständigkeiten für die Sofortmaßnahmen nicht festgelegt, herrscht im Ernstfall Unklarheit, wer was tun darf oder muss. Sie riskieren, dass sich niemand verantwortlich fühlt, Maßnahmen doppelt oder gar nicht ausgeführt werden und wertvolle Zeit durch Abstimmungsbedarf verloren geht, während der Schaden fortschreitet.','BSI200_4','BSI2004-A0135') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0135','R-R3-0364','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0365','R3-2026-07','Hat Ihre Institution keine Sofortmaßnahmen für Notfallszenarien mit „Gefahr im Verzug" festgelegt, fehlt in genau den Momenten eine Handlungsanleitung, in denen Sekunden zählen. Ihre Mitarbeitenden zögern oder handeln falsch, wenn sofortiges, entschlossenes Eingreifen nötig wäre, wodurch sich vermeidbare Personen- und Sachschäden ausweiten.','BSI200_4','BSI2004-A0136') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0136','R-R3-0365','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0366','R3-2026-07','Sind für branchenspezifische weitere Schadensereignisse keine Sofortmaßnahmen festgelegt, sind Sie auf die für Ihren Betrieb typischen Gefahren nicht vorbereitet. Tritt ein solches spezifisches Ereignis ein, fehlt Ihren Mitarbeitenden die passende Handlungsanleitung, sie improvisieren unter Druck und die Bewältigung verläuft langsamer und fehleranfälliger als nötig.','BSI200_4','BSI2004-A0137') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0137','R-R3-0366','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0367','R3-2026-07','Wird im Notfallhandbuch nicht auf vorhandene Regelungen und Rollen wie Ersthelfende, Brandhelfende und Evakuierungshelfende verwiesen, bleiben bestehende Schutzstrukturen im Ernstfall ungenutzt. Sie riskieren doppelte oder widersprüchliche Anweisungen, verlieren Zeit bei der Koordination und schöpfen vorhandene Kompetenzen und Ressourcen nicht aus, wenn sie am dringendsten gebraucht werden.','BSI200_4','BSI2004-A0138') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0138','R-R3-0367','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0368','R3-2026-07','Werden Methodik und Regeln für die Stabsarbeit nicht bereits in der Vorsorge erarbeitet, abgestimmt und in einem Verhaltenskodex zusammengefasst, muss Ihr Stab im Ernstfall improvisieren. Sie riskieren unkoordinierte Abläufe, Reibungsverluste und Fehlentscheidungen, weil grundlegende Spielregeln der Zusammenarbeit erst unter dem Druck der akuten Lage geklärt werden müssen.','BSI200_4','BSI2004-A0139') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0139','R-R3-0368','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0369','R3-2026-07','Sind die Rahmenbedingungen zur Konstituierung und Auflösung der BAO nicht im Vorfeld festgelegt, entsteht im Ernstfall Unklarheit darüber, wann der Stab formal aktiv wird und wann er endet. Sie riskieren einen verzögerten Start, Kompetenzstreitigkeiten und einen fließenden, unkontrollierten Übergang zurück in den Normalbetrieb ohne saubere Übergabe.','BSI200_4','BSI2004-A0140') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0140','R-R3-0369','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0370','R3-2026-07','Klärt und regelt der oder die BCB weitere Aspekte wie Arbeitsbedingungen und Protokollierung nicht zusätzlich schriftlich, bleiben wichtige organisatorische Fragen im Ernstfall offen. Sie riskieren, dass unter Belastung improvisiert wird, Entscheidungen unzureichend dokumentiert sind und arbeitsrechtliche oder organisatorische Konflikte die Handlungsfähigkeit Ihres Stabes beeinträchtigen.','BSI200_4','BSI2004-A0141') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0141','R-R3-0370','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0371','R3-2026-07','Wurde die Möglichkeit eines Schichtbetriebs für den Stab nicht geprüft, geregelt und dokumentiert und ist bei gewähltem Schichtbetrieb die Übergabe ungeregelt, droht bei länger andauernden Lagen Übermüdung. Sie riskieren Fehlentscheidungen erschöpfter Stabsmitglieder und Informationsverluste bei der Übergabe, wodurch die Bewältigung des Notfalls ernsthaft gefährdet wird.','BSI200_4','BSI2004-A0142') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0142','R-R3-0371','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0372','R3-2026-07','Sind abweichende Arbeitszeit- und Überstundenregelungen für den Notfall nicht geprüft, festgelegt und mit Rechtsabteilung und Personalvertretung abgestimmt, geraten Sie im Ernstfall in einen Konflikt zwischen Bewältigungsdruck und Arbeitsrecht. Sie riskieren rechtswidrigen Personaleinsatz, Haftungsfolgen und Auseinandersetzungen, die die dringend benötigte Handlungsfähigkeit Ihres Stabes zusätzlich schwächen.','BSI200_4','BSI2004-A0143') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0143','R-R3-0372','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0373','R3-2026-07','Wird die Stabsarbeit nicht so protokolliert, dass alle wesentlichen Aktivitäten, Entscheidungen samt Entscheidungsgrundlage und Beteiligte erfasst sind, verlieren Sie die Nachvollziehbarkeit Ihres Krisenmanagements. Sie können Entscheidungen im Nachhinein nicht rechtfertigen, erschweren Lessons Learned und stehen bei Aufsicht, Versicherung oder rechtlicher Auseinandersetzung ohne belastbaren Nachweis da.','BSI200_4','BSI2004-A0144') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0144','R-R3-0373','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0374','R3-2026-07','Ist keine Dokumentvorlage oder ein anderes Hilfsmittel für die Protokolle entwickelt, protokolliert Ihr Stab im Ernstfall unstrukturiert, lückenhaft oder gar nicht. Sie riskieren, dass wichtige Informationen unter Zeitdruck verloren gehen, Einträge uneinheitlich und schwer auswertbar sind und Ihnen später eine belastbare, nachvollziehbare Dokumentation der Krise fehlt.','BSI200_4','BSI2004-A0145') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0145','R-R3-0374','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0375','R3-2026-07','Sind keine Kriterien festgelegt, mit denen der Stab final über das Vorliegen eines Notfalls entscheidet, trifft Ihr Stab diese folgenreiche Entscheidung ohne einheitliche Grundlage. Sie riskieren willkürliche, inkonsistente oder verzögerte Einstufungen, unnötige Eskalationen ebenso wie übersehene echte Notfälle und verlieren wertvolle Zeit in der kritischen Bewertungsphase.','BSI200_4','BSI2004-A0146') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0146','R-R3-0375','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0376','R3-2026-07','Werden die Einstufungskriterien durch den Stab nicht ad hoc überprüft, wenn noch keine BIA-Ergebnisse vorliegen, entscheiden Sie möglicherweise auf einer unvollständigen oder unpassenden Basis. Sie riskieren, dass die Bewertung des Ereignisses nicht zur tatsächlichen Lage passt, Prioritäten falsch gesetzt werden und Ihre Reaktion die wirklich kritischen Prozesse verfehlt.','BSI200_4','BSI2004-A0147') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0147','R-R3-0376','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0377','R3-2026-07','Hat Ihre Institution keine standardisierten Abläufe zum Ausrufen und Deeskalieren eines Notfalls oder einer Krise festgelegt, entstehen an diesen entscheidenden Übergängen Unsicherheit und Verzögerung. Sie riskieren, dass der Notfall zu spät ausgerufen oder verfrüht beendet wird, Zuständigkeiten unklar bleiben und der Wechsel zwischen den Betriebszuständen unkontrolliert verläuft.','BSI200_4','BSI2004-A0148') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0148','R-R3-0377','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0378','R3-2026-07','Regelt die Geschäftsordnung die konkreten Einzelschritte der Startphase wie die Prüfung der Handlungs- und Entscheidungsfähigkeit des Stabes nicht, beginnt Ihre Stabsarbeit im Ernstfall ungeordnet. Sie riskieren, dass grundlegende Voraussetzungen übersprungen werden, der Stab handlungsunfähig startet und die erste, entscheidende Phase der Krisenbewältigung wertvolle Zeit verliert.','BSI200_4','BSI2004-A0149') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0149','R-R3-0378','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0379','R3-2026-07','Ist die BAO-Reaktionszeit nicht zentral festgelegt und kein zeitlicher Puffer eingeplant, fehlt Ihnen eine verbindliche Vorgabe, bis wann der Stab einsatzbereit sein muss. Sie riskieren, dass die Reaktion zu langsam anläuft, Verzögerungen nicht auffallen und die tolerierbaren Ausfallzeiten Ihrer kritischen Prozesse bereits überschritten sind, bevor der Stab arbeitet.','BSI200_4','BSI2004-A0150') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0150','R-R3-0379','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0380','R3-2026-07','Sind die Rechte und Pflichten der BAO nicht klar und ohne Interpretationsspielraum festgelegt, entstehen im Ernstfall Kompetenzstreitigkeiten und Unsicherheit über Befugnisse. Sie riskieren, dass notwendige Entscheidungen nicht getroffen oder überschritten werden, sich Verantwortliche gegenseitig blockieren und wertvolle Zeit mit Zuständigkeitsfragen statt mit der Bewältigung des Notfalls vergeht.','BSI200_4','BSI2004-A0151') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0151','R-R3-0380','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0381','R3-2026-07','Dokumentiert die Geschäftsordnung des Stabes personelle Besetzung, besondere Befugnisse, Konstituierung, Auflösung, Zusammenarbeitsmodell und Arbeitsbedingungen nicht, fehlt Ihrem Stab die verbindliche Handlungsgrundlage. Sie riskieren im Ernstfall Unklarheit über Rollen und Befugnisse, uneinheitliches Vorgehen und Entscheidungen, deren Legitimation später angezweifelt werden kann.','BSI200_4','BSI2004-A0152') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0152','R-R3-0381','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0382','R3-2026-07','Ist der Führungszyklus zur strukturierten Entscheidungsfindung nicht bereits in der Vorsorge definiert und in der Geschäftsordnung dokumentiert, entscheidet Ihr Stab im Ernstfall unsystematisch. Sie riskieren übereilte, schlecht begründete Entscheidungen, das Übersehen wichtiger Informationen und einen unkoordinierten Ablauf, der die Qualität und Geschwindigkeit Ihrer Krisenbewältigung deutlich verschlechtert.','BSI200_4','BSI2004-A0153') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0153','R-R3-0382','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0383','R3-2026-07','Hat Ihre Institution nicht vorab abgestimmt und dokumentiert, inwieweit im Not- oder Krisenfall ein Schichtbetrieb für den Stab möglich ist, sind Sie auf lang andauernde Lagen nicht vorbereitet. Sie riskieren, dass erschöpfte Stabsmitglieder ohne Ablösung weiterarbeiten, die Entscheidungsqualität sinkt und die Handlungsfähigkeit Ihres Stabes über die Zeit zusammenbricht.','BSI200_4','BSI2004-A0154') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0154','R-R3-0383','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0384','R3-2026-07','Sind der Wechsel zwischen den Arbeitsphasen und die Taktung der Besprechungen im Führungsrhythmus nicht geklärt und berücksichtigt, arbeitet Ihr Stab ohne verlässliche Struktur. Sie riskieren, dass Lagebesprechungen unregelmäßig stattfinden, Informationen nicht rechtzeitig zusammenlaufen und Entscheidungen entweder überhastet oder zu spät getroffen werden.','BSI200_4','BSI2004-A0155') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0155','R-R3-0384','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0385','R3-2026-07','Ist in der Geschäftsordnung des Stabs nicht geregelt, inwieweit Weisungen in die Institution gegeben und über Geldmittel verfügt werden dürfen, fehlt dem Stab im Ernstfall die nötige Durchsetzungs- und Handlungsfähigkeit. Sie riskieren, dass dringende Maßnahmen mangels Befugnis blockiert werden oder umgekehrt Befugnisse überschritten werden und dadurch Haftungs- und Compliance-Risiken entstehen.','BSI200_4','BSI2004-A0156') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0156','R-R3-0385','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0386','R3-2026-07','Sind die elementarsten Regeln nicht in einem Verhaltenskodex zusammengefasst, im Notfallhandbuch dokumentiert und den Stabsmitgliedern während der Arbeit zugänglich, fehlt im Ernstfall der schnelle Orientierungsrahmen. Sie riskieren, dass unter Stress grundlegende Verhaltensregeln missachtet werden, die Zusammenarbeit leidet und der Stab weniger diszipliniert und effektiv arbeitet.','BSI200_4','BSI2004-A0157') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0157','R-R3-0386','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0387','R3-2026-07','Ist durch Schulungen und Übungen nicht sichergestellt, dass alle Stabsmitglieder einschließlich Stellvertretender ihre Aufgaben im Not- und Krisenfall kennen, agieren sie im Ernstfall unsicher und ungeübt. Sie riskieren Fehlentscheidungen, langsame Reaktionen und Ausfälle, wenn eingearbeitete Personen fehlen und unvorbereitete Vertretungen einspringen müssen.','BSI200_4','BSI2004-A0158') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0158','R-R3-0387','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0388','R3-2026-07','Werden die Schulungsinhalte für die Stabsmitglieder nicht regelmäßig geprüft und angepasst, veralten die vermittelten Kenntnisse und passen nicht mehr zu aktuellen Bedrohungen, Prozessen und Zuständigkeiten. Sie riskieren, dass Ihr Stab nach überholten Vorgaben handelt, neue Risiken nicht kennt und im Ernstfall auf Grundlage falscher oder lückenhafter Annahmen entscheidet.','BSI200_4','BSI2004-A0159') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0159','R-R3-0388','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0389','R3-2026-07','Nehmen nicht alle Mitglieder der BAO einschließlich Vertretender mindestens einmal in drei Jahren an einer Übung teil, fehlt ihnen die praktische Routine für den Schadensfall. Sie riskieren, dass Abläufe im Ernstfall zum ersten Mal ausprobiert werden, Schwachstellen unentdeckt bleiben und der Stab unter realem Druck deutlich langsamer und fehleranfälliger reagiert.','BSI200_4','BSI2004-A0160') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0160','R-R3-0389','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0390','R3-2026-07','Sind für die Lagebeobachtung nicht die zuständigen Rollen, die Quellen, die Vorgaben zum Medienmonitoring und die Erreichbarkeit der Personen am Ort des Geschehens festgelegt, bleibt Ihr Lagebild im Ernstfall lückenhaft. Sie riskieren, dass wichtige Entwicklungen zu spät erkannt werden, Entscheidungen auf veralteten Informationen beruhen und Sie von der realen Lage überrascht werden.','BSI200_4','BSI2004-A0161') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0161','R-R3-0390','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0391','R3-2026-07','Sind die Elemente der Lagevisualisierung wie Detailgrad, fortlaufende Aktualisierung, Aufgabenübersicht mit Status und Priorisierung, Stabsbesetzung und Kommunikationsübersicht nicht festgelegt, fehlt Ihrem Stab ein gemeinsames, aktuelles Lagebild. Sie riskieren Missverständnisse, doppelte oder vergessene Aufgaben und Entscheidungen auf unvollständiger Grundlage, weil niemand den Gesamtüberblick über die Krise behält.','BSI200_4','BSI2004-A0162') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0162','R-R3-0391','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0392','R3-2026-07','Werden nicht bevorzugt gesicherte Informationen visualisiert und Vermutungen sowie Annahmen nicht als solche kenntlich gemacht, vermischen sich Fakten und Spekulation im Lagebild. Sie riskieren, dass Ihr Stab unbestätigte Annahmen für gesicherte Tatsachen hält, darauf folgenschwere Entscheidungen aufbaut und die Krise auf Basis eines verzerrten Lagebildes falsch bewertet.','BSI200_4','BSI2004-A0163') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0163','R-R3-0392','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0393','R3-2026-07','Ist die Rolle Visualisierung nicht ausführlich geschult oder sind ansonsten nicht alle Mitglieder des Kernteams mit den Grundsätzen der Lagevisualisierung vertraut, entsteht im Ernstfall ein unübersichtliches oder fehlerhaftes Lagebild. Sie riskieren, dass wichtige Informationen falsch dargestellt oder übersehen werden und Ihr Stab dadurch schlechter informierte Entscheidungen trifft.','BSI200_4','BSI2004-A0164') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0164','R-R3-0393','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0394','R3-2026-07','Hat Ihre Institution keinen Stabsraum samt Ausstattung festgelegt, geplant, beschafft und eingerichtet, der im Notfall zeitnah verfügbar und einsatzfähig ist, fehlt Ihrem Stab der zentrale Arbeitsort. Sie riskieren, dass sich die Handlungsfähigkeit verzögert, Kommunikation und Koordination improvisiert ablaufen und wertvolle Zeit mit der Suche nach Räumen und Technik vergeht.','BSI200_4','BSI2004-A0165') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0165','R-R3-0394','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0395','R3-2026-07','Ist der Stabsraum nicht für alle Stabsmitglieder in angemessener Zeit erreichbar und nicht auch außerhalb der üblichen Arbeitszeiten jederzeit zugänglich, kann Ihr Stab im Ernstfall nicht rechtzeitig zusammenkommen. Sie riskieren, dass sich der Aufbau der Notfallorganisation verzögert, insbesondere nachts oder am Wochenende, und wertvolle Zeit in der kritischen Anfangsphase verloren geht.','BSI200_4','BSI2004-A0166') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0166','R-R3-0395','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0396','R3-2026-07','Sind die Stabsmitglieder und ihre Stellvertretenden nicht mit den nötigen Zutrittsmitteln und -rechten für alle erforderlichen Räumlichkeiten ausgestattet, stehen sie im Ernstfall vor verschlossenen Türen. Sie riskieren, dass zentrale Personen den Stabsraum oder wichtige Bereiche nicht betreten können, die Handlungsfähigkeit sich verzögert und die Krisenreaktion an einem organisatorischen Detail scheitert.','BSI200_4','BSI2004-A0167') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0167','R-R3-0396','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0397','R3-2026-07','Lassen sich die Zutrittsregelungen für kurzfristig hinzugezogene Stabsmitglieder nicht zeitnah erweitern, stehen benötigte Fachleute im Notfall vor verschlossenen Türen. Sie verlieren wertvolle Zeit, die Handlungsfähigkeit des Stabs sinkt, und Entscheidungen zur Bewältigung des Schadensereignisses verzögern sich unnötig.','BSI200_4','BSI2004-A0168') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0168','R-R3-0397','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0398','R3-2026-07','Überprüfen Sie nicht durch Begehungen oder Stabsübungen, ob der Stabsraum jederzeit für alle Mitglieder zugänglich ist, bleiben verschlossene Wege, defekte Zugänge oder Sperrzeiten unentdeckt. Im Ernstfall kann der Stab dann nicht zusammentreten, wodurch die Notfallbewältigung ins Stocken gerät und sich der Schaden ausweitet.','BSI200_4','BSI2004-A0169') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0169','R-R3-0398','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0399','R3-2026-07','Ist bei anderweitiger Nutzung des Stabsraums nicht organisatorisch geregelt, dass sein Einsatz als Stabsraum Vorrang hat, kann er im Notfall belegt oder umgebaut sein. Sie müssen den Stab dann improvisiert an anderer Stelle einrichten, was Zeit kostet und die koordinierte Krisenbewältigung erheblich erschwert.','BSI200_4','BSI2004-A0170') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0170','R-R3-0399','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0400','R3-2026-07','Haben Sie keinen alternativen Stabsraum an einem Ausweichstandort mit vergleichbaren Gegebenheiten definiert, fällt bei Ausfall des Hauptraums die zentrale Führungsstelle ersatzlos weg. Der Stab kann dann nicht arbeiten, die Notfallbewältigung bricht zusammen und der Schaden vergrößert sich unkontrolliert.','BSI200_4','BSI2004-A0171') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0171','R-R3-0400','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0401','R3-2026-07','Ist der Stabsraum nicht gegen Ausfälle der Grundversorgung wie Strom, Wasser oder Wärme abgesichert, etwa durch eigene Notstromversorgung, fallen bei einem Versorgungsausfall Beleuchtung, Kommunikation und IT aus. Sie können den Stab dann nicht mehr betreiben und verlieren genau in der kritischen Phase die Handlungsfähigkeit.','BSI200_4','BSI2004-A0172') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0172','R-R3-0401','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0402','R3-2026-07','Stellen Sie nicht sicher, dass die Sicherheitsanforderungen der Institution bei Planung und Betrieb aller Stabsräume eingehalten werden, drohen unbefugter Zugriff und der Verlust vertraulicher Informationen. Sensible Lagedaten können abfließen, wodurch Sie zusätzlich zum eigentlichen Notfall einen Sicherheitsvorfall bewältigen müssen.','BSI200_4','BSI2004-A0173') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0173','R-R3-0402','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0403','R3-2026-07','Überprüfen Sie die Ausstattung aller Stabsräume nicht regelmäßig auf Vollständigkeit, Aktualität und Funktionsfähigkeit, entdecken Sie fehlende oder defekte Mittel erst im Ernstfall. Der Stab kann dann nicht arbeitsfähig starten, wichtige Hilfsmittel fehlen und die Reaktion auf das Schadensereignis verzögert sich.','BSI200_4','BSI2004-A0174') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0174','R-R3-0403','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0404','R3-2026-07','Halten Sie im Stabsraum keine ausreichenden und geeigneten Materialien zur Visualisierung der Lage vor, kann der Stab das Geschehen nicht übersichtlich darstellen. Sie verlieren den gemeinsamen Überblick, Absprachen werden fehleranfällig und Entscheidungen fallen auf unvollständiger Grundlage.','BSI200_4','BSI2004-A0175') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0175','R-R3-0404','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0405','R3-2026-07','Halten Sie die notfallrelevante BCM-Dokumentation nicht doppelt, also im Stabsraum und zentral zugänglich, vor, kann ein Ausfall eines Ablageorts alle Unterlagen unerreichbar machen. Dem Stab fehlen dann Pläne und Handlungsanweisungen, sodass die Notfallbewältigung ohne verlässliche Grundlage improvisiert werden muss.','BSI200_4','BSI2004-A0176') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0176','R-R3-0405','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0406','R3-2026-07','Drucken Sie papierhafte Dokumente bei Aktualisierungen nicht neu aus und tauschen sie an den Ablageorten aus, arbeitet der Stab im Notfall mit veralteten Fassungen. Falsche Kontakte oder überholte Abläufe führen zu Fehlentscheidungen, und der Verbleib alter Ausdrucke gefährdet zudem Informationssicherheit und Datenschutz.','BSI200_4','BSI2004-A0177') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0177','R-R3-0406','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0407','R3-2026-07','Sind die Vorgaben zur Stabsarbeit sowie zur Alarmierung und Eskalation, insbesondere die zentrale Entscheidungsinstanz, der Institutionsleitung nicht vorgelegt und von ihr freigegeben, fehlt den Abläufen die verbindliche Legitimation. Im Ernstfall sind Zuständigkeiten unklar, Entscheidungen werden angezweifelt und die Notfallbewältigung verzögert sich.','BSI200_4','BSI2004-A0178') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0178','R-R3-0407','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0408','R3-2026-07','Setzen Sie die aus der Freigabe erforderlichen Maßnahmen nicht um und verfolgen sie nicht im Maßnahmenplan nach, bleiben beschlossene Verbesserungen auf dem Papier. Bekannte Schwachstellen bestehen fort, und im nächsten Notfall wirken die eigentlich vorgesehenen Schutzvorkehrungen nicht.','BSI200_4','BSI2004-A0179') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0179','R-R3-0408','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0409','R3-2026-07','Ist die Notfall- und Krisenkommunikation nicht im Vorfeld vorbereitet, geplant und dokumentiert, einschließlich verbindlicher Regeln zu interner und externer Kommunikation, müssen Sie im Ernstfall unter Druck improvisieren. Widersprüchliche oder verspätete Botschaften verunsichern Beteiligte und beschädigen das Vertrauen in Ihre Institution.','BSI200_4','BSI2004-A0180') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0180','R-R3-0409','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0410','R3-2026-07','Ist die Notfall- und Krisenkommunikation nicht auf die Meldepflichten der Institution abgestimmt, können gesetzlich vorgeschriebene Meldungen verspätet, unvollständig oder gar nicht erfolgen. Sie riskieren Rechtsverstöße, Bußgelder und den Verlust von Glaubwürdigkeit gegenüber Aufsichtsbehörden und Öffentlichkeit.','BSI200_4','BSI2004-A0181') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0181','R-R3-0410','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0411','R3-2026-07','Sind die Kommunikationsmöglichkeiten nicht bekannt und die Kommunikationstechnik nicht einsatzbereit, erreichen Sie im Notfall die Interessengruppen nicht rechtzeitig auf geeignetem Weg. Wichtige Warnungen und Abstimmungen verzögern sich, wodurch sich das Schadensereignis unkontrolliert ausweiten kann.','BSI200_4','BSI2004-A0182') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0182','R-R3-0411','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0412','R3-2026-07','Erfüllen die Kommunikationsmittel nicht die Anforderungen an Ausfallsicherheit, Redundanz und Schutz der vertraulichen Kommunikation, kann die Verständigung im Ernstfall ausfallen oder abgehört werden. Der Stab verliert dann die Verbindung zu wichtigen Beteiligten, und sensible Informationen geraten in falsche Hände.','BSI200_4','BSI2004-A0183') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0183','R-R3-0412','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0413','R3-2026-07','Legen Sie die anzuwendenden Kommunikationskanäle und Medienformate nicht vorab fest, entsteht im Notfall Unsicherheit darüber, wer worüber informiert wird. Botschaften erreichen die Empfänger verspätet oder auf ungeeignetem Weg, und die Reaktion auf das Ereignis wird unnötig verzögert.','BSI200_4','BSI2004-A0184') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0184','R-R3-0413','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0414','R3-2026-07','Sind bei mehreren für die Kommunikation zuständigen Personen die Aufgaben und Zuständigkeiten nicht festgelegt und dokumentiert, kommt es im Ernstfall zu Doppelarbeit oder Lücken. Widersprüchliche Aussagen nach außen und intern schwächen Ihre Glaubwürdigkeit und erschweren die geordnete Krisenbewältigung.','BSI200_4','BSI2004-A0185') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0185','R-R3-0414','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0415','R3-2026-07','Stellen Sie nicht sicher, dass die Mitarbeitenden mindestens die erforderlichen Details des Schadensereignisses kennen, insbesondere wenn diese ihre persönliche Situation betreffen, entstehen Verunsicherung und Gerüchte. Beschäftigte treffen dann falsche Entscheidungen für sich selbst, und das Vertrauen in die Institution leidet spürbar.','BSI200_4','BSI2004-A0186') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0186','R-R3-0415','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0416','R3-2026-07','Stellen Sie relevante Informationen zum Status der Notfallbewältigung nicht bereit, vor allem den Mitarbeitenden mit Kontakt zu externen Interessengruppen, geben diese veraltete oder falsche Auskünfte. Nach außen entsteht ein widersprüchliches Bild, das die Glaubwürdigkeit Ihrer Institution im Krisenfall beschädigt.','BSI200_4','BSI2004-A0187') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0187','R-R3-0416','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0417','R3-2026-07','Liegen für die externe Kommunikation keine gründliche Analyse der Interessengruppen, keine Kommunikationsstrategie und kein Kommunikationskonzept vor, kommunizieren Sie im Ernstfall planlos. Wichtige Zielgruppen werden übersehen oder falsch angesprochen, sodass Fehlinformationen und Reputationsschäden entstehen.','BSI200_4','BSI2004-A0188') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0188','R-R3-0417','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0418','R3-2026-07','Sind keine Pressesprecherin oder kein Pressesprecher und eine Vertretung namentlich benannt und intern wie extern veröffentlicht, fehlt im Krisenfall eine klare Ansprechperson. Medien und Öffentlichkeit erhalten unkoordinierte oder widersprüchliche Aussagen, was den Reputationsschaden für Ihre Institution vergrößert.','BSI200_4','BSI2004-A0189') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0189','R-R3-0418','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0419','R3-2026-07','Beobachten Sie im Not- oder Krisenfall die Medien nicht stetig durch Medienmonitoring, bemerken Sie Fehldarstellungen und Gerüchte zu spät. Falsche Berichterstattung verbreitet sich ungehindert, und Sie können kommunikative Gegenmaßnahmen nicht rechtzeitig einleiten, wodurch der Reputationsschaden wächst.','BSI200_4','BSI2004-A0190') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0190','R-R3-0419','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0420','R3-2026-07','Erklärt der Stab nach Überwindung des Schadensereignisses den Notfall nicht offiziell für beendet und kommuniziert diese Entscheidung nicht innerhalb der Institution, bleiben Beteiligte im Ausnahmemodus. Ressourcen werden unnötig gebunden, und es entsteht Unsicherheit, ob der Normalbetrieb wieder gilt.','BSI200_4','BSI2004-A0191') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0191','R-R3-0420','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0421','R3-2026-07','Entwickeln Sie keine Checkliste mit konkreten Prüfpunkten und Entscheidungen für die Rückführung in den Normalbetrieb, erfolgt die Wiederaufnahme unstrukturiert. Wichtige Schritte werden übersehen, und Sie riskieren, dass ungelöste Probleme in den Regelbetrieb übernommen werden und dort erneut zu Störungen führen.','BSI200_4','BSI2004-A0192') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0192','R-R3-0421','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0422','R3-2026-07','Sind für die Deeskalation keine geeigneten Kriterien und Zuständigkeiten definiert, wird der Notfall zu früh oder zu spät für beendet erklärt. Bei verfrühter Entwarnung flammt das Schadensereignis erneut auf, bei verspäteter binden Sie unnötig Ressourcen und belasten die Beteiligten.','BSI200_4','BSI2004-A0193') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0193','R-R3-0422','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0423','R3-2026-07','Ist durch Vorgaben nicht sichergestellt, dass nach jedem Notfall analysiert wird, welche Korrektur- und Verbesserungsmaßnahmen nötig sind, bleiben die Ursachen im Dunkeln. Ihre Institution lernt nicht aus dem Ereignis, und dieselben Schwachstellen führen beim nächsten Vorfall erneut zu Schäden.','BSI200_4','BSI2004-A0194') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0194','R-R3-0423','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0424','R3-2026-07','Führen Sie nicht sowohl eine Analyse zeitnah zum Schadensereignis als auch eine weitere mit zeitlichem Abstand durch, gehen wichtige Erkenntnisse verloren. Frische Details verblassen ohne die erste, langfristige Auswirkungen bleiben ohne die zweite unentdeckt, sodass Ihre Verbesserungen unvollständig ausfallen.','BSI200_4','BSI2004-A0195') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0195','R-R3-0424','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0425','R3-2026-07','Ist nicht sichergestellt, dass die Analyseergebnisse dokumentiert und an die Institutionsleitung berichtet werden, bleiben Erkenntnisse in Einzelköpfen. Die Leitung kann keine fundierten Entscheidungen über Verbesserungen treffen, notwendige Ressourcen werden nicht bereitgestellt und die gleichen Mängel bestehen fort.','BSI200_4','BSI2004-A0196') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0196','R-R3-0425','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0426','R3-2026-07','Initiieren Sie bei identifizierten Mängeln nicht zeitnah entsprechende Korrektur- und Verbesserungsmaßnahmen, bleiben erkannte Schwachstellen bestehen. Der Wert der Analyse verpufft, und beim nächsten Notfall wirken sich dieselben Defizite erneut aus und verursachen vermeidbaren Schaden.','BSI200_4','BSI2004-A0197') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0197','R-R3-0426','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0427','R3-2026-07','Nehmen Sie die Verbesserungsbedarfe des BCMS nicht in den Maßnahmenplan des BCM auf, geraten sie ohne verbindliche Nachverfolgung in Vergessenheit. Notwendige Weiterentwicklungen bleiben aus, das Notfallmanagement veraltet und schützt Ihre Institution im Ernstfall nur unzureichend.','BSI200_4','BSI2004-A0198') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0198','R-R3-0427','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0428','R3-2026-07','Wählt der oder die BCB keinen für die eigene Institution geeigneten Ansatz für den BIA-Vorfilter aus und passt ihn nicht an, liefert die Vorauswahl unpassende Ergebnisse. Sie übersehen dann zeitkritische Bereiche oder analysieren die falschen, wodurch die gesamte weitere Notfallplanung auf falscher Grundlage steht.','BSI200_4','BSI2004-A0199') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0199','R-R3-0428','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0429','R3-2026-07','Ist die Institutionsleitung nicht aktiv in den BIA-Vorfilter eingebunden, trägt niemand bewusst das Risiko der nicht berücksichtigten Bereiche. Wichtige Prozesse können unbeabsichtigt aus der Betrachtung fallen, und im Notfall stellt sich heraus, dass kritische Bereiche ungeschützt geblieben sind.','BSI200_4','BSI2004-A0200') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0200','R-R3-0429','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0430','R3-2026-07','Ist keine mit der Institutionsleitung abgestimmte Leitfrage zur einheitlichen Bestimmung des Begriffs zeitkritisch definiert, bevor Sie mit dem BIA-Vorfilter beginnen, bewerten Beteiligte uneinheitlich. Die Ergebnisse werden inkonsistent und angreifbar, sodass Ihre Priorisierung der schützenswerten Prozesse unzuverlässig ausfällt.','BSI200_4','BSI2004-A0201') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0201','R-R3-0430','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0431','R3-2026-07','Ist der Untersuchungszeitraum des BIA-Vorfilters nicht kleiner als der abzusichernde Zeitraum des BCMS und nicht ausreichend kurz gewählt, verzerren sich die Ergebnisse. Sie stufen Prozesse falsch als unkritisch ein und lassen tatsächlich zeitkritische Bereiche ungeschützt, was sich im Notfall gefährlich auswirkt.','BSI200_4','BSI2004-A0202') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0202','R-R3-0431','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0432','R3-2026-07','Ist mit der Institutionsleitung nicht konkret festgelegt, welches Schadenspotenzial als zu hoch gilt, fehlt dem BIA-Vorfilter ein verbindlicher Maßstab. Die Einstufungen werden willkürlich, kritische Prozesse können übersehen werden und die Ergebnisse sind gegenüber der Leitung nicht belastbar.','BSI200_4','BSI2004-A0203') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0203','R-R3-0432','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0433','R3-2026-07','Führen Sie den BIA-Vorfilter nicht im Rahmen moderierter Workshops durch, fehlt der strukturierte Austausch der Fachbereiche. Wichtiges Wissen bleibt ungenutzt, Einschätzungen werden einseitig, und Sie riskieren, dass zeitkritische Abhängigkeiten unerkannt bleiben.','BSI200_4','BSI2004-A0204') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0204','R-R3-0433','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0434','R3-2026-07','Legt der oder die BCB nicht in Abstimmung mit der Institutionsleitung fest, wie viele Hierarchieebenen im BIA-Vorfilter berücksichtigt werden, wird die Analyse zu grob oder zu detailliert. Bei zu grober Betrachtung übersehen Sie kritische Einheiten, bei zu feiner binden Sie unnötig Aufwand.','BSI200_4','BSI2004-A0205') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0205','R-R3-0434','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0435','R3-2026-07','Überprüft der oder die BCB nicht, ob die Ergebnisse des BIA-Vorfilters plausibel sind, übernehmen Sie möglicherweise fehlerhafte Einstufungen ungeprüft. Falsch als unkritisch bewertete Prozesse bleiben dann ohne Schutz, und der Fehler pflanzt sich durch die gesamte weitere Notfallplanung fort.','BSI200_4','BSI2004-A0206') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0206','R-R3-0435','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0436','R3-2026-07','Fasst der oder die BCB die als zeitkritisch ausgewählten Einheiten nicht in einer Gesamtübersicht zusammen, fehlt der klare Überblick über den Schutzbedarf. Einzelne kritische Bereiche können übersehen werden, und die Institutionsleitung kann keine fundierte Entscheidung über den weiteren BCM-Umfang treffen.','BSI200_4','BSI2004-A0207') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0207','R-R3-0436','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0437','R3-2026-07','Stellt der oder die BCB der Institutionsleitung die Ergebnisse des BIA-Vorfilters nicht vor, entscheidet die Leitung ohne Kenntnis der zeitkritischen Bereiche. Notwendige Ressourcen werden nicht bereitgestellt, und die Verantwortung für nicht abgesicherte Prozesse bleibt ungeklärt.','BSI200_4','BSI2004-A0208') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0208','R-R3-0437','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0438','R3-2026-07','Überprüft die Institutionsleitung nicht, ob der Analysebereich der BIA angemessen eingegrenzt wurde, kann die Untersuchung zu eng oder zu weit angelegt sein. Bei zu enger Eingrenzung übersehen Sie schützenswerte Prozesse, bei zu weiter verzetteln Sie sich und binden Ressourcen ohne Mehrwert.','BSI200_4','BSI2004-A0209') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0209','R-R3-0438','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0439','R3-2026-07','Überarbeiten Sie bei unangemessener Eingrenzung die Parameter nicht oder wählen keine alternative Methode und wiederholen den BIA-Vorfilter nicht, bauen Sie die weitere Notfallplanung auf einer fehlerhaften Grundlage auf. Kritische Prozesse bleiben unberücksichtigt, und der gesamte BCM-Aufwand schützt die Institution nur unzureichend.','BSI200_4','BSI2004-A0210') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0210','R-R3-0439','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0440','R3-2026-07','Gilt der BIA-Vorfilter bereits als abgeschlossen, bevor die Institutionsleitung die Ergebnisse freigegeben hat, fehlt die verbindliche Legitimation der Vorauswahl. Spätere Einwände der Leitung können die gesamte Analyse infrage stellen, sodass Sie den Vorfilter erneut durchführen müssen und wertvolle Zeit verlieren.','BSI200_4','BSI2004-A0211') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0211','R-R3-0440','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0441','R3-2026-07','Wenn Sie die Prozessabhängigkeiten zeitkritischer Geschäftsprozesse nicht ermitteln, übersehen Sie verdeckte Wirkungsketten, über die ein Ausfall auf weitere Bereiche durchschlägt. Im Notfall planen Sie Wiederanläufe in falscher Reihenfolge, benötigte Vorprozesse fehlen, und die eigentlich zeitkritischen Abläufe kommen deutlich später wieder in Gang als vorgesehen.','BSI200_4','BSI2004-A0212') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0212','R-R3-0441','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0442','R3-2026-07','Gehen Sie in der Business Impact Analyse nicht vom Totalausfall im Worst Case aus, unterschätzen Sie das tatsächliche Schadenspotenzial systematisch. Ihre Wiederanlaufziele und Ressourcenvorsorge fallen dann zu knapp aus, sodass Sie bei einem schweren Ausfall unvorbereitet sind und tragbare Schadensgrenzen unbemerkt überschreiten.','BSI200_4','BSI2004-A0213') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0213','R-R3-0442','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0443','R3-2026-07','Ist Ihre RTO nicht zwingend kürzer als die MTPD und fehlt der zeitliche Puffer, riskieren Sie, dass der Wiederanlauf zu spät erfolgt. Der Geschäftsprozess erreicht dann das Untragbarkeitsniveau, und es entstehen irreversible Schäden, weil kein Spielraum für Verzögerungen oder unvorhergesehene Störungen im Notfall bleibt.','BSI200_4','BSI2004-A0214') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0214','R-R3-0443','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0444','R3-2026-07','Legen Sie Vorgehensweise, Methodik, Rollen und Hilfsmittel der BIA nicht einheitlich fest und dokumentieren sie schriftlich, erheben Beteiligte uneinheitlich und nicht nachvollziehbar. Ergebnisse werden unvergleichbar und fehleranfällig, Wissen geht bei Personalwechsel verloren, und die BIA lässt sich weder prüfen noch verlässlich wiederholen.','BSI200_4','BSI2004-A0215') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0215','R-R3-0444','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0445','R3-2026-07','Identifizieren Sie nicht alle im aktuellen Geltungsbereich zu bewertenden Geschäftsprozesse, bleiben einzelne Abläufe unbewertet. Übersehene zeitkritische Prozesse erhalten keine Notfallvorsorge, sodass Sie im Ernstfall ausgerechnet dort ohne Wiederanlaufplanung dastehen und unerwartet hohe Schäden erleiden, die Ihre BIA eigentlich hätte aufdecken sollen.','BSI200_4','BSI2004-A0216') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0216','R-R3-0445','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0446','R3-2026-07','Prüfen Sie vorhandene Prozessübersichten nicht auf Vollständigkeit und Aktualität, arbeiten Sie mit einer veralteten Grundlage. Fehlende oder überholte Prozesse fließen dann nicht in die BIA ein, wichtige zeitkritische Abläufe bleiben unentdeckt, und Ihre gesamte Notfallvorsorge baut auf einem lückenhaften Bild der Organisation auf.','BSI200_4','BSI2004-A0217') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0217','R-R3-0446','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0447','R3-2026-07','Erheben oder aktualisieren Sie eine fehlende Prozessübersicht nicht im Rahmen der BIA, bleiben Abhängigkeiten und zeitkritische Abläufe unbekannt. Sie bewerten dann auf unvollständiger Basis, übersehen kritische Prozesse und deren Verflechtungen und treffen Fehlentscheidungen bei der Priorisierung Ihrer Notfallvorsorge mit entsprechend hohem Restrisiko.','BSI200_4','BSI2004-A0218') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0218','R-R3-0447','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0448','R3-2026-07','Legen Sie vor der BIA Abstraktionsebene und Detailgrad der Geschäftsprozesse nicht fest und richten sie nicht an Ihren Strukturen aus, wird die Erhebung uneinheitlich. Zu grobe Betrachtung verdeckt kritische Abläufe, zu feine erzeugt kaum beherrschbaren Aufwand, und die Ergebnisse werden unbrauchbar oder nicht vergleichbar.','BSI200_4','BSI2004-A0219') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0219','R-R3-0448','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0449','R3-2026-07','Berücksichtigt Ihre BIA nicht alle Hierarchieebenen der Organisationseinheiten, sondern nur die unterste, entgehen Ihnen übergreifende Abhängigkeiten und aggregierte Auswirkungen. Sie unterschätzen so das Zusammenspiel mehrerer Einheiten und übersehen, dass ein Ausfall auf höherer Ebene weitreichendere Folgen hat als die Summe der Einzelbetrachtungen.','BSI200_4','BSI2004-A0220') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0220','R-R3-0449','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0450','R3-2026-07','Legen Sie für die Bewertung des Schadenspotenzials keine nachvollziehbaren, an Ihrer Institution ausgerichteten Zeithorizonte fest, lässt sich der zeitliche Schadensverlauf nicht sauber abbilden. Die Bestimmung von MTPD und RTO wird beliebig, Bewertungen sind nicht vergleichbar, und Ihre Notfallplanung beruht auf willkürlich gewählten Zeitpunkten.','BSI200_4','BSI2004-A0221') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0221','R-R3-0450','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0451','R3-2026-07','Definieren Sie für Zeithorizonte und Schadenspotenziale keine eindeutigen Skalenwerte, bewerten verschiedene Personen dasselbe Schadensausmaß unterschiedlich. Die Ergebnisse werden inkonsistent und nicht vergleichbar, sodass Sie zeitkritische Prozesse falsch priorisieren und Ihre Ableitung von Wiederanlaufzielen auf einer uneinheitlichen, wenig belastbaren Bewertungsgrundlage steht.','BSI200_4','BSI2004-A0222') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0222','R-R3-0451','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0452','R3-2026-07','Legen Sie kein Untragbarkeitsniveau anhand der definierten Parameter fest, fehlt der objektive Schwellenwert für nicht mehr hinnehmbare Schäden. Sie können die MTPD nicht eindeutig bestimmen, bewerten die Zeitkritikalität von Prozessen willkürlich und riskieren, Wiederanlaufziele zu spät oder gar nicht an einer belastbaren Grenze auszurichten.','BSI200_4','BSI2004-A0223') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0223','R-R3-0452','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0453','R3-2026-07','Richtet sich Ihr längster betrachteter Zeithorizont nicht am festgelegten abzusichernden Zeitraum aus, entsteht eine Lücke zwischen Analyse und Absicherungsziel. Schäden, die erst nach dem betrachteten Horizont ihr volles Ausmaß erreichen, bleiben unbewertet, und Ihre Notfallvorsorge deckt den eigentlich vorgesehenen Betrachtungszeitraum nicht vollständig ab.','BSI200_4','BSI2004-A0224') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0224','R-R3-0453','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0454','R3-2026-07','Richten sich Ihre Schadensszenarien nicht an den Rahmenbedingungen der Institution aus und lassen indirekte Schäden außer Acht, unterschätzen Sie die tatsächlichen Folgen eines Ausfalls. Reputations-, Folge- und Kaskadenschäden bleiben unberücksichtigt, sodass Ihre Bewertung zu optimistisch ausfällt und die abgeleitete Vorsorge dem realen Risiko nicht gerecht wird.','BSI200_4','BSI2004-A0225') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0225','R-R3-0454','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0455','R3-2026-07','Betrachten Sie nicht mindestens die Szenarien persönliche Unversehrtheit, Aufgabenerfüllung, Verstoß gegen Gesetze, Vorschriften und Verträge, Imageschaden und finanzielle Auswirkungen, bleiben ganze Schadensdimensionen unbewertet. Sie übersehen so etwa Haftungs- oder Reputationsfolgen, priorisieren Prozesse falsch und schätzen das Gesamtrisiko eines Ausfalls deutlich zu niedrig ein.','BSI200_4','BSI2004-A0226') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0226','R-R3-0455','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0456','R3-2026-07','Definieren Sie das Schadenspotenzial nicht für alle Schadensszenarien anhand verschiedener Schadenskategorien, bleibt die Bewertung grob und angreifbar. Einzelne Schadensarten werden über- oder unterschätzt, die Einstufung der Prozesse wird uneinheitlich, und Sie können Ihre Priorisierung im Ernstfall gegenüber Leitung und Prüfern nicht nachvollziehbar begründen.','BSI200_4','BSI2004-A0227') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0227','R-R3-0456','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0457','R3-2026-07','Definieren Sie die Anzahl der Schadenskategorien nicht einheitlich über alle Schadensszenarien, werden die Bewertungen untereinander unvergleichbar. Ein Szenario erscheint dann nur wegen der feineren oder gröberen Unterteilung schwerer oder leichter, sodass Sie Prozesse verzerrt priorisieren und Ihre BIA-Ergebnisse insgesamt an Aussagekraft und Nachvollziehbarkeit verlieren.','BSI200_4','BSI2004-A0228') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0228','R-R3-0457','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0458','R3-2026-07','Trifft nicht die Institutionsleitung die Entscheidung über das Untragbarkeitsniveau, fehlt der maßgeblichen Schwelle die notwendige Legitimation und Verantwortung. Fachbereiche setzen die Grenze dann uneinheitlich oder zu risikofreudig an, die Leitung trägt Restrisiken unwissentlich mit, und Ihre Notfallvorsorge ist im Zweifel nicht ausreichend abgesichert.','BSI200_4','BSI2004-A0229') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0229','R-R3-0458','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0459','R3-2026-07','Erheben Sie in der BIA nicht die Ressourcenabhängigkeiten der zeitkritischen Geschäftsprozesse, wissen Sie nicht, welche Mittel für den Notbetrieb unverzichtbar sind. Im Ernstfall fehlen dann benötigte IT, Personal oder Infrastruktur unbemerkt, der Wiederanlauf verzögert sich, und Ihre RTO lässt sich nicht einhalten.','BSI200_4','BSI2004-A0230') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0230','R-R3-0459','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0460','R3-2026-07','Legen Sie nicht fest, welche Ressourcenkategorien relevant sind, und ordnen ihnen keine konkreten Ressourcen zu, bleibt die Ressourcenerhebung lückenhaft. Wichtige Abhängigkeiten werden übersehen, Sie planen die Notfallvorsorge auf unvollständiger Basis, und im Ernstfall fehlen genau die Mittel, die Sie nie systematisch erfasst haben.','BSI200_4','BSI2004-A0231') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0231','R-R3-0460','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0461','R3-2026-07','Berücksichtigen Sie nicht mindestens die Ressourcenkategorien IT, Personal, Infrastruktur und Dienstleistungen, entstehen blinde Flecken in Ihrer Abhängigkeitsanalyse. Ein Ausfall von Personal oder Dienstleistern bleibt dann unbewertet, obwohl er den Notbetrieb genauso verhindern kann wie fehlende IT, und Ihre Wiederanlaufplanung greift zu kurz.','BSI200_4','BSI2004-A0232') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0232','R-R3-0461','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0462','R3-2026-07','Verwenden Sie im produzierenden Gewerbe nicht zusätzlich die Kategorien Maschinen, Geräte, Anlagen, Fahrzeuge und Betriebsmittel, übersehen Sie zentrale physische Abhängigkeiten Ihrer Produktion. Der Ausfall einer Anlage oder fehlender Betriebsmittel bleibt unbewertet, sodass Ihre Notfallvorsorge die tatsächlich produktionskritischen Ressourcen nicht abdeckt und der Wiederanlauf scheitert.','BSI200_4','BSI2004-A0233') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0233','R-R3-0462','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0463','R3-2026-07','Fassen Sie einzelne Ressourcen nicht sinnvoll zu Ressourcenclustern zusammen, wird die BIA durch eine unübersichtliche Vielzahl von Einzelressourcen aufgebläht. Der Aufwand steigt stark, wesentliche Abhängigkeiten gehen im Detail unter, und Sie verlieren den Blick für die wirklich kritischen Ressourcenverbünde, die den Notbetrieb tatsächlich tragen.','BSI200_4','BSI2004-A0234') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0234','R-R3-0463','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0464','R3-2026-07','Legen Sie vor Beginn der BIA nicht fest, in welchem Format die Informationen erhoben werden, liefern die Beteiligten uneinheitliche und schwer zusammenführbare Angaben. Die Auswertung wird aufwendig und fehleranfällig, Ergebnisse sind kaum vergleichbar, und wichtige Angaben fehlen oder liegen in einer Form vor, die Sie nicht verlässlich weiterverarbeiten können.','BSI200_4','BSI2004-A0235') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0235','R-R3-0464','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0465','R3-2026-07','Führen Sie die erstmalige BIA nicht in moderierten Workshops durch, in denen eine BCM-sachkundige Person die Methodik erläutert, verstehen die Beteiligten Begriffe und Bewertungsmaßstäbe unterschiedlich. Die Erhebung wird uneinheitlich und fehlerhaft, wichtige Rückfragen bleiben aus, und die Qualität Ihrer ersten BIA-Ergebnisse leidet spürbar.','BSI200_4','BSI2004-A0236') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0236','R-R3-0465','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0466','R3-2026-07','Werten die Verantwortlichen die BIA-Ergebnisse nicht zur Qualitätssicherung aus und prüfen sie nicht auf Vollständigkeit, Korrektheit und Nachvollziehbarkeit, gelangen Fehler und Lücken unbemerkt in die weitere Planung. Sie leiten dann Wiederanlaufziele aus fehlerhaften Daten ab, und Ihre gesamte Notfallvorsorge beruht auf ungeprüften, möglicherweise falschen Bewertungen.','BSI200_4','BSI2004-A0237') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0237','R-R3-0466','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0467','R3-2026-07','Legen Sie keinen maximal erwünschten Gesamtzeitraum für die BIA inklusive Nachbereitung und Auswertung fest, zieht sich die Erhebung unkontrolliert in die Länge. Ergebnisse veralten bereits während der Durchführung, die Auswertung verzögert sich, und Ihre Notfallvorsorge stützt sich am Ende auf Daten, die die aktuelle Lage nicht mehr abbilden.','BSI200_4','BSI2004-A0238') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0238','R-R3-0467','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0468','R3-2026-07','Nutzen Sie kein Hilfsmittel, das eine einheitliche, vollständige und nachvollziehbare Erhebung, Auswertung und Dokumentation der BIA sicherstellt, erfassen die Beteiligten Daten uneinheitlich und unstrukturiert. Ergebnisse werden lückenhaft und schwer vergleichbar, die Auswertung ist fehleranfällig, und die Nachvollziehbarkeit gegenüber Leitung und Prüfern geht verloren.','BSI200_4','BSI2004-A0239') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0239','R-R3-0468','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0469','R3-2026-07','Stellen Sie den Kontaktpersonen keine Hilfsmittel zur Bewertung des Schadenspotenzials bereit, insbesondere keine schriftliche Übersicht der Szenarien und Kategorien, bewerten diese aus dem Gedächtnis und uneinheitlich. Szenarien werden übersehen oder unterschiedlich interpretiert, sodass Ihre Schadensbewertungen inkonsistent ausfallen und die daraus abgeleiteten Wiederanlaufziele an Verlässlichkeit verlieren.','BSI200_4','BSI2004-A0240') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0240','R-R3-0469','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0470','R3-2026-07','Befüllen Sie die Vorlage oder das Tool nicht vorab mit den bereits bekannten Daten zu Geschäftsprozessen und möglichen Ressourcen, müssen die Kontaktpersonen Bekanntes erneut zusammentragen. Das erhöht Aufwand und Fehlerquote, führt zu Auslassungen und Widersprüchen und erschwert es Ihnen, vorhandenes Wissen konsistent in die BIA einzubinden.','BSI200_4','BSI2004-A0241') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0241','R-R3-0470','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0471','R3-2026-07','Bewerten Sie das Schadenspotenzial nicht für jeden Geschäftsprozess über die definierten Szenarien und Kategorien hinweg und über verschiedene Zeithorizonte, erfassen Sie den zeitlichen Schadensverlauf nur unvollständig. Sie erkennen dann nicht, ab wann ein Ausfall untragbar wird, und können MTPD und RTO nicht belastbar ableiten.','BSI200_4','BSI2004-A0242') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0242','R-R3-0471','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0472','R3-2026-07','Führen nicht die zuständigen Kontaktpersonen wie Prozesszuständige oder Prozessfachleute die Bewertung des Schadenspotenzials durch, sondern fachfremde Beteiligte, fehlt der Bewertung die notwendige Sachkenntnis. Auswirkungen werden falsch eingeschätzt, kritische Abhängigkeiten übersehen, und Sie leiten Wiederanlaufziele aus Bewertungen ab, die die tatsächliche Prozessrealität nicht zutreffend abbilden.','BSI200_4','BSI2004-A0243') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0243','R-R3-0472','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0473','R3-2026-07','Berücksichtigen Sie bei der Bewertung nicht, dass ein eingetretener Schaden über die Zeit nur gleichbleiben oder steigen, nicht aber wieder abnehmen kann, entstehen unplausible Schadensverläufe. Sinkende Bewertungen über längere Zeithorizonte verfälschen die MTPD-Bestimmung, sodass Sie zeitkritische Prozesse falsch einstufen und Ihre Wiederanlaufziele auf einer methodisch fehlerhaften Grundlage stehen.','BSI200_4','BSI2004-A0244') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0244','R-R3-0473','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0474','R3-2026-07','Wählen Sie zur Bestimmung der MTPD nicht den kleinsten Zeithorizont, bei dem das Untragbarkeitsniveau erreicht wird, setzen Sie die maximal tolerierbare Ausfallzeit zu lang an. Ihre daraus abgeleitete RTO wird zu großzügig, der Wiederanlauf erfolgt zu spät, und der Prozess überschreitet unbemerkt die Grenze zum nicht mehr tragbaren Schaden.','BSI200_4','BSI2004-A0245') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0245','R-R3-0474','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0475','R3-2026-07','Begründen und dokumentieren Sie die Bewertung des Schadenspotenzials und die MTPD je Geschäftsprozess nicht einschließlich der maßgeblichen Szenarien und Annahmen, bleiben Ihre Entscheidungen nicht nachvollziehbar. Bei Personalwechsel geht das Wissen verloren, Ergebnisse lassen sich weder überprüfen noch fortschreiben, und gegenüber Leitung und Prüfern fehlt jede belastbare Herleitung.','BSI200_4','BSI2004-A0246') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0246','R-R3-0475','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0476','R3-2026-07','Legen Sie für jeden zeitkritischen Geschäftsprozess nicht die geforderte Wiederanlaufzeit und das zu erreichende Notbetriebsniveau fest, fehlen dem Notfallmanagement klare Zielvorgaben. Im Ernstfall ist unklar, wie schnell und auf welchem Leistungsniveau der Prozess wiederherzustellen ist, sodass Wiederanlauf und Ressourceneinsatz ungesteuert und unzureichend verlaufen.','BSI200_4','BSI2004-A0247') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0247','R-R3-0476','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0477','R3-2026-07','Ermitteln Sie nicht für alle zeitkritischen Geschäftsprozesse, ob für den Notbetrieb eine unverzichtbare Abhängigkeit zu anderen Prozessen besteht, übersehen Sie versteckte Voraussetzungen des Wiederanlaufs. Ein zeitkritischer Prozess läuft im Notfall nicht an, weil ein benötigter Vorprozess fehlt, und Ihre RTO lässt sich trotz aller Vorbereitung nicht einhalten.','BSI200_4','BSI2004-A0248') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0248','R-R3-0477','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0478','R3-2026-07','Stimmen Sie bei einer unverzichtbaren Prozessabhängigkeit die RTO des benötigten Prozesses nicht so ab und begründen sie nicht, dass die RTO des abhängigen Prozesses eingehalten wird, entsteht eine inkonsistente Wiederanlaufplanung. Der abhängige Prozess wartet dann auf einen zu spät wiederanlaufenden Vorprozess, sodass seine Wiederanlaufzeit trotz eigener Vorbereitung überschritten wird.','BSI200_4','BSI2004-A0249') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0249','R-R3-0478','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0479','R3-2026-07','Legen Sie für einen benötigten Geschäftsprozess, der durch eine Abhängigkeit automatisch zeitkritisch wird, nicht ebenfalls ein Notbetriebsniveau fest, bleibt dieser Prozess ohne konkrete Vorgabe. Im Notfall ist unklar, auf welchem Leistungsniveau er den abhängigen Prozess stützen muss, sodass dessen Wiederanlauf trotz eigener Planung ins Leere läuft.','BSI200_4','BSI2004-A0250') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0250','R-R3-0479','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0480','R3-2026-07','Berücksichtigen Sie parallele Prozessabhängigkeiten nicht unabhängig von der gewählten Betrachtungsrichtung, entgehen Ihnen wechselseitige Verflechtungen zwischen Prozessen. Je nach Blickwinkel bleiben Abhängigkeiten unentdeckt, sodass Sie im Notfall Prozesse anlaufen lassen, deren benötigte Partnerprozesse fehlen, und die Wiederanlaufplanung insgesamt lückenhaft und widersprüchlich wird.','BSI200_4','BSI2004-A0251') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0251','R-R3-0480','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0481','R3-2026-07','Ermitteln Sie für die zeitkritischen Geschäftsprozesse nicht die für das definierte Notbetriebsniveau erforderlichen Ressourcen anhand der Ressourcenkategorien, wissen Sie nicht, was der Wiederanlauf konkret benötigt. Im Ernstfall fehlen unbemerkt kritische Mittel, die Notbetriebsvorsorge greift zu kurz, und der Prozess erreicht das geforderte Niveau nicht rechtzeitig.','BSI200_4','BSI2004-A0252') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0252','R-R3-0481','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0482','R3-2026-07','Leiten Sie die RTO der prozessnotwendigen Ressourcen nicht so aus der RTO des zeitkritischen Geschäftsprozesses ab, dass der Notbetrieb rechtzeitig erreicht wird, stehen benötigte Ressourcen zu spät bereit. Der Prozess kann trotz eigener Planung nicht fristgerecht wiederanlaufen, sodass Sie Ihre Wiederanlaufziele verfehlen und untragbare Schäden riskieren.','BSI200_4','BSI2004-A0253') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0253','R-R3-0482','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0483','R3-2026-07','Wählen Sie bei Ressourcen, die mehrere Geschäftsprozesse nutzen, nicht jeweils die kleinste RTO und analog die kleinste RPO, richtet sich die Wiederherstellung an einem zu langsamen Prozess aus. Der anspruchsvollste abhängige Prozess erhält die Ressource dann zu spät oder mit zu großem Datenverlust und verfehlt sein Wiederanlaufziel.','BSI200_4','BSI2004-A0254') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0254','R-R3-0483','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0484','R3-2026-07','Bestimmen Sie bei informationsbasierten Ressourcenkategorien nicht zusätzlich den maximal zulässigen Datenverlust, bleibt unklar, wie aktuell die Datenbestände nach einem Ausfall sein müssen. Ihre Backup- und Wiederherstellungsvorsorge wird darauf nicht ausgelegt, sodass im Notfall mehr Daten verloren gehen als der Prozess verkraftet und Wiederanlauf sowie Aufgabenerfüllung gefährdet sind.','BSI200_4','BSI2004-A0255') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0255','R-R3-0484','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0485','R3-2026-07','Wenn Sie Ressourcen nicht anhand vorgegebener Listen ermitteln und dokumentieren, entstehen durch uneinheitliche Schreibweisen und Dubletten fehlerhafte oder doppelte Einträge. Dadurch verlieren Sie den Überblick über Ihre tatsächlichen Abhängigkeiten, unterschätzen kritische Ressourcen und treffen im Notfall Entscheidungen auf einer unzuverlässigen Datenbasis, was die Wiederanlaufplanung insgesamt gefährdet.','BSI200_4','BSI2004-A0256') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0256','R-R3-0485','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0486','R3-2026-07','Wenn Sie Single Points of Failure nicht systematisch identifizieren und risikoorientiert absichern, bleibt eine einzelne verwundbare Ressource unerkannt, deren Ausfall den gesamten Geschäftsprozess zum Erliegen bringt. Sie riskieren so einen längeren, unvorhergesehenen Betriebsstillstand, weil keine Ausweichlösung vorbereitet ist und die Wiederherstellung erst improvisiert werden muss.','BSI200_4','BSI2004-A0257') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0257','R-R3-0486','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0487','R3-2026-07','Wenn Sie bei nicht plausiblen oder inkorrekten Einzelergebnissen keine Rücksprache mit den Kontaktpersonen halten und diese nicht gemeinsam abstimmen, übernehmen Sie fehlerhafte Annahmen in Ihre BIA. Auf dieser verzerrten Grundlage leiten Sie falsche Wiederanlaufzeiten und Strategien ab, sodass Ihre gesamte Notfallplanung an der Realität vorbeigeht und im Ernstfall versagt.','BSI200_4','BSI2004-A0258') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0258','R-R3-0487','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0488','R3-2026-07','Wenn Sie nicht prüfen, ob die RTO der Ressourcen korrekt aus der MTPD der zeitkritischen Prozesse abgeleitet wurde, setzen Sie möglicherweise zu lange Wiederanlaufzeiten an. Dann stellen Sie Ressourcen erst wieder her, nachdem der Prozess bereits einen nicht mehr tolerierbaren Schaden erlitten hat, und verfehlen Ihre eigentlichen Verfügbarkeitsziele.','BSI200_4','BSI2004-A0259') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0259','R-R3-0488','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0489','R3-2026-07','Wenn Sie die qualitätsgesicherten Einzelergebnisse nicht zu einer vollständigen Gesamtübersicht mit zeitkritischen Prozessen, Kontaktpersonen und Prioritäten zusammenfassen, fehlt Ihnen die konsolidierte Entscheidungsgrundlage. Sie können dann Abhängigkeiten nicht überblicken, Prioritäten im Notfall nicht sauber setzen und riskieren, dass wichtige Prozesse übersehen und zu spät wiederhergestellt werden.','BSI200_4','BSI2004-A0260') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0260','R-R3-0489','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0490','R3-2026-07','Wenn Sie vor dem Soll-Ist-Vergleich die Ressourcenzuständigen nicht identifizieren, fehlt Ihnen die fachkundige Auskunft über den tatsächlichen Zustand der Ressourcen. Sie beurteilen die vorhandenen Wiederanlauffähigkeiten dann auf Vermutungen statt auf belastbaren Angaben und erkennen bestehende Lücken zwischen Soll und Ist nicht rechtzeitig.','BSI200_4','BSI2004-A0261') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0261','R-R3-0490','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0491','R3-2026-07','Wenn Sie der geforderten RTO nicht die tatsächliche Wiederanlaufzeit gegenüberstellen und beurteilen, ob die RTO mit vorhandenen Maßnahmen erreichbar ist, bleiben kritische Lücken verborgen. Sie gehen dann fälschlich von einer ausreichenden Absicherung aus und stellen erst im Ernstfall fest, dass der Wiederanlauf viel länger dauert als tolerierbar.','BSI200_4','BSI2004-A0262') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0262','R-R3-0491','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0492','R3-2026-07','Wenn Sie für die Ressourcenkategorie Dienstleistungen nicht in Verträgen oder Service Level Agreements prüfen, ob Aussagen zur Realisierbarkeit der RTO vorliegen, verlassen Sie sich auf unverbindliche Zusagen. Im Notfall erbringt der Dienstleister die Leistung dann möglicherweise nicht in der benötigten Zeit, und Ihr zeitkritischer Prozess bleibt ohne vertragliche Absicherung liegen.','BSI200_4','BSI2004-A0263') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0263','R-R3-0492','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0493','R3-2026-07','Wenn Sie die RTA bei fehlenden Test- oder Übungsergebnissen nicht durch eine fachkundige Person realistisch schätzen oder mangels Grundlage als unbekannt kennzeichnen, entsteht ein trügerisches Bild der Wiederanlauffähigkeit. Sie planen dann mit erfundenen oder geschönten Zeiten und stellen im Ernstfall fest, dass der reale Wiederanlauf deutlich länger dauert.','BSI200_4','BSI2004-A0264') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0264','R-R3-0493','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0494','R3-2026-07','Wenn Sie die RPO nicht mit dem vom IT-Betrieb festgelegten Datensicherungszyklus abgleichen, kann der tatsächliche Sicherungsrhythmus hinter Ihrem tolerierbaren Datenverlust zurückbleiben. Nach einem Ausfall verlieren Sie dann mehr Daten als vorgesehen und müssen Vorgänge aufwendig rekonstruieren oder mit dauerhaften Datenlücken weiterarbeiten.','BSI200_4','BSI2004-A0265') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0265','R-R3-0494','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0495','R3-2026-07','Wenn Sie keine Übersicht aller zeitkritischen bzw. unzureichend abgesicherten Ressourcen samt Risikoeinschätzung der Lücken erstellen und der Institutionsleitung zur Kenntnis geben, bleibt die Leitung über die tatsächliche Gefährdungslage im Unklaren. Sie kann dann keine fundierten Entscheidungen über Investitionen treffen, und bekannte Schwachstellen bleiben ohne bewusste Risikoübernahme ungelöst.','BSI200_4','BSI2004-A0266') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0266','R-R3-0495','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0496','R3-2026-07','Wenn Sie nicht alle zeitkritischen Geschäftsprozesse und Ressourcen aus der BIA, insbesondere Single Points of Failure als eigenständige Zielobjekte, systematisch in der BCM-Risikoanalyse untersuchen, bleiben gefährliche Ausfallszenarien unbewertet. Sie erkennen dann relevante Bedrohungen nicht und lassen zentrale Schwachstellen ohne passende Continuity-Strategie, sodass Ihr Notfallkonzept lückenhaft bleibt.','BSI200_4','BSI2004-A0267') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0267','R-R3-0496','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0497','R3-2026-07','Wenn Sie die Grundwerte Integrität und Vertraulichkeit in der BCM-Risikoanalyse nicht berücksichtigen, obwohl kein hinreichendes ISMS vorliegt, betrachten Sie nur die Verfügbarkeit und übersehen Manipulations- und Vertraulichkeitsrisiken. Im Notbetrieb arbeiten Sie dann möglicherweise mit verfälschten oder unzulässig offengelegten Daten und verursachen zusätzliche Schäden neben dem eigentlichen Ausfall.','BSI200_4','BSI2004-A0268') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0268','R-R3-0497','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0498','R3-2026-07','Wenn Ihre Risikoeinschätzung die Kriterien Eintrittshäufigkeit und Schadenshöhe nicht berücksichtigt, fehlt Ihnen ein einheitlicher Maßstab zur Bewertung der Risiken. Sie können Gefährdungen dann nicht sinnvoll priorisieren, investieren Ihre Mittel möglicherweise in unwesentliche Risiken und lassen die wirklich gefährlichen Szenarien unbehandelt.','BSI200_4','BSI2004-A0269') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0269','R-R3-0498','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0499','R3-2026-07','Wenn Ihre Risikoeinschätzung nicht alle vorhandenen risikoreduzierenden Maßnahmen als Netto-Risiko berücksichtigt, bewerten Sie Risiken entweder zu hoch oder zu niedrig. Sie verschwenden dann Mittel für bereits abgesicherte Gefährdungen oder unterschätzen das verbleibende Restrisiko und treffen Ihre Behandlungsentscheidungen auf einer verzerrten Grundlage.','BSI200_4','BSI2004-A0270') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0270','R-R3-0499','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0500','R3-2026-07','Wenn Sie den Detailgrad von Ressourcen, Gefährdungen und Risiken nicht so wählen, dass sich geeignete BC-Strategien und -Lösungen ableiten lassen, bleibt die Analyse entweder zu grob oder unnötig kleinteilig. Zu grob übersehen Sie relevante Schwachstellen, zu kleinteilig binden Sie Ressourcen unproduktiv, und in beiden Fällen finden Sie keine wirksamen Lösungen.','BSI200_4','BSI2004-A0271') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0271','R-R3-0500','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0501','R3-2026-07','Wenn Sie die identifizierten Risiken nicht hinsichtlich des weiteren Handlungsbedarfs bewerten, bleibt offen, welche Risiken Sie behandeln müssen und welche Sie tragen können. Erkannte Gefährdungen versanden dann ohne Entscheidung, notwendige Maßnahmen unterbleiben, und Sie sind im Ernstfall gegen vermeidbare Schäden nicht gewappnet.','BSI200_4','BSI2004-A0272') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0272','R-R3-0501','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0502','R3-2026-07','Wenn Sie vor einer Risikoakzeptanz nicht sicherstellen, dass alle anderen Behandlungsoptionen angemessen geprüft wurden, akzeptieren Sie Risiken vorschnell, die Sie mit vertretbarem Aufwand hätten vermeiden oder mindern können. Sie tragen dann bewusst ein unnötig hohes Risiko und setzen Ihren Geschäftsbetrieb einer vermeidbaren Gefährdung aus.','BSI200_4','BSI2004-A0273') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0273','R-R3-0502','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0503','R3-2026-07','Wenn die Institutionsleitung die Ergebnisse der BCM-Risikoanalyse, insbesondere die bestehenden Restrisiken, nicht zur Kenntnis nimmt und akzeptiert, fehlt die formale Rückendeckung für die getroffenen Entscheidungen. Die verbleibenden Risiken werden dann nicht bewusst getragen, und im Schadensfall fehlt die legitimierte Verantwortungsübernahme durch die oberste Leitung.','BSI200_4','BSI2004-A0274') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0274','R-R3-0503','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0504','R3-2026-07','Wenn Sie aus der Liste der elementaren Gefährdungen nicht gezielt nur die für das Schutzziel Verfügbarkeit relevanten betrachten, verzetteln Sie sich in unpassenden Bedrohungen. Sie binden dann Aufwand für nebensächliche Aspekte und verlieren den Fokus auf die verfügbarkeitsrelevanten Ausfallszenarien, die Ihr BCM eigentlich absichern soll.','BSI200_4','BSI2004-A0275') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0275','R-R3-0504','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0505','R3-2026-07','Wenn Sie die Gefährdungen nicht vorab den Ressourcenkategorien zuordnen, um den Analyseaufwand zu minimieren, prüfen Sie jede Ressource unstrukturiert gegen alle Gefährdungen. Der Aufwand wächst dann unverhältnismäßig, die Analyse zieht sich in die Länge, und die Gefahr steigt, dass sie unvollständig bleibt oder ganz abgebrochen wird.','BSI200_4','BSI2004-A0276') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0276','R-R3-0505','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0506','R3-2026-07','Wenn Ihre Risikofachleute nicht anhand der tatsächlichen Bedrohungen und Schwachstellen mögliche weitere Gefährdungen identifizieren, beschränken Sie sich auf die generische Standardliste. Individuelle, für Ihre Institution besonders relevante Gefahren bleiben dann unerkannt, und Sie werden von einem spezifischen Ausfallszenario überrascht, für das keine Vorsorge getroffen wurde.','BSI200_4','BSI2004-A0277') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0277','R-R3-0506','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0507','R3-2026-07','Wenn Sie nicht alle Risiken, die einer weiteren Behandlung unterzogen werden sollen, bei der Festlegung der Business-Continuity-Strategien berücksichtigen, bleiben erkannte Gefährdungen ohne passende Gegenmaßnahme. Die Lücke zwischen Risikoanalyse und Strategie führt dann dazu, dass gerade die als behandlungsbedürftig eingestuften Risiken im Ernstfall ungeschützt schlagend werden.','BSI200_4','BSI2004-A0278') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0278','R-R3-0507','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0508','R3-2026-07','Wenn Sie die Ergebnisse der BCM-Risikoanalyse nicht in einem Bericht zusammenfassen, der explizit auf bestehende Restrisiken hinweist, und diesen der Institutionsleitung mitteilen, bleibt die Leitung über die verbleibenden Gefahren uninformiert. Sie kann dann keine bewusste Entscheidung über deren Akzeptanz treffen, und die Verantwortung für die Restrisiken bleibt ungeklärt.','BSI200_4','BSI2004-A0279') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0279','R-R3-0508','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0509','R3-2026-07','Wenn die Institutionsleitung nicht strategisch für den gesamten Geltungsbereich des BCMS festlegt, wie die BC-Planung der zeitkritischen Ressourcen und Prozesse zu gestalten ist, fehlt eine verbindliche Leitlinie. Die Fachbereiche planen dann uneinheitlich und ohne gemeinsame Zielrichtung, sodass Ihre Notfallvorsorge lückenhaft, widersprüchlich und im Ernstfall unwirksam wird.','BSI200_4','BSI2004-A0280') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0280','R-R3-0509','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0510','R3-2026-07','Wenn Sie keine geeigneten BC-Strategien definieren, die den Handlungsbedarf aus Risikoanalyse und BIA abdecken, bleiben die erkannten Lücken ohne konkrete Lösung. Sie verfügen dann zwar über eine Analyse, aber über keinen Weg, den Notbetrieb tatsächlich sicherzustellen, sodass Ihre Institution im Ernstfall handlungsunfähig ist.','BSI200_4','BSI2004-A0281') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0281','R-R3-0510','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0511','R3-2026-07','Wenn Sie nicht gewährleisten, dass die BC-Strategien den Geschäftsbetrieb mindestens über den abzusichernden Zeitraum mit angemessenem Notbetrieb abdecken, bricht Ihre Notfallversorgung vorzeitig ab. Der Notbetrieb endet dann, bevor der Regelbetrieb wiederhergestellt ist, und Sie stehen mitten in der Krise erneut ohne funktionierende Prozesse da.','BSI200_4','BSI2004-A0282') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0282','R-R3-0511','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0512','R3-2026-07','Wenn Ihre BC-Strategien die noch nicht adressierten Korrekturbedarfe und Verbesserungsmöglichkeiten aus vorangegangenen BCMS-Zyklen nicht berücksichtigen, wiederholen sich bekannte Schwächen. Bereits erkannte Mängel bleiben ungelöst, das BCM lernt nicht aus früheren Erfahrungen, und dieselben Lücken führen im Ernstfall erneut zu vermeidbaren Ausfällen.','BSI200_4','BSI2004-A0283') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0283','R-R3-0512','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0513','R3-2026-07','Wenn der oder die BCB nicht anhand konkret festgelegter Bewertungskriterien beurteilt, ob die identifizierten BC-Strategien wirksam und angemessen sind, treffen Sie die Auswahl nach Bauchgefühl. Sie wählen dann möglicherweise unwirksame oder unverhältnismäßig teure Strategien, die im Ernstfall nicht tragen oder Ihre Mittel unnötig binden.','BSI200_4','BSI2004-A0284') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0284','R-R3-0513','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0514','R3-2026-07','Wenn Sie für jede betrachtete BC-Strategie nicht prüfen, ob nach ihrer Umsetzung der Notbetrieb der Ressourcen innerhalb der RTO hergestellt werden kann, wählen Sie möglicherweise eine zu langsame Lösung. Sie stellen dann erst im Ernstfall fest, dass der Wiederanlauf die tolerierbare Zeit überschreitet und der Prozess bereits kritischen Schaden nimmt.','BSI200_4','BSI2004-A0285') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0285','R-R3-0514','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0515','R3-2026-07','Wenn Sie für jede betrachtete BC-Strategie nicht prüfen, ob sie das erforderliche Notbetriebsniveau sicherstellen kann, unterschätzen Sie die benötigte Leistungsfähigkeit. Der Notbetrieb deckt dann im Ernstfall nur einen Teil des erforderlichen Umfangs ab, sodass wichtige Leistungen ausfallen und die Krise trotz umgesetzter Strategie nicht bewältigt wird.','BSI200_4','BSI2004-A0286') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0286','R-R3-0515','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0516','R3-2026-07','Wenn Sie für jede betrachtete BC-Strategie nicht prüfen, welches Restrisiko eines Ressourcenausfalls trotz umgesetzter Strategie bestehen bleibt, wiegen Sie sich in falscher Sicherheit. Sie übersehen dann verbleibende Schwachstellen, treffen keine Vorsorge für den Restfall und werden von einem Ausfall überrascht, den die Strategie gerade nicht abdeckt.','BSI200_4','BSI2004-A0287') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0287','R-R3-0516','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0517','R3-2026-07','Wenn Sie für jede betrachtete BC-Strategie nicht prüfen, ob die finanziellen Aufwände in einem angemessenen Verhältnis zu den erwarteten Schäden stehen, investieren Sie unwirtschaftlich. Sie geben dann entweder zu viel für gering bewertete Risiken aus oder sparen an kritischer Absicherung, sodass Ihr BCM-Budget nicht dort wirkt, wo es am nötigsten ist.','BSI200_4','BSI2004-A0288') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0288','R-R3-0517','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0518','R3-2026-07','Wenn Sie nicht prüfen, ob die betrachteten BC-Strategien die internen und externen Anforderungen aus Recht, Regulierung, Interessengruppen und Risikobereitschaft einhalten, wählen Sie möglicherweise unzulässige Lösungen. Sie riskieren dann Gesetzes- und Vertragsverstöße, verlieren das Vertrauen der Stakeholder und müssen die Strategie nachträglich verwerfen und teuer neu aufsetzen.','BSI200_4','BSI2004-A0289') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0289','R-R3-0518','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0519','R3-2026-07','Wenn der oder die BCB nicht je Ressourcenkategorie eine oder mehrere geeignete BC-Strategien vorauswählt, fehlt der Institutionsleitung eine strukturierte Entscheidungsgrundlage. Die Auswahl erfolgt dann unvorbereitet und lückenhaft, wichtige Ressourcenkategorien bleiben ohne passende Strategie, und die Notfallplanung wird nicht flächendeckend abgedeckt.','BSI200_4','BSI2004-A0290') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0290','R-R3-0519','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0520','R3-2026-07','Wenn die Institutionsleitung nicht über die letztlich umzusetzenden BC-Strategien entscheidet und diese Entscheidung nicht dokumentiert wird, fehlt die verbindliche Freigabe und Verantwortungsübernahme. Die Umsetzung bleibt dann in der Schwebe, Zuständige handeln ohne klaren Auftrag, und im Streitfall lässt sich nicht nachweisen, welche Strategie bewusst beschlossen wurde.','BSI200_4','BSI2004-A0291') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0291','R-R3-0520','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0521','R3-2026-07','Wenn Sie bei zeitkritischen Prozessen, die durch Dienstleister oder Lieferketten erbracht werden, keine BC-Strategien wählen, die eine angemessene Leistungserbringung im Notfall sicherstellen, machen Sie sich von der Ausfallvorsorge Dritter abhängig. Fällt der Dienstleister aus, steht Ihr Prozess still, weil Sie keine eigene Absicherung oder Ausweichlösung vorbereitet haben.','BSI200_4','BSI2004-A0292') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0292','R-R3-0521','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0522','R3-2026-07','Wenn Sie ein von der Institutionsleitung übernommenes Restrisiko nicht dokumentieren, regelmäßig neu bewerten und darauf prüfen, ob es durch neue BC-Strategien gesenkt werden kann, verliert die Leitung das Risiko aus dem Blick. Veränderte Bedingungen bleiben unbeachtet, und ein einst akzeptables Restrisiko wächst unbemerkt zu einer ernsten, ungesteuerten Gefährdung heran.','BSI200_4','BSI2004-A0293') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0293','R-R3-0522','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0523','R3-2026-07','Wenn Sie nicht festlegen, wer für die Umsetzung der BC-Strategien zuständig ist und wer das notwendige Fachwissen beisteuert, bleibt die Verantwortung ungeklärt. Die beschlossenen Maßnahmen versanden dann zwischen den Bereichen, notwendiges Know-how wird nicht eingebunden, und die Strategien bleiben auf dem Papier stehen, ohne im Ernstfall zu wirken.','BSI200_4','BSI2004-A0294') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0294','R-R3-0523','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0524','R3-2026-07','Wenn Sie bei Wahl der BC-Strategie „Ausreichende BC-Fähigkeit des Dienstleistungsunternehmens“ die erwarteten BC-Fähigkeiten der zeitkritischen Dienstleister nicht abstimmen, verlassen Sie sich auf unbestätigte Annahmen. Im Notfall erbringt der Dienstleister die Leistung dann möglicherweise nicht wie erwartet, und Ihr zeitkritischer Prozess bricht mangels vereinbarter Notfallvorsorge zusammen.','BSI200_4','BSI2004-A0295') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0295','R-R3-0524','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0525','R3-2026-07','Wenn Sie zur Umsetzung der ausgewählten BC-Strategien keinen Umsetzungsplan mit konkreten Handlungsschritten sowie benötigten finanziellen, personellen und zeitlichen Ressourcen erstellen, bleibt die Umsetzung unkoordiniert. Aufgaben werden dann nicht terminiert, Mittel nicht bereitgestellt, und die beschlossenen Strategien verzögern sich oder scheitern, sodass Ihre Notfallvorsorge nicht rechtzeitig wirksam wird.','BSI200_4','BSI2004-A0296') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0296','R-R3-0525','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0526','R3-2026-07','Wenn Sie die erstellten Umsetzungspläne nicht daraufhin überprüfen, ob das erwartete Gesamtergebnis im Hinblick auf die ausgewählten BC-Strategien weiterhin wirksam und angemessen ist, übersehen Sie zwischenzeitliche Änderungen. Der Plan zielt dann an den aktuellen Anforderungen vorbei, und Sie investieren Aufwand in eine Lösung, die im Ernstfall nicht mehr trägt.','BSI200_4','BSI2004-A0297') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0297','R-R3-0526','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0527','R3-2026-07','Wenn Sie die Umsetzungspläne und die benötigten Ressourcen nicht vor der Umsetzung durch die Institutionsleitung freigeben lassen, fehlt die verbindliche Zusage der erforderlichen Mittel. Die Umsetzung startet dann ohne gesicherte Finanzierung und Personalbindung, gerät ins Stocken, und die geplante Notfallvorsorge bleibt unvollständig oder wird gar nicht erst begonnen.','BSI200_4','BSI2004-A0298') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0298','R-R3-0527','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0528','R3-2026-07','Wenn die beschlossenen Maßnahmen nach der Freigabe nicht durch die Zuständigen im festgelegten Zeitraum umgesetzt werden, bleibt Ihre Notfallvorsorge trotz Planung und Freigabe wirkungslos. Die vorgesehenen Fähigkeiten stehen dann im Ernstfall nicht bereit, und Sie stehen einer Krise ohne die eigentlich beschlossene Absicherung gegenüber.','BSI200_4','BSI2004-A0299') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0299','R-R3-0528','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0529','R3-2026-07','Wenn niemand die Umsetzung der beschlossenen Maßnahmen steuert und kontrolliert, verlaufen Ihre Notfallvorkehrungen unkoordiniert und bleiben oft unvollständig. Sie erkennen Verzögerungen und Lücken erst im Ernstfall, wenn zeitkritische Prozesse bereits ausfallen. Ohne zentrale Steuerung durch die BCB-Rolle riskieren Sie, dass wichtige Vorsorgemaßnahmen versanden und Ihre Institution im Notfall handlungsunfähig ist.','BSI200_4','BSI2004-A0300') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0300','R-R3-0529','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0530','R3-2026-07','Fehlt für zeitkritische Geschäftsprozesse eine dokumentierte Geschäftsfortführungsplanung, stehen Ihre Mitarbeitenden im Notfall ohne verbindliche Handlungsanweisung da. Sie müssen improvisieren, verlieren wertvolle Zeit und überschreiten die zulässige Ausfalldauer. Dadurch drohen Ihnen erhebliche Betriebsunterbrechungen, finanzielle Schäden und ein nachhaltiger Vertrauensverlust bei Bürgern und Partnern.','BSI200_4','BSI2004-A0301') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0301','R-R3-0530','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0531','R3-2026-07','Wenn Sie bestehende Notfallpläne nicht auf ihre Übereinstimmung mit den festgelegten BC-Strategien prüfen und anpassen, arbeiten Sie im Ernstfall mit veralteten oder unpassenden Maßnahmen. Diese greifen dann nicht wie erwartet und lassen kritische Lücken offen. So verlassen Sie sich auf eine trügerische Sicherheit, während Ihre tatsächliche Fortführungsfähigkeit ungewiss bleibt.','BSI200_4','BSI2004-A0302') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0302','R-R3-0531','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0532','R3-2026-07','Legt die BCB nicht fest, wie die Geschäftsfortführungspläne auf die Struktur Ihrer Institution aufgeteilt werden, entstehen Überschneidungen und Zuständigkeitslücken. Einzelne Organisationseinheiten fühlen sich nicht verantwortlich, oder mehrere planen dasselbe doppelt. Im Notfall wissen Ihre Bereiche nicht, welcher Plan für sie gilt, wodurch die Fortführung ins Stocken gerät.','BSI200_4','BSI2004-A0303') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0303','R-R3-0532','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0533','R3-2026-07','Ohne eine einheitlich aufgebaute GFP-Dokumentvorlage entstehen uneinheitliche, schwer vergleichbare Pläne. Sie finden benötigte Informationen im Notfall nur mühsam, weil jeder Bereich anders dokumentiert. Diese fehlende Nachvollziehbarkeit kostet Sie im Ernstfall wertvolle Zeit und erhöht das Risiko, dass wichtige Angaben übersehen werden.','BSI200_4','BSI2004-A0304') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0304','R-R3-0533','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0534','R3-2026-07','Beschreibt ein Geschäftsfortführungsplan seinen organisatorischen und räumlichen Geltungsbereich sowie seine Zielstellung nicht, bleibt unklar, wofür er überhaupt gilt. Im Notfall ist Ihren Mitarbeitenden nicht ersichtlich, welche Prozesse und Standorte abgedeckt sind. Dadurch werden Maßnahmen falsch angewendet oder ganze Bereiche versehentlich ausgelassen.','BSI200_4','BSI2004-A0305') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0305','R-R3-0534','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0535','R3-2026-07','Werden im GFP nicht alle zeitkritischen Geschäftsprozesse mit ihren MTPD, RTO und Abhängigkeiten dokumentiert, kennen Sie die tatsächlichen Fristen und Verflechtungen nicht. Sie priorisieren im Ernstfall falsch und starten Prozesse in ungünstiger Reihenfolge. So überschreiten Sie kritische Zeitvorgaben und gefährden die Wiederaufnahme des Betriebs.','BSI200_4','BSI2004-A0306') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0306','R-R3-0535','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0536','R3-2026-07','Fehlen im GFP die zeitkritischen Ressourcen samt RTA, RTO, RPO und RPA, wissen Sie im Notfall nicht, was in welcher Zeit wiederhergestellt werden muss. Sie erkennen Engpässe zu spät und verlieren möglicherweise Daten über den zulässigen Punkt hinaus. Dadurch geraten Wiederanlauf und Notbetrieb ins Wanken.','BSI200_4','BSI2004-A0307') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0307','R-R3-0536','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0537','R3-2026-07','Werden im GFP je möglichem Ressourcenausfall keine Notfallmaßnahmen abgeleitet, mit denen Sie die Prozesse innerhalb der RTO auf Notbetriebsniveau bringen, fehlt Ihnen die konkrete Handlungsgrundlage. Ihre Mitarbeitenden stehen dann ohne erprobtes Vorgehen da. So dauert der Wiederanlauf länger als zulässig und der Notbetrieb kommt nicht rechtzeitig zustande.','BSI200_4','BSI2004-A0308') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0308','R-R3-0537','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0538','R3-2026-07','Sind im GFP nicht alle relevanten internen und externen Kontakte mit den im Notfall erreichbaren Telefonnummern dokumentiert oder referenziert, verlieren Sie im Ernstfall Zeit mit der Suche nach Ansprechpartnern. Wichtige Dienstleister oder Verantwortliche bleiben unerreichbar. Diese Verzögerung bei der Alarmierung und Koordination gefährdet die fristgerechte Bewältigung des Notfalls.','BSI200_4','BSI2004-A0309') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0309','R-R3-0538','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0539','R3-2026-07','Wird nicht sichergestellt, dass die für die Geschäftsfortführung benötigten Dokumente entsprechend ihrem Schutzbedarf abgesichert und zugleich im Notfall zugänglich sind, stehen Ihnen die Pläne ausgerechnet dann nicht zur Verfügung, wenn Sie sie brauchen. Ein Ausfall des zentralen Systems macht sie unbrauchbar. So verlieren Sie die Grundlage für Ihr gesamtes Notfallhandeln.','BSI200_4','BSI2004-A0310') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0310','R-R3-0539','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0540','R3-2026-07','Werden im GFP der Aktivierungsprozess samt Alarmierung, Information der Mitarbeitenden und deren gesonderte Rechte und Berechtigungen nicht dokumentiert, weiß im Ernstfall niemand, wer den Notbetrieb wie auslöst. Ihre Mitarbeitenden handeln unkoordiniert oder gar nicht. Dadurch verstreicht wertvolle Zeit, bevor die eigentliche Bewältigung überhaupt beginnt.','BSI200_4','BSI2004-A0311') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0311','R-R3-0540','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0541','R3-2026-07','Werden Dokumente, auf die im GFP verwiesen wird, nicht nachvollziehbar referenziert, finden Ihre Mitarbeitenden im Notfall die benötigten Unterlagen nicht. Sie suchen unter Zeitdruck nach Anhängen, Versionen oder Ablageorten. Diese Unklarheit verzögert die Fortführung und führt dazu, dass mit falschen oder veralteten Dokumenten gearbeitet wird.','BSI200_4','BSI2004-A0312') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0312','R-R3-0541','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0542','R3-2026-07','Werden besondere Melde- und Berichtspflichten, die nur für die Dauer des Notfalls gelten, nicht im GFP dokumentiert, versäumen Sie im Ernstfall gesetzlich oder vertraglich geforderte Meldungen. Aufsichtsbehörden, Partner oder die Leitung werden nicht rechtzeitig informiert. Dadurch drohen Ihnen rechtliche Konsequenzen und ein zusätzlicher Vertrauensverlust während der Krise.','BSI200_4','BSI2004-A0313') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0313','R-R3-0542','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0543','R3-2026-07','Werden bei zeitkritischen Prozessabhängigkeiten die einzuhaltenden zeitlichen Reihenfolgen des Notbetriebsanlaufs nicht im GFP dokumentiert oder referenziert, starten Sie Prozesse in falscher Abfolge. Abhängige Abläufe laufen ins Leere, weil ihre Voraussetzungen noch fehlen. So verzögert sich der gesamte Wiederanlauf und die zulässigen Zeitvorgaben werden überschritten.','BSI200_4','BSI2004-A0314') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0314','R-R3-0543','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0544','R3-2026-07','Werden einfache, im Reaktiv-BCMS umgesetzte BC-Lösungen nicht mit einer Umsetzungsfrist im Maßnahmenplan dokumentiert, verlieren Sie den Überblick über offene Vorkehrungen. Notwendige Maßnahmen bleiben ohne Termin liegen und geraten in Vergessenheit. Dadurch gehen Sie im Ernstfall von einem Schutzniveau aus, das tatsächlich noch gar nicht hergestellt ist.','BSI200_4','BSI2004-A0315') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0315','R-R3-0544','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0545','R3-2026-07','Wird bei erreichter RTO und erreichtem Notbetriebsniveau nicht dokumentiert, dass die vorhandenen Maßnahmen die Ressourcen fristgerecht bereitstellen, fehlt Ihnen der Nachweis über die Wirksamkeit Ihrer Vorsorge. Sie können nicht belegen, dass Ihre Planung tatsächlich trägt. So bleibt die Fortführungsfähigkeit ungeprüft und Verbesserungspotenziale bleiben unerkannt.','BSI200_4','BSI2004-A0316') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0316','R-R3-0545','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0546','R3-2026-07','Wird bei Nichterreichen der geforderten Parameter keine Gesamtübersicht der betroffenen Geschäftsprozesse und Ressourcen erstellt, bleiben Ihre Lücken im Verborgenen. Sie erkennen nicht, wo Ihr Notbetrieb tatsächlich versagt. Ohne diese Übersicht steuern Sie Verbesserungsmaßnahmen ins Blaue und die Schwachstellen bestehen fort, bis sie sich im Ernstfall rächen.','BSI200_4','BSI2004-A0317') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0317','R-R3-0546','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0547','R3-2026-07','Werden identifizierte Defizite und Verbesserungsbedarfe je Ressource nicht im BCM-Maßnahmenplan dokumentiert, gehen erkannte Schwachstellen verloren. Niemand fühlt sich für ihre Behebung zuständig, und sie werden nicht nachverfolgt. So wiederholen sich dieselben Mängel und Ihr Notfallmanagement verbessert sich trotz erkannter Lücken nicht.','BSI200_4','BSI2004-A0318') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0318','R-R3-0547','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0548','R3-2026-07','Werden Schwachstellen, Verbesserungsbedarfe, getroffene Annahmen und Lücken aus der Geschäftsfortführungsplanung nicht an die BCB gemeldet, fehlt der verantwortlichen Rolle das vollständige Lagebild. Sie kann Risiken nicht bewerten und keine Gegenmaßnahmen anstoßen. Dadurch bleiben kritische Restrisiken unbehandelt und werden erst im Ernstfall sichtbar.','BSI200_4','BSI2004-A0319') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0319','R-R3-0548','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0549','R3-2026-07','Werden im Geschäftsfortführungsplan keine Notfallmaßnahmen entwickelt, die die ausgefallenen Prozesse auf Basis der BC-Strategien fristgerecht fortführen, bleibt Ihre Strategie folgenlos. Es fehlt die Übersetzung in konkretes Handeln. Im Ernstfall stehen Ihre Mitarbeitenden ohne umsetzbare Anweisungen da und der Notbetrieb kommt nicht rechtzeitig in Gang.','BSI200_4','BSI2004-A0320') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0320','R-R3-0549','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0550','R3-2026-07','Sind im Geschäftsfortführungsplan Ablauf, konkrete Tätigkeiten zur Wiederaufnahme und die Zuständigkeiten nicht dokumentiert, weiß im Notfall niemand genau, wer was in welcher Reihenfolge tut. Ihre Mitarbeitenden handeln uneinheitlich oder warten aufeinander. Diese Unklarheit führt zu Verzögerungen und dazu, dass wichtige Schritte übersehen werden.','BSI200_4','BSI2004-A0321') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0321','R-R3-0550','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0551','R3-2026-07','Werden die Notfallmaßnahmen des GFP nicht mit der aktuellen Wiederanlaufplanung der Ressourcen abgestimmt, klaffen Planung und Realität auseinander. Sie setzen im GFP Ressourcen voraus, die laut Wiederanlaufplan noch gar nicht verfügbar sind. Dadurch scheitert die Fortführung an fehlenden Grundlagen und die Zeitvorgaben werden verfehlt.','BSI200_4','BSI2004-A0322') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0322','R-R3-0551','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0552','R3-2026-07','Ist im GFP nicht beschrieben, wie die Prozesse vom Notbetrieb in den Normalbetrieb zurückgeführt werden und wie mit Nacharbeiten wie Arbeitsrückständen umzugehen ist, verharren Sie unnötig lange im improvisierten Notbetrieb. Rückstände häufen sich an und werden unkontrolliert abgearbeitet. So entstehen Fehler, Datenverluste und ein holpriger Übergang zurück zum Regelbetrieb.','BSI200_4','BSI2004-A0323') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0323','R-R3-0552','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0553','R3-2026-07','Sind die Notfallmaßnahmen nicht am Ablauf der Notfallbewältigung aus Wiederanlauf, Geschäftsfortführung und Rückführung ausgerichtet, greifen sie nicht ineinander. Einzelne Maßnahmen laufen isoliert und passen nicht zur jeweiligen Phase. Dadurch entstehen Brüche im Ablauf, die die geordnete Bewältigung des Notfalls erschweren und verzögern.','BSI200_4','BSI2004-A0324') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0324','R-R3-0553','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0554','R3-2026-07','Ist der Detailgrad der Maßnahmen nicht so gewählt, dass eine fachkundige dritte Person die Geschäftsfortführung anhand des GFP umsetzen könnte, hängt Ihr Notbetrieb allein an einzelnen Wissensträgern. Fallen diese aus, kann niemand einspringen. So gefährden Sie die Fortführung genau dann, wenn Schlüsselpersonen selbst betroffen oder nicht erreichbar sind.','BSI200_4','BSI2004-A0325') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0325','R-R3-0554','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0555','R3-2026-07','Sind die im GFP aufgeführten Dokumente nicht am Ende in einer Gesamtliste mit relevantem Abschnitt und Ablageort referenziert, fehlt Ihnen im Notfall der schnelle Überblick über alle benötigten Unterlagen. Sie suchen zeitraubend an verstreuten Orten. Diese fehlende Bündelung verzögert das Notfallhandeln und lässt Sie einzelne Dokumente übersehen.','BSI200_4','BSI2004-A0326') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0326','R-R3-0555','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0556','R3-2026-07','Ist nicht sichergestellt, dass die in den Plänen referenzierten Dokumente entsprechend ihrem Schutzbedarf abgelegt und zugleich im Notfall zugänglich sind, stehen Ihnen die Unterlagen im Ernstfall womöglich nicht zur Verfügung. Ein Systemausfall oder ein unsicherer Ablageort macht sie unbrauchbar. So verlieren Sie die Arbeitsgrundlage für Ihre gesamte Notfallbewältigung.','BSI200_4','BSI2004-A0327') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0327','R-R3-0556','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0557','R3-2026-07','Werden die erstellten GFPs nicht formal auf Vollständigkeit, Plausibilität und Aktualität qualitätsgesichert, verlassen Sie sich auf möglicherweise fehlerhafte oder veraltete Pläne. Lücken und Widersprüche bleiben unentdeckt, bis der Ernstfall sie offenlegt. So scheitert Ihre Fortführung an Mängeln, die eine Prüfung leicht hätte aufdecken können.','BSI200_4','BSI2004-A0328') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0328','R-R3-0557','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0558','R3-2026-07','Werden die erstellten GFPs und WAPs nach der Qualitätssicherung nicht offiziell freigegeben, etwa durch die Leitungen der Organisationseinheiten, fehlt die verbindliche Autorisierung. Es bleibt unklar, ob die Pläne tatsächlich gelten und getragen werden. Im Notfall zögern Ihre Mitarbeitenden zu handeln, weil die verbindliche Grundlage fehlt.','BSI200_4','BSI2004-A0329') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0329','R-R3-0558','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0559','R3-2026-07','Teilt die BCB die aktualisierten Informationen zu GFPs und Ressourcenbedarf nicht der Institutionsleitung und dem Risikomanagement mit, treffen diese ihre Entscheidungen auf veralteter Grundlage. Risiken werden falsch eingeschätzt und notwendige Mittel nicht bereitgestellt. So bleibt Ihr Notfallmanagement unterfinanziert und die Leitung trägt Verantwortung, ohne die tatsächliche Lage zu kennen.','BSI200_4','BSI2004-A0330') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0330','R-R3-0559','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0560','R3-2026-07','Wird die Wiederanlaufplanung nicht für alle zeitkritischen Ressourcen erstellt und dokumentiert, fehlt Ihnen für einzelne Ressourcen die konkrete Anleitung zum Wiederanlauf. Im Notfall wissen Ihre Mitarbeitenden nicht, wie diese Ressourcen fristgerecht wiederhergestellt werden. Dadurch bleiben Lücken, die den gesamten Notbetrieb ins Stocken bringen.','BSI200_4','BSI2004-A0331') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0331','R-R3-0560','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0561','R3-2026-07','Stellt die BCB durch eine WAP-Dokumentvorlage keinen einheitlichen und nachvollziehbaren Aufbau der Wiederanlaufpläne sicher, entstehen uneinheitliche Pläne unterschiedlicher Qualität. Sie finden benötigte Angaben im Ernstfall nur schwer und vergleichen die Pläne mühsam. Diese fehlende Struktur erhöht das Risiko von Fehlern und Verzögerungen beim Wiederanlauf.','BSI200_4','BSI2004-A0332') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0332','R-R3-0561','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0562','R3-2026-07','Sind in einem WAP Zweck und Zielsetzung nicht dokumentiert, bleibt unklar, was der Plan überhaupt bewirken soll. Ihre Mitarbeitenden können nicht einschätzen, ob sie das richtige Ziel verfolgen. Diese Unklarheit führt dazu, dass der Wiederanlauf in die falsche Richtung läuft oder wichtige Aspekte unbeachtet bleiben.','BSI200_4','BSI2004-A0333') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0333','R-R3-0562','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0563','R3-2026-07','Sind in einem WAP Geltungsbereich und betrachtete Ressourcen nicht klar dokumentiert und gegenüber anderen WAPs abgegrenzt, entstehen Überschneidungen und Lücken. Manche Ressourcen werden doppelt geplant, andere fallen durch das Raster. Im Notfall wissen Ihre Mitarbeitenden nicht, welcher Plan zuständig ist, wodurch der Wiederanlauf unkoordiniert verläuft.','BSI200_4','BSI2004-A0334') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0334','R-R3-0563','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0564','R3-2026-07','Ist der Aktivierungsprozess des WAP nicht dokumentiert, weiß im Ernstfall niemand, wer den Wiederanlauf wann und wie auslöst. Der Plan bleibt liegen, weil der Startpunkt unklar ist. Diese Verzögerung beim Aktivieren kostet Sie wertvolle Zeit und gefährdet die Einhaltung der geforderten Wiederanlaufzeiten.','BSI200_4','BSI2004-A0335') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0335','R-R3-0564','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0565','R3-2026-07','Sind nicht alle zum Wiederanlauf relevanten Dokumente samt Ablageorten im WAP notiert, suchen Ihre Mitarbeitenden im Notfall zeitraubend nach den benötigten Unterlagen. Wichtige Konfigurationen oder Anleitungen bleiben unauffindbar. Dadurch verzögert sich der Wiederanlauf der Ressource und die zulässige Ausfalldauer wird überschritten.','BSI200_4','BSI2004-A0336') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0336','R-R3-0565','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0566','R3-2026-07','Sind die organisatorischen und technischen Voraussetzungen zum Wiederanlauf der Ressource nicht im WAP aufgeführt, starten Ihre Mitarbeitenden den Wiederanlauf, ohne dass die nötigen Bedingungen erfüllt sind. Der Anlauf scheitert oder muss wiederholt werden. So verlieren Sie Zeit und die Ressource steht später als geplant wieder zur Verfügung.','BSI200_4','BSI2004-A0337') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0337','R-R3-0566','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0567','R3-2026-07','Sind im WAP nicht alle erforderlichen Rollen, Rolleninhabenden und Vertretenden mit aktuellen Kontaktdaten sowie die benötigten Dienstleister benannt, erreichen Sie im Notfall die entscheidenden Personen nicht. Der Wiederanlauf stockt, weil Verantwortliche oder Dienstleister fehlen. Diese Lücke bei den Kontakten verzögert die Wiederherstellung erheblich.','BSI200_4','BSI2004-A0338') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0338','R-R3-0567','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0568','R3-2026-07','Sind nicht alle für den Wiederanlauf benötigten Ressourcen mit ihren RTO sowie die benötigten Dokumentationen im WAP aufgeführt, kennen Sie die tatsächlichen Abhängigkeiten und Fristen nicht. Sie starten den Wiederanlauf ohne vollständige Grundlage. Dadurch fehlen im entscheidenden Moment benötigte Mittel und die Zeitvorgaben werden verfehlt.','BSI200_4','BSI2004-A0339') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0339','R-R3-0568','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0569','R3-2026-07','Sind Ablauf und konkrete Tätigkeiten zum Wiederanlauf mit durchführender Rolle und üblicher Dauer je Schritt nicht im WAP beschrieben oder referenziert, fehlt Ihren Mitarbeitenden die Schritt-für-Schritt-Anleitung. Sie handeln uneinheitlich und können den Fortschritt nicht einschätzen. So dauert der Wiederanlauf länger als nötig und wichtige Teilschritte werden übersprungen.','BSI200_4','BSI2004-A0340') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0340','R-R3-0569','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0570','R3-2026-07','Sind die technischen und organisatorischen Abhängigkeiten zu anderen Ressourcen sowie die erforderlichen Dienstleister nicht im WAP dokumentiert und bereits bei der Planung berücksichtigt, übersehen Sie kritische Verflechtungen. Der Wiederanlauf einer Ressource scheitert, weil eine andere noch nicht bereitsteht. Dadurch geraten Ihre Wiederherstellungsketten aus dem Takt und verzögern den gesamten Notbetrieb.','BSI200_4','BSI2004-A0341') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0341','R-R3-0570','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0571','R3-2026-07','Ist im WAP kein Funktionstest zur Prüfung des erfolgreichen Wiederanlaufs und keine Übergabe in den Notbetrieb vorgesehen, nehmen Sie eine Ressource in Betrieb, ohne ihre Funktionsfähigkeit zu bestätigen. Verborgene Fehler bleiben unentdeckt und schlagen im Notbetrieb durch. So setzen Sie auf eine Ressource, die möglicherweise erneut ausfällt.','BSI200_4','BSI2004-A0342') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0342','R-R3-0571','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0572','R3-2026-07','Sind die Notfallmaßnahmen nicht geeignet, ausgefallene Ressourcen innerhalb der erforderlichen Zeit auf dem definierten Notbetriebsniveau wiederanlaufen zu lassen, erfüllen sie ihren eigentlichen Zweck nicht. Sie überschreiten die zulässige Ausfalldauer, obwohl Maßnahmen vorhanden sind. Dadurch entsteht ein trügerisches Sicherheitsgefühl, während Ihr Notbetrieb im Ernstfall tatsächlich nicht rechtzeitig zustande kommt.','BSI200_4','BSI2004-A0343') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0343','R-R3-0572','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0573','R3-2026-07','Dokumentieren Sie die Einschränkungen des Notbetriebs nicht, bleibt unklar, welche Kapazitäten und Funktionen im Krisenfall tatsächlich zur Verfügung stehen. Die Notfallorganisation trifft dann Entscheidungen auf falschen Annahmen, priorisiert Ressourcen fehlerhaft und überlastet den reduzierten Betrieb. So drohen unbemerkte Versorgungslücken, verlängerte Ausfälle und ein unkontrollierter Übergang in die Krise.','BSI200_4','BSI2004-A0344') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0344','R-R3-0573','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0574','R3-2026-07','Fehlt eine übergeordnete Wiederanlaufplanung mit dokumentierten Abhängigkeiten und Reihenfolgen, starten Sie Ressourcen in falscher Folge wieder an. Kritische Systeme laufen ohne ihre Vorbedingungen ins Leere, Teams behindern sich gegenseitig und der Wiederanlauf verzögert sich erheblich. Dadurch überschreiten Sie Ihre Wiederanlaufzeiten und verlängern den Schaden aus dem Ausfall.','BSI200_4','BSI2004-A0345') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0345','R-R3-0574','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0575','R3-2026-07','Stellt die Wiederanlaufplanung nicht sicher, dass die Gesamt-Wiederanlaufzeit unter Berücksichtigung abhängiger Ressourcen innerhalb der RTO bleibt, überschätzen Sie Ihre tatsächliche Wiederherstellungsfähigkeit. Im Ernstfall dauert der Wiederanlauf länger als toleriert, zeitkritische Prozesse fallen zu lange aus. Vertragsstrafen, Versorgungsengpässe und regulatorische Verstöße können die Folge sein.','BSI200_4','BSI2004-A0346') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0346','R-R3-0575','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0576','R3-2026-07','Überprüfen Sie Ihre BC-Lösungen, Rollen und Pläne nicht kontinuierlich durch Übungen, bleiben Schwachstellen und veraltete Annahmen unentdeckt. Im tatsächlichen Notfall stellen Sie fest, dass Pläne unvollständig sind und Beteiligte ihre Aufgaben nicht beherrschen. Die Notfallbewältigung scheitert genau dann, wenn sie funktionieren muss, und der Schaden eskaliert.','BSI200_4','BSI2004-A0347') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0347','R-R3-0576','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0577','R3-2026-07','Ohne ein abgestimmtes Programm von Übungen und Tests können Sie die Aktualität und Einsatzbereitschaft Ihrer Notfallbewältigung nicht sicherstellen. Fähigkeiten verfallen unbemerkt, neue Risiken bleiben ungeübt und die Organisation verliert Routine. Im Ernstfall reagieren Ihre Teams unsicher und zu langsam, wodurch sich Ausfälle unnötig verlängern.','BSI200_4','BSI2004-A0348') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0348','R-R3-0577','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0578','R3-2026-07','Führen Sie die vorgesehenen Übungsarten wie Stabs-, Alarmierungsübung, Planbesprechung und Funktionstest nicht regelmäßig durch, prüfen Sie einzelne Fähigkeitsebenen Ihrer Notfallbewältigung nie realistisch. Lücken in Alarmierung, Entscheidungsfindung oder Technik bleiben verborgen. Im Krisenfall versagen genau diese ungeübten Elemente und gefährden den gesamten Wiederanlauf.','BSI200_4','BSI2004-A0349') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0349','R-R3-0578','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0579','R3-2026-07','Hat der oder die BCB die Rahmenbedingungen zum systematischen Üben nicht festgelegt und dokumentiert, finden Übungen beliebig, unvollständig und ohne roten Faden statt. Wichtige Szenarien und Zielgruppen bleiben unberücksichtigt, Ergebnisse sind nicht vergleichbar. Sie können weder Fortschritt noch Reifegrad Ihres BCMS belegen und riskieren blinde Flecken.','BSI200_4','BSI2004-A0350') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0350','R-R3-0579','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0580','R3-2026-07','Ist nicht festgelegt und dokumentiert, welche Übungsarten Sie unterscheiden und wie diese definiert sind, üben Beteiligte mit unterschiedlichem Verständnis. Übungen werden falsch zugeschnitten, Ziele verfehlt und Ergebnisse nicht vergleichbar. So entstehen Deckungslücken zwischen dem, was Sie glauben geübt zu haben, und Ihrer tatsächlichen Einsatzbereitschaft.','BSI200_4','BSI2004-A0351') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0351','R-R3-0580','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0581','R3-2026-07','Legen Sie nicht fest, welche übergreifenden Übungsziele mit welchen Übungsarten erreicht werden und ob sie messbar sind, üben Sie ohne klaren Zweck. Sie können den Erfolg nicht bewerten, Verbesserungsbedarfe bleiben unerkannt und Ressourcen verpuffen. Ihre Notfallfähigkeit entwickelt sich planlos, ohne dass Sie den Fortschritt belegen können.','BSI200_4','BSI2004-A0352') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0352','R-R3-0581','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0582','R3-2026-07','Sind die regulatorischen, rechtlichen und vertraglichen Anforderungen an das Üben nicht festgelegt, übersehen Sie verpflichtende Nachweise und Prüffristen. Aufsichtsbehörden oder Vertragspartner können fehlende oder unzureichende Übungen beanstanden. Ihnen drohen Beanstandungen, Vertragsstrafen und Haftungsrisiken, weil Sie Ihre Notfallvorsorge nicht nachweisbar den Vorgaben entsprechend geübt haben.','BSI200_4','BSI2004-A0353') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0353','R-R3-0582','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0583','R3-2026-07','Ist nicht festgelegt, wie viele Übungen welcher Art in welchen Zeiträumen und mit welcher Detailtiefe stattfinden, üben Sie zu selten oder zu oberflächlich. Wichtige Szenarien bleiben über Jahre ungeprüft, während anderes redundant geübt wird. So bleiben kritische Lücken unentdeckt und Ihre Notfallbereitschaft ist nicht belastbar nachgewiesen.','BSI200_4','BSI2004-A0354') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0354','R-R3-0583','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0584','R3-2026-07','Legen Sie nicht fest, welche Zielgruppen mit welcher Übungsart adressiert werden und wie oft deren Mitglieder teilnehmen, bleiben Schlüsselpersonen ungeübt. Einzelne Rollen sind im Ernstfall überfordert, andere gar nicht eingebunden. Fällt eine ungeübte Person aus oder handelt falsch, gerät die gesamte Notfallbewältigung ins Stocken.','BSI200_4','BSI2004-A0355') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0355','R-R3-0584','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0585','R3-2026-07','Ist nicht festgelegt und dokumentiert, welche Ausfallszenarien wie oft geübt werden, decken Sie über die Jahre nicht alle relevanten Szenarien ab. Bestimmte Krisenlagen treffen Sie völlig ungeübt, während andere überproportional trainiert werden. Im realen, ungeprobten Szenario reagieren Ihre Teams unvorbereitet und der Wiederanlauf misslingt.','BSI200_4','BSI2004-A0356') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0356','R-R3-0585','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0586','R3-2026-07','Sind die Anforderungen an Realitätsnähe und Komplexität der Übungen nicht festgelegt, bleiben Ihre Übungen zu einfach und praxisfern. Beteiligte gewinnen ein trügerisches Sicherheitsgefühl, das im echten, komplexen Notfall nicht trägt. Unvorhergesehene Wechselwirkungen und Belastungen treffen Sie unvorbereitet und lassen die Notfallbewältigung überraschend scheitern.','BSI200_4','BSI2004-A0357') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0357','R-R3-0586','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0587','R3-2026-07','Ist nicht festgelegt, wie Sie mögliche Auswirkungen von Übungen auf den Geschäftsbetrieb einschätzen, kann eine Übung selbst zu Störungen führen. Ohne Risikobewertung lösen Sie ungewollt reale Ausfälle, Datenverluste oder Kundenbeeinträchtigungen aus. So verursacht ausgerechnet Ihre Notfallvorsorge einen Schaden und untergräbt die Akzeptanz künftiger Übungen.','BSI200_4','BSI2004-A0358') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0358','R-R3-0587','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0588','R3-2026-07','Legen Sie nicht fest, wie die verschiedenen Übungsarten vorbereitet, durchgeführt, ausgewertet und dokumentiert werden, laufen Übungen unstrukturiert und ohne verwertbare Ergebnisse ab. Erkenntnisse gehen verloren, Verbesserungsbedarfe werden nicht nachgehalten. Ihr BCMS lernt nicht aus den Übungen, sodass dieselben Schwächen im Ernstfall unverändert bestehen bleiben.','BSI200_4','BSI2004-A0359') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0359','R-R3-0588','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0589','R3-2026-07','Ist nicht festgelegt, welche Rollen mit welchen Aufgaben, Rechten und Zuständigkeiten bei Übungen mitwirken, entstehen Verantwortungslücken und Doppelarbeit. Übungsleitung, Beobachter und Übende agieren unkoordiniert, wichtige Aspekte werden nicht abgedeckt. Die Übung verliert an Aussagekraft und liefert kein belastbares Bild Ihrer tatsächlichen Notfallfähigkeit.','BSI200_4','BSI2004-A0360') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0360','R-R3-0589','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0590','R3-2026-07','Stellen Sie nicht sicher, dass die Rahmenbedingungen zum Üben geeignet sind, verfehlen Ihre Übungen die Ziele des BCMS. Unpassende Vorgaben führen zu Übungen, die weder die richtigen Szenarien noch die relevanten Fähigkeiten prüfen. Sie investieren Aufwand, ohne Ihre Notfallbereitschaft wirklich zu verbessern oder nachzuweisen.','BSI200_4','BSI2004-A0361') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0361','R-R3-0590','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0591','R3-2026-07','Stimmen Sie die Rahmenbedingungen zum Üben nicht mit der Institutionsleitung ab und lassen sie nicht freigeben, fehlt der Übungsplanung die notwendige Verbindlichkeit und Rückendeckung. Ressourcen werden nicht bereitgestellt, Übungen fallen aus oder werden nicht ernst genommen. Ohne Managementbeteiligung bleibt Ihr Übungsprogramm wirkungslos und im Ernstfall ungenutzt.','BSI200_4','BSI2004-A0362') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0362','R-R3-0591','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0592','R3-2026-07','Erstellen Sie keine Jahresübungsplanung, die über einen festgelegten Zeitraum alle BC-Strategien, -Lösungen und -Pläne abdeckt, üben Sie unsystematisch und lückenhaft. Manche Pläne bleiben jahrelang ungeprüft und veralten unbemerkt. Im Notfall verlassen Sie sich auf Lösungen, deren Funktionsfähigkeit Sie nie bestätigt haben, mit entsprechendem Ausfallrisiko.','BSI200_4','BSI2004-A0363') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0363','R-R3-0592','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0593','R3-2026-07','Umfasst Ihre Jahresübungsplanung keinen Zeitraum von mindestens zwölf Monaten, planen Sie zu kurzsichtig und ohne verlässlichen Turnus. Wichtige Szenarien und Zielgruppen fallen durch das Raster, weil eine vollständige Abdeckung nicht gewährleistet ist. So bleiben Übungslücken bestehen und Ihre Notfallbereitschaft entwickelt sich nicht planbar weiter.','BSI200_4','BSI2004-A0364') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0364','R-R3-0593','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0594','R3-2026-07','Berücksichtigt Ihre Jahresübungsplanung die Rahmenbedingungen, rechtlichen Anforderungen sowie zeitlichen und personellen Ressourcen nicht, planen Sie Übungen unrealistisch. Termine kollidieren mit dem Tagesgeschäft, Beteiligte fehlen und Übungen werden verschoben oder abgesagt. Ihr Übungsprogramm zerfällt in der Praxis und liefert keine belastbare Notfallvorsorge.','BSI200_4','BSI2004-A0365') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0365','R-R3-0594','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0595','R3-2026-07','Berücksichtigen Sie im Aufbau- und Standard-BCMS die Erwartungen der Interessengruppen und die Reife des BCMS nicht in der Jahresübungsplanung, üben Sie am Bedarf vorbei. Wichtige Stakeholder-Anforderungen bleiben unerfüllt und der Reifegrad wächst nicht gezielt. So verfehlen Ihre Übungen ihre steuernde Wirkung und die Weiterentwicklung stagniert.','BSI200_4','BSI2004-A0366') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0366','R-R3-0595','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0596','R3-2026-07','Erfassen Sie pro Übung nicht mindestens Datum, Übungsart, Ziel, Umfang, Zuständige, Zielgruppe und den Ressourcenbedarf, bleibt die Planung unvollständig und unverbindlich. Übungen werden schlecht vorbereitet, Ressourcen fehlen und Ziele verschwimmen. Ohne diese Eckdaten lassen sich Durchführung und Erfolg weder steuern noch nachvollziehbar belegen.','BSI200_4','BSI2004-A0367') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0367','R-R3-0596','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0597','R3-2026-07','Sind Ihre Übungsziele nicht möglichst messbar definiert, können Sie den Übungserfolg nicht objektiv bewerten. Ob eine Fähigkeit wirklich beherrscht wird, bleibt Auslegungssache, und Schwächen werden schöngeredet. So entsteht ein trügerisches Bild Ihrer Notfallbereitschaft, und tatsächliche Defizite bleiben bis zum Ernstfall unentdeckt.','BSI200_4','BSI2004-A0368') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0368','R-R3-0597','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0598','R3-2026-07','Stimmen Sie den Jahresübungsplan nicht mit der Institutionsleitung ab und lassen ihn nicht freigeben, fehlt ihm Verbindlichkeit und Ressourcenzusage. Ohne Rückhalt des Managements werden Übungen zugunsten des Tagesgeschäfts verschoben oder gestrichen. Ihr Übungsprogramm verliert an Durchsetzungskraft, und geplante Notfalltests finden am Ende gar nicht statt.','BSI200_4','BSI2004-A0369') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0369','R-R3-0598','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0599','R3-2026-07','Überwacht der oder die BCB nicht, dass alle geplanten Übungen stattfinden, und werden ausgefallene Übungen nicht zeitnah nachgeholt, entstehen unbemerkte Übungslücken. Der Plan existiert nur auf dem Papier, während wichtige Szenarien ungeübt bleiben. So überschätzen Sie Ihre Notfallbereitschaft und stehen im Ernstfall vor ungeprüften Lösungen.','BSI200_4','BSI2004-A0370') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0370','R-R3-0599','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0600','R3-2026-07','Berücksichtigen Sie neben den regelmäßigen keine anlassbezogenen Übungen, reagieren Sie nicht auf neue Bedrohungen, Änderungen oder Vorfälle. Aktuelle Risiken und frisch geänderte Prozesse bleiben ungeübt, bis der Ernstfall sie offenlegt. Ihre Notfallvorsorge hinkt der realen Gefährdungslage hinterher und schützt Sie gerade bei neuen Szenarien nicht.','BSI200_4','BSI2004-A0371') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0371','R-R3-0600','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0601','R3-2026-07','Steigern Sie Komplexität und Herausforderung der Übungen nicht kontinuierlich und risikoorientiert, verharren Ihre Teams auf einfachem Niveau. Anspruchsvolle, realistische Krisenlagen werden nie trainiert, und ein trügerisches Sicherheitsgefühl entsteht. Trifft Sie ein wirklich komplexer Notfall, sind die Beteiligten überfordert und die Notfallbewältigung bricht zusammen.','BSI200_4','BSI2004-A0372') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0372','R-R3-0601','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0602','R3-2026-07','Üben Sie die technischen und organisatorischen Aspekte der Notfallbewältigung nicht schrittweise im Zusammenspiel, prüfen Sie nur isolierte Einzelteile. Die entscheidenden Schnittstellen zwischen Technik und Organisation bleiben ungetestet und versagen im Ernstfall. So funktioniert zwar jede Komponente für sich, das Gesamtsystem des Wiederanlaufs jedoch nicht.','BSI200_4','BSI2004-A0373') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0373','R-R3-0602','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0603','R3-2026-07','Stellen Sie nicht sicher, dass auch die Stellvertretenden der BAO an Übungen teilnehmen, sind diese im Ernstfall unvorbereitet. Fällt die Erstbesetzung aus, was in Krisen häufig vorkommt, übernehmen ungeübte Personen zentrale Rollen. Die Notfallbewältigung verliert genau dann an Schlagkraft, wenn die Belastung am höchsten ist.','BSI200_4','BSI2004-A0374') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0374','R-R3-0603','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0604','R3-2026-07','Entscheiden Sie nicht bewusst für jede Übung, ob sie angekündigt wird oder nicht, verzerren Sie das Übungsergebnis. Stets angekündigte Übungen prüfen keine realistische Reaktions- und Alarmierungsfähigkeit, unangekündigte ohne Vorbereitung können unnötigen Schaden anrichten. So gewinnen Sie entweder ein geschöntes oder ein durch Störungen belastetes Bild Ihrer Notfallbereitschaft.','BSI200_4','BSI2004-A0375') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0375','R-R3-0604','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0605','R3-2026-07','Stellt der oder die BCB durch Mindestanforderungen, Vorlagen und Anweisungen keine einheitliche Dokumentation innerhalb einer Übungsart sicher, sind Übungsergebnisse uneinheitlich und schwer vergleichbar. Wichtige Erkenntnisse gehen verloren oder werden übersehen. So können Sie Fortschritte und wiederkehrende Schwächen nicht erkennen und Ihr BCMS lernt nicht systematisch aus Übungen.','BSI200_4','BSI2004-A0376') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0376','R-R3-0605','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0606','R3-2026-07','Erstellen Sie in der Vorbereitungsphase kein Übungskonzept mit den organisatorischen Eckpunkten, läuft die Übung planlos und improvisiert ab. Zeitrahmen, Ort, Ablauf und Ziele sind unklar, Beteiligte agieren unkoordiniert. Die Übung verliert an Aussagekraft, verschwendet Ressourcen und liefert kein verlässliches Bild Ihrer Notfallbereitschaft.','BSI200_4','BSI2004-A0377') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0377','R-R3-0606','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0607','R3-2026-07','Dokumentieren Sie Übungsverlauf und -ergebnisse nicht nachvollziehbar durch eine Übungsprotokollierung, lässt sich die Übung später nicht auswerten. Entscheidungen, Reaktionszeiten und Fehler bleiben unbelegt, Verbesserungsbedarfe versanden. Ohne belastbare Protokolle können Sie weder den Zielerreichungsgrad nachweisen noch aus der Übung lernen, sodass dieselben Schwächen bestehen bleiben.','BSI200_4','BSI2004-A0378') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0378','R-R3-0607','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0608','R3-2026-07','Erstellen Sie für eine Übung keinen Übungsbericht mit den wesentlichen Ergebnissen, Zielerreichungsgrad und Verbesserungsbedarfen, bleiben die Erkenntnisse unverwertet. Entscheidungsträger erfahren nicht, wo die Notfallbewältigung schwächelt, und Maßnahmen werden nicht angestoßen. So verpufft der Übungsaufwand wirkungslos, und identifizierte Schwachstellen wirken sich ungebremst im nächsten Ernstfall aus.','BSI200_4','BSI2004-A0379') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0379','R-R3-0608','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0609','R3-2026-07','Prüfen Sie in Planbesprechungen die Notfallpläne nicht gemeinsam mit den Anwendenden auf fachliche Plausibilität, bleiben Fehler, Lücken und unrealistische Annahmen unentdeckt. Die Pläne wirken vollständig, versagen aber in der Praxis. Im Ernstfall folgen Ihre Teams Anweisungen, die nicht umsetzbar sind, und der Wiederanlauf scheitert an vermeidbaren Mängeln.','BSI200_4','BSI2004-A0380') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0380','R-R3-0609','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0610','R3-2026-07','Übernimmt die Vorbereitung einer Planbesprechung keine Person aus der zuständigen Organisationseinheit, in deren Bereich der Plan entstand, fehlt das nötige Fachwissen. Wichtige Details und Praxisbezüge werden übersehen, die Besprechung bleibt oberflächlich. So bestätigen Sie Pläne, deren fachliche Schwächen erst im realen Notfall zutage treten.','BSI200_4','BSI2004-A0381') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0381','R-R3-0610','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0611','R3-2026-07','Führen Sie die Planbesprechung nicht als durch die Übungsleitung moderierte Besprechung mit Leitfragen durch, verläuft sie unstrukturiert und lückenhaft. Wichtige Aspekte werden übersprungen, dominante Teilnehmer lenken ab, kritische Fragen bleiben ungestellt. So übersehen Sie Schwachstellen in Ihren Notfallplänen, die im Ernstfall den Wiederanlauf gefährden.','BSI200_4','BSI2004-A0382') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0382','R-R3-0611','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0612','R3-2026-07','Prüfen Sie in der Planbesprechung nicht Vollständigkeit, Plausibilität, realistische Umsetzbarkeit im RTO-Zeitraum und Aktualität der Maßnahmen, bleiben veraltete oder undurchführbare Pläne im Umlauf. Sie verlassen sich im Notfall auf Annahmen, die nicht mehr stimmen. Der Wiederanlauf dauert länger als toleriert, und zeitkritische Prozesse fallen zu lange aus.','BSI200_4','BSI2004-A0383') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0383','R-R3-0612','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0613','R3-2026-07','Erstellen Sie für Stabsübungen nicht die notwendigen Vorlagen und Hilfsmittel wie Übungskonzept, Drehbuch mit Einlagen und Protokoll, verläuft die Übung unstrukturiert und wenig realitätsnah. Der Stab wird nicht gezielt gefordert, Ergebnisse sind nicht auswertbar. So bleibt ungeprüft, ob Ihr Krisenstab im Ernstfall handlungsfähig und entscheidungsstark ist.','BSI200_4','BSI2004-A0384') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0384','R-R3-0613','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0614','R3-2026-07','Legen Sie für Stabsübungen keine klar definierten und dokumentierten Übungsziele fest, üben Sie den Krisenstab ohne Maßstab. Ob Entscheidungsfindung, Kommunikation und Zusammenarbeit tatsächlich funktionieren, lässt sich nicht bewerten. Schwächen im Stabsverhalten bleiben unerkannt und offenbaren sich erst im realen Krisenfall, wenn Fehlentscheidungen den Schaden vergrößern.','BSI200_4','BSI2004-A0385') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0385','R-R3-0614','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0615','R3-2026-07','Planen und dokumentieren Sie den Rahmenablauf der Stabsübung einschließlich Ankündigung und vorgeschalteter Alarmierung nicht, startet die Übung chaotisch und unvollständig. Die Alarmierungskette wird nicht mitgeprüft, Beteiligte sind unvorbereitet. So bleibt offen, ob Ihr Stab im Ernstfall überhaupt rechtzeitig zusammenkommt und die Arbeit koordiniert aufnimmt.','BSI200_4','BSI2004-A0386') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0386','R-R3-0615','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0616','R3-2026-07','Führen Sie nach der Stabsübung keine erste und keine zweite strukturierte Auswertungsrunde mit den Teilnehmenden durch, gehen wertvolle Erkenntnisse verloren. Beobachtungen bleiben unstrukturiert, Verbesserungsbedarfe werden nicht erfasst und keine Maßnahmen abgeleitet. So lernt Ihr Krisenstab nicht aus der Übung, und dieselben Fehler wiederholen sich im echten Notfall.','BSI200_4','BSI2004-A0387') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0387','R-R3-0616','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0617','R3-2026-07','Ohne verbindliche Regeln zur Abgrenzung kann eine Stabsübung unbeabsichtigt in den Wirkbetrieb übergreifen und produktive Systeme, Datenbestände oder Geschäftsprozesse stören. Sie riskieren dadurch reale Ausfälle, verunsicherte Beschäftigte und Schäden, die weit über den beabsichtigten Übungsrahmen hinausgehen und Ihre Institution auch nach Übungsende belasten.','BSI200_4','BSI2004-A0388') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0388','R-R3-0617','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0618','R3-2026-07','Fehlen definierte Abbruchbedingungen, läuft eine Stabsübung auch dann weiter, wenn sie außer Kontrolle gerät oder ein echter Notfall eintritt. Sie können die Übung nicht mehr geordnet stoppen, gefährden Beschäftigte und Betrieb und verlieren im entscheidenden Moment die Fähigkeit, klar zwischen Übung und Ernstfall zu trennen.','BSI200_4','BSI2004-A0389') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0389','R-R3-0618','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0619','R3-2026-07','Wird bei der Außenkommunikation nicht deutlich gemacht, dass es sich um eine Übung handelt, können Empfänger eine Anfrage für einen echten Notfall halten. Sie lösen dadurch unnötige Alarmierungen, Einsätze externer Stellen oder öffentliche Verunsicherung aus und beschädigen Vertrauen sowie Glaubwürdigkeit Ihrer Institution nachhaltig.','BSI200_4','BSI2004-A0390') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0390','R-R3-0619','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0620','R3-2026-07','Ein unplausibles oder nicht auf Ihre Institution zugeschnittenes Szenario führt dazu, dass die Übung als realitätsfern empfunden wird. Die Übenden nehmen sie nicht ernst, gewonnene Erkenntnisse sind wenig belastbar, und Sie überprüfen Ihre Notfallorganisation letztlich nicht unter Bedingungen, die einem echten Ernstfall nahekommen.','BSI200_4','BSI2004-A0391') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0391','R-R3-0620','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0621','R3-2026-07','Ohne ein aus allen Einlagen erstelltes Übungsdrehbuch verläuft die Stabsübung unstrukturiert und für die Übungsleitung nicht steuerbar. Sie verlieren den roten Faden, Einlagen greifen nicht ineinander, und wichtige Übungsziele bleiben ungetestet, sodass der Aufwand keine verwertbaren Ergebnisse für Ihr BCM liefert.','BSI200_4','BSI2004-A0392') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0392','R-R3-0621','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0622','R3-2026-07','Sind die Übungsrollen nicht festgelegt und konkret besetzt, ist während der Durchführung unklar, wer leitet, unterstützt, protokolliert oder beobachtet. Verantwortlichkeiten überschneiden sich oder bleiben offen, die Übung gerät ins Stocken, und Sie erhalten weder eine saubere Steuerung noch eine belastbare Auswertung.','BSI200_4','BSI2004-A0393') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0393','R-R3-0622','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0623','R3-2026-07','Wird die Vorbereitungsphase abgeschlossen, obwohl die Übungsziele nicht realistisch erreichbar sind, startet die Übung mit unlösbaren Vorgaben. Die Übenden werden überfordert oder demotiviert, die Ergebnisse verzerren das tatsächliche Reifegradbild, und Sie ziehen aus einer schlecht vorbereiteten Übung falsche Schlüsse für Ihr Notfallmanagement.','BSI200_4','BSI2004-A0394') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0394','R-R3-0623','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0624','R3-2026-07','Wird die Zeit bis zum Ausrufen von Notfall oder Krise nicht gemessen und mit der BAO-Reaktionszeit verglichen, bleibt unbekannt, ob Ihre Alarmierung schnell genug funktioniert. Sie erkennen Verzögerungen in der Reaktionskette nicht und riskieren, dass die besondere Aufbauorganisation im Ernstfall zu spät handlungsfähig wird.','BSI200_4','BSI2004-A0395') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0395','R-R3-0624','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0625','R3-2026-07','Besitzt die Übungsleitung nicht das Recht, von der Zeitplanung abzuweichen oder abzubrechen, kann sie auf unvorhergesehene Entwicklungen nicht angemessen reagieren. Sie verlieren die Kontrolle über den Übungsverlauf, gefährden bei kritischen Situationen Beschäftigte und Betrieb und können eine entgleisende Übung nicht rechtzeitig stoppen.','BSI200_4','BSI2004-A0396') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0396','R-R3-0625','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0626','R3-2026-07','Greifen Protokollierende und Beobachtende in das Geschehen ein, verfälschen sie den natürlichen Übungsverlauf und die Reaktionen der Übenden. Sie erhalten dadurch ein geschöntes, nicht aussagekräftiges Bild der tatsächlichen Handlungsfähigkeit und verlieren die neutrale Grundlage, die Sie für eine ehrliche Auswertung Ihrer Notfallorganisation benötigen.','BSI200_4','BSI2004-A0397') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0397','R-R3-0626','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0627','R3-2026-07','Wird die Übung nicht durch die Übungsleitung offiziell beendet, bleibt für die Teilnehmenden unklar, ab wann wieder Normalbetrieb gilt. Sie riskieren, dass Übungshandlungen in den Wirkbetrieb hineinreichen, echte Meldungen mit Übungseinlagen verwechselt werden und der Übergang zurück in den Alltag ungeordnet und fehleranfällig verläuft.','BSI200_4','BSI2004-A0398') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0398','R-R3-0627','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0628','R3-2026-07','Werden bei Stabsrahmenübungen nicht alle Anforderungen an Stabsübungen erfüllt, fehlen grundlegende Regeln, Rollen und Sicherheitsvorkehrungen. Die erweiterte Übung wird dadurch unkontrollierbar und riskant, Sie gefährden den Normalbetrieb und erhalten trotz höheren Aufwands keine belastbaren Erkenntnisse über die Leistungsfähigkeit Ihrer Notfallorganisation.','BSI200_4','BSI2004-A0399') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0399','R-R3-0628','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0629','R3-2026-07','Werden die für Stabsrahmenübungen erforderlichen Sicherheitsvorkehrungen nicht vorab geklärt und getroffen, können während der aufwändigen Übung reale Schäden entstehen. Sie riskieren Beeinträchtigungen von Personen, Systemen und Betrieb an mehreren Übungsorten und stehen unvorbereitet da, wenn Zwischenfälle ein sofortiges, geordnetes Eingreifen erfordern.','BSI200_4','BSI2004-A0400') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0400','R-R3-0629','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0630','R3-2026-07','Ist an einem Übungsort kein Teammitglied oder keine beobachtende Person anwesend oder zugeschaltet, bleibt das dortige Geschehen unbeaufsichtigt und undokumentiert. Sie können weder steuernd eingreifen noch Auffälligkeiten erfassen und riskieren, dass Fehlentwicklungen oder ein realer Notfall an diesem Standort unbemerkt eskalieren.','BSI200_4','BSI2004-A0401') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0401','R-R3-0630','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0631','R3-2026-07','Werden Einlagen und schriftliche Unterlagen nicht eindeutig mit Übungsdatum und Bezeichnung als Übungselemente gekennzeichnet, können sie mit echten Notfalldokumenten verwechselt werden. Sie riskieren, dass Übungsschreiben reale Prozesse auslösen oder umgekehrt echte Meldungen als Übung abgetan werden, was im Ernstfall zu gefährlichen Fehlentscheidungen führt.','BSI200_4','BSI2004-A0402') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0402','R-R3-0631','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0632','R3-2026-07','Fehlen für die Stabsrahmenübung Verhaltensregeln, insbesondere für die Kommunikation aus dem Stabsraum heraus, können vertrauliche oder als echt missverstandene Meldungen nach außen dringen. Sie riskieren dadurch reale Reaktionen bei Externen, Verunsicherung und Reputationsschäden sowie einen Kontrollverlust über die Informationen, die Ihre Institution während der Übung verlassen.','BSI200_4','BSI2004-A0403') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0403','R-R3-0632','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0633','R3-2026-07','Ist nicht geregelt, wie sich die Teilnehmenden beim Eintritt einer Abbruchbedingung oder eines realen Notfalls verhalten sollen, reagieren sie in dieser kritischen Lage uneinheitlich und unsicher. Sie riskieren, dass Übung und Ernstfall vermischt werden und im entscheidenden Moment wertvolle Zeit für eine geordnete Reaktion verloren geht.','BSI200_4','BSI2004-A0404') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0404','R-R3-0633','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0634','R3-2026-07','Wird bei Alarmierungsübungen nicht getestet, ob die organisatorischen und technischen Maßnahmen eine Alarmierung im erforderlichen Zeitraum ermöglichen, bleibt die tatsächliche Leistungsfähigkeit ungeprüft. Sie verlassen sich auf eine Alarmierung, die im Ernstfall zu langsam oder außerhalb der Geschäftszeiten gar nicht funktioniert, und bemerken Lücken erst dann, wenn es zu spät ist.','BSI200_4','BSI2004-A0405') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0405','R-R3-0634','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0635','R3-2026-07','Liegt für anwendungsorientierte Alarmierungsübungen kein abgestimmter Alarmierungspfad mit aktuellen Kontaktdaten und funktionstüchtigen Kommunikationswegen vor, laufen Meldungen ins Leere. Sie riskieren, dass Verantwortliche im Ernstfall über veraltete Nummern nicht erreichbar sind und Ihre Notfallorganisation dadurch verspätet oder unvollständig alarmiert wird.','BSI200_4','BSI2004-A0406') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0406','R-R3-0635','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0636','R3-2026-07','Wird bei anwendungsorientierten Alarmierungsübungen nicht entschieden und geregelt, ob die Erreichbarkeit auch außerhalb der Dienstzeit getestet wird, bleibt ein entscheidender Bereich ungeprüft. Da Notfälle häufig abends, nachts oder am Wochenende eintreten, riskieren Sie, dass gerade dann die Alarmierung versagt, ohne dass Sie es vorher bemerkt haben.','BSI200_4','BSI2004-A0407') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0407','R-R3-0636','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0637','R3-2026-07','Wird in der Jahresplanung nicht sichergestellt, dass über einen festgelegten Zeitraum alle definierten Alarmierungswege getestet werden, bleiben einzelne Wege dauerhaft ungeprüft. Sie verlassen sich auf Alarmierungskanäle, deren Funktionsfähigkeit nie bestätigt wurde, und riskieren, dass genau ein solcher Weg im Ernstfall ausfällt und die Notfallreaktion verzögert.','BSI200_4','BSI2004-A0408') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0408','R-R3-0637','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0638','R3-2026-07','Werden keine Funktionstests durchgeführt, die realitätsnah prüfen, ob Vorsorgemaßnahmen, Notfallpläne und Notfallmaßnahmen wie vorgesehen wirken, bleibt deren Tauglichkeit reine Annahme. Sie entdecken Schwachstellen und Planungsfehler erst im Ernstfall, wenn ein Versagen der Maßnahmen unmittelbar zu Ausfällen und erheblichen Schäden führt.','BSI200_4','BSI2004-A0409') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0409','R-R3-0638','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0639','R3-2026-07','Wird nicht verifiziert, ob die im Notfallplan enthaltenen Zeitvorgaben eingehalten werden können, bleiben Wiederanlauf- und Wiederherstellungszeiten unbewiesene Papierwerte. Sie riskieren, dass die tatsächliche Wiederherstellung deutlich länger dauert als geplant und wichtige Geschäftsprozesse im Ernstfall die tolerierbaren Ausfallzeiten überschreiten.','BSI200_4','BSI2004-A0410') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0410','R-R3-0639','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0640','R3-2026-07','Überprüfen die ressourcenzuständigen Einheiten vor Funktionstests nicht mittels Komponententests, ob die erforderlichen Einrichtungen funktionsfähig sind, kann der eigentliche Funktionstest an vermeidbaren Grundproblemen scheitern. Sie verlieren Zeit und Aussagekraft und riskieren, dass ein Fehlschlag fälschlich der Notfallmaßnahme statt einer defekten Komponente zugeschrieben wird.','BSI200_4','BSI2004-A0411') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0411','R-R3-0640','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0641','R3-2026-07','Wird die Planung der Komponententests nicht mit der Planung des BCM abgestimmt, laufen beide Aktivitäten unkoordiniert nebeneinander. Sie riskieren doppelten Aufwand, Terminkonflikte und Lücken, in denen wichtige Ressourcen ungeprüft bleiben, sodass Funktionstests auf unbestätigten Grundlagen aufsetzen und an Aussagekraft verlieren.','BSI200_4','BSI2004-A0412') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0412','R-R3-0641','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0642','R3-2026-07','Führt der Übungsautor für Funktionstests keine Risikoeinschätzung durch, ermittelt keine risikosenkenden Maßnahmen und dokumentiert diese nicht, bleiben Gefahren für den Geschäftsbetrieb unerkannt. Sie riskieren, dass ein Test produktive Systeme beeinträchtigt oder ausfallen lässt, ohne dass vorab Vorkehrungen zur Begrenzung dieser Schäden getroffen wurden.','BSI200_4','BSI2004-A0413') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0413','R-R3-0642','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0643','R3-2026-07','Wird für Funktionstests mit potenziellen Auswirkungen auf den Geschäftsbetrieb keine Freigabe der Institutionsleitung eingeholt, fehlt die bewusste Abwägung und Verantwortungsübernahme auf oberster Ebene. Sie riskieren, dass ein Test ohne Rückhalt der Leitung produktive Prozesse stört und im Schadensfall Zuständigkeit und Legitimation der Maßnahme unklar bleiben.','BSI200_4','BSI2004-A0414') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0414','R-R3-0643','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0644','R3-2026-07','Werden anhand der Risikoeinschätzung keine Maßnahmen vorgesehen, die einen Abbruch des Funktionstests und die schnellstmögliche Wiederherstellung des Ausgangszustands ermöglichen, können Sie bei unbeabsichtigten Auswirkungen nicht gegensteuern. Sie riskieren, dass sich ein Testfehler ungebremst zu einer echten Betriebsstörung ausweitet und der reguläre Zustand nur mühsam wiederhergestellt werden kann.','BSI200_4','BSI2004-A0415') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0415','R-R3-0644','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0645','R3-2026-07','Wird ein Funktionstest, für den vorab eine Testumgebung vorbereitet werden muss, nicht in der Institution angekündigt, können Beschäftigte die Testaktivitäten für reale Störungen halten. Sie riskieren unnötige Meldungen, Fehlreaktionen und Betriebsunruhe und behindern zudem die geordnete Bereitstellung der benötigten Testumgebung.','BSI200_4','BSI2004-A0416') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0416','R-R3-0645','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0646','R3-2026-07','Werden Herstellung und Rückbau der Testumgebung nicht geplant und speziell geschaffene Vorkehrungen nach Übungsende nicht rückgängig gemacht, verbleiben temporäre Konfigurationen im Wirkbetrieb. Sie riskieren dadurch Sicherheitslücken, instabile Systeme und Fehlfunktionen, weil Übungsprovisorien unbeabsichtigt zum Dauerzustand werden und den Normalbetrieb gefährden.','BSI200_4','BSI2004-A0417') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0417','R-R3-0646','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0647','R3-2026-07','Werden Funktionstests nicht auf Basis der dem Notfallplan zugrunde liegenden Ressourcenkategorien durchgeführt, testen Sie möglicherweise andere Elemente als die tatsächlich notfallrelevanten. Sie riskieren, dass wesentliche Ressourcen ungeprüft bleiben und die Testergebnisse keinen belastbaren Bezug zu den im Notfallplan vorausgesetzten Wiederanlaufbedingungen haben.','BSI200_4','BSI2004-A0418') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0418','R-R3-0647','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0648','R3-2026-07','Steuert die Übungsleitung den Ablauf des Funktionstests nicht unter Beachtung von Zielen und Zeitplanung, und fehlt bei komplexen Tests eine koordinierende Unterstützung, verläuft der Test unkontrolliert. Sie riskieren, dass Ziele verfehlt, Zeitvorgaben gesprengt und kritische Auswirkungen auf den Betrieb nicht rechtzeitig erkannt und begrenzt werden.','BSI200_4','BSI2004-A0419') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0419','R-R3-0648','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0649','R3-2026-07','Wird pro getesteter Maßnahme oder Ressource nicht anhand einer einheitlichen Protokollvorlage dokumentiert, ob sie ohne Befund funktioniert hat oder Auffälligkeiten zeigte, gehen Ergebnisse verloren oder werden uneinheitlich erfasst. Sie können Schwachstellen später nicht nachvollziehen, vergleichen oder gezielt beheben und verlieren die Grundlage für eine belastbare Auswertung.','BSI200_4','BSI2004-A0420') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0420','R-R3-0649','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0650','R3-2026-07','Werden durchgeführte Übungen nicht ausgewertet und nachbereitet und daraus keine Korrekturbedarfe und Verbesserungsmöglichkeiten abgeleitet, bleibt der Übungsaufwand ohne Nutzen. Sie erkennen bestehende Schwächen nicht, wiederholen dieselben Fehler und verpassen die Chance, Ihr Notfallmanagement gezielt zu verbessern, sodass der Reifegrad des BCM stagniert.','BSI200_4','BSI2004-A0421') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0421','R-R3-0650','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0651','R3-2026-07','Werden sowohl die für die Übung herangezogenen als auch die in der Übung erstellten Dokumente nicht ausgewertet, entgehen Ihnen wichtige Hinweise auf veraltete, unvollständige oder unpraktikable Unterlagen. Sie riskieren, dass fehlerhafte Notfalldokumente unbemerkt bleiben und im Ernstfall zu falschen Entscheidungen und Verzögerungen führen.','BSI200_4','BSI2004-A0422') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0422','R-R3-0651','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0652','R3-2026-07','Werden Übungsergebnisse sowie identifizierte Korrekturbedarfe und Verbesserungsmöglichkeiten nicht in einem Übungsbericht dokumentiert, gehen die gewonnenen Erkenntnisse verloren. Sie können Maßnahmen nicht nachverfolgen, Fortschritte nicht belegen und den Verantwortlichen keine nachvollziehbare Grundlage liefern, um das BCM systematisch weiterzuentwickeln.','BSI200_4','BSI2004-A0423') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0423','R-R3-0652','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0653','R3-2026-07','Bewertet der oder die BCB den Reifegrad des BCM nicht anhand der Übungsergebnisse, fehlt eine objektive Einschätzung des tatsächlichen Leistungsstands. Sie riskieren, die Handlungsfähigkeit Ihrer Institution zu über- oder unterschätzen, setzen Ressourcen an falscher Stelle ein und erkennen strukturelle Schwächen des Notfallmanagements nicht rechtzeitig.','BSI200_4','BSI2004-A0424') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0424','R-R3-0653','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0654','R3-2026-07','Wird im Anschluss an Stabs- oder Stabsrahmenübungen keine Auswertungsrunde mit allen Teilnehmenden durchgeführt, bleiben deren unmittelbare Beobachtungen und Erfahrungen ungenutzt. Sie verlieren wertvolles Feedback zu Abläufen, Zusammenarbeit und Kommunikation und verpassen die Gelegenheit, konkrete Schwachstellen zu erkennen und gemeinsam Verbesserungen zu vereinbaren.','BSI200_4','BSI2004-A0425') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0425','R-R3-0654','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0655','R3-2026-07','Werden beim Einsatz einer Alarmierungssoftware deren Protokolle nicht ausgewertet und die BAO-Reaktionszeit nicht anhand der tatsächlich benötigten Alarmierungszeit überprüft, bleibt die reale Leistungsfähigkeit der Alarmierung im Dunkeln. Sie verlassen sich auf angenommene Reaktionszeiten und riskieren, dass Ihre Notfallorganisation im Ernstfall langsamer handlungsfähig ist als geplant.','BSI200_4','BSI2004-A0426') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0426','R-R3-0655','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0656','R3-2026-07','Wird der Übungsbericht nicht an den oder die BCB kommuniziert und werden die Ergebnisse nicht im Maßnahmenplan zur Korrektur und Verbesserung des BCMS aufgegriffen, verpuffen die Erkenntnisse folgenlos. Sie riskieren, dass erkannte Schwachstellen ungelöst bleiben, sich Fehler wiederholen und das Notfallmanagement sich trotz Übungen nicht weiterentwickelt.','BSI200_4','BSI2004-A0427') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0427','R-R3-0656','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0657','R3-2026-07','Wird nicht regelmäßig überprüft, ob das BCMS angemessen, wirksam, effizient und anforderungsgerecht ist, kann es unbemerkt veralten und an Wirksamkeit verlieren. Sie riskieren, dass sich Ihr Notfallmanagement von den tatsächlichen Risiken und Anforderungen entfernt und im Ernstfall nicht den erwarteten Schutz bietet.','BSI200_4','BSI2004-A0428') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0428','R-R3-0657','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0658','R3-2026-07','Werden die BCM-Prozessschritte nicht regelmäßig auf Vollständigkeit, Aktualität, Angemessenheit, Wirksamkeit, Plausibilität und Effizienz überprüft, schleichen sich Lücken und veraltete Annahmen ein. Sie riskieren, dass fehlerhafte oder überholte Prozesse unbemerkt bleiben und Ihr Notfallmanagement im Ernstfall an unentdeckten Schwachstellen scheitert.','BSI200_4','BSI2004-A0429') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0429','R-R3-0658','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0659','R3-2026-07','Legt die Institution keine Messziele fest und leitet daraus keine messbaren Kennzahlen auf angemessener Datengrundlage ab, lässt sich die Leistung des BCM nicht objektiv beurteilen. Sie steuern Ihr Notfallmanagement dann nach Gefühl statt nach Fakten und erkennen Fehlentwicklungen oder Verbesserungsbedarf nicht rechtzeitig und nicht belastbar.','BSI200_4','BSI2004-A0430') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0430','R-R3-0659','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0660','R3-2026-07','Werden für die Kennzahlen, wo möglich, keine Zielwerte festgelegt, fehlt der Maßstab, an dem Sie den Erfolg und die Wirksamkeit des BCM messen können. Sie erkennen dann weder das Verfehlen von Vorgaben noch positive Entwicklungen eindeutig und verlieren die Grundlage für eine gezielte, faktenbasierte Steuerung Ihres Notfallmanagements.','BSI200_4','BSI2004-A0431') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0431','R-R3-0660','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0661','R3-2026-07','Wenn Sie nicht festlegen, wer die Kennzahlen in welchen Abständen erhebt und auswertet, bleibt die Verantwortung ungeklärt und Messungen unterbleiben oder erfolgen unregelmäßig. Sie erkennen Fehlentwicklungen im BCMS dann zu spät und steuern Ihre Notfallvorsorge blind, ohne belastbare Grundlage für Entscheidungen.','BSI200_4','BSI2004-A0432') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0432','R-R3-0661','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0662','R3-2026-07','Werden Kennzahlen nicht dokumentiert und zentral zusammengeführt, liegen Ihnen die Informationen verstreut, unvollständig oder gar nicht vor. Sie können den Zustand des BCMS nicht nachvollziehbar bewerten, Trends bleiben unsichtbar, und gegenüber Leitung und Auditoren fehlt Ihnen ein prüfbarer Nachweis der Steuerung.','BSI200_4','BSI2004-A0433') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0433','R-R3-0662','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0663','R3-2026-07','Ohne stichprobenartige Qualitätsprüfung im Vier-Augen-Prinzip können fehlerhafte oder manipulierte Kennzahlen unbemerkt in Ihre Auswertung einfließen. Sie treffen dann Entscheidungen auf Basis falscher Daten, bewerten die Leistungsfähigkeit Ihres BCMS zu optimistisch und übersehen tatsächliche Schwachstellen in der Notfallvorsorge.','BSI200_4','BSI2004-A0434') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0434','R-R3-0663','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0664','R3-2026-07','Vergleichen Sie die Kennzahlen nicht mit Zielwerten und bewerten Abweichungen nicht nach Ursache und Schwere, bleiben Messwerte bloße Zahlen ohne Aussagekraft. Sie erkennen weder, ob Ihre Ziele erreicht werden, noch welche Abweichungen dringend Handlungsbedarf auslösen, und verlieren die Steuerungswirkung der Kennzahlen.','BSI200_4','BSI2004-A0435') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0435','R-R3-0664','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0665','R3-2026-07','Ohne regelmäßigen Überblick über den Status des BCMS und die einzelnen Prozessschritte verlieren Sie die Kontrolle über den Fortschritt Ihrer Maßnahmen. Verzögerungen und liegengebliebene Aufgaben bleiben unbemerkt, sodass Sie im Notfall auf eine unfertige oder lückenhafte Vorsorge zurückgreifen müssen.','BSI200_4','BSI2004-A0436') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0436','R-R3-0665','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0666','R3-2026-07','Ermitteln Sie keine Trends und untersuchen negative Entwicklungen nicht näher, erkennen Sie schleichende Verschlechterungen Ihres BCMS erst, wenn sie zum akuten Problem geworden sind. Sie verlieren die Chance, frühzeitig gegenzusteuern, und lassen sich abzeichnende Notfallrisiken ungebremst wachsen.','BSI200_4','BSI2004-A0437') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0437','R-R3-0666','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0667','R3-2026-07','Bewerten Sie die BC-Fähigkeiten zeitkritischer externer Dienstleister nicht anhand Ihrer Anforderungen und überwachen diese nicht, bleibt deren tatsächliche Belastbarkeit unklar. Fällt ein solcher Dienstleister im Notfall aus, bricht Ihr eigener Geschäftsbetrieb unerwartet ein, weil Sie sich auf ungeprüfte Zusagen verlassen haben.','BSI200_4','BSI2004-A0438') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0438','R-R3-0667','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0668','R3-2026-07','Überlegen Sie nicht, wie sich der Geschäftsbetrieb ohne den ursprünglichen Dienstleister wiederherstellen lässt, entsteht eine gefährliche Abhängigkeit ohne Ausweg. Bei Insolvenz, Kündigung oder Ausfall des Dienstleisters stehen Sie ohne Exit-Strategie da und können zeitkritische Prozesse nicht rechtzeitig fortführen.','BSI200_4','BSI2004-A0439') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0439','R-R3-0668','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0669','R3-2026-07','Sind Ziele und Geltungsbereich der Überprüfungen nicht festgelegt, verlaufen Audits und Revisionen unfokussiert und lassen wesentliche Bereiche außen vor. Sie erhalten dann kein aussagekräftiges Prüfergebnis, übersehen relevante Schwachstellen und können nicht belegen, dass Ihr BCMS tatsächlich wirksam geprüft wurde.','BSI200_4','BSI2004-A0440') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0440','R-R3-0669','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0670','R3-2026-07','Prüfen Sie das BCMS nicht jährlich und anlassbezogen durch Revisionen oder Audits, bleiben Mängel und veraltete Annahmen unentdeckt. Ihr Notfallmanagement passt sich dann nicht an veränderte Bedrohungen und Strukturen an, sodass Sie sich im Ernstfall auf eine überholte und unwirksame Vorsorge stützen.','BSI200_4','BSI2004-A0441') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0441','R-R3-0670','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0671','R3-2026-07','Werden Überprüfungen nicht von unabhängigen Personen durchgeführt, sondern von den am Aufbau Beteiligten, prüfen diese ihre eigene Arbeit. Betriebsblindheit und Interessenkonflikte führen dazu, dass Schwächen beschönigt oder übersehen werden und Sie ein trügerisch positives Bild Ihres BCMS erhalten.','BSI200_4','BSI2004-A0442') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0442','R-R3-0671','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0672','R3-2026-07','Prüft die interne Revision nicht, ob das BCMS die Leitlinienziele, die Anforderungen der Interessengruppen und des Standards erfüllt, bleibt unklar, ob Ihr System überhaupt zweckmäßig ist. Sie halten dann möglicherweise ein BCMS für konform, das zentrale Vorgaben verfehlt und im Notfall versagt.','BSI200_4','BSI2004-A0443') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0443','R-R3-0672','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0673','R3-2026-07','Ziehen Sie Korrektur- und Verbesserungsmaßnahmen aus früheren Überprüfungen nicht heran, prüfen Sie nicht, ob Mängel tatsächlich behoben wurden. Dieselben Schwachstellen treten dann wiederholt auf, Ihr Verbesserungsprozess läuft ins Leere, und dokumentierte Feststellungen bleiben folgenlos.','BSI200_4','BSI2004-A0444') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0444','R-R3-0673','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0674','R3-2026-07','Erstellt der oder die BCB keine zeitliche Übersicht der geplanten Überprüfungen, drohen Termine sich zu überschneiden, zu kollidieren oder ganz auszufallen. Sie verlieren den Überblick über Prüfzyklen, riskieren Lücken in der Kontrolle des BCMS und geraten bei angekündigten Audits unter Zeitdruck.','BSI200_4','BSI2004-A0445') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0445','R-R3-0674','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0675','R3-2026-07','Legen Sie nicht fest, wie auf Revisions- und Audit-Ankündigungen reagiert wird und welche Dokumente bereitzustellen sind, entsteht bei jeder Prüfung Hektik und Improvisation. Wichtige Unterlagen fehlen oder werden verspätet geliefert, was die Prüfung verzögert und einen unprofessionellen, unvorbereiteten Eindruck hinterlässt.','BSI200_4','BSI2004-A0446') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0446','R-R3-0675','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0676','R3-2026-07','Unterstützt der oder die BCB die Prüfer nicht aktiv bei der Auswahl von Dokumenten und Kontaktpersonen, verlieren diese Zeit und greifen auf ungeeignete oder unvollständige Grundlagen zurück. Die Prüfung wird dadurch langwieriger und ungenauer, und Sie riskieren ein verzerrtes Ergebnis über den Zustand Ihres BCMS.','BSI200_4','BSI2004-A0447') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0447','R-R3-0676','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0677','R3-2026-07','Werden die BCM-Rolleninhabenden nicht über eine bevorstehende Überprüfung informiert, sind sie nicht auskunftsfähig und stehen für Nachfragen nicht bereit. Die Prüfung verzögert sich, wichtige Ansprechpartner fehlen, und die Ergebnisse spiegeln dann eher Unvorbereitetheit als den tatsächlichen Zustand Ihres BCMS wider.','BSI200_4','BSI2004-A0448') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0448','R-R3-0677','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0678','R3-2026-07','Bewerten Sie festgestellte Abweichungen nach Audits und Revisionen nicht zeitnah und leiten keine Korrektur- und Verbesserungsmaßnahmen ab, bleiben erkannte Mängel unbehandelt. Der Aufwand der Prüfung verpufft, dieselben Schwächen bestehen fort, und Ihr BCMS verbessert sich trotz vorliegender Erkenntnisse nicht.','BSI200_4','BSI2004-A0449') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0449','R-R3-0678','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0679','R3-2026-07','Werden Ergebnisse, Abweichungen und abgeleitete Korrekturbedarfe nicht für die Institutionsleitung aufbereitet und kommuniziert, bleibt der Leitung der Handlungsbedarf verborgen. Sie erhält dann keine Grundlage für Entscheidungen und Ressourcenfreigaben, sodass notwendige Verbesserungen mangels Kenntnis und Rückhalt an der Spitze unterbleiben.','BSI200_4','BSI2004-A0450') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0450','R-R3-0679','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0680','R3-2026-07','Stellen Sie nicht sicher, dass festgestellte Mängel und ihre Ursachen zeitnah untersucht, dokumentiert und durch Korrekturmaßnahmen behandelt und deren Wirksamkeit geprüft wird, behandeln Sie nur Symptome. Die eigentlichen Ursachen bestehen fort, gleichartige Störungen wiederholen sich, und Ihr BCMS bleibt dauerhaft anfällig.','BSI200_4','BSI2004-A0451') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0451','R-R3-0680','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0681','R3-2026-07','Informiert der oder die BCB die Institutionsleitung nicht regelmäßig und zielgruppengerecht über den Status des BCMS und kommuniziert notwendige Handlungsbedarfe nicht als Entscheidungsgrundlage, trifft die Leitung Entscheidungen ohne Faktenbasis. Erforderliche Mittel und Prioritäten werden nicht bereitgestellt, und das BCMS verliert Rückhalt und Wirksamkeit.','BSI200_4','BSI2004-A0452') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0452','R-R3-0681','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0682','R3-2026-07','Vereinbart der oder die BCB mit der Institutionsleitung nicht, wie häufig über das BCMS berichtet wird, erfolgt die Berichterstattung willkürlich oder zu selten. Die Leitung verliert den Anschluss an den aktuellen Stand, reagiert verspätet auf Risiken und kann ihrer Verantwortung für die Notfallvorsorge nicht angemessen nachkommen.','BSI200_4','BSI2004-A0453') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0453','R-R3-0682','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0683','R3-2026-07','Berücksichtigt der Bericht des oder der BCB nicht den Status der Maßnahmen aus dem vorangegangenen Zyklus und aus früheren Entscheidungen, verliert die Leitung den Überblick über die Umsetzung. Beschlossene Maßnahmen versanden unbemerkt, und Sie können nicht nachvollziehen, ob getroffene Entscheidungen tatsächlich Wirkung entfaltet haben.','BSI200_4','BSI2004-A0454') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0454','R-R3-0683','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0684','R3-2026-07','Berücksichtigt der Bericht interne und externe Veränderungen des Umfeldes sowie Rückmeldungen der Interessengruppen nicht, bewertet die Leitung das BCMS auf veralteter Grundlage. Neue Bedrohungen, geänderte Rahmenbedingungen und wichtige Hinweise bleiben unbeachtet, sodass Ihre Notfallvorsorge den tatsächlichen Anforderungen zunehmend hinterherhinkt.','BSI200_4','BSI2004-A0455') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0455','R-R3-0684','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0685','R3-2026-07','Fließen die identifizierten Abweichungen, Trends und weiteren Erkenntnisse aus den Leistungsüberprüfungen sowie Audit- und Revisionsergebnisse nicht in den Bericht ein, entscheidet die Leitung ohne Kenntnis der wesentlichen Befunde. Erkannte Schwachstellen bleiben ohne Konsequenz, und die Steuerung des BCMS beruht auf einem unvollständigen Lagebild.','BSI200_4','BSI2004-A0456') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0456','R-R3-0685','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0686','R3-2026-07','Berücksichtigt der Bericht nicht die Bewertung der Angemessenheit von Leitlinie und Zielen sowie Verfahren und Ressourcen zur Effektivitätssteigerung, bleibt offen, ob Ihr BCMS noch zum Bedarf passt. Die Leitung kann dann weder Ziele nachschärfen noch Mittel bedarfsgerecht steuern, und das System veraltet schleichend.','BSI200_4','BSI2004-A0457') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0457','R-R3-0686','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0687','R3-2026-07','Fehlen im Bericht die Ergebnisse der Business-Impact-Analyse und der BCM-Risikoanalyse sowie die unzureichend abgesicherten Risiken früherer Analysen, entscheidet die Leitung ohne Kenntnis der kritischsten Gefahren. Ungedeckte Risiken bleiben ohne Ressourcen und Maßnahmen, sodass gerade Ihre größten Schwachstellen im Notfall ungeschützt bleiben.','BSI200_4','BSI2004-A0458') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0458','R-R3-0687','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0688','R3-2026-07','Berücksichtigt der Bericht nicht die Erkenntnisse aus Störungen mit Notfallpotenzial, aus eingetretenen Notfällen und die Chancen zur Verbesserung, verschenken Sie wertvolle Lernerfahrung. Dieselben Fehler wiederholen sich, aus realen Vorfällen wird nichts gelernt, und Ihr BCMS reift nicht an den tatsächlich erlebten Ereignissen.','BSI200_4','BSI2004-A0459') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0459','R-R3-0688','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0689','R3-2026-07','Überprüft die Institutionsleitung nicht regelmäßig auf Basis des BCMS-Status, ob das System geeignet, angemessen und effektiv ist, fehlt die oberste Steuerungsinstanz. Fehlentwicklungen bleiben ohne Korrektur, das BCMS entwickelt sich unkontrolliert, und die Leitung nimmt ihre Gesamtverantwortung für die Notfallvorsorge nicht wahr.','BSI200_4','BSI2004-A0460') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0460','R-R3-0689','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0690','R3-2026-07','Berücksichtigt die Institutionsleitung bei ihrer Bewertung nicht notwendige Änderungen des Geltungsbereichs, deckt Ihr BCMS mit der Zeit nicht mehr alle relevanten Bereiche ab. Neue Prozesse, Standorte oder Dienstleistungen bleiben ungeschützt, und im Notfall stellen Sie fest, dass kritische Teile Ihrer Institution außerhalb der Vorsorge lagen.','BSI200_4','BSI2004-A0461') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0461','R-R3-0690','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0691','R3-2026-07','Berücksichtigt die Leitung nicht die Korrekturbedarfe und Verbesserungsmöglichkeiten an Analyse-Methoden, BC-Strategien und Notfalllösungen, verfestigen sich veraltete oder untaugliche Ansätze. Ihre Vorsorge beruht dann auf überholten Annahmen, und im Ernstfall greifen Strategien und Lösungen nicht, weil sie nie hinterfragt und angepasst wurden.','BSI200_4','BSI2004-A0462') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0462','R-R3-0691','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0692','R3-2026-07','Berücksichtigt die Leitung nicht die Korrekturbedarfe an Verfahren und Überprüfungen aufgrund interner oder externer Anforderungen, verfehlt Ihr BCMS geänderte Vorgaben. Sie riskieren Compliance-Verstöße, Beanstandungen durch Aufsicht oder Auditoren und ein System, das gesetzliche und regulatorische Pflichten nicht mehr erfüllt.','BSI200_4','BSI2004-A0463') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0463','R-R3-0692','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0693','R3-2026-07','Berücksichtigt die Leitung nicht die Korrekturbedarfe an der Leistungsüberprüfung selbst, bleibt Ihr Mess- und Prüfsystem ineffizient und wenig aussagekräftig. Sie steuern das BCMS dann auf Basis unzuverlässiger Erkenntnisse, verschwenden Ressourcen für wenig ergiebige Prüfungen und übersehen weiterhin die eigentlich relevanten Schwachstellen.','BSI200_4','BSI2004-A0464') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0464','R-R3-0693','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0694','R3-2026-07','Berücksichtigt die Leitung bei geplanten Änderungen nicht deren Konsequenzen, führen Anpassungen zu ungewollten Neben- und Wechselwirkungen. Sie riskieren, dass eine Verbesserung an einer Stelle an anderer Stelle neue Lücken reißt, Abläufe stört oder Ressourcen bindet, weil die Folgen nicht durchdacht wurden.','BSI200_4','BSI2004-A0465') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0465','R-R3-0694','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0695','R3-2026-07','Werden die Ergebnisse der Bewertung durch die Institutionsleitung nicht dokumentiert und an die relevanten internen und externen Interessengruppen kommuniziert, bleiben Entscheidungen unverbindlich und unbekannt. Die Umsetzung lässt sich nicht nachhalten, Beteiligte handeln uninformiert, und Ihnen fehlt der Nachweis, dass die Leitung ihrer Bewertungspflicht nachgekommen ist.','BSI200_4','BSI2004-A0466') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0466','R-R3-0695','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0696','R3-2026-07','Trifft die Institutionsleitung anhand des BCMS-Status nicht die notwendigen strategischen oder taktischen Entscheidungen zur Neuausrichtung und Weiterentwicklung, stagniert Ihr System trotz erkanntem Handlungsbedarf. Wichtige Weichenstellungen unterbleiben, das BCMS verliert den Anschluss an neue Anforderungen, und aus Erkenntnissen erwachsen keine Verbesserungen.','BSI200_4','BSI2004-A0467') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0467','R-R3-0696','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0697','R3-2026-07','Werden aus den identifizierten Korrekturbedarfen und Verbesserungsmöglichkeiten keine konkreten Maßnahmen entwickelt, in einem Plan festgehalten und umgesetzt, bleiben Erkenntnisse folgenlose Absichtserklärungen. Ohne verbindlichen Maßnahmenplan versanden Verbesserungen im Alltag, und Ihr BCMS wird trotz erkannter Schwächen nicht wirksam weiterentwickelt.','BSI200_4','BSI2004-A0468') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0468','R-R3-0697','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0698','R3-2026-07','Wird die Eignung, Angemessenheit und Wirksamkeit des BCMS nicht fortlaufend verbessert und prüft der oder die BCB nicht stetig, ob Abweichungen dokumentiert und korrigiert werden, erstarrt Ihr System. Ohne kontinuierlichen Verbesserungsprozess veraltet die Notfallvorsorge, und erkannte Mängel bleiben dauerhaft unbehoben.','BSI200_4','BSI2004-A0469') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0469','R-R3-0698','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0699','R3-2026-07','Bereitet der oder die BCB keine Dokumentvorlage für den Maßnahmenplan vor und dokumentiert Korrektur- und Verbesserungsmaßnahmen nicht einheitlich darin, gehen Maßnahmen unstrukturiert und unvollständig verloren. Sie verlieren den Überblick über offene Punkte, können den Fortschritt nicht nachhalten und riskieren, dass wichtige Verbesserungen vergessen werden.','BSI200_4','BSI2004-A0470') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0470','R-R3-0699','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0700','R3-2026-07','Werden für jede Maßnahme der Korrekturbedarf beziehungsweise die Verbesserungsmöglichkeit sowie die geeignete Maßnahme nicht beschrieben, bleibt unklar, welches Problem wie gelöst werden soll. Umsetzende handeln dann ziellos, Maßnahmen verfehlen ihren Zweck, und Sie können weder Eignung noch Wirksamkeit der Behebung beurteilen.','BSI200_4','BSI2004-A0471') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0471','R-R3-0700','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0701','R3-2026-07','Werden Umsetzungsstatus, zuständige Stellen, benötigte finanzielle, personelle und zeitliche Ressourcen sowie der Fertigstellungstermin nicht dokumentiert, ist die Umsetzung nicht steuerbar. Verantwortlichkeiten verschwimmen, Ressourcen fehlen, Termine verstreichen unbemerkt, und Ihre Verbesserungsmaßnahmen bleiben ohne verbindlichen Rahmen liegen.','BSI200_4','BSI2004-A0472') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0472','R-R3-0701','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0702','R3-2026-07','Werden für jede Maßnahme keine eindeutige Kennung, keine Priorisierung und keine relevanten Umsetzungsdetails dokumentiert, verlieren Sie die Nachverfolgbarkeit und die richtige Reihenfolge. Dringende Maßnahmen geraten hinter unwichtige zurück, Verweise werden unklar, und die Steuerung Ihres Maßnahmenplans wird fehleranfällig und unübersichtlich.','BSI200_4','BSI2004-A0473') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0473','R-R3-0702','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0703','R3-2026-07','Werden die geplanten und dokumentierten Korrektur- und Verbesserungsmaßnahmen nicht durch die jeweils zuständigen Stellen bestätigt und umgesetzt, bleibt der Plan ein unverbindliches Papier. Ohne verbindliche Zusage und tatsächliche Umsetzung verpufft der Planungsaufwand, und erkannte Schwächen Ihres BCMS bestehen trotz vorliegender Maßnahmen fort.','BSI200_4','BSI2004-A0474') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0474','R-R3-0703','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0704','R3-2026-07','Überwacht der oder die BCB den Umsetzungsstatus nicht regelmäßig anhand des Maßnahmenplans, erkennen Sie Fehlentwicklungen und Verzögerungen erst, wenn es zu spät ist. Maßnahmen bleiben unbemerkt liegen, Termine reißen unkontrolliert, und Ihr Verbesserungsprozess läuft ohne Steuerung ins Leere.','BSI200_4','BSI2004-A0475') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0475','R-R3-0704','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0705','R3-2026-07','Wenn Sie umgesetzte Maßnahmen nicht auf Angemessenheit und Wirksamkeit prüfen und das Ergebnis nicht im Maßnahmenplan dokumentieren, verlassen Sie sich möglicherweise auf einen Schutz, den es faktisch nicht gibt. Unwirksame Vorkehrungen bleiben unentdeckt, im Ernstfall versagt Ihr Notfallmanagement, und Sie tragen dann vermeidbare Ausfälle, Nachweisdefizite und Haftungsrisiken.','BSI200_4','BSI2004-A0476') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('BSI200_4','BSI2004-A0476','R-R3-0705','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0706','R3-2026-07','Fehlen in Ihrer Informationssicherheitsrichtlinie klare Ziele und die Bedeutung der Informationssicherheit, bleibt für die Beschäftigten unklar, was Sie erreichen wollen und warum. Sicherheit wird beliebig ausgelegt, Vorgaben werden nicht ernst genommen, und Ihre Schutzmaßnahmen greifen nur zufällig statt gesteuert.','TISAX','1.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.1.1-2','R-R3-0706','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0707','R3-2026-07','Berücksichtigt Ihre Richtlinie die Organisationsstrategie sowie geltende Gesetze und vertragliche Verpflichtungen nicht, laufen Ihre Sicherheitsvorgaben an den realen Anforderungen vorbei. Sie riskieren Gesetzesverstöße, Vertragsbrüche gegenüber Kunden und Partnern sowie Bußgelder, weil Ihre Regeln den tatsächlichen Pflichten nicht gerecht werden.','TISAX','1.1.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.1.1-3','R-R3-0707','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0708','R3-2026-07','Weist Ihre Richtlinie nicht ausdrücklich auf die Folgen einer Nichtbeachtung hin, fehlt den Beschäftigten der spürbare Anreiz, sich an die Vorgaben zu halten. Regelverstöße bleiben ohne erkennbare Konsequenz, die Verbindlichkeit sinkt, und Sie können Fehlverhalten arbeitsrechtlich kaum sanktionieren.','TISAX','1.1.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.1.1-4','R-R3-0708','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0709','R3-2026-07','Erstellen Sie über die zentrale Richtlinie hinaus keine themenspezifischen Sicherheitsrichtlinien, bleiben wichtige Bereiche ohne konkrete Vorgaben. Die Beschäftigten wissen dann nicht, wie sie in Spezialfällen sicher handeln sollen, und es entstehen Lücken, die Angreifer und Fehler gezielt ausnutzen können.','TISAX','1.1.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.1.1-5','R-R3-0709','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0710','R3-2026-07','Ohne einen etablierten Prozess zur regelmäßigen Überprüfung und Aktualisierung veralten Ihre Richtlinien unbemerkt. Neue Bedrohungen, Techniken und rechtliche Änderungen bleiben unberücksichtigt, sodass Sie Ihre Sicherheit an gestern statt an heute ausrichten und im Ernstfall schutzlos dastehen.','TISAX','1.1.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.1.1-6','R-R3-0710','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0711','R3-2026-07','Machen Sie die Sicherheitsrichtlinien den Beschäftigten nicht in geeigneter Form zugänglich, kennen diese die geltenden Regeln schlicht nicht. Sie können sich dann nicht regelkonform verhalten, Verstöße häufen sich unbeabsichtigt, und Sie können die Verbindlichkeit der Vorgaben im Zweifel nicht nachweisen.','TISAX','1.1.1-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.1.1-7','R-R3-0711','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0712','R3-2026-07','Informieren Sie Mitarbeiter und externe Geschäftspartner nicht zeitnah über relevante Änderungen der Sicherheitsrichtlinien, handeln diese weiter nach überholten Regeln. Neue Schutzvorgaben verpuffen, gefährliche Altpraktiken bestehen fort, und Sie tragen Sicherheitslücken, die längst hätten geschlossen sein müssen.','TISAX','1.1.1-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.1.1-8','R-R3-0712','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0713','R3-2026-07','Ermitteln und dokumentieren Sie die Anforderungen Ihrer Organisation an das ISMS nicht, bauen Sie Ihr Sicherheitsmanagement auf ungeprüften Annahmen auf. Wesentliche Schutzbedarfe werden übersehen, das ISMS passt nicht zu Ihrer Organisation, und Sie investieren Aufwand an den falschen Stellen.','TISAX','1.2.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.1-2','R-R3-0713','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0714','R3-2026-07','Hat die Organisationsleitung das ISMS nicht offiziell beauftragt und freigegeben, fehlt ihm die notwendige Autorität und Ressourcenzusage. Sicherheitsvorgaben werden im Tagesgeschäft übergangen, Verantwortliche stehen ohne Rückhalt da, und Ihr Sicherheitsmanagement bleibt wirkungslos.','TISAX','1.2.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.1-3','R-R3-0714','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0715','R3-2026-07','Stellt Ihr ISMS der Leitung keine geeigneten Kontroll- und Steuerungsmittel wie ein regelmäßiges Management-Review bereit, steuert die Führung blind. Fehlentwicklungen und offene Risiken bleiben unbemerkt, notwendige Entscheidungen unterbleiben, und Sie verlieren die Kontrolle über den tatsächlichen Sicherheitsstand.','TISAX','1.2.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.1-4','R-R3-0715','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0716','R3-2026-07','Ermitteln Sie die anwendbaren Sicherheitsmaßnahmen nicht, etwa in einer Erklärung zur Anwendbarkeit oder einem ausgefüllten ISA-Katalog, wissen Sie nicht, welche Kontrollen gelten und umgesetzt sind. Schutzlücken bleiben verborgen, Nachweise fehlen, und Sie können Vollständigkeit und Wirksamkeit Ihres Sicherheitskonzepts nicht belegen.','TISAX','1.2.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.1-5','R-R3-0716','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0717','R3-2026-07','Überprüft das Management die Wirksamkeit des ISMS nicht regelmäßig, verlassen Sie sich auf einen Schutz, dessen tatsächliche Leistung niemand kennt. Schwachstellen und veraltete Maßnahmen bestehen fort, Verbesserungen unterbleiben, und Ihr Sicherheitsniveau sinkt schleichend, ohne dass Sie gegensteuern.','TISAX','1.2.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.1-6','R-R3-0717','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0718','R3-2026-07','Sind die Verantwortlichen für Informationssicherheit nicht definiert oder für ihre Aufgaben nicht ausreichend qualifiziert, bleiben wichtige Sicherheitsaufgaben liegen oder werden fehlerhaft erledigt. Zuständigkeiten verschwimmen, im Ernstfall handelt niemand kompetent, und Ihre Schutzmaßnahmen greifen nicht wie vorgesehen.','TISAX','1.2.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.2-2','R-R3-0718','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0719','R3-2026-07','Stehen die für die Umsetzung der Informationssicherheit notwendigen Ressourcen nicht in ausreichendem Umfang bereit, bleiben geplante Maßnahmen auf dem Papier. Überlastete Verantwortliche priorisieren notgedrungen falsch, Schutzlücken bleiben offen, und Ihr Sicherheitsniveau fällt hinter die tatsächlichen Anforderungen zurück.','TISAX','1.2.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.2-3','R-R3-0719','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0720','R3-2026-07','Sind die Ansprechpartner für Informationssicherheit intern und bei relevanten Geschäftspartnern nicht bekannt, gehen sicherheitsrelevante Meldungen ins Leere. Vorfälle werden zu spät oder gar nicht gemeldet, Reaktionen verzögern sich, und aus kleinen Störungen werden vermeidbare größere Schäden.','TISAX','1.2.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.2-4','R-R3-0720','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0721','R3-2026-07','Ist keine geeignete Informationssicherheitsstruktur definiert und dokumentiert, die auch weitere Sicherheitsaufgaben berücksichtigt, fehlt Ihrer Sicherheit das tragende Gerüst. Aufgaben fallen zwischen die Zuständigkeiten, Schnittstellen bleiben ungeregelt, und Sie können Sicherheit nicht verlässlich und nachvollziehbar organisieren.','TISAX','1.2.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.2-5','R-R3-0721','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0722','R3-2026-07','Ohne eine angemessene Funktionstrennung vereinen einzelne Personen unvereinbare Rollen und Rechte in einer Hand. Interessenkonflikte und unbemerkter Missbrauch werden möglich, das Vier-Augen-Prinzip fehlt, und Sie erhöhen das Risiko von Betrug, Manipulation und unentdeckten Fehlern erheblich.','TISAX','1.2.2-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.2-6','R-R3-0722','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0723','R3-2026-07','Sind Vorgehen und Kriterien zur sicherheitsbezogenen Klassifizierung von Projekten nicht dokumentiert, bewerten unterschiedliche Beteiligte den Schutzbedarf willkürlich. Kritische Projekte werden unterschätzt, notwendige Sicherheitsmaßnahmen unterbleiben, und Sie starten Vorhaben mit unerkannten Risiken.','TISAX','1.2.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.3-2','R-R3-0723','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0724','R3-2026-07','Führen Sie in einer frühen Projektphase keine Risikobewertung nach definiertem Vorgehen durch und wiederholen sie bei Änderungen nicht, bleiben Risiken bis spät im Projekt verborgen. Nachträgliche Korrekturen werden teuer, Sicherheitsmängel wandern ins fertige Ergebnis, und Sie verlieren die Steuerungsfähigkeit.','TISAX','1.2.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.3-3','R-R3-0724','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0725','R3-2026-07','Leiten Sie für identifizierte Informationssicherheitsrisiken keine geeigneten Maßnahmen ab und berücksichtigen diese nicht im Projekt, bleibt die Risikobewertung folgenlos. Bekannte Gefahren bestehen ungehindert fort, das Projektergebnis erbt vermeidbare Schwachstellen, und im Betrieb realisieren sich vorhersehbare Schäden.','TISAX','1.2.3-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.3-4','R-R3-0725','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0726','R3-2026-07','Überprüfen Sie die abgeleiteten Maßnahmen im Projektverlauf nicht regelmäßig und bewerten sie bei geänderten Kriterien nicht neu, passt Ihr Schutz nicht mehr zur veränderten Lage. Neue Risiken bleiben ungedeckt, überholte Maßnahmen binden Ressourcen, und Ihr Projekt läuft mit falschem Sicherheitsgefühl weiter.','TISAX','1.2.3-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.3-5','R-R3-0726','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0727','R3-2026-07','Beziehen Sie die Konfiguration der IT-Dienste nicht in die regelmäßigen Sicherheitsbewertungen ein, bleiben Fehlkonfigurationen und schleichende Abweichungen unentdeckt. Über die Zeit entstehen ausnutzbare Schwachstellen, das tatsächliche Schutzniveau sinkt unbemerkt, und Sie erkennen Angriffe erst, wenn der Schaden bereits eingetreten ist.','TISAX','1.2.4-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-10','R-R3-0727','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0728','R3-2026-07','Liegen keine Nachweise vor, dass Ihre IT-Dienstleister ihrer Verantwortung für die Informationssicherheit tatsächlich gerecht werden, verlassen Sie sich auf bloße Zusagen. Vernachlässigte Pflichten bleiben verborgen, im Schadensfall stehen Sie ohne belastbaren Beleg da, und Sie tragen die Folgen fremder Versäumnisse.','TISAX','1.2.4-11') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-11','R-R3-0728','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0729','R3-2026-07','Ist die Integration der IT-Dienste in lokale Schutzmaßnahmen wie sichere Authentifikationsverfahren nicht etabliert und dokumentiert, entstehen Brüche an den Schnittstellen. Angreifer nutzen ungeschützte Übergänge, Zugänge lassen sich umgehen, und Ihre lokalen Schutzvorkehrungen verlieren an den Rändern ihre Wirkung.','TISAX','1.2.4-12') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-12','R-R3-0729','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0730','R3-2026-07','Ermitteln Sie die für einen IT-Dienst relevanten Sicherheitsanforderungen nicht vollständig, betreiben Sie den Dienst mit unbekannten Lücken. Notwendige Schutzmaßnahmen fehlen, Schwachstellen bleiben unadressiert, und Sie setzen die vom Dienst verarbeiteten Informationen vermeidbaren Angriffen und Ausfällen aus.','TISAX','1.2.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-2','R-R3-0730','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0731','R3-2026-07','Ist die für die Umsetzung verantwortliche Organisation nicht eindeutig definiert und sich ihrer Verantwortung bewusst, fühlt sich am Ende niemand zuständig. Sicherheitsaufgaben bleiben unerledigt, jeder verlässt sich auf den anderen, und im Ernstfall verzögert unklare Verantwortung die dringend nötige Reaktion.','TISAX','1.2.4-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-3','R-R3-0731','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0732','R3-2026-07','Sind für gemeinsame Verantwortlichkeiten keine geeigneten Mechanismen festgelegt und umgesetzt, entstehen an den Übergaben zwischen Ihnen und dem Dienstleister gefährliche Lücken. Aufgaben fallen durch das Raster, beide Seiten gehen von der jeweils anderen aus, und Schutzmaßnahmen unterbleiben unbemerkt.','TISAX','1.2.4-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-4','R-R3-0732','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0733','R3-2026-07','Wird die verantwortliche Organisation ihren Verantwortlichkeiten rund um den IT-Dienst nicht tatsächlich gerecht, bleibt vereinbarte Sicherheit reine Theorie. Zugesagte Maßnahmen werden nicht gelebt, Schwachstellen bestehen fort, und Sie erkennen die Diskrepanz zwischen Anspruch und Wirklichkeit oft erst nach einem Vorfall.','TISAX','1.2.4-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-5','R-R3-0733','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0734','R3-2026-07','Wurde die Konfiguration der IT-Dienste nicht anhand der notwendigen Sicherheitsanforderungen konzipiert, umgesetzt und dokumentiert, betreiben Sie die Dienste möglicherweise unsicher voreingestellt. Standardkonfigurationen öffnen Angriffsflächen, und ohne Dokumentation können Sie den sicheren Sollzustand weder herstellen noch überprüfen.','TISAX','1.2.4-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-6','R-R3-0734','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0735','R3-2026-07','Ist das für die IT-Dienste verantwortliche Personal nicht entsprechend den Sicherheitsanforderungen geschult, entstehen im Betrieb Konfigurations- und Bedienfehler. Sicherheitsfunktionen werden falsch eingesetzt oder abgeschaltet, Warnzeichen übersehen, und aus vermeidbaren menschlichen Fehlern werden ernste Sicherheitsvorfälle.','TISAX','1.2.4-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-7','R-R3-0735','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0736','R3-2026-07','Fehlt ein Verzeichnis der betreffenden IT-Dienste und der jeweils verantwortlichen IT-Dienstleister, verlieren Sie den Überblick über Ihre Abhängigkeiten. Unbekannte oder vergessene Dienste bleiben ungeprüft, im Störungsfall wissen Sie nicht, an wen Sie sich wenden müssen, und Schwachstellen bleiben unverwaltet.','TISAX','1.2.4-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-8','R-R3-0736','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0737','R3-2026-07','Wurde die Anwendbarkeit der ISA-Maßnahmen für die betreffenden IT-Dienste nicht verifiziert und dokumentiert, bleibt offen, welche Schutzanforderungen tatsächlich gelten. Sie übersehen möglicherweise notwendige Maßnahmen oder halten falsche für erledigt und können die Angemessenheit Ihres Schutzes nicht belegen.','TISAX','1.2.4-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.2.4-9','R-R3-0737','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0738','R3-2026-07','Sind die Informationsträger, die Ihre Informationswerte verarbeiten, nicht identifiziert, erfasst und einem Verantwortlichen zugeordnet, schützen Sie Werte, deren Speicherorte Sie gar nicht vollständig kennen. Vergessene Systeme bleiben ungesichert, niemand kümmert sich um sie, und dort lagernde Daten sind Angriffen und Verlust schutzlos ausgesetzt.','TISAX','1.3.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.1-2','R-R3-0738','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0739','R3-2026-07','Fehlt ein regelmäßig überprüftes Verzeichnis der relevanten Informationswerte mit zugeordneten Informationsträgern, verlieren Sie den Überblick über Ihre schützenswerten Daten. Veränderungen bleiben unbemerkt, Schutzmaßnahmen passen nicht mehr zum Bestand, und Sie können weder Vollständigkeit noch angemessenen Schutz nachweisen.','TISAX','1.3.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.1-3','R-R3-0739','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0740','R3-2026-07','Werden die identifizierten Informationswerte nicht nach definierten Kriterien beurteilt und dem Klassifizierungsschema zugeordnet, behandeln Sie vertrauliche und unkritische Daten gleich. Sensible Informationen werden unzureichend geschützt oder unnötig überschützt, und Sie steuern Ihren Schutzaufwand an den tatsächlichen Schutzbedarfen vorbei.','TISAX','1.3.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.2-2','R-R3-0740','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0741','R3-2026-07','Fehlen klassifizierungsabhängige Vorgaben für den Umgang mit Informationsträgern bei Kennzeichnung, Transport, Speicherung, Rückgabe und Löschung, gehen Beschäftigte mit sensiblen Daten nach eigenem Ermessen um. Vertrauliche Informationen geraten in falsche Hände, werden unsicher entsorgt, und Sie verlieren die Kontrolle über ihren gesamten Lebenszyklus.','TISAX','1.3.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.2-3','R-R3-0741','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0742','R3-2026-07','Berücksichtigen Sie bei Klassifizierung und Umgang nur die Vertraulichkeit und lassen Integrität und Verfügbarkeit außer Acht, schützen Sie Ihre Werte nur halb. Unbemerkte Verfälschungen und Ausfälle wichtiger Informationen bleiben ungedeckt, sodass Fehlentscheidungen auf falscher Datenbasis und Betriebsunterbrechungen drohen.','TISAX','1.3.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.2-4','R-R3-0742','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0743','R3-2026-07','Wurden organisationsfremde IT-Dienste nicht auf den Schutzbedarf der von ihnen verarbeiteten Informationswerte abgestimmt, vertrauen Sie sensible Daten möglicherweise unzureichend geschützten Diensten an. Der Schutz bleibt hinter dem Bedarf zurück, vertrauliche Informationen sind gefährdet, und Sie verlieren die Kontrolle über deren Sicherheit.','TISAX','1.3.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.3-2','R-R3-0743','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0744','R3-2026-07','Sind die Anforderungen an Beschaffung, Inbetriebnahme und Freigabe organisationsfremder IT-Dienste nicht ermittelt und erfüllt, gelangen ungeprüfte Dienste in Ihren Betrieb. Sicherheitsmängel wandern unbemerkt ein, vertragliche und rechtliche Vorgaben bleiben offen, und Sie tragen Risiken, die vor dem Einsatz hätten ausgeschlossen werden müssen.','TISAX','1.3.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.3-3','R-R3-0744','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0745','R3-2026-07','Fehlt ein Verfahren zur Freigabe organisationsfremder IT-Dienste unter Berücksichtigung des Schutzbedarfs, entscheidet jeder eigenmächtig über deren Einsatz. Ungeeignete Dienste werden ohne Prüfung genutzt, Schatten-IT breitet sich aus, und sensible Daten landen auf Plattformen, die Sie nie bewertet haben.','TISAX','1.3.3-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.3-4','R-R3-0745','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0746','R3-2026-07','Sind die eingesetzten organisationsfremden IT-Dienste und deren Freigaben nicht dokumentiert, wissen Sie nicht verlässlich, welche externen Dienste Ihre Daten verarbeiten. Nicht freigegebene Dienste bleiben unbemerkt im Einsatz, im Vorfall fehlt der Nachweis, und Sie können Ihre Datenverarbeitung weder überblicken noch belegen.','TISAX','1.3.3-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.3-5','R-R3-0746','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0747','R3-2026-07','Überprüfen Sie nicht regelmäßig, dass ausschließlich freigegebene organisationsfremde IT-Dienste eingesetzt werden, schleichen sich mit der Zeit ungeprüfte Dienste ein. Beschäftigte greifen zu unautorisierten Lösungen, Schatten-IT wächst, und sensible Informationen fließen auf Plattformen ab, deren Sicherheit Sie nicht kontrollieren.','TISAX','1.3.3-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.3-6','R-R3-0747','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0748','R3-2026-07','Erstreckt sich Ihr Software-Freigabeverfahren nicht auch auf Software für besondere Zwecke wie Wartungswerkzeuge, gelangen mächtige Programme ungeprüft in Ihre Systeme. Gerade Wartungswerkzeuge verfügen über weitreichende Rechte, sodass Schadcode oder Schwachstellen unbemerkt eindringen und Angreifern tiefen Zugriff eröffnen können.','TISAX','1.3.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.4-2','R-R3-0748','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0749','R3-2026-07','Ohne eine vollständige Erfassung aller Software-Typen wie Firmware, Betriebssysteme, Anwendungen, Bibliotheken und Gerätetreiber verlieren Sie den Überblick über Ihre tatsächliche Angriffsfläche. Unbekannte oder vergessene Komponenten bleiben ungepatcht und werden bei Sicherheitsbewertungen übersehen. Angreifer nutzen genau solche blinden Flecken aus, was zu unentdeckten Kompromittierungen und schwer nachvollziehbaren Vorfällen führen kann.','TISAX','1.3.4-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.4-3','R-R3-0749','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0750','R3-2026-07','Fehlen zentrale Repositorys für freigegebene Softwarestände, verteilen sich Versionen unkontrolliert über einzelne Systeme und Mitarbeiter. Sie können dann nicht mehr zuverlässig nachvollziehen, welcher Stand geprüft und freigegeben ist, sodass veraltete oder manipulierte Versionen in Betrieb geraten. Dies erhöht die Gefahr von Sicherheitslücken, Inkompatibilitäten und einer aufwendigen, fehleranfälligen Wiederherstellung.','TISAX','1.3.4-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.4-4','R-R3-0750','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0751','R3-2026-07','Sind Ihre Software-Repositorys nicht vor unbefugtem Zugriff und Manipulation geschützt, können Angreifer oder unautorisierte Personen freigegebene Softwarestände verändern oder mit Schadcode versehen. Solche kompromittierten Pakete verteilen sich anschließend auf zahlreiche Systeme, bevor die Manipulation auffällt. Dadurch drohen weitreichende Kompromittierungen, Datenverlust und ein erheblicher Vertrauensschaden gegenüber Kunden und Partnern.','TISAX','1.3.4-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.4-5','R-R3-0751','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0752','R3-2026-07','Wird die Freigabe eingesetzter Software nicht regelmäßig auf ihre Gültigkeit und Angemessenheit überprüft, setzen Sie möglicherweise Produkte ein, die der Hersteller nicht mehr unterstützt oder die neue Sicherheitsanforderungen nicht erfüllen. Solche veralteten Freigaben verschleiern reale Risiken und ungepatchte Schwachstellen. In der Folge betreiben Sie unbemerkt verwundbare Systeme, die Angreifern leichte Ziele bieten.','TISAX','1.3.4-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.4-6','R-R3-0752','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0753','R3-2026-07','Kennen und dokumentieren Sie die jeweiligen Versionen und Patch-Levels Ihrer Software nicht, können Sie bei neu bekannt werdenden Schwachstellen nicht zuverlässig feststellen, welche Systeme betroffen sind. Dringend nötige Updates verzögern sich oder unterbleiben ganz. Angreifer nutzen bekannte Lücken gezielt aus, wodurch Ihnen Kompromittierungen, Ausfälle und ein erschwertes Schwachstellenmanagement drohen.','TISAX','1.3.4-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.4-7','R-R3-0753','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0754','R3-2026-07','Legen Sie keine zusätzlichen Anforderungen an die Software-Nutzung fest, etwa zur Steuerung oder Überwachung, bleibt eine missbräuchliche oder unzulässige Verwendung schutzbedürftiger Anwendungen unbemerkt. Gerade bei sehr hohem Schutzbedarf können so vertrauliche Informationen unkontrolliert abfließen oder Funktionen zweckentfremdet werden. Ohne diese Kontrollen fehlt Ihnen die Nachvollziehbarkeit, um Verstöße rechtzeitig zu erkennen und zu unterbinden.','TISAX','1.3.4-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.3.4-8','R-R3-0754','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0755','R3-2026-07','Werden Informationssicherheitsrisiken nicht angemessen hinsichtlich Eintrittswahrscheinlichkeit und potenziellem Schaden bewertet, können Sie Ihre Ressourcen nicht gezielt auf die wirklich bedrohlichen Risiken lenken. Schwerwiegende Gefahren werden unterschätzt, während unwichtige überbewertet werden. Dadurch bleiben kritische Schwachstellen unbehandelt, und im Ernstfall treffen Sie Vorfälle mit hohem Schaden völlig unvorbereitet.','TISAX','1.4.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.4.1-2','R-R3-0755','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0756','R3-2026-07','Werden identifizierte Informationssicherheitsrisiken nicht nachvollziehbar dokumentiert, verlieren Sie den Überblick über den aktuellen Risikostand und dessen Entwicklung. Einmal erkannte Gefahren geraten in Vergessenheit und werden nicht weiterverfolgt. Ohne diese Grundlage können Sie weder Fortschritte belegen noch fundierte Entscheidungen treffen, was zu unbehandelten Risiken und Lücken bei Audits und Nachweisen führt.','TISAX','1.4.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.4.1-3','R-R3-0756','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0757','R3-2026-07','Ist Informationssicherheitsrisiken kein Verantwortlicher zugeordnet, fühlt sich niemand für deren Bewertung und Behandlung zuständig. Notwendige Maßnahmen bleiben liegen, weil unklar ist, wer entscheiden und handeln muss. Diese fehlende Verantwortlichkeit führt dazu, dass erkannte Risiken über lange Zeit offen bleiben und sich im Ernstfall zu vermeidbaren Sicherheitsvorfällen auswachsen.','TISAX','1.4.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.4.1-4','R-R3-0757','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0758','R3-2026-07','Fehlt ein festgelegtes Verfahren zur Identifikation, Bewertung und Behandlung von Sicherheitsrisiken, erfolgt das Risikomanagement uneinheitlich und vom Zufall abhängig. Unterschiedliche Personen gehen verschieden vor, sodass Risiken übersehen oder widersprüchlich behandelt werden. Dadurch entstehen Lücken in Ihrem Schutzniveau, und die Vergleichbarkeit sowie Nachvollziehbarkeit Ihrer Risikoentscheidungen gehen verloren.','TISAX','1.4.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.4.1-5','R-R3-0758','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0759','R3-2026-07','Liegen keine einheitlichen Kriterien für die Bewertung und Behandlung von Sicherheitsrisiken vor, treffen verschiedene Verantwortliche ihre Entscheidungen nach subjektivem Ermessen. Gleichartige Risiken werden dann ungleich eingestuft und unterschiedlich behandelt. Dies führt zu inkonsistenten Schutzmaßnahmen, Fehlallokationen von Ressourcen und dem Risiko, dass gefährliche Bedrohungen unbeabsichtigt akzeptiert werden.','TISAX','1.4.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.4.1-6','R-R3-0759','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0760','R3-2026-07','Sind Maßnahmen zum Umgang mit Sicherheitsrisiken samt Verantwortlichen nicht festgelegt, dokumentiert und über einen Maßnahmenplan verfolgt, bleibt die Risikobehandlung folgenlos. Beschlossene Maßnahmen werden nicht umgesetzt, verzögern sich oder geraten in Vergessenheit. Ohne diese Nachverfolgung bleiben erkannte Risiken faktisch bestehen, und Sie können weder Fortschritt noch Wirksamkeit Ihrer Schutzmaßnahmen belegen.','TISAX','1.4.1-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.4.1-7','R-R3-0760','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0761','R3-2026-07','Erfolgt bei Änderungen des Umfelds wie Organisationsstruktur, Standort oder Regelwerken keine rechtzeitige erneute Risikobewertung, veraltet Ihre Risikoeinschätzung unbemerkt. Neue Bedrohungen und veränderte Rahmenbedingungen bleiben unberücksichtigt, sodass Ihre Schutzmaßnahmen nicht mehr passen. Dadurch entstehen unerkannte Sicherheitslücken, die Angreifer oder unvorhergesehene Ereignisse ausnutzen können, bevor Sie reagieren.','TISAX','1.4.1-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.4.1-8','R-R3-0761','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0762','R3-2026-07','Werden Ihre Richtlinien und Verfahren der Informationssicherheit nicht regelmäßig auf Einhaltung und Wirksamkeit geprüft, wissen Sie nicht, ob die vorgesehenen Schutzmaßnahmen tatsächlich gelebt werden und greifen. Unwirksame oder umgangene Regelungen bleiben unentdeckt. So wiegen Sie sich in falscher Sicherheit, während reale Schwachstellen fortbestehen und im Ernstfall zu vermeidbaren Vorfällen führen.','TISAX','1.5.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.5.1-2','R-R3-0762','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0763','R3-2026-07','Werden bei festgestellten Nicht-Konformitäten keine Korrekturmaßnahmen eingeleitet und nachverfolgt, bleiben erkannte Abweichungen dauerhaft bestehen. Dieselben Fehler und Schwachstellen treten wiederholt auf, ohne dass die Ursachen behoben werden. Dadurch verschlechtert sich Ihr Sicherheitsniveau schleichend, und im Audit sowie im Schadensfall müssen Sie ungelöste, teils lang bekannte Mängel verantworten.','TISAX','1.5.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.5.1-3','R-R3-0763','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0764','R3-2026-07','Wird die Einhaltung von Sicherheitsanforderungen wie technischen Vorgaben nicht in regelmäßigen Abständen überprüft, weichen Systemkonfigurationen mit der Zeit unbemerkt vom Sollzustand ab. Fehlkonfigurationen, deaktivierte Schutzfunktionen und schleichende Verstöße bleiben verborgen. Angreifer finden so leicht ausnutzbare Lücken, und Sie erkennen die Abweichung oft erst, wenn ein Sicherheitsvorfall bereits eingetreten ist.','TISAX','1.5.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.5.1-4','R-R3-0764','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0765','R3-2026-07','Werden die Ergebnisse durchgeführter Überprüfungen nicht aufgezeichnet und aufbewahrt, fehlen Ihnen später die Nachweise über Zustand und Entwicklung Ihrer Informationssicherheit. Sie können Fortschritte nicht belegen, Trends nicht erkennen und gegenüber Auditoren oder Behörden keine Konformität nachweisen. Im Streit- oder Schadensfall stehen Sie ohne belastbare Dokumentation da, was Ihre Position erheblich schwächt.','TISAX','1.5.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.5.1-5','R-R3-0765','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0766','R3-2026-07','Liegt kein Plan mit Zeitplan, Umfang und zu prüfenden Kontrollen vor, erfolgen Überprüfungen unsystematisch und lückenhaft. Wichtige Bereiche werden möglicherweise nie geprüft, während andere doppelt betrachtet werden. Ohne diese Planung bleiben blinde Flecken bestehen, Prüfungen verzögern sich oder entfallen ganz, und Sie können die Vollständigkeit Ihrer Kontrolltätigkeit nicht sicherstellen.','TISAX','1.5.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.5.1-6','R-R3-0766','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0767','R3-2026-07','Werden für festgestellte Abweichungen keine Korrekturmaßnahmen eingeleitet und konsequent bis zur Umsetzung nachverfolgt, verpuffen die Erkenntnisse Ihrer Prüfungen wirkungslos. Bekannte Mängel bleiben offen und wiederholen sich, weil ihre Ursachen nicht behoben werden. Dadurch bleibt Ihr Sicherheitsniveau dauerhaft hinter den Anforderungen zurück, und dieselben Schwachstellen gefährden Ihre Systeme immer wieder.','TISAX','1.5.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.5.2-2','R-R3-0767','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0768','R3-2026-07','Werden die Ergebnisse durchgeführter Prüfungen nicht dokumentiert und der Organisationsleitung berichtet, fehlt der Führung der Überblick über den tatsächlichen Sicherheitszustand. Notwendige Entscheidungen und Ressourcen für die Behebung von Mängeln bleiben aus. Ohne diese Transparenz werden Risiken auf Leitungsebene unterschätzt, und wichtige Verbesserungen unterbleiben, bis ein Vorfall die Versäumnisse offenlegt.','TISAX','1.5.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.5.2-3','R-R3-0768','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0769','R3-2026-07','Werden Meldeprozesse für Sicherheitsereignisse nicht regelmäßig durch Prüfungen und Übungen erprobt, wissen Sie im Ernstfall nicht, ob Meldewege und Zuständigkeiten tatsächlich funktionieren. Mitarbeitende sind unsicher, wie und wohin sie melden sollen, und verlieren wertvolle Zeit. Dadurch werden Vorfälle verspätet oder gar nicht gemeldet, sodass sich Schäden ausweiten, bevor Sie reagieren können.','TISAX','1.6.1-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-10','R-R3-0769','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0770','R3-2026-07','Sind keine angemessenen Meldemechanismen festgelegt, umgesetzt und allen potenziell meldenden Personen bekannt, bleiben Sicherheitsereignisse häufig unentdeckt oder unkommuniziert. Betroffene wissen nicht, wie sie Auffälligkeiten weitergeben sollen, und behalten Beobachtungen für sich. Dadurch erfahren die zuständigen Stellen zu spät von Vorfällen, sodass sich Schäden unnötig vergrößern und Reaktionschancen ungenutzt verstreichen.','TISAX','1.6.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-2','R-R3-0770','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0771','R3-2026-07','Stehen den meldenden Personen keine geeigneten Kommunikationskanäle zur Verfügung, können sie Sicherheitsereignisse nicht zuverlässig und zeitnah melden. Hinweise gehen verloren, verzögern sich oder erreichen nie die richtige Stelle. Dadurch bleiben Vorfälle unbearbeitet, und Ihre Organisation verliert die entscheidende Zeitspanne, in der sich Schäden noch begrenzen ließen.','TISAX','1.6.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-3','R-R3-0771','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0772','R3-2026-07','Fehlt eine einheitliche Anlaufstelle für die Meldung von Sicherheitsereignissen, wissen Mitarbeitende nicht, an wen sie sich wenden sollen. Meldungen versickern zwischen unklaren Zuständigkeiten oder erreichen die falschen Personen. Dadurch verzögert sich die Bearbeitung, Ereignisse werden übersehen, und im Ernstfall geht wertvolle Zeit verloren, die zur Eindämmung eines Vorfalls nötig wäre.','TISAX','1.6.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-4','R-R3-0772','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0773','R3-2026-07','Stehen je nach Schweregrad keine unterschiedlichen Meldewege bereit, etwa Echtzeitkommunikation für Notfälle neben asynchronen Kanälen, werden dringende Vorfälle wie unaufschiebbare Notfälle behandelt wie Routinemeldungen. Kritische Ereignisse verharren dann in Warteschlangen, statt sofort bearbeitet zu werden. Dadurch verzögert sich Ihre Reaktion auf akute Bedrohungen, sodass sich Schäden ungebremst ausbreiten können.','TISAX','1.6.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-5','R-R3-0773','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0774','R3-2026-07','Sind Mitarbeitende nicht verpflichtet, relevante Ereignisse zu melden, und werden sie nicht entsprechend geschult, erkennen und melden sie sicherheitsrelevante Vorfälle häufig gar nicht. Aus Unsicherheit, Unkenntnis oder Sorge vor Konsequenzen behalten sie Beobachtungen für sich. Dadurch bleiben Angriffe und Schwachstellen verborgen, bis sie erheblichen Schaden anrichten und eine frühzeitige Reaktion unmöglich geworden ist.','TISAX','1.6.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-6','R-R3-0774','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0775','R3-2026-07','Werden Meldungen organisationsfremder Parteien nicht berücksichtigt, weil keine von außen zugängliche und kommunizierte Meldemöglichkeit besteht, entgehen Ihnen wertvolle Hinweise von Kunden, Partnern oder Sicherheitsforschern. Entdeckte Schwachstellen werden dann nicht gemeldet oder gelangen im schlimmsten Fall an Angreifer. Dadurch verpassen Sie die Chance, Lücken frühzeitig zu schließen, bevor sie ausgenutzt werden.','TISAX','1.6.1-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-7','R-R3-0775','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0776','R3-2026-07','Sind die Verfahren zur Meldung von Vorfällen und die zugehörigen Hinweise nicht für alle maßgeblichen Meldenden zugänglich, wissen diese im entscheidenden Moment nicht, wie sie richtig vorgehen sollen. Meldungen unterbleiben, erfolgen fehlerhaft oder über falsche Wege. Dadurch verzögert sich die Bearbeitung von Sicherheitsereignissen, und wichtige Informationen erreichen die zuständigen Stellen zu spät oder unvollständig.','TISAX','1.6.1-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-8','R-R3-0776','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0777','R3-2026-07','Ist kein Verfahren etabliert, über das Meldende eine Rückmeldung zum Bearbeitungsstand erhalten, fühlen sich diese in ihrem Engagement nicht ernst genommen. Sie wissen nicht, ob ihre Meldung ankam und bearbeitet wird, und melden künftig seltener. Dadurch sinkt die Meldebereitschaft insgesamt, sodass Ihnen wertvolle Frühwarnungen zu Sicherheitsereignissen zunehmend verloren gehen.','TISAX','1.6.1-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.1-9','R-R3-0777','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0778','R3-2026-07','Liegt keine Kommunikationsstrategie für sicherheitsbezogene Ereignisse vor, die regelt, mit wem, wann und worüber kommuniziert wird, entsteht im Ernstfall Chaos in der Außen- und Innenkommunikation. Widersprüchliche oder verspätete Informationen verunsichern Kunden, Partner und Behörden. Dadurch drohen Ihnen erhebliche Reputationsschäden, Vertrauensverluste und im Zweifel rechtliche Konsequenzen wegen unzureichender oder falscher Benachrichtigung.','TISAX','1.6.2-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-10','R-R3-0778','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0779','R3-2026-07','Sind keine Verfahren für die Reaktion auf Sicherheitsvorfälle bei Lieferanten etabliert, einschließlich Analyse der Auswirkungen auf Ihre Organisation und notwendiger Meldungen, treffen Sie Vorfälle in der Lieferkette unvorbereitet. Sie erkennen zu spät, ob und wie Sie selbst betroffen sind. Dadurch breiten sich Kompromittierungen über Ihre Zulieferer bis in Ihre eigenen Systeme aus, ohne dass Sie rechtzeitig gegensteuern.','TISAX','1.6.2-11') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-11','R-R3-0779','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0780','R3-2026-07','Wird der Umgang mit Ereignissen verschiedener Kategorien und Prioritäten nicht regelmäßig geprüft, einschließlich Übungen seltener Fälle und der Eskalationsverfahren, bleiben Schwächen in Ihren Reaktionsprozessen bis zum Ernstfall verborgen. Gerade selten auftretende, aber schwerwiegende Vorfälle bewältigen Sie dann ungeübt und fehleranfällig. Dadurch verzögert sich die Reaktion, Eskalationen scheitern, und der Schaden fällt deutlich größer aus als nötig.','TISAX','1.6.2-12') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-12','R-R3-0780','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0781','R3-2026-07','Ist durch geeignete Prozesse nicht sichergestellt, dass auf gemeldete Sicherheitsereignisse angemessen und zeitnah reagiert wird, verpuffen selbst korrekte Meldungen wirkungslos. Vorfälle bleiben liegen, während Angreifer ungestört weiter agieren. Dadurch verlieren Sie die entscheidende Zeit zur Eindämmung, sodass sich zunächst kleine Ereignisse zu schwerwiegenden Sicherheitsvorfällen mit hohem Schaden ausweiten.','TISAX','1.6.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-2','R-R3-0781','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0782','R3-2026-07','Werden die aus Sicherheitsereignissen gewonnenen Erfahrungen nicht in die ständige Verbesserung der Informationssicherheit einbezogen, wiederholen sich vermeidbare Vorfälle immer wieder. Dieselben Schwachstellen und Fehler führen erneut zu Schäden, weil ihre Ursachen nicht behoben werden. Dadurch stagniert Ihr Sicherheitsniveau, und Sie verschenken das wertvolle Lernpotenzial, das jeder Vorfall für einen besseren Schutz bietet.','TISAX','1.6.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-3','R-R3-0782','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0783','R3-2026-07','Werden gemeldete Ereignisse während der Bearbeitung nicht kategorisiert, etwa nach Personal, physischer Sicherheit und Cybersicherheit, und hinsichtlich ihrer Sicherheitsrelevanz bewertet, behandeln Sie schwerwiegende und harmlose Vorfälle undifferenziert. Kritische Ereignisse gehen in der Masse unter oder werden zu spät erkannt. Dadurch fehlt die richtige Priorisierung, Ressourcen fließen falsch, und gefährliche Vorfälle bleiben zu lange unbearbeitet.','TISAX','1.6.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-4','R-R3-0783','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0784','R3-2026-07','Sind die Verantwortlichkeiten für den Umgang mit Ereignissen nicht auf Grundlage der Ereigniskategorie definiert und zugewiesen, inklusive Koordination, Qualifikation und Kontaktdaten, herrscht im Ernstfall Unklarheit darüber, wer handeln muss. Wertvolle Zeit vergeht mit Abstimmung statt Bearbeitung. Dadurch bleiben Vorfälle unkoordiniert liegen oder werden von unzureichend qualifizierten Personen bearbeitet, was die Schäden vergrößert.','TISAX','1.6.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-5','R-R3-0784','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0785','R3-2026-07','Verfügen Sie über keine Strategie zur Archivierung offizieller Berichte und zur Strafverfolgung möglicherweise strafrechtlich relevanter Aspekte von Sicherheitsvorfällen, gehen wichtige Beweismittel unwiederbringlich verloren. Spuren werden überschrieben oder unsachgemäß gesichert. Dadurch können Sie Täter nicht belangen, Schadenersatzansprüche nicht durchsetzen und geraten bei behördlichen Nachfragen in Erklärungsnot, weil belastbare Nachweise fehlen.','TISAX','1.6.2-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-6','R-R3-0785','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0786','R3-2026-07','Sind auf Grundlage von Klasse, Kategorie und Schweregrad keine maximalen Reaktionszeiten für die Bearbeitung von Sicherheitsereignissen definiert, fehlt der verbindliche Maßstab für ein rechtzeitiges Eingreifen. Dringende Vorfälle bleiben ohne klare Fristen ebenso lange liegen wie unwichtige. Dadurch verzögert sich Ihre Reaktion auf akute Bedrohungen, sodass sich Schäden ausweiten, bevor Gegenmaßnahmen greifen.','TISAX','1.6.2-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-7','R-R3-0786','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0787','R3-2026-07','Werden Ereignisse, die nicht ihrer Priorität entsprechend bearbeitet wurden, nicht anhand definierter Bedingungen, Schwellenwerte und Eskalationswege eskaliert, bleiben liegengebliebene kritische Vorfälle unbemerkt in der Warteschlange. Niemand hebt sie rechtzeitig auf die nächste Handlungsebene. Dadurch verstreicht wertvolle Zeit ungenutzt, und schwerwiegende Ereignisse entfalten ihre volle Wirkung, bevor die Führung überhaupt einbezogen wird.','TISAX','1.6.2-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-8','R-R3-0787','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0788','R3-2026-07','Sind die gesetzlichen, regulatorischen und vertraglichen Meldepflichten samt zugehöriger Kontaktinformationen nicht bekannt und dokumentiert, versäumen Sie im Ernstfall fristgebundene Benachrichtigungen an Behörden, Kunden oder Partner. Meldungen erfolgen zu spät, an die falsche Stelle oder gar nicht. Dadurch drohen Ihnen Bußgelder, Vertragsstrafen und Reputationsschäden, weil Sie Ihre rechtlichen Pflichten nachweislich verletzt haben.','TISAX','1.6.2-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.2-9','R-R3-0788','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0789','R3-2026-07','Sind unterschiedliche relevante Krisenszenarien wie die Nichtverfügbarkeit von Schlüsselpersonal, Standorten oder IT-Systemen nicht identifiziert, trifft Sie eine Krise ohne vorbereiteten Plan. Sie improvisieren unter Zeitdruck und übersehen dabei kritische Abhängigkeiten. Dadurch verlängern sich Ausfälle erheblich, wichtige Prozesse brechen weg, und Ihre Organisation kann ihre Handlungsfähigkeit im Ernstfall nicht rechtzeitig wiederherstellen.','TISAX','1.6.3-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-10','R-R3-0789','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0790','R3-2026-07','Sind die zur Krisenbewältigung notwendigen Ressourcen und Informationen wie Kommunikationsinfrastruktur, Kontaktdaten und Risiken nicht identifiziert und ihre Verfügbarkeit nicht sichergestellt, fehlen Ihnen im Ernstfall genau die Mittel, die Sie dringend benötigen. Sie suchen unter Druck nach Kontakten und funktionierenden Kommunikationswegen. Dadurch verzögert sich die Krisenreaktion entscheidend, und die Bewältigung des Vorfalls gerät unnötig ins Stocken.','TISAX','1.6.3-11') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-11','R-R3-0790','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0791','R3-2026-07','Existiert keine Kommunikationsstrategie für Krisensituationen, die festlegt, mit wem, wann und durch wen kommuniziert wird, entsteht im Ernstfall ein widersprüchliches und unkoordiniertes Informationschaos. Betroffene, Behörden und die Öffentlichkeit erhalten verspätete oder falsche Aussagen. Dadurch verstärken Sie die Verunsicherung, verlieren die Deutungshoheit über die Lage und riskieren erhebliche Reputations- und Vertrauensschäden.','TISAX','1.6.3-12') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-12','R-R3-0791','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0792','R3-2026-07','Werden Effizienz, Durchführbarkeit und Angemessenheit der Krisenplanung nicht regelmäßig evaluiert, veralten Ihre Pläne unbemerkt und passen nicht mehr zur tatsächlichen Lage. Schwächen und Lücken bleiben verborgen, bis der Ernstfall sie schmerzhaft offenlegt. Dadurch erweist sich Ihre Krisenplanung genau dann als untauglich, wenn Sie sie am dringendsten brauchen, und die Schäden fallen deutlich größer aus.','TISAX','1.6.3-13') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-13','R-R3-0792','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0793','R3-2026-07','Ohne stichprobenartige Prüfungen wie Simulationen oder Planübungen bleibt Ihre Krisenplanung ungetestet und existiert nur auf dem Papier. Verborgene Lücken in Abläufen und Zuständigkeiten fallen erst im Ernstfall auf, wenn Schlüsselpersonal unvorbereitet reagiert. Sie riskieren verzögerte Entscheidungen, chaotische Reaktionen und vermeidbare Schäden während einer realen Krise.','TISAX','1.6.3-14') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-14','R-R3-0793','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0794','R3-2026-07','Führen Sie keine regelmäßigen Krisenübungen unter Beteiligung aller Entscheidungsträger durch, bleiben Zusammenarbeit und Kommunikationswege im Ernstfall ungeübt. Rollen sind unklar, Reaktionszeiten verlängern sich und Entscheidungen werden unter Druck falsch getroffen. Sie riskieren, dass eine reale Krise eskaliert und erheblichen Schaden an Betrieb und Reputation verursacht.','TISAX','1.6.3-15') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-15','R-R3-0794','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0795','R3-2026-07','Sind Verantwortlichkeiten und Befugnisse für das Krisenmanagement nicht klar definiert und zugewiesen, weiß im Ernstfall niemand, wer entscheidet und handelt. Es entstehen Verzögerungen, Kompetenzstreitigkeiten und ungesteuerte Reaktionen. Sie riskieren, dass eine Krise unkontrolliert eskaliert und Ihre Organisation handlungsunfähig bleibt, wenn schnelles Handeln entscheidend ist.','TISAX','1.6.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-2','R-R3-0795','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0796','R3-2026-07','Sind keine qualifizierten Verantwortlichen für das Krisenmanagement benannt, fehlt im Ernstfall die fachliche Kompetenz zur richtigen Lagebeurteilung und Steuerung. Falsche oder zögerliche Entscheidungen verschärfen die Situation. Sie riskieren vermeidbare Schäden, weil unvorbereitete Personen mit einer Krise überfordert sind und wirksame Gegenmaßnahmen ausbleiben.','TISAX','1.6.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-3','R-R3-0796','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0797','R3-2026-07','Fehlen etablierte Verfahren zur frühzeitigen Erkennung von Krisensituationen, bemerken Sie Warnhinweise und sich anbahnende Krisen zu spät. Wertvolle Reaktionszeit geht verloren, und aus beherrschbaren Vorfällen werden ausgewachsene Krisen. Sie riskieren, dass Ihre Organisation überrascht wird und Gegenmaßnahmen erst greifen, wenn der Schaden bereits eingetreten ist.','TISAX','1.6.3-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-4','R-R3-0797','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0798','R3-2026-07','Existiert kein festgelegtes Verfahren zum Abruf und zur Eskalation des Krisenmanagements, verstreicht im Ernstfall wertvolle Zeit, bis die richtigen Stellen aktiviert sind. Meldungen versanden oder erreichen die Verantwortlichen zu spät. Sie riskieren einen verzögerten Krisenstart, in dem sich Schäden ausweiten, bevor koordinierte Maßnahmen überhaupt beginnen.','TISAX','1.6.3-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-5','R-R3-0798','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0799','R3-2026-07','Sind strategische Ziele und ihre Priorität für Krisensituationen nicht definiert und bekannt, treffen Beteiligte unter Druck widersprüchliche Entscheidungen. Ohne klare Rangfolge, etwa Schutz von Leben vor Kerngeschäft, werden Ressourcen falsch eingesetzt. Sie riskieren Fehlentscheidungen mit gravierenden Folgen für Menschen, Betrieb und Reputation Ihrer Organisation.','TISAX','1.6.3-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-6','R-R3-0799','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0800','R3-2026-07','Ist kein Krisenstab unter Einbindung der Leitung und wichtiger Funktionsbereiche festgelegt, fehlt im Ernstfall das zentrale Steuerungsgremium. Entscheidungen werden unabgestimmt oder gar nicht getroffen, wichtige Perspektiven fehlen. Sie riskieren eine unkoordinierte Krisenbewältigung, in der sich Schäden ausweiten, weil niemand die Gesamtlage verantwortlich führt.','TISAX','1.6.3-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-7','R-R3-0800','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0801','R3-2026-07','Sind Krisenmaßnahmen und -verfahren mit Ausnahmebefugnissen, Kommunikationsmitteln und Notfallbetrieb nicht definiert und genehmigt, improvisieren Beteiligte im Ernstfall ohne verbindliche Grundlage. Notwendige Handlungen unterbleiben oder verzögern sich. Sie riskieren rechtliche Unsicherheit, blockierte Abläufe und einen Notbetrieb, der die Krise verschärft statt sie einzudämmen.','TISAX','1.6.3-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-8','R-R3-0801','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0802','R3-2026-07','Wird Ihre Krisenplanung nicht regelmäßig überprüft und aktualisiert, veralten Kontakte, Zuständigkeiten und Abläufe unbemerkt. Im Ernstfall verlassen Sie sich auf Angaben, die nicht mehr stimmen, und verlieren wertvolle Zeit. Sie riskieren, dass eine formal vorhandene, aber unwirksame Planung im entscheidenden Moment versagt.','TISAX','1.6.3-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','1.6.3-9','R-R3-0802','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0803','R3-2026-07','Ermitteln Sie die Anforderungen an Mitarbeiter nicht entsprechend ihrem Stellenprofil oder prüfen deren Erfüllung nicht, besetzen Sie sicherheitsrelevante Positionen mit ungeeigneten Personen. Fehlende Qualifikation oder Zuverlässigkeit bleibt unentdeckt. Sie riskieren Fehler, Sicherheitsverstöße und Schäden, weil Aufgaben von dafür nicht befähigten Personen wahrgenommen werden.','TISAX','2.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.1-2','R-R3-0803','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0804','R3-2026-07','Überprüfen Sie die Identität potenzieller Mitarbeiter vor der Einstellung nicht, etwa anhand von Ausweisdokumenten, können sich Personen unter falscher Identität Zugang zu Ihrer Organisation verschaffen. Betrug und gezielte Unterwanderung bleiben unerkannt. Sie riskieren, dass sensible Informationen an Unbefugte gelangen und Ihre Organisation vorsätzlich geschädigt wird.','TISAX','2.1.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.1-3','R-R3-0804','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0805','R3-2026-07','Prüfen Sie die persönliche Eignung potenzieller Mitarbeiter nicht einmal mit einfachen Verfahren wie einem Einstellungsgespräch, stellen Sie Personen ohne Bild von deren Zuverlässigkeit ein. Ungeeignete Kandidaten gelangen an sensible Aufgaben. Sie riskieren Fehlbesetzungen, die zu Sicherheitsverstößen, Vertrauensbruch und vermeidbaren Schäden für Ihre Organisation führen.','TISAX','2.1.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.1-4','R-R3-0805','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0806','R3-2026-07','Findet je nach Tätigkeit keine erweiterte Eignungsprüfung durch Referenzen, Zeugnisse oder Führungszeugnisse statt, besetzen Sie besonders sensible Positionen ohne belastbare Absicherung. Verschwiegene Vorbelastungen oder falsche Angaben bleiben unentdeckt. Sie riskieren, dass unzuverlässige Personen Zugang zu kritischen Werten erhalten und erheblichen Schaden anrichten.','TISAX','2.1.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.1-5','R-R3-0806','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0807','R3-2026-07','Sind Mitarbeiter nicht verpflichtet, die Richtlinien zur Informationssicherheit einzuhalten, bleiben Ihre Vorgaben unverbindlich und werden im Alltag ignoriert. Verstöße lassen sich weder einfordern noch ahnden. Sie riskieren eine flächendeckende Missachtung von Schutzmaßnahmen, wodurch Sicherheitsvorfälle wahrscheinlicher werden und sensible Informationen ungeschützt bleiben.','TISAX','2.1.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.2-2','R-R3-0807','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0808','R3-2026-07','Besteht für Mitarbeiter keine über das Arbeitsverhältnis hinaus fortbestehende Geheimhaltungsverpflichtung, dürfen ausscheidende Personen vertrauliches Wissen ungehindert weitergeben. Betriebsgeheimnisse und Kundendaten gelangen an Wettbewerber oder Dritte. Sie riskieren dauerhafte Informationsabflüsse, rechtliche Nachteile und Schäden, gegen die Sie nach dem Austritt kaum noch vorgehen können.','TISAX','2.1.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.2-3','R-R3-0808','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0809','R3-2026-07','Wird Informationssicherheit in den Arbeitsverträgen nicht ausdrücklich berücksichtigt, fehlt eine verbindliche vertragliche Grundlage für sicheres Verhalten. Bei Verstößen können Sie kaum arbeitsrechtlich reagieren. Sie riskieren, dass Mitarbeiter Sicherheitspflichten als unverbindlich betrachten und Ihnen im Schadensfall die Handhabe zur Durchsetzung von Konsequenzen fehlt.','TISAX','2.1.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.2-4','R-R3-0809','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0810','R3-2026-07','Ist keine Vorgehensweise für die Reaktion auf Verstöße gegen Informationssicherheits- und Geheimhaltungspflichten beschrieben, werden Vorfälle uneinheitlich oder gar nicht behandelt. Konsequenzen bleiben aus, und das Fehlverhalten wiederholt sich. Sie riskieren eine schleichende Aushöhlung Ihrer Sicherheitskultur sowie rechtliche Angreifbarkeit mangels nachvollziehbarer, gleichbehandelnder Reaktion.','TISAX','2.1.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.2-5','R-R3-0810','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0811','R3-2026-07','Ist kein Konzept zur Sensibilisierung und Schulung der Mitarbeiter erstellt, das Sicherheitsrichtlinie, Ereignismeldung und Schadsoftware abdeckt, bleiben Ihre Beschäftigten unwissend über zentrale Gefahren. Phishing, Fehlbedienung und unerkannte Vorfälle nehmen zu. Sie riskieren, dass der Faktor Mensch zur größten Schwachstelle wird und vermeidbare Sicherheitsvorfälle eintreten.','TISAX','2.1.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.3-2','R-R3-0811','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0812','R3-2026-07','Sind besondere Zielgruppen wie Administratoren oder Personal in risikobehafteten Umgebungen nicht ermittelt und im Schulungskonzept berücksichtigt, erhalten gerade kritische Rollen keine passgenaue Sensibilisierung. Ihre höheren Rechte und Risiken bleiben ungeschult. Sie riskieren schwerwiegende Fehler und Angriffe genau dort, wo der potenzielle Schaden für Ihre Organisation am größten ist.','TISAX','2.1.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.3-3','R-R3-0812','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0813','R3-2026-07','Wurde das Schulungs- und Sensibilisierungskonzept nicht vom verantwortlichen Management freigegeben, fehlt ihm die verbindliche Grundlage und die nötige Rückendeckung. Inhalte werden unverbindlich, Ressourcen fehlen, die Umsetzung schläft ein. Sie riskieren ein wirkungsloses Awareness-Programm, das mangels Verbindlichkeit die Mitarbeiter nicht erreicht und Sicherheitslücken offen lässt.','TISAX','2.1.3-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.3-4','R-R3-0813','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0814','R3-2026-07','Werden Schulungs- und Sensibilisierungsmaßnahmen nicht regelmäßig und anlassbezogen durchgeführt, veraltet das Wissen Ihrer Mitarbeiter und neue Bedrohungen bleiben unberücksichtigt. Nach aktuellen Vorfällen fehlt die gezielte Nachschärfung. Sie riskieren, dass Beschäftigte auf moderne Angriffsmethoden unvorbereitet reagieren und vermeidbare Sicherheitsvorfälle sich wiederholen.','TISAX','2.1.3-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.3-5','R-R3-0814','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0815','R3-2026-07','Wird die Teilnahme an Schulungs- und Sensibilisierungsmaßnahmen nicht nachvollziehbar dokumentiert, können Sie weder belegen noch steuern, wer tatsächlich geschult wurde. Lücken bleiben unerkannt, Nachweise gegenüber Auditoren fehlen. Sie riskieren, dass ungeschulte Mitarbeiter unbemerkt zum Sicherheitsrisiko werden und Sie Ihre Sorgfaltspflicht nicht nachweisen können.','TISAX','2.1.3-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.3-6','R-R3-0815','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0816','R3-2026-07','Sind den Mitarbeitern die zuständigen Ansprechpartner für Fragen zur Informationssicherheit nicht bekannt, wissen sie im Zweifel nicht, an wen sie sich wenden sollen. Verdächtige Vorfälle werden verschwiegen oder falsch behandelt. Sie riskieren, dass Sicherheitsprobleme unnötig lange unbemerkt bleiben und sich zu größeren Schäden ausweiten.','TISAX','2.1.3-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.3-7','R-R3-0816','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0817','R3-2026-07','Erfolgt der Zugang zum Netzwerk nicht über eine gesicherte Verbindung wie VPN mit starker Authentifizierung, können Angreifer Datenverkehr abfangen oder sich mit gestohlenen Zugangsdaten anmelden. Externe Zugriffe bleiben ungeschützt. Sie riskieren unbefugte Eindringversuche, Datenabfluss und die Kompromittierung Ihres internen Netzwerks über schwach gesicherte Fernzugänge.','TISAX','2.1.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.4-2','R-R3-0817','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0818','R3-2026-07','Werden Schutzmaßnahmen für mobiles Arbeiten und Reisen nicht berücksichtigt, insbesondere in sicherheitskritischen Ländern, sind Geräte und Daten unterwegs erhöhten Risiken ausgesetzt. Diebstahl, Zugriff durch Dritte und Überwachung bleiben unbedacht. Sie riskieren den Verlust vertraulicher Informationen und die Kompromittierung von Geräten außerhalb Ihrer geschützten Umgebung.','TISAX','2.1.4-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.4-3','R-R3-0818','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0819','R3-2026-07','Werden Mitarbeiter für die Risiken des mobilen Arbeitens und ortsungebundenen Zugriffs nicht sensibilisiert, handeln sie unterwegs sorglos mit Geräten, Netzwerken und vertraulichen Inhalten. Unsichere WLANs und Einblick durch Dritte werden übersehen. Sie riskieren Datenverluste und Kompromittierungen, weil Ihren Beschäftigten das Gefahrenbewusstsein außerhalb des Büros fehlt.','TISAX','2.1.4-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.4-4','R-R3-0819','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0820','R3-2026-07','Sind keine Maßnahmen gegen Mithören und unbefugte Einsichtnahme beim mobilen Arbeiten umgesetzt, können Dritte in Zügen, Cafés oder Wartebereichen vertrauliche Bildschirme einsehen oder Gespräche mithören. Sensible Informationen gelangen unbemerkt nach außen. Sie riskieren Datenabfluss und Verletzungen der Vertraulichkeit an öffentlichen Orten außerhalb Ihrer Kontrolle.','TISAX','2.1.4-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','2.1.4-5','R-R3-0820','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0821','R3-2026-07','Sind die für Ihre Sicherheitszonen definierten Schutzmaßnahmen nicht tatsächlich umgesetzt, existiert der Schutz nur auf dem Papier. Unbefugte können physisch in sensible Bereiche gelangen. Sie riskieren Diebstahl, Manipulation und Sabotage an Informationswerten und Infrastruktur, weil die geplanten Barrieren real gar nicht wirken.','TISAX','3.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-2','R-R3-0821','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0822','R3-2026-07','Sind die Verhaltensregeln für Sicherheitszonen nicht allen beteiligten Personen bekannt gemacht, verstoßen Menschen unwissentlich gegen wichtige Schutzvorgaben. Türen bleiben offen, Fremde werden nicht hinterfragt. Sie riskieren, dass Unbefugte in sensible Bereiche gelangen und der physische Schutz durch alltägliches Fehlverhalten unbemerkt ausgehebelt wird.','TISAX','3.1.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-3','R-R3-0822','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0823','R3-2026-07','Sind keine Verfahren zur Vergabe und zum Entzug von Zutrittsberechtigungen etabliert, sammeln sich unkontrollierte und veraltete Zutrittsrechte an. Ausgeschiedene Personen behalten Zugang, Berechtigungen passen nicht zur Aufgabe. Sie riskieren, dass Unbefugte physischen Zutritt zu sensiblen Bereichen erhalten und Sie den Überblick über die Zutrittslage verlieren.','TISAX','3.1.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-4','R-R3-0823','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0824','R3-2026-07','Sind keine Richtlinien für das Besuchermanagement mit Registrierung und Begleitung definiert, bewegen sich Externe unkontrolliert und unbegleitet in Ihren Räumen. Ihr Aufenthalt ist weder nachvollziehbar noch überwacht. Sie riskieren Diebstahl, Ausspähung und Manipulation durch Besucher sowie den fehlenden Nachweis, wer sich wann in sensiblen Bereichen aufhielt.','TISAX','3.1.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-5','R-R3-0824','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0825','R3-2026-07','Sind keine Richtlinien für das Einbringen und Nutzen mobiler IT-Geräte und Datenträger, etwa Registrierung und Kennzeichnung, definiert und umgesetzt, gelangen unkontrollierte Geräte in Ihre Sicherheitszonen. Schadsoftware wird eingeschleppt, Daten unbemerkt abgezogen. Sie riskieren Infektionen und Datenabflüsse über private oder fremde Datenträger, deren Nutzung niemand nachvollziehen kann.','TISAX','3.1.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-6','R-R3-0825','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0826','R3-2026-07','Sind Netzwerk- und Infrastrukturkomponenten der eigenen oder von Kundennetzwerken nicht vor unbefugtem Zugang geschützt, können Dritte Kabel, Switches oder Anschlüsse physisch manipulieren. Angreifer klinken sich ein oder legen Systeme lahm. Sie riskieren das Abhören von Datenverkehr, unbefugte Netzwerkzugänge und Betriebsstörungen mit Auswirkungen bis in Kundennetzwerke.','TISAX','3.1.1-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-7','R-R3-0826','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0827','R3-2026-07','Sind externe Liegenschaften wie Lagerräume, Werkstätten oder Rechenzentren nicht im Sicherheitszonenkonzept berücksichtigt, bleiben dort gelagerte Informationswerte ungeschützt. An entlegenen Standorten fehlen Zutrittskontrolle und Aufsicht. Sie riskieren Diebstahl, Manipulation und Verlust von Werten an Orten, die außerhalb Ihres eigentlichen Schutzkonzepts liegen und leicht übersehen werden.','TISAX','3.1.1-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-8','R-R3-0827','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0828','R3-2026-07','Sind keine Maßnahmen gegen einfaches Mithören und unbefugte Einsichtnahme in den Sicherheitszonen umgesetzt, können Anwesende vertrauliche Gespräche mithören oder Bildschirme und Unterlagen einsehen. Sensible Informationen gelangen unbemerkt an Unbefugte. Sie riskieren Verletzungen der Vertraulichkeit direkt innerhalb Ihrer eigentlich geschützten Bereiche.','TISAX','3.1.1-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.1-9','R-R3-0828','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0829','R3-2026-07','Werden Informationsträger nicht geschützt und nicht nach einer einschlägigen Norm wie ISO 21964 mit mindestens Sicherheitsstufe 4 entsorgt, lassen sich vermeintlich vernichtete Daten rekonstruieren. Aus dem Abfall gewinnen Dritte vertrauliche Informationen zurück. Sie riskieren Datenabfluss und Compliance-Verstöße durch unsachgemäß entsorgte Dokumente und Datenträger.','TISAX','3.1.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.3-2','R-R3-0829','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0830','R3-2026-07','Werden mobile IT-Geräte vor ihrer Nutzung nicht registriert, fehlt Ihnen der Überblick, welche Geräte im Einsatz sind und wer sie verantwortet. Verlust oder Missbrauch bleibt unbemerkt. Sie riskieren, dass nicht erfasste Geräte unkontrolliert auf Ihre Daten zugreifen und Sie im Ernstfall weder sperren noch nachverfolgen können.','TISAX','3.1.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.4-2','R-R3-0830','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0831','R3-2026-07','Sind Anwender nicht darüber informiert, dass auf mobilen Geräten der Datenschutz eingeschränkt sein kann, gehen sie von falschen Annahmen über die Vertraulichkeit ihrer Daten aus. Sensible Inhalte werden unbedacht mobil verarbeitet. Sie riskieren Datenschutzverletzungen und Konflikte, weil Nutzer die tatsächlichen Schutzgrenzen mobiler Geräte nicht kennen.','TISAX','3.1.4-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.4-3','R-R3-0831','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0832','R3-2026-07','Werden mobile Datenträger oder die darauf gespeicherten Informationen nicht grundsätzlich verschlüsselt und bei technischer Unmöglichkeit nicht durch gleichwertige Maßnahmen geschützt, sind Ihre Daten bei Verlust oder Diebstahl frei lesbar. Dritte greifen ungehindert zu. Sie riskieren den vollständigen Abfluss vertraulicher Informationen, sobald ein Datenträger verloren geht oder entwendet wird.','TISAX','3.1.4-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','3.1.4-4','R-R3-0832','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0833','R3-2026-07','Werden Identifikationsmittel wie Ausweise oder Token nicht unter kontrollierten Bedingungen hergestellt, lassen sie sich fälschen oder unbefugt vervielfältigen. Angreifer verschaffen sich mit gefälschten Mitteln Zutritt und Zugriff. Sie riskieren, dass Unbefugte unter falscher Identität in geschützte Bereiche und Systeme gelangen und dort erheblichen Schaden anrichten.','TISAX','4.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.1-2','R-R3-0833','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0834','R3-2026-07','Ist die Gültigkeit von Identifikationsmitteln nicht auf einen angemessenen Zeitraum begrenzt, bleiben Ausweise und Token unbefristet nutzbar, auch nach Rollenwechsel oder Austritt. Vergessene oder verlorene Mittel behalten dauerhaft ihre Wirkung. Sie riskieren, dass veraltete Berechtigungen unbemerkt fortbestehen und Unbefugten langfristig Zutritt oder Zugriff ermöglichen.','TISAX','4.1.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.1-3','R-R3-0834','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0835','R3-2026-07','Besteht kein umgesetztes Konzept, um Identifikationsmittel bei Verlust zu sperren oder ungültig zu machen, bleiben verlorene oder gestohlene Ausweise und Token weiterhin gültig. Findet ein Angreifer sie, nutzt er sie ungehindert. Sie riskieren unbefugten Zutritt und Zugriff mit abhandengekommenen Mitteln, gegen die Sie nicht rechtzeitig einschreiten können.','TISAX','4.1.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.1-4','R-R3-0835','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0836','R3-2026-07','Werden zur Authentifizierung der Benutzer keine Verfahren nach dem aktuellen Stand der Technik eingesetzt, sind Ihre Zugänge mit veralteten oder schwachen Methoden angreifbar. Passwörter werden erraten, abgefangen oder umgangen. Sie riskieren die Übernahme von Benutzerkonten durch Angreifer und damit unbefugten Zugriff auf sensible Systeme und Daten.','TISAX','4.1.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.2-2','R-R3-0836','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0837','R3-2026-07','Wenn Sie Benutzer nicht durch starke, dem Stand der Technik entsprechende Passwörter authentifizieren, können Angreifer schwache Zugangsdaten leicht erraten oder per automatisierter Angriffe knacken. Sie riskieren dadurch unbefugten Zugriff auf Systeme und schützenswerte Informationen, was zu Datenabfluss, Manipulation und einem erheblichen Vertrauens- und Reputationsschaden für Ihre Organisation führen kann.','TISAX','4.1.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.2-3','R-R3-0837','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0838','R3-2026-07','Wenn Sie privilegierte Konten nicht durch höherwertige Verfahren wie Zwei-Faktor-Authentifizierung oder privilegiertes Zugangsmanagement schützen, wird ein kompromittiertes Administratorkonto zur offenen Tür für Angreifer. Sie riskieren die vollständige Übernahme kritischer Systeme, weitreichende Manipulation und Datenabfluss, da privilegierte Rechte kaum Grenzen kennen und der Schaden entsprechend gravierend ausfällt.','TISAX','4.1.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.2-4','R-R3-0838','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0839','R3-2026-07','Wenn Sie Authentifizierung und Zugriffskontrolle nicht risikobasiert durch ergänzende Maßnahmen wie Zugriffsüberwachung oder starke Authentifizierung absichern, bleiben besonders gefährdete Zugänge unzureichend geschützt. Sie riskieren, dass Angriffe und Missbrauch unbemerkt bleiben und schützenswerte Informationen kompromittiert werden, ohne dass Sie rechtzeitig gegensteuern können.','TISAX','4.1.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.2-5','R-R3-0839','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0840','R3-2026-07','Wenn Sie den Zugriff auf Daten mit sehr hohem Schutzbedarf nicht durch starke Authentifizierung wie Zwei-Faktor absichern, genügt ein einzelnes gestohlenes Passwort für den Zugang zu Ihren sensibelsten Informationen. Sie riskieren schwerwiegenden Datenabfluss, Verstöße gegen vertragliche und rechtliche Vorgaben sowie erhebliche Schäden für Kunden und Ihre Organisation.','TISAX','4.1.2-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.2-6','R-R3-0840','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0841','R3-2026-07','Wenn Sie herstellerseitige Standardkonten und Standardpasswörter nicht deaktivieren oder ändern, sind diese allgemein bekannten Zugangsdaten eine leicht ausnutzbare Schwachstelle. Angreifer nutzen solche Voreinstellungen gezielt aus und verschaffen sich mühelos Zugang zu Ihren Systemen, wodurch Sie unbefugten Zugriff, Manipulation und Datenverlust riskieren.','TISAX','4.1.3-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-10','R-R3-0841','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0842','R3-2026-07','Wenn die Einrichtung von Benutzerkonten nicht durch die verantwortliche Stelle erfolgt oder autorisiert wird, entstehen unkontrolliert Konten mit unklaren Berechtigungen. Sie riskieren, dass unberechtigte oder überprivilegierte Zugänge entstehen, die Nachvollziehbarkeit verloren geht und Angreifer sowie Innentäter die fehlende Kontrolle für unbefugten Zugriff ausnutzen.','TISAX','4.1.3-11') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-11','R-R3-0842','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0843','R3-2026-07','Wenn die Einrichtung von Benutzerkonten keinem Vier-Augen-Prinzip unterliegt, kann eine einzelne Person unbemerkt Konten mit weitreichenden Rechten anlegen. Sie riskieren die Einrichtung heimlicher oder überprivilegierter Zugänge, Manipulation und Betrug, da die fehlende gegenseitige Kontrolle Missbrauch und Fehler erst spät oder gar nicht aufdeckt.','TISAX','4.1.3-12') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-12','R-R3-0843','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0844','R3-2026-07','Wenn Sie Benutzerkonten von Dienstleistern nach Abschluss ihrer Aufgabe nicht zuverlässig sperren, bleiben aktive Zugänge außerhalb Ihrer direkten Kontrolle bestehen. Sie riskieren, dass diese verwaisten Konten unbemerkt für unbefugten Zugriff missbraucht werden, sei es durch den Dienstleister selbst oder durch Angreifer, die kompromittierte Zugangsdaten ausnutzen.','TISAX','4.1.3-13') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-13','R-R3-0844','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0845','R3-2026-07','Wenn Sperr- und Löschfristen für Benutzerkonten nicht verbindlich definiert sind, bleiben nicht mehr benötigte Konten unkontrolliert und uneinheitlich bestehen. Sie riskieren eine wachsende Zahl verwaister Zugänge, die als Angriffsfläche dienen und unbemerkten Missbrauch ermöglichen, während die Nachvollziehbarkeit über den Lebenszyklus der Konten verloren geht.','TISAX','4.1.3-14') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-14','R-R3-0845','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0846','R3-2026-07','Wenn Sie die Verwendung von Standard-Passwörtern nicht technisch verhindern, bleiben unsichere und allgemein bekannte Voreinstellungen im Einsatz. Angreifer nutzen genau diese Schwachstelle systematisch aus, sodass Sie unbefugten Zugriff auf Systeme und Daten riskieren, obwohl sich das Problem durch technische Erzwingung sicherer Passwörter vermeiden ließe.','TISAX','4.1.3-15') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-15','R-R3-0846','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0847','R3-2026-07','Wenn Sie beim Einsatz starker Authentifizierung das Medium wie den Besitzfaktor nicht sicher verwenden und vor Missbrauch schützen, kann ein gestohlener oder kopierter Faktor die zusätzliche Sicherheit aushebeln. Sie riskieren, dass Angreifer trotz mehrstufiger Authentifizierung unbefugten Zugang erlangen und der eigentliche Schutzgewinn ins Leere läuft.','TISAX','4.1.3-16') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-16','R-R3-0847','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0848','R3-2026-07','Wenn Sie Benutzerkonten nicht regelmäßig überprüfen, auch die in Kundensystemen, bleiben nicht mehr benötigte oder unberechtigte Zugänge unentdeckt. Sie riskieren, dass sich überflüssige und überprivilegierte Konten ansammeln, die als Angriffsfläche dienen und Missbrauch ermöglichen, ohne dass Sie den tatsächlichen Zugriffsstand noch überblicken.','TISAX','4.1.3-17') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-17','R-R3-0848','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0849','R3-2026-07','Wenn Sie die interaktive Anmeldung bei Dienst- oder technischen Konten nicht technisch verhindern, können Angreifer diese oft weitreichend berechtigten Konten für direkten Systemzugriff missbrauchen. Sie riskieren, dass solche Konten für unbemerkte Angriffe genutzt werden, da ihre Aktivitäten schwer einer Person zuzuordnen und daher kaum nachvollziehbar sind.','TISAX','4.1.3-18') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-18','R-R3-0849','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0850','R3-2026-07','Wenn Sie keine eindeutigen und personalisierten Benutzerkonten verwenden, lassen sich Aktionen nicht mehr einzelnen Personen zuordnen. Sie riskieren den Verlust der Nachvollziehbarkeit, sodass Fehlverhalten, Manipulation und Sicherheitsvorfälle nicht aufgeklärt werden können und Verantwortliche sich hinter geteilten Zugängen verbergen, was Missbrauch begünstigt.','TISAX','4.1.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-2','R-R3-0850','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0851','R3-2026-07','Wenn die Nutzung von Sammelkonten nicht geregelt und auf begründete Ausnahmen beschränkt ist, gehen Handlungen im Kollektiv unter und lassen sich keiner Person zuordnen. Sie riskieren den Verlust der Rückverfolgbarkeit, wodurch Missbrauch, Fehler und Sicherheitsvorfälle nicht aufgeklärt werden können und Verantwortlichkeit nicht mehr durchsetzbar ist.','TISAX','4.1.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-3','R-R3-0851','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0852','R3-2026-07','Wenn Sie Benutzerkonten nicht unmittelbar sperren, sobald ein Benutzer die Organisation verlässt, behalten ehemalige Mitarbeitende weiter Zugriff auf Systeme und Daten. Sie riskieren, dass solche aktiven Zugänge absichtlich oder durch Kompromittierung missbraucht werden, was zu Datenabfluss, Manipulation und erheblichem Schaden führen kann.','TISAX','4.1.3-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-4','R-R3-0852','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0853','R3-2026-07','Wenn Sie Benutzerkonten nicht in regelmäßigen Abständen überprüfen, bleiben nicht mehr benötigte oder unberechtigte Zugänge unbemerkt bestehen. Sie riskieren eine wachsende Zahl verwaister und überprivilegierter Konten, die als Angriffsfläche dienen und unbemerkten Missbrauch ermöglichen, wodurch die Kontrolle über die tatsächlichen Zugriffsrechte verloren geht.','TISAX','4.1.3-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-5','R-R3-0853','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0854','R3-2026-07','Wenn die Zustellung der Anmeldeinformationen nicht auf einem sicheren Weg erfolgt, können Zugangsdaten bereits bei der Übermittlung durch Unbefugte abgefangen werden. Sie riskieren, dass Angreifer noch vor der ersten Nutzung Kenntnis von Passwörtern erlangen und sich unbemerkt Zugang zu Systemen und schützenswerten Informationen verschaffen.','TISAX','4.1.3-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-6','R-R3-0854','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0855','R3-2026-07','Wenn keine Richtlinie zum Umgang mit Anmeldeinformationen umgesetzt ist, geben Mitarbeitende Passwörter womöglich weiter oder notieren sie unsicher. Sie riskieren, dass Zugangsdaten in falsche Hände geraten, unbefugter Zugriff entsteht und die Zuordnung von Aktionen zu Personen verloren geht, wodurch Missbrauch begünstigt und die Nachvollziehbarkeit untergraben wird.','TISAX','4.1.3-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-7','R-R3-0855','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0856','R3-2026-07','Wenn nicht sichergestellt ist, dass die Anmeldeinformationen eines personalisierten Kontos nur dem zugeordneten Benutzer bekannt sind, lassen sich Aktionen nicht mehr eindeutig einer Person zuweisen. Sie riskieren den Verlust der Nachvollziehbarkeit und unbefugten Zugriff, da geteilte oder ausgespähte Passwörter Missbrauch ermöglichen und Verantwortlichkeit nicht mehr durchsetzbar ist.','TISAX','4.1.3-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-8','R-R3-0856','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0857','R3-2026-07','Wenn kein Basis-Benutzerprofil mit minimalen Zugriffsrechten standardmäßig angewendet wird, erhalten neue Konten leicht mehr Rechte als nötig. Sie riskieren eine schleichende Überberechtigung, die im Falle einer Kompromittierung den möglichen Schaden erheblich vergrößert und dem Grundsatz der minimalen Rechtevergabe zuwiderläuft.','TISAX','4.1.3-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.1.3-9','R-R3-0857','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0858','R3-2026-07','Wenn Sie bestehende Zugriffsrechte nicht in kürzeren Abständen wie vierteljährlich überprüfen, bleiben unberechtigte oder überflüssige Berechtigungen bei besonders schützenswerten Informationen lange unentdeckt. Sie riskieren, dass sich Rechte unbemerkt anhäufen und im Falle eines Missbrauchs weitreichender Schaden entsteht, weil die engmaschige Kontrolle fehlt.','TISAX','4.2.1-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-10','R-R3-0858','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0859','R3-2026-07','Wenn Sie die Zugriffsrechte normaler, privilegierter und technischer Konten nicht regelmäßig überprüfen, auch in Kundensystemen, sammeln sich unbemerkt überflüssige und überprivilegierte Berechtigungen an. Sie riskieren, dass diese ungeprüften Rechte als Angriffsfläche dienen und im Falle einer Kompromittierung erheblichen Schaden ermöglichen, ohne dass Sie den tatsächlichen Rechtestand kennen.','TISAX','4.2.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-2','R-R3-0859','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0860','R3-2026-07','Wenn keine Berechtigungskonzepte erstellt und dokumentiert sind, erfolgt die Rechtevergabe unstrukturiert und intransparent. Sie riskieren, dass Benutzer mehr Rechte erhalten als nötig, Berechtigungen nicht nachvollziehbar sind und Prüfungen ins Leere laufen, wodurch Missbrauch begünstigt und die Kontrolle über den Zugriff auf Ihre Informationen erschwert wird.','TISAX','4.2.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-3','R-R3-0860','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0861','R3-2026-07','Wenn Sie zur Steuerung der Zugriffsrechte keine definierten Berechtigungsrollen verwenden, wird die Rechtevergabe unübersichtlich und fehleranfällig. Sie riskieren inkonsistente und übermäßige Berechtigungen, die sich kaum noch überblicken und prüfen lassen, wodurch überprivilegierte Konten entstehen und der mögliche Schaden bei Missbrauch steigt.','TISAX','4.2.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-4','R-R3-0861','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0862','R3-2026-07','Wenn die Vergabe von Rechten nicht bedarfsorientiert und rollenbezogen erfolgt, erhalten Benutzer regelmäßig mehr Berechtigungen als für ihre Aufgabe erforderlich. Sie riskieren eine schleichende Überberechtigung, die im Falle einer Kompromittierung oder eines Innentäters den möglichen Schaden erheblich vergrößert und dem Prinzip der minimalen Rechtevergabe widerspricht.','TISAX','4.2.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-5','R-R3-0862','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0863','R3-2026-07','Wenn nicht sichergestellt ist, dass normalen Benutzerkonten keine privilegierten Zugriffsrechte erteilt werden, verschwimmt die Grenze zwischen alltäglichen und administrativen Tätigkeiten. Sie riskieren, dass ein kompromittiertes Standardkonto weitreichenden Schaden anrichtet, da Angreifer die unnötig hohen Rechte für tiefe Eingriffe in Ihre Systeme ausnutzen können.','TISAX','4.2.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-6','R-R3-0863','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0864','R3-2026-07','Wenn Sie die Zugriffsrechte eines Benutzers nach einem Wechsel nicht anpassen, sammeln sich über die Zeit Berechtigungen aus früheren Rollen an. Sie riskieren, dass Mitarbeitende weit mehr Rechte besitzen als für ihre aktuelle Aufgabe nötig, was das Prinzip der minimalen Rechtevergabe verletzt und den Schaden bei Missbrauch vergrößert.','TISAX','4.2.1-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-7','R-R3-0864','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0865','R3-2026-07','Wenn Zugriffsrechte nicht vor ihrer Wirksamkeit durch den internen Informationsverantwortlichen freigegeben werden, entstehen Berechtigungen ohne fachliche Kontrolle. Sie riskieren, dass unberechtigte oder überprivilegierte Zugänge unbemerkt vergeben werden und schützenswerte Informationen Personen offenstehen, die dafür keine Freigabe hätten, wodurch Missbrauch und Datenabfluss begünstigt werden.','TISAX','4.2.1-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-8','R-R3-0865','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0866','R3-2026-07','Wenn Sie Informationen mit sehr hohem Schutzbedarf nicht inhaltlich verschlüsseln oder vergleichbar wirksam schützen, können privilegierte Benutzer wie Administratoren uneingeschränkt auf diese sensibelsten Daten zugreifen. Sie riskieren, dass technische Zugriffsmöglichkeiten für Missbrauch genutzt werden und ein kompromittiertes Administratorkonto zu schwerwiegendem Datenabfluss führt.','TISAX','4.2.1-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','4.2.1-9','R-R3-0866','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0867','R3-2026-07','Wenn kein technisches Regelwerk die Verschlüsselungsanforderungen entsprechend der Klassifizierung festlegt, wird Kryptografie uneinheitlich und nach Gutdünken eingesetzt. Sie riskieren, dass schützenswerte Informationen unzureichend oder gar nicht verschlüsselt werden, wodurch vertrauliche Daten bei Verlust oder Abfangen offenliegen und weder Nachvollziehbarkeit noch ein angemessenes Schutzniveau gewährleistet sind.','TISAX','5.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.1-2','R-R3-0867','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0868','R3-2026-07','Wenn kein Nutzungskonzept für Kryptografie den gesamten Schlüssellebenszyklus regelt, werden Verfahren, Schlüsselstärken und Schlüsselverwaltung unkontrolliert gehandhabt. Sie riskieren schwache oder veraltete Verschlüsselung, unsicher verwahrte Schlüssel und den Verlust der Kontrolle über kryptografisches Material, wodurch der eigentlich beabsichtigte Schutz Ihrer Informationen unterlaufen wird.','TISAX','5.1.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.1-3','R-R3-0868','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0869','R3-2026-07','Wenn kein Notfallprozess die Wiederherstellung von Schlüsselmaterial ermöglicht, kann der Verlust eines Schlüssels verschlüsselte Daten dauerhaft unbrauchbar machen. Sie riskieren, dass schützenswerte Informationen unwiederbringlich verloren gehen und Geschäftsprozesse zum Stillstand kommen, weil im Ernstfall kein geregelter Zugriff auf das benötigte Schlüsselmaterial besteht.','TISAX','5.1.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.1-4','R-R3-0869','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0870','R3-2026-07','Wenn die Anforderungen an die Schlüsselhoheit, besonders bei organisationsfremder Verarbeitung, nicht ermittelt und erfüllt sind, verlieren Sie womöglich die Kontrolle über Ihr kryptografisches Material. Sie riskieren, dass Dritte oder Dienstleister Zugriff auf Ihre Schlüssel und damit auf verschlüsselte, schützenswerte Informationen erhalten, wodurch der beabsichtigte Vertraulichkeitsschutz ausgehebelt wird.','TISAX','5.1.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.1-5','R-R3-0870','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0871','R3-2026-07','Wenn keine Richtlinien und Verfahren zur Nutzung von Netzwerkdiensten entsprechend der Klassifizierung definiert und umgesetzt sind, erfolgt die Datenübertragung ungeregelt und uneinheitlich. Sie riskieren, dass vertrauliche Informationen über unsichere Kanäle übertragen und dabei abgefangen oder manipuliert werden, weil verbindliche Schutzvorgaben für den jeweiligen Schutzbedarf fehlen.','TISAX','5.1.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.2-2','R-R3-0871','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0872','R3-2026-07','Wenn Sie übertragene Inhalte nicht durch geeignete Maßnahmen während der Übertragung schützen, können Dritte den Datenverkehr abfangen und mitlesen. Sie riskieren, dass vertrauliche Informationen bei der Übermittlung offenliegen oder unbemerkt manipuliert werden, was zu Datenabfluss, Vertrauensverlust und Verstößen gegen vertragliche wie rechtliche Vorgaben führen kann.','TISAX','5.1.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.2-3','R-R3-0872','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0873','R3-2026-07','Wenn keine Maßnahmen die korrekte Adressierung und den korrekten Transport von Informationen sicherstellen, können Daten an falsche Empfänger gelangen oder auf ihrem Weg umgeleitet werden. Sie riskieren, dass vertrauliche Informationen in unbefugte Hände geraten oder verloren gehen, wodurch Datenabfluss, Fehlleitungen und ein Verlust der Integrität entstehen.','TISAX','5.1.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.2-4','R-R3-0873','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0874','R3-2026-07','Wenn der elektronische Datenaustausch nicht je nach Klassifizierung durch Inhalts- oder Transportverschlüsselung abgesichert ist, werden vertrauliche Daten womöglich im Klartext übertragen. Sie riskieren, dass Angreifer diese Informationen abfangen und mitlesen, was zu Datenabfluss, dem Verlust von Geschäftsgeheimnissen und Verstößen gegen vertragliche wie rechtliche Vorgaben führen kann.','TISAX','5.1.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.2-5','R-R3-0874','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0875','R3-2026-07','Wenn Sie bei Fernzugriffsverbindungen nicht auf angemessene Sicherheitsmerkmale wie Verschlüsselung und kontrolliertes Gewähren und Beenden des Zugriffs achten, werden diese Zugänge zu einer offenen Angriffsfläche. Sie riskieren, dass Angreifer ungeschützte Fernverbindungen abfangen oder übernehmen und sich unbemerkt Zugang zu Ihren internen Systemen und Daten verschaffen.','TISAX','5.1.2-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.2-6','R-R3-0875','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0876','R3-2026-07','Wenn Sie Informationen nicht verschlüsselt übertragen und bei fehlender Verschlüsselung keine gleichwertigen Schutzmaßnahmen ergreifen, liegen schützenswerte Daten während der Übertragung ungeschützt vor. Sie riskieren, dass Angreifer den Datenverkehr abfangen und vertrauliche Inhalte mitlesen oder manipulieren, was zu Datenabfluss und Verstößen gegen Schutzvorgaben führen kann.','TISAX','5.1.2-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.2-7','R-R3-0876','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0877','R3-2026-07','Wenn Sie Informationen mit sehr hohem Schutzbedarf beim Transport nicht inhaltsverschlüsseln, bleiben Ihre sensibelsten Daten allein durch die Transportsicherung geschützt und liegen an den Endpunkten offen. Sie riskieren, dass ein kompromittierter Übertragungsweg oder Zwischensystem die Daten preisgibt, was zu schwerwiegendem Datenabfluss und erheblichem Schaden für Ihre Organisation führt.','TISAX','5.1.2-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.1.2-8','R-R3-0877','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0878','R3-2026-07','Wenn für Änderungen an Systemen und Prozessen kein formales Genehmigungsverfahren etabliert ist, werden Anpassungen unkontrolliert und ohne verbindliche Freigabe umgesetzt. Sie riskieren, dass fehlerhafte oder unsichere Änderungen ungeprüft in Betrieb gehen, Sicherheitslücken entstehen und Störungen auftreten, deren Ursachen sich mangels Nachvollziehbarkeit nur schwer aufklären lassen.','TISAX','5.2.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.1-2','R-R3-0878','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0879','R3-2026-07','Wenn geplante Änderungen nicht hinsichtlich ihrer Auswirkungen auf die Informationssicherheit bewertet werden, bleiben neu eingeführte Risiken und Schwachstellen unerkannt. Sie riskieren, dass Anpassungen unbeabsichtigt Sicherheitslücken öffnen oder Schutzmaßnahmen aushebeln und diese Schwächen erst nach einem Vorfall auffallen, wenn der Schaden bereits eingetreten ist.','TISAX','5.2.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.1-3','R-R3-0879','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0880','R3-2026-07','Wenn Änderungen mit Auswirkung auf die Informationssicherheit nicht strukturiert geplant und geprüft, sondern ungeplant vorgenommen werden, geschehen Eingriffe überhastet und ohne ausreichende Kontrolle. Sie riskieren, dass unbedachte Änderungen Sicherheitslücken verursachen, Systeme destabilisieren und Störungen auslösen, die sich mangels Planung und Dokumentation nur schwer beheben lassen.','TISAX','5.2.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.1-4','R-R3-0880','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0881','R3-2026-07','Ohne Notfallverfahren für fehlgeschlagene Änderungen können Sie nach einem misslungenen Update oder einer fehlerhaften Konfiguration nicht schnell in einen sicheren Ausgangszustand zurückkehren. Systeme bleiben dann über längere Zeit gestört oder verwundbar, Ausfallzeiten wachsen und in der Hektik werden häufig zusätzliche Fehler gemacht, die den Schaden vergrößern.','TISAX','5.2.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.1-5','R-R3-0881','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0882','R3-2026-07','Wenn Sie die Einhaltung der Sicherheitsanforderungen während und nach Änderungen nicht überprüfen, schleichen sich unbemerkt Fehlkonfigurationen und neue Schwachstellen ein. Solche unentdeckten Lücken werden von Angreifern ausgenutzt oder führen zu Compliance-Verstößen, weil niemand bestätigt hat, dass das geänderte System weiterhin sicher betrieben wird.','TISAX','5.2.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.1-6','R-R3-0882','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0883','R3-2026-07','Ohne eine an der Risikoanalyse ausgerichtete Netzwerksegmentierung liegen schützenswerte Bereiche ungetrennt im selben Netz. Ein Angreifer, der einen einzelnen Rechner kompromittiert, kann sich dann ungehindert seitlich ausbreiten und auf besonders sensible Systeme zugreifen, wodurch aus einem lokalen Vorfall schnell ein flächendeckender Schaden wird.','TISAX','5.2.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.2-2','R-R3-0883','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0884','R3-2026-07','Wenn Sie Entwicklungs-, Test- und Produktivsysteme nicht trennen, gelangen unfertiger Code, Testdaten oder fehlerhafte Konfigurationen ungewollt in den Produktivbetrieb. Zudem geraten echte, oft personenbezogene Daten in ungeschützte Testumgebungen, was Ausfälle, Datenschutzverstöße und schwer nachvollziehbare Sicherheitslücken zur Folge hat.','TISAX','5.2.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.2-3','R-R3-0884','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0885','R3-2026-07','Werden Ihre Mitarbeiter nicht anlassbezogen für aktuelle Schadsoftware-Bedrohungen sensibilisiert, erkennen sie neue Angriffsmaschen und Vorfälle zu spät. Sie öffnen dann eher gefährliche Anhänge oder Links, sodass Malware in Ihre Systeme gelangt und sich ausbreitet, obwohl technische Schutzmaßnahmen allein solche Angriffe oft nicht abfangen.','TISAX','5.2.3-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-10','R-R3-0885','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0886','R3-2026-07','Wenn Sie für IT-Systeme ohne Schutzsoftware keine alternativen Maßnahmen wie Netzisolierung oder Dienstereduzierung umsetzen, bleiben diese Systeme ungeschützt angreifbar. Schadsoftware kann sich dort einnisten und von dort aus in das übrige Netz ausbreiten, wodurch ein einzelnes ungeschütztes Gerät zum Einfallstor für weitreichende Kompromittierungen wird.','TISAX','5.2.3-11') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-11','R-R3-0886','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0887','R3-2026-07','Ohne definierte und tatsächlich umgesetzte technische und organisatorische Maßnahmen gegen Schadsoftware sind Ihre Systeme Malware schutzlos ausgeliefert. Viren, Trojaner oder Ransomware können sich ungehindert einnisten, Daten verschlüsseln oder abfließen lassen und den Betrieb lahmlegen, was zu erheblichen finanziellen und reputativen Schäden führt.','TISAX','5.2.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-2','R-R3-0887','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0888','R3-2026-07','Bleiben nicht benötigte Netzwerkdienste aktiv, vergrößern Sie unnötig die Angriffsfläche Ihrer Systeme. Jeder offene Dienst ist ein potenzielles Einfallstor mit eigenen Schwachstellen, das Angreifer zum Eindringen nutzen können, ohne dass der Dienst überhaupt für den Betrieb erforderlich wäre.','TISAX','5.2.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-3','R-R3-0888','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0889','R3-2026-07','Wenn der Zugriff auf Netzwerkdienste nicht auf das tatsächlich Benötigte eingeschränkt ist, können Unbefugte Dienste erreichen, die ihnen gar nicht offenstehen sollten. Angreifer nutzen solche unnötig weit geöffneten Zugänge aus, um Schwachstellen anzugreifen, sich Zugriff zu verschaffen und sich im Netz weiter auszubreiten.','TISAX','5.2.3-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-4','R-R3-0889','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0890','R3-2026-07','Ist keine Schutzsoftware installiert oder wird sie nicht regelmäßig automatisch aktualisiert, erkennt sie neue Schadsoftware nicht mehr. Ihre Systeme bleiben gegenüber aktuellen Viren und Trojanern blind, sodass sich Malware ungehindert einnisten und ausbreiten kann, bevor überhaupt jemand den Befall bemerkt.','TISAX','5.2.3-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-5','R-R3-0890','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0891','R3-2026-07','Werden empfangene Dateien und Software nicht automatisch vor der Ausführung geprüft, kann Schadcode direkt beim Öffnen aktiv werden. Ohne On-Access-Scan verlassen Sie sich allein auf die Aufmerksamkeit der Nutzer, sodass ein einziger unbedachter Doppelklick genügt, um Malware auf dem System und im Netz zu verbreiten.','TISAX','5.2.3-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-6','R-R3-0891','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0892','R3-2026-07','Wird der gesamte Datenbestand nicht regelmäßig vollständig auf Schadsoftware geprüft, bleiben ruhende oder zunächst unerkannte Infektionen unentdeckt. Solche schlafende Malware kann später aktiv werden, sich verbreiten oder Daten abgreifen, weil ein reiner Zugriffsscan Bedrohungen in selten genutzten Dateien und Archiven leicht übersieht.','TISAX','5.2.3-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-7','R-R3-0892','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0893','R3-2026-07','Werden von zentralen Gateways übertragene Daten wie E-Mail und Internetverkehr nicht automatisch, auch verschlüsselt, geprüft, passiert Schadsoftware ungehindert die Netzgrenze. Sie verlieren einen wichtigen zentralen Filterpunkt, sodass Malware über alltägliche Kanäle bis auf die Endgeräte durchdringt, bevor lokale Schutzmaßnahmen greifen können.','TISAX','5.2.3-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-8','R-R3-0893','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0894','R3-2026-07','Können Benutzer die Schutzsoftware deaktivieren oder verändern, entsteht schnell ein ungeschütztes Zeitfenster. Ob aus Bequemlichkeit oder durch Manipulation von Angreifern abgeschaltet, bleibt das System dann ohne Malware-Abwehr, sodass Schadsoftware ungehindert eindringen und sich unbemerkt im Netz ausbreiten kann.','TISAX','5.2.3-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.3-9','R-R3-0894','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0895','R3-2026-07','Werden Zugriffe beim Auf- und Abbau organisationsfremder Verbindungen wie Fernwartung nicht protokolliert, können Sie im Nachhinein nicht nachvollziehen, wer wann von außen auf Ihre Systeme zugegriffen hat. Missbrauch durch Dienstleister oder gekaperte Zugänge bleibt so unentdeckt, und bei einem Vorfall fehlen Ihnen entscheidende Beweise.','TISAX','5.2.4-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-10','R-R3-0895','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0896','R3-2026-07','Werden Zugriffe auf Daten mit sehr hohem Schutzbedarf nicht protokolliert, lässt sich unbefugtes Lesen oder Kopieren dieser besonders sensiblen Informationen nicht erkennen oder belegen. Ein Datenabfluss bleibt dann unbemerkt, und Sie können weder den Verursacher ermitteln noch den Umfang des Schadens rekonstruieren.','TISAX','5.2.4-11') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-11','R-R3-0896','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0897','R3-2026-07','Sind die Anforderungen an die Protokollierung von Administrator- und Nutzeraktivitäten nicht ermittelt und erfüllt, fehlen Ihnen aussagekräftige Aufzeichnungen über kritische Handlungen. Missbrauch privilegierter Rechte oder unbefugte Zugriffe bleiben dann unerkannt, und bei einem Sicherheitsvorfall können Sie den Ablauf weder analysieren noch verantwortliche Personen benennen.','TISAX','5.2.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-2','R-R3-0897','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0898','R3-2026-07','Bewerten Sie Ihre IT-Systeme nicht hinsichtlich der Protokollierungsnotwendigkeit, zeichnen Sie entweder zu wenig oder wahllos zu viel auf. Im ersten Fall fehlen bei einem Vorfall die entscheidenden Spuren, im zweiten ertrinken relevante Ereignisse in Datenmengen, sodass Angriffe in beiden Fällen unerkannt bleiben.','TISAX','5.2.4-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-3','R-R3-0898','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0899','R3-2026-07','Holen Sie bei organisationsfremden IT-Diensten keine Informationen zu deren Überwachungsmöglichkeiten ein, wissen Sie nicht, ob und wie Aktivitäten dort protokolliert werden. Bei einem Vorfall beim Dienstleister stehen Sie ohne verwertbare Nachweise da und können weder Ursache noch Umfang eines Sicherheitsproblems aufklären.','TISAX','5.2.4-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-4','R-R3-0899','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0900','R3-2026-07','Werden Ereignisprotokolle nicht regelmäßig auf Regelverstöße und Auffälligkeiten geprüft, bleiben aufgezeichnete Warnzeichen ungenutzt liegen. Angriffe oder Missbrauch, die sich in den Logs bereits abzeichnen, werden dann nicht rechtzeitig erkannt, sodass Sie erst reagieren, wenn der Schaden längst eingetreten und schwer eindämmbar ist.','TISAX','5.2.4-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-5','R-R3-0900','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0901','R3-2026-07','Fehlt ein etabliertes Verfahren zur Eskalation relevanter Ereignisse an die zuständigen Stellen, versanden erkannte Vorfälle ohne Reaktion. Meldungen erreichen dann nicht rechtzeitig Datenschutz, Unternehmenssicherheit oder IT-Sicherheit, wodurch aus einem beherrschbaren Ereignis eine ausgewachsene Krise wird, weil niemand die Verantwortung übernimmt und gegensteuert.','TISAX','5.2.4-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-6','R-R3-0901','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0902','R3-2026-07','Sind Ereignisprotokolle nicht gegen nachträgliche Änderungen geschützt, kann ein Angreifer nach einem Einbruch seine Spuren verwischen. Manipulierte oder gelöschte Logs verlieren jeden Beweiswert, sodass Sie den Vorfall nicht mehr rekonstruieren, den Verursacher nicht ermitteln und weder rechtliche noch vertragliche Nachweispflichten erfüllen können.','TISAX','5.2.4-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-7','R-R3-0902','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0903','R3-2026-07','Fehlt eine angemessene Überwachung und Aufzeichnung sicherheitsrelevanter Aktionen im Netzwerk, bleiben verdächtige Vorgänge und Angriffe unsichtbar. Sie bemerken Eindringlinge oder ungewöhnliche Datenbewegungen dann nicht rechtzeitig und können bei einem Vorfall den Hergang nicht nachvollziehen, wodurch Angreifer lange unentdeckt im Netz agieren.','TISAX','5.2.4-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-8','R-R3-0903','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0904','R3-2026-07','Ermitteln und erfüllen Sie die für die Handhabung von Ereignisprotokollen geltenden Anforderungen wie vertragliche Vorgaben nicht, verstoßen Sie unbemerkt gegen Kunden- oder Gesetzespflichten. Protokolle werden dann falsch aufbewahrt, zu früh gelöscht oder unzureichend geschützt, was zu Vertragsbrüchen, Bußgeldern und fehlenden Nachweisen bei Vorfällen führt.','TISAX','5.2.4-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.4-9','R-R3-0904','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0905','R3-2026-07','Werden potenziell betroffene Systeme und Software nicht identifiziert, bewertet und ihre Schwachstellen behandelt, bleiben bekannte Sicherheitslücken offen. Angreifer nutzen genau solche unbehandelten Schwachstellen gezielt aus, um in Ihre Systeme einzudringen, sodass eine öffentlich bekannte Lücke unbemerkt zum Einfallstor für einen schweren Vorfall wird.','TISAX','5.2.5-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.5-2','R-R3-0905','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0906','R3-2026-07','Ohne ein definiertes und umgesetztes Patch-Management werden Sicherheitsupdates verspätet, unvollständig oder gar nicht eingespielt. Bekannte Schwachstellen bleiben dadurch über lange Zeit offen, und da Angreifer neue Lücken oft schon kurz nach Bekanntwerden ausnutzen, steigt das Risiko einer erfolgreichen Kompromittierung Ihrer Systeme erheblich.','TISAX','5.2.5-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.5-3','R-R3-0906','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0907','R3-2026-07','Setzen Sie keine Maßnahmen um, um verbleibende Risiken auf ein Mindestmaß zu senken, bleiben bekannte Restschwachstellen ohne jede Kompensation bestehen. Wenn ein Patch nicht verfügbar oder anwendbar ist, fehlt dann jeder ausgleichende Schutz, sodass Angreifer die ungeschützte Lücke ausnutzen und in Ihre Systeme eindringen können.','TISAX','5.2.5-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.5-4','R-R3-0907','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0908','R3-2026-07','Verifizieren Sie die erfolgreiche Installation von Patches nicht, verlassen Sie sich auf einen trügerischen Schutz. Fehlgeschlagene oder nur teilweise eingespielte Updates bleiben unbemerkt, sodass Sie eine Schwachstelle für geschlossen halten, während sie in Wahrheit weiter offen ist und von Angreifern ausgenutzt werden kann.','TISAX','5.2.5-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.5-5','R-R3-0908','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0909','R3-2026-07','Werden Ihre Systeme und Dienste nicht regelmäßig auf Schwachstellen gescannt und nicht scanbare Systeme nicht anderweitig geschützt, bleiben neu auftretende Sicherheitslücken unentdeckt. Sie erkennen verwundbare Systeme dann nicht rechtzeitig, sodass Angreifer bekannte Schwachstellen ausnutzen können, bevor Sie überhaupt von deren Existenz erfahren.','TISAX','5.2.6-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-10','R-R3-0909','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0910','R3-2026-07','Wird der Umfang eines Systemaudits nicht rechtzeitig vor der Durchführung festgelegt, drohen entweder Lücken oder unkontrollierte Eingriffe. Wichtige Systeme werden dann übersehen oder unbeabsichtigt gestört, und ohne klaren Rahmen liefert das Audit keine belastbaren Ergebnisse, sodass Schwachstellen unentdeckt bleiben oder der Betrieb unnötig beeinträchtigt wird.','TISAX','5.2.6-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-2','R-R3-0910','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0911','R3-2026-07','Werden System- oder Dienst-Audits nicht vorab mit Betreibern und Nutzern abgestimmt, können Prüfaktivitäten wie Scans laufende Dienste stören oder ausfallen lassen. Zudem sind die Verantwortlichen nicht vorbereitet, deuten die Aktivität womöglich als echten Angriff und ergreifen Fehlmaßnahmen, wodurch das Audit selbst zum Auslöser eines Betriebsvorfalls wird.','TISAX','5.2.6-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-3','R-R3-0911','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0912','R3-2026-07','Werden Auditergebnisse nicht rückverfolgbar gespeichert und an das Management berichtet, bleiben erkannte Schwachstellen ohne Konsequenz. Die Entscheider erfahren nichts von den Risiken, sodass keine Ressourcen für die Behebung bereitgestellt werden und identifizierte Mängel unbearbeitet fortbestehen, während zugleich der Nachweis der Prüfung für spätere Audits fehlt.','TISAX','5.2.6-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-4','R-R3-0912','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0913','R3-2026-07','Werden aus den Auditergebnissen keine konkreten Maßnahmen abgeleitet, verpufft der gesamte Prüfaufwand wirkungslos. Erkannte Schwachstellen bleiben dann trotz Kenntnis offen bestehen, und Angreifer können genau die Lücken ausnutzen, die Sie im Audit bereits dokumentiert, aber nie geschlossen haben.','TISAX','5.2.6-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-5','R-R3-0913','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0914','R3-2026-07','Werden System- und Dienst-Audits nicht unter Berücksichtigung der dadurch möglichen Sicherheitsrisiken geplant, können Prüfhandlungen selbst Störungen oder Ausfälle auslösen. Intensive Scans oder Tests überlasten empfindliche Systeme, sodass ausgerechnet die Maßnahme zur Erhöhung der Sicherheit unbeabsichtigt den Betrieb unterbricht und Schaden verursacht.','TISAX','5.2.6-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-6','R-R3-0914','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0915','R3-2026-07','Werden regelmäßige Audits nicht von Fachpersonal mit geeigneten Werkzeugen und sowohl von außen als auch aus dem internen Netz durchgeführt, bleiben ganze Schwachstellenklassen unentdeckt. Oberflächliche oder einseitige Prüfungen übersehen von innen erreichbare Angriffswege, sodass Sie sich in falscher Sicherheit wiegen, während real ausnutzbare Lücken offen bleiben.','TISAX','5.2.6-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-7','R-R3-0915','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0916','R3-2026-07','Wird nach Abschluss eines Audits nicht zeitnah ein Ergebnisbericht erstellt, geraten Feststellungen in Vergessenheit und verlieren an Aktualität. Ohne dokumentierte Grundlage werden Schwachstellen nicht nachverfolgt und behoben, sodass erkannte Risiken unbearbeitet bestehen bleiben und der Nachweis der Prüfung gegenüber Kunden und Auditoren fehlt.','TISAX','5.2.6-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-8','R-R3-0916','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0917','R3-2026-07','Fehlen für kritische Systeme zusätzliche Audit-Anforderungen wie Penetrationstests oder risikobasierte Prüfintervalle, werden gerade Ihre wichtigsten Dienste nur oberflächlich geprüft. Tiefer liegende oder gezielt ausnutzbare Schwachstellen bleiben dann unentdeckt, sodass ein erfolgreicher Angriff auf ein besonders schützenswertes System unbemerkt vorbereitet werden kann.','TISAX','5.2.6-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.6-9','R-R3-0917','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0918','R3-2026-07','Haben Sie die Anforderungen an eine Netzwerksegmentierung nicht ermittelt und erfüllt, liegen unterschiedlich schützenswerte Bereiche ungetrennt im selben Netz. Ein Angreifer, der einen Bereich kompromittiert, kann sich dann ungehindert bis zu Ihren kritischen Systemen ausbreiten, wodurch aus einem begrenzten Vorfall ein flächendeckender Schaden entsteht.','TISAX','5.2.7-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.7-2','R-R3-0918','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0919','R3-2026-07','Fehlen definierte Verfahren zur Verwaltung und Steuerung Ihrer Netzwerke, geschehen Änderungen unkoordiniert und unkontrolliert. Fehlkonfigurationen, unbemerkt offene Zugänge und uneinheitliche Regeln häufen sich, sodass Sicherheitslücken entstehen und der Netzbetrieb bei Störungen nur schwer und langsam wiederhergestellt werden kann.','TISAX','5.2.7-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.7-3','R-R3-0919','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0920','R3-2026-07','Berücksichtigen Sie bei der risikobasierten Segmentierung nicht Aspekte wie Anbindungsbeschränkungen, Sicherheitstechnologien und Vertrauensstellungen, entstehen unpassend geschnittene Netzbereiche. Sensible Systeme werden dann unzureichend abgeschottet, sodass ein Angreifer Vertrauensbeziehungen ausnutzen und über schlecht abgegrenzte Zonen tiefer in Ihr Netzwerk vordringen kann.','TISAX','5.2.7-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.7-4','R-R3-0920','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0921','R3-2026-07','Setzen Sie erweiterte Anforderungen an Netzverwaltung wie die Authentifizierung von Systemen und den eingeschränkten Zugriff auf Managementschnittstellen nicht um, sind Ihre Steuerungswege ungeschützt. Angreifer können sich unbefugt einbinden oder Managementzugänge übernehmen und darüber Ihr gesamtes Netzwerk kontrollieren, umkonfigurieren oder gezielt lahmlegen.','TISAX','5.2.7-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.7-5','R-R3-0921','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0922','R3-2026-07','Prüfen Sie Ihre Kontinuitätsplanung nicht regelmäßig einschließlich vollständiger Wiederherstellung und Einhaltung der Zeitvorgaben, verlassen Sie sich auf ungetestete Annahmen. Im Ernstfall zeigt sich dann, dass Backups unbrauchbar sind oder die Wiederherstellung viel länger dauert als geplant, sodass sich Ausfallzeiten und Schäden erheblich verlängern.','TISAX','5.2.8-10') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-10','R-R3-0922','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0923','R3-2026-07','Fehlt eine Sicherungs- und Wiederherstellungsstrategie, die Backups vor Manipulation, Löschung durch Schadsoftware und unbefugtem Zugriff schützt, können auch Ihre Datensicherungen kompromittiert werden. Ransomware verschlüsselt oder löscht dann die Backups gleich mit, sodass Ihnen im Ernstfall die letzte Rückfalloption fehlt und ein dauerhafter Datenverlust droht.','TISAX','5.2.8-11') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-11','R-R3-0923','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0924','R3-2026-07','Stimmen Sie Ihre Kontinuitätsplanung nicht mit den Plänen maßgeblicher organisationsfremder Dienstleister ab, entstehen im Krisenfall gefährliche Lücken. Sie gehen dann von Wiederherstellungszeiten aus, die Ihre Dienstleister gar nicht einhalten können, sodass Ihre eigene Notfallplanung ins Leere läuft und sich Ausfälle unerwartet verlängern.','TISAX','5.2.8-12') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-12','R-R3-0924','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0925','R3-2026-07','Wenn Ihr Kontinuitätsplan die Fortführung des zentralen Auftrags nicht mit geringstmöglichem Verlust sichert, drohen bei einer Störung unkontrollierte Ausfälle wesentlicher Geschäftsfunktionen. Sie verlieren dann die Handlungsfähigkeit, können vertragliche Zusagen nicht mehr erfüllen und riskieren erhebliche finanzielle Schäden sowie einen dauerhaften Reputationsverlust bei Kunden und Partnern.','TISAX','5.2.8-13') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-13','R-R3-0925','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0926','R3-2026-07','Wird Ihre Kontinuitätsplanung nicht regelmäßig geprüft und werden Prüfungen samt Erkenntnissen nicht dokumentiert, bleiben Lücken und veraltete Annahmen unentdeckt. Im Ernstfall stellen Sie fest, dass Ihre Pläne nicht funktionieren, verlieren wertvolle Zeit bei der Wiederherstellung und können gegenüber Auditoren keinen Nachweis über die Wirksamkeit Ihrer Vorsorge erbringen.','TISAX','5.2.8-14') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-14','R-R3-0926','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0927','R3-2026-07','Sind den maßgeblichen Beteiligten die Anforderungen und Verantwortlichkeiten für Kontinuität und Wiederherstellung nicht bekannt, entsteht im Krisenfall Chaos, weil niemand weiß, wer welche Aufgabe übernimmt. Sie riskieren, dass wichtige Wiederherstellungsschritte unterbleiben, sich Ausfallzeiten verlängern und der Schaden für Ihre IT-Dienste und Ihr Geschäft deutlich größer ausfällt als nötig.','TISAX','5.2.8-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-2','R-R3-0927','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0928','R3-2026-07','Wenn Sie kritische IT-Systeme nicht identifizieren, nach Schutzbedarf klassifizieren und angemessen absichern, schützen Sie möglicherweise unwichtige Systeme stark und geschäftskritische Systeme unzureichend. Dadurch bleiben gefährliche Schwachstellen an den entscheidenden Stellen bestehen, die Angreifer oder technische Störungen ausnutzen und so einen Ausfall Ihrer wichtigsten Prozesse verursachen können.','TISAX','5.2.8-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-3','R-R3-0928','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0929','R3-2026-07','Schließt Ihre Kontinuitätsplanung Szenarien wie DDoS-Angriffe, Ransomware, Sabotage, Systemausfall und Naturkatastrophen nicht ein, sind Sie auf genau die Ereignisse unvorbereitet, die Ihren Betrieb am schwersten treffen. Sie müssen dann improvisieren, verlieren im Ernstfall kostbare Zeit und riskieren, dass ein absehbares Szenario zu einem langanhaltenden und teuren Totalausfall führt.','TISAX','5.2.8-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-4','R-R3-0929','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0930','R3-2026-07','Berücksichtigt Ihre Kontinuitätsplanung keine alternativen Kommunikations-, Speicher- und Energieversorgungsstrategien, stehen Sie beim Ausfall der primären Mittel ohne Rückfallebene da. Sie können dann nicht mehr kommunizieren, verlieren den Zugriff auf Daten oder müssen den Betrieb einstellen, wodurch sich eine Störung schnell zu einem vollständigen Stillstand ausweitet.','TISAX','5.2.8-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-5','R-R3-0930','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0931','R3-2026-07','Wird Ihre Kontinuitätsplanung nicht regelmäßig überprüft und aktualisiert, veraltet sie mit jeder Änderung an Systemen, Prozessen oder Zuständigkeiten. Im Krisenfall greifen Sie dann auf Pläne zurück, die nicht mehr zur Realität passen, verlieren Vertrauen in Ihre Vorsorge und riskieren, dass die Wiederherstellung an falschen Kontaktdaten oder überholten Abläufen scheitert.','TISAX','5.2.8-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-6','R-R3-0931','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0932','R3-2026-07','Fehlen in Ihrer Kontinuitätsplanung vordefinierte Zeitrahmen für die Wiederaufnahme des Betriebs, bleibt unklar, wie schnell einzelne Dienste zurückkehren müssen. Sie priorisieren die Wiederherstellung dann ohne klare Vorgaben, überziehen tolerierbare Ausfallzeiten und können vertragliche oder gesetzliche Fristen verletzen, was zu Schäden bei Kunden und rechtlichen Konsequenzen führt.','TISAX','5.2.8-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-7','R-R3-0932','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0933','R3-2026-07','Haben Sie mit externen Dienstleistern keine angemessenen SLAs entsprechend Ihrer Kontinuitätsplanung vereinbart, können Sie sich im Ernstfall nicht auf verbindliche Reaktions- und Wiederherstellungszeiten verlassen. Ihre Wiederherstellung hängt dann vom Wohlwollen des Dienstleisters ab, verzögert sich unkalkulierbar und untergräbt Ihre eigenen Zeitziele, ohne dass Sie eine vertragliche Handhabe haben.','TISAX','5.2.8-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-8','R-R3-0933','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0934','R3-2026-07','Schließen Ihre Kontinuitätspläne die Abstimmung der vertraglich vereinbarten Kommunikation mit Geschäftspartnern nicht ein, bleiben diese im Krisenfall uninformiert und ungewiss über Ihren Status. Dadurch entstehen Missverständnisse, Partner treffen eigene Notmaßnahmen und Sie riskieren Vertragsverletzungen sowie einen nachhaltigen Vertrauensverlust in Ihrer Lieferkette.','TISAX','5.2.8-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.8-9','R-R3-0934','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0935','R3-2026-07','Liegen für die maßgeblichen IT-Dienste keine Wiederherstellungs-Konzepte vor, fehlt im Ernstfall die Anleitung, um Systeme geordnet wieder in Betrieb zu nehmen. Ihre Mitarbeiter müssen dann unter Druck improvisieren, machen Fehler und verlängern die Ausfallzeit, sodass aus einer beherrschbaren Störung ein langwieriger und kostspieliger Betriebsstillstand werden kann.','TISAX','5.2.9-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-2','R-R3-0935','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0936','R3-2026-07','Existiert für maßgebliche IT-Dienste kein Sicherungs- und Wiederherstellungs-Konzept, das Abhängigkeiten und die Reihenfolge berücksichtigt, stellen Sie Systeme womöglich in falscher Ordnung wieder her. Dadurch scheitern Wiederanläufe, weil vorausgesetzte Dienste fehlen, Sie verlieren wertvolle Zeit und riskieren Datenverluste sowie eine deutlich verlängerte Betriebsunterbrechung.','TISAX','5.2.9-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-3','R-R3-0936','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0937','R3-2026-07','Werden Ihre Sicherungs- und Wiederherstellungskonzepte nicht in regelmäßigen Abständen methodisch überprüft, verlassen Sie sich auf Vorsorge, deren Funktion Sie nie bestätigt haben. Im Ernstfall entdecken Sie dann, dass Backups unvollständig oder Konzepte veraltet sind, und stehen ohne verwertbare Wiederherstellungsmöglichkeit vor einem drohenden dauerhaften Datenverlust.','TISAX','5.2.9-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-4','R-R3-0937','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0938','R3-2026-07','Wird die allgemeine Wiederherstellungskapazität nicht berücksichtigt und geprüft, etwa durch Stichproben oder Prüfsysteme, wissen Sie nicht, ob Ihre Ressourcen für eine echte Wiederherstellung ausreichen. Sie riskieren dann, dass im Ernstfall Speicher, Rechenleistung oder Zeit fehlen und die Wiederherstellung mitten im Prozess scheitert, während der Betrieb weiter stillsteht.','TISAX','5.2.9-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-5','R-R3-0938','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0939','R3-2026-07','Berücksichtigen Ihre Sicherungs- und Wiederherstellungskonzepte den Recovery Point Objective, den Recovery Time Objective und die erforderlichen Ressourcen nicht, bleibt offen, wie viel Datenverlust und Ausfallzeit tolerierbar sind. Sie planen Ihre Backups dann ins Blaue, verlieren im Ernstfall mehr Daten als vertretbar und verfehlen die für Ihr Geschäft notwendigen Wiederherstellungszeiten.','TISAX','5.2.9-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-6','R-R3-0939','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0940','R3-2026-07','Führen Sie keine zusätzlichen Backups über Offline-Verfahren, unveränderliche Backups oder isolierte IAM-Technologie durch, kann ein Angreifer bei einem Ransomware-Vorfall auch Ihre Sicherungen verschlüsseln oder löschen. Sie verlieren dann Ihre letzte Rückfallebene, sind erpressbar und stehen im schlimmsten Fall vor einem unwiederbringlichen Totalverlust Ihrer Daten.','TISAX','5.2.9-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-7','R-R3-0940','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0941','R3-2026-07','Werden Ihre Wiederherstellungsverfahren nicht in regelmäßigen Abständen systematisch technisch geprüft, bleibt ungewiss, ob sie unter realen Bedingungen tatsächlich funktionieren. Im Ernstfall stellen Sie dann fest, dass Restores fehlschlagen oder länger dauern als erwartet, verlieren kritische Zeit und riskieren, dass sich ein vermeintlich abgesicherter Vorfall zur Katastrophe entwickelt.','TISAX','5.2.9-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-8','R-R3-0941','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0942','R3-2026-07','Berücksichtigen Sie in Ihren Backup- und Wiederherstellungskonzepten keine geografische Redundanz, kann ein lokales Ereignis wie Brand, Überschwemmung oder Stromausfall zugleich Ihre Primärsysteme und Ihre Backups vernichten. Sie verlieren dann sämtliche Daten an einem Standort auf einen Schlag und haben keine räumlich getrennte Kopie mehr, um Ihren Betrieb wiederaufzunehmen.','TISAX','5.2.9-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.2.9-9','R-R3-0942','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0943','R3-2026-07','Wenn Sie die Anforderungen an die Informationssicherheit bei Beschaffung oder Erweiterung von IT-Systemen nicht ermitteln und berücksichtigen, holen Sie sich unsichere Komponenten ins Haus. Diese bringen von Beginn an Schwachstellen mit, die sich später nur schwer und teuer beheben lassen, und öffnen Angreifern ein dauerhaftes Einfallstor in Ihre Infrastruktur.','TISAX','5.3.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-2','R-R3-0943','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0944','R3-2026-07','Berücksichtigen Sie die Anforderungen an die Informationssicherheit bei Änderungen an selbst entwickelten IT-Systemen nicht, schleichen sich mit jeder Anpassung neue Schwachstellen ein. Sie merken diese Fehler oft erst im Produktivbetrieb, wenn Angreifer sie bereits ausnutzen, und riskieren Datenabflüsse sowie Systemausfälle durch unsicher umgesetzte Änderungen.','TISAX','5.3.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-3','R-R3-0944','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0945','R3-2026-07','Führen Sie keine Systemabnahmetests unter Berücksichtigung der Informationssicherheit durch, gehen Systeme mit unerkannten Sicherheitsmängeln in Betrieb. Sie entdecken diese Lücken dann erst, wenn es zu einem Vorfall kommt, und tragen die Folgen von Datenverlust, Manipulation oder Ausfall, die ein Test vor der Inbetriebnahme leicht hätte aufdecken können.','TISAX','5.3.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-4','R-R3-0945','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0946','R3-2026-07','Erstellen Sie keine Lastenhefte mit Informationssicherheitsanforderungen, Herstellerempfehlungen zur sicheren Konfiguration und Ausfallsicherheit, beschaffen Sie Systeme ohne klar definierte Schutzvorgaben. Lieferanten liefern dann unsicher konfigurierte Lösungen, deren Mängel Sie erst nachträglich und teuer korrigieren müssen, während unnötige Angriffsflächen offen bleiben.','TISAX','5.3.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-5','R-R3-0946','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0947','R3-2026-07','Werden Ihre Lastenhefte nicht gegen die Anforderungen an die Informationssicherheit geprüft, können darin geforderte Schutzmaßnahmen fehlen oder widersprüchlich sein. Sie beschaffen dann auf Basis lückenhafter Vorgaben Systeme, die Ihre Sicherheitsziele verfehlen, und stellen die Mängel erst fest, wenn eine nachträgliche Korrektur mit hohem Aufwand verbunden ist.','TISAX','5.3.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-6','R-R3-0947','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0948','R3-2026-07','Führen Sie vor dem produktiven Einsatz keine Prüfung des IT-Systems auf Einhaltung der Vorgaben durch, gelangen fehlkonfigurierte oder unsichere Systeme unbemerkt in den Betrieb. Sie verlassen sich dann auf Annahmen statt auf einen Nachweis und riskieren, dass genau die Sicherheitslücken produktiv werden, die eine abschließende Prüfung zuverlässig aufgedeckt hätte.','TISAX','5.3.1-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-7','R-R3-0948','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0949','R3-2026-07','Vermeiden Sie die Nutzung produktiver Daten zu Testzwecken nicht und sichern diese bei Nutzung nicht wie im Produktivsystem ab, geraten sensible Echtdaten in weniger geschützte Testumgebungen. Dort sind sie leichter zugänglich und können abfließen oder missbraucht werden, wodurch Sie einen Datenschutzverstoß und den Verlust vertraulicher Informationen riskieren.','TISAX','5.3.1-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-8','R-R3-0949','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0950','R3-2026-07','Prüfen Sie die Sicherheit speziell entwickelter oder stark maßgeschneiderter Software nicht, etwa durch Penetrationstests bei Inbetriebnahme oder wesentlichen Änderungen, bleiben individuelle Schwachstellen unentdeckt. Angreifer finden diese maßgeschneiderten Lücken oft gezielt und nutzen sie aus, sodass Sie einen Einbruch erst bemerken, wenn bereits Daten kompromittiert oder Systeme manipuliert wurden.','TISAX','5.3.1-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.1-9','R-R3-0950','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0951','R3-2026-07','Haben Sie kein Verfahren zur Absicherung und Nutzung von Netzwerkdiensten definiert und umgesetzt, werden diese uneinheitlich und teils unsicher betrieben. Es entstehen offene Zugänge und Fehlkonfigurationen, die Angreifer für das Eindringen in Ihr Netzwerk ausnutzen können, und Sie verlieren den Überblick darüber, welche Dienste überhaupt wie abgesichert sind.','TISAX','5.3.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.2-2','R-R3-0951','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0952','R3-2026-07','Haben Sie die Anforderungen an die Netzwerkdienste nicht in Form von SLAs vereinbart, fehlen verbindliche Zusagen zu Verfügbarkeit und Leistung. Bei Störungen können Sie keine definierte Reaktion einfordern, Ausfälle ziehen sich unkalkulierbar in die Länge und Ihre darauf angewiesenen Geschäftsprozesse stehen ohne vertragliche Absicherung still.','TISAX','5.3.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.2-3','R-R3-0952','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0953','R3-2026-07','Haben Sie keine angemessenen Redundanzlösungen für Ihre Netzwerkdienste umgesetzt, führt der Ausfall einer einzelnen Komponente sofort zum Verlust der Netzwerkverbindung. Ihre abhängigen Systeme und Kommunikationswege fallen dann komplett aus, der Betrieb kommt zum Erliegen und Sie haben keine Ausweichmöglichkeit, um die Verfügbarkeit aufrechtzuerhalten.','TISAX','5.3.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.2-4','R-R3-0953','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0954','R3-2026-07','Haben Sie keine Verfahren zur Überwachung der Netzwerkqualität wie Verkehrsflussanalysen oder Verfügbarkeitsmessungen definiert und führen diese nicht durch, erkennen Sie Störungen und Engpässe erst, wenn sie bereits spürbar sind. Anomalien wie ein beginnender Angriff oder eine Überlastung bleiben unbemerkt, sodass Sie zu spät reagieren und vermeidbare Ausfälle in Kauf nehmen.','TISAX','5.3.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.2-5','R-R3-0954','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0955','R3-2026-07','Liegt keine Beschreibung des Terminierungsprozesses vor, die bei Änderungen angepasst und vertraglich geregelt ist, verläuft die Beendigung von Dienstleistungsbeziehungen unkontrolliert. Zugänge bleiben womöglich bestehen, Daten werden nicht sauber zurückgegeben oder gelöscht, und Sie riskieren, dass ehemalige Dienstleister weiterhin unberechtigt auf Ihre Informationen zugreifen können.','TISAX','5.3.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.3-2','R-R3-0955','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0956','R3-2026-07','Ist das Abgrenzungskonzept des Anbieters nicht dokumentiert, wird bei Änderungen nicht angepasst und berücksichtigt es die Separierung von Daten, Funktionen, Software, Betriebssystem und Speicher nicht, vermischen sich Ihre Daten mit denen anderer Mandanten. Dadurch können Fremde Ihre Informationen einsehen oder verändern, und Sie verlieren die Kontrolle über die Vertraulichkeit Ihrer in geteilten Umgebungen verarbeiteten Daten.','TISAX','5.3.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','5.3.4-2','R-R3-0956','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0957','R3-2026-07','Stellen Sie mit Auftragnehmern und Kooperationspartnern nicht durch vertragliche Vereinbarungen ein angemessenes Informationssicherheitsniveau sicher, geben Sie Ihre Daten ohne verbindliche Schutzpflichten aus der Hand. Der Partner behandelt Ihre Informationen dann möglicherweise nachlässig, und Sie haften am Ende für Sicherheitsvorfälle, gegen die Sie sich vertraglich nicht abgesichert haben.','TISAX','6.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.1-2','R-R3-0957','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0958','R3-2026-07','Werden vertragliche Vereinbarungen mit Ihren Auftraggebern nicht an Ihre eigenen Auftragnehmer und Kooperationspartner weitergegeben, entsteht in Ihrer Lieferkette eine Schutzlücke. Vorgaben, zu deren Einhaltung Sie verpflichtet sind, greifen dann bei Ihren Subdienstleistern nicht, und Sie geraten in einen Vertragsbruch gegenüber Ihrem Auftraggeber, wenn dort ein Sicherheitsvorfall auftritt.','TISAX','6.1.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.1-3','R-R3-0958','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0959','R3-2026-07','Überprüfen Sie nicht regelmäßig, ob Auftragnehmer und Kooperationspartner die getroffenen vertraglichen Vereinbarungen tatsächlich einhalten, verlassen Sie sich allein auf Zusagen auf dem Papier. Verstöße bleiben dann unentdeckt, das vereinbarte Schutzniveau erodiert unbemerkt und Sie erfahren von Sicherheitsmängeln erst, wenn bei einem Partner bereits Ihre Daten kompromittiert wurden.','TISAX','6.1.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.1-4','R-R3-0959','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0960','R3-2026-07','Verpflichten Sie Ihre Auftragnehmer und Kooperationspartner nicht vertraglich, alle Anforderungen auch an deren Unterauftragnehmer weiterzugeben, verliert sich Ihr Schutzniveau in der Tiefe der Lieferkette. Ihre Daten landen dann bei Vierten, die keinerlei Sicherheitspflichten kennen, und Sie haben weder Überblick noch Handhabe, wenn dort ein Datenabfluss geschieht.','TISAX','6.1.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.1-5','R-R3-0960','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0961','R3-2026-07','Werden Serviceberichte und Dokumente von Auftragnehmern und Kooperationspartnern nicht systematisch auf Vollständigkeit und Erfüllung der Vorgaben überprüft, übersehen Sie Hinweise auf Mängel und offene Punkte. Sie gehen dann fälschlich von einer ordnungsgemäßen Leistungserbringung aus, während sich unbemerkt Sicherheitsdefizite aufbauen, die erst bei einem Vorfall zutage treten.','TISAX','6.1.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.1-6','R-R3-0961','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0962','R3-2026-07','Liegt Ihnen kein Nachweis wie Zertifikat, Bescheinigung oder interne Revision über ein dem Schutzbedarf angemessenes Sicherheitsniveau Ihres Lieferanten vor, vertrauen Sie ihm ohne belastbare Grundlage. Sie können weder gegenüber Auditoren noch im Schadensfall belegen, dass der Partner geeignet abgesichert war, und tragen das volle Risiko eines dort verursachten Sicherheitsvorfalls.','TISAX','6.1.1-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.1-7','R-R3-0962','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0963','R3-2026-07','Sind die Anforderungen und Verfahren zum Einsatz von Geheimhaltungsvereinbarungen nicht allen Personen bekannt, die schutzbedürftige Informationen an Dritte weitergeben, geschieht die Weitergabe unkontrolliert und ohne rechtliche Absicherung. Mitarbeiter teilen dann sensible Daten ohne gültige NDA, und Sie verlieren jeden Anspruch, den Empfänger zur Vertraulichkeit zu verpflichten.','TISAX','6.1.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-2','R-R3-0963','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0964','R3-2026-07','Stellen Sie nicht sicher, dass vor der Weitergabe sensibler Informationen jeweils eine gültige Geheimhaltungsvereinbarung abgeschlossen ist, geben Sie schutzbedürftige Daten ohne rechtlichen Schutz preis. Der Empfänger darf diese Informationen dann faktisch frei verwenden oder weitergeben, und Sie können bei Missbrauch keine Ansprüche geltend machen, wodurch vertrauliches Wissen unwiederbringlich verloren geht.','TISAX','6.1.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-3','R-R3-0964','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0965','R3-2026-07','Werden die Anforderungen und Verfahren für Geheimhaltungsvereinbarungen und den Umgang mit schutzbedürftigen Informationen nicht regelmäßig überprüft und aktualisiert, veralten Ihre Vorlagen und Abläufe. Sie arbeiten dann mit rechtlich überholten oder lückenhaften Vereinbarungen, die im Streitfall nicht durchsetzbar sind, und schützen Ihre sensiblen Informationen nur noch scheinbar.','TISAX','6.1.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-4','R-R3-0965','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0966','R3-2026-07','Halten Sie keine auf rechtliche Anwendbarkeit geprüften Vorlagen für Geheimhaltungsvereinbarungen vor, entstehen im Alltag uneinheitliche oder fehlerhafte NDAs. Solche Vereinbarungen erweisen sich im Streitfall häufig als unwirksam, sodass Sie Ihre vertraulichen Informationen trotz unterschriebener Dokumente nicht wirksam schützen und die Weitergabe an Dritte unnötig verzögert wird.','TISAX','6.1.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-5','R-R3-0966','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0967','R3-2026-07','Enthalten Ihre Geheimhaltungsvereinbarungen nicht die nötigen Angaben wie beteiligte Personen und Organisationen, Art der Informationen, Gegenstand, Gültigkeitsdauer und Verantwortlichkeiten, bleiben sie inhaltlich unbestimmt. Im Streitfall ist dann unklar, was überhaupt geschützt sein soll, und Sie können die Vereinbarung nicht durchsetzen, wodurch Ihre vertraulichen Informationen faktisch ungeschützt bleiben.','TISAX','6.1.2-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-6','R-R3-0967','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0968','R3-2026-07','Regeln Ihre Geheimhaltungsvereinbarungen den Umgang mit sensiblen Informationen nicht über das Ende des Vertragsverhältnisses hinaus, endet der Schutz Ihrer Daten mit dem Vertrag. Ehemalige Partner dürfen Ihre vertraulichen Informationen dann ohne Konsequenzen offenlegen oder verwerten, sodass langfristig wertvolles Wissen abfließt und Sie keine rechtliche Handhabe mehr haben.','TISAX','6.1.2-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-7','R-R3-0968','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0969','R3-2026-07','Ohne definierte Nachweismöglichkeiten wie Auditrechte oder eine Prüfung durch unabhängige Dritte können Sie nicht belegen, dass ein Vertragspartner die vereinbarten Sicherheitsvorgaben tatsächlich einhält. Verstöße bleiben unentdeckt, schützenswerte Informationen sind gefährdet, und im Schadensfall fehlt Ihnen jede Handhabe, Verbindlichkeit oder rechtliche Durchsetzbarkeit gegenüber der Gegenseite.','TISAX','6.1.2-8') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-8','R-R3-0969','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0970','R3-2026-07','Wenn Sie die Laufzeit befristeter Geheimhaltungsvereinbarungen nicht überwachen und Verlängerungen nicht rechtzeitig anstoßen, laufen Vereinbarungen unbemerkt aus. Vertrauliche Informationen sind dann rechtlich ungeschützt, Partner könnten diese ohne Konsequenzen weitergeben, und Ihnen fehlt im Streitfall die vertragliche Grundlage, um Ihre Interessen durchzusetzen.','TISAX','6.1.2-9') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','6.1.2-9','R-R3-0970','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0971','R3-2026-07','Ohne definierte, umgesetzte und kommunizierte Richtlinien zur Einhaltung gesetzlicher, regulatorischer und vertraglicher Vorgaben handeln Ihre Mitarbeiter unwissentlich rechtswidrig. Sie riskieren Bußgelder, Vertragsstrafen und Haftungsansprüche, und im Ernstfall können Sie gegenüber Aufsichtsbehörden nicht nachweisen, dass Sie Ihren Sorgfaltspflichten überhaupt nachgekommen sind.','TISAX','7.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','7.1.1-2','R-R3-0971','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0972','R3-2026-07','Wird die Integrität von Aufzeichnungen nicht entsprechend den gesetzlichen und vertraglichen Anforderungen sichergestellt, können Dokumente unbemerkt verändert, verfälscht oder gelöscht werden. Bei Prüfungen oder Rechtsstreitigkeiten fehlt Ihnen dann eine verlässliche Beweisgrundlage, was zu Bußgeldern, Nachweispflichtverletzungen und erheblichen rechtlichen Nachteilen führen kann.','TISAX','7.1.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','7.1.1-3','R-R3-0972','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0973','R3-2026-07','Sind Vorschriften zum Schutz personenbezogener Daten nicht definiert und den beauftragten Personen nicht bekannt, verarbeiten Ihre Mitarbeiter Daten unwissentlich unrechtmäßig. Das führt zu Datenschutzverstößen, empfindlichen Bußgeldern nach DSGVO und einem erheblichen Vertrauens- und Reputationsverlust bei betroffenen Personen und Geschäftspartnern.','TISAX','7.1.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','7.1.2-2','R-R3-0973','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0974','R3-2026-07','Wenn Prozesse und Verfahren zum Schutz personenbezogener Daten nicht im Informationssicherheitsmanagement verankert sind, bleibt Datenschutz zufällig und lückenhaft. Sie riskieren, dass Daten unbefugt verarbeitet oder offengelegt werden, was Bußgelder, Meldepflichten gegenüber Aufsichtsbehörden und dauerhafte Reputationsschäden nach sich zieht.','TISAX','7.1.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','7.1.2-3','R-R3-0974','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0975','R3-2026-07','Fehlt eine wirksame Perimetersicherung Ihres Geländes, können Unbefugte ungehindert eindringen und Zugang zu schützenswerten Bereichen, Anlagen und Informationen erlangen. Das erhöht das Risiko von Diebstahl, Sabotage und Spionage erheblich und untergräbt die gesamte darauf aufbauende Sicherheitsarchitektur Ihres Standorts.','TISAX','8.1.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.1-2','R-R3-0975','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0976','R3-2026-07','Ohne geeignete künstliche, technische oder natürliche Barrieren fehlt Ihrem Gelände die erste physische Hürde gegen unbefugtes Eindringen. Angreifer überwinden die Grenze mühelos und unbemerkt, was Diebstahl, Sabotage und den unberechtigten Zugriff auf schützenswerte Bereiche und Informationen deutlich wahrscheinlicher macht.','TISAX','8.1.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.2-2','R-R3-0976','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0977','R3-2026-07','Sind schutzbedürftige Bereiche nicht in massiver Bauweise ausgeführt, lassen sich Wände und Decken vergleichsweise leicht durchbrechen. Angreifer können so unter Umgehung der regulären Zugänge in sensible Räume gelangen, wodurch Diebstahl, Sabotage und der unbefugte Zugriff auf vertrauliche Werte erheblich erleichtert werden.','TISAX','8.1.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.3-2','R-R3-0977','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0978','R3-2026-07','Wenn Fenster und Türen in der Außenhaut nicht mindestens der Einbruchhemmung RC2 entsprechen, bieten sie Angreifern einfach zu überwindende Schwachstellen. Unbefugte können mit einfachem Werkzeug in schützenswerte Bereiche eindringen, was Diebstahl, Sabotage und die Kompromittierung vertraulicher Informationen wahrscheinlich macht.','TISAX','8.1.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.3-3','R-R3-0978','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0979','R3-2026-07','Ist der Schutz vor Einblick durch Glasflächen in schutzbedürftige Bereiche nicht sichergestellt, können Außenstehende vertrauliche Vorgänge, Prototypen oder Dokumente ausspähen. Bereits das bloße Beobachten ermöglicht Industriespionage und den Abfluss schützenswerter Informationen, ohne dass ein physisches Eindringen überhaupt erforderlich wäre.','TISAX','8.1.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.4-2','R-R3-0979','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0980','R3-2026-07','Wird die Einsicht in Sicherheitsbereiche durch offene Türen, Tore oder Fenster nicht wirksam verhindert, können Unbefugte sensible Inhalte im Vorübergehen erfassen oder fotografieren. So gelangen vertrauliche Informationen und Prototypendaten unbemerkt nach außen, was zu Wettbewerbsnachteilen und der Verletzung von Geheimhaltungspflichten führt.','TISAX','8.1.4-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.4-3','R-R3-0980','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0981','R3-2026-07','Ist die räumliche Situation nicht geeignet, schutzbedürftige Fahrzeuge vor unberechtigtem Einblick zu schützen, können Dritte getarnte Prototypen ausspähen und dokumentieren. Bilder gelangen an Wettbewerber oder in die Öffentlichkeit, wodurch Sie erhebliche Wettbewerbsnachteile, Vertragsstrafen und den Verlust des Kundenvertrauens riskieren.','TISAX','8.1.4-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.4-4','R-R3-0981','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0982','R3-2026-07','Kann die räumliche Situation schutzbedürftige Fahrzeuge nicht vor unberechtigtem Zugriff schützen, könnten Unbefugte Prototypen berühren, manipulieren oder Bauteile entwenden. Das gefährdet die Geheimhaltung, führt zu Vertragsstrafen gegenüber dem Auftraggeber und kann Ihre Zulassung als vertrauenswürdiger Prototypenschutzpartner kosten.','TISAX','8.1.5-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.5-2','R-R3-0982','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0983','R3-2026-07','Fehlen Alarmierungspläne, die im Ereignisfall Vorgehen und zu benachrichtigende Stellen festlegen, reagieren Ihre Mitarbeiter im Ernstfall unkoordiniert oder zu spät. Wertvolle Zeit geht verloren, Schäden weiten sich aus, und ein Sicherheitsvorfall kann eskalieren, bevor die richtigen Stellen überhaupt informiert sind.','TISAX','8.1.6-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.6-2','R-R3-0983','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0984','R3-2026-07','Ist keine zeitnahe Alarmverfolgung sichergestellt, bleiben ausgelöste Alarme unbewertet und unbearbeitet liegen. Ein tatsächlicher Einbruch oder Angriff wird dadurch zu spät oder gar nicht erkannt, sodass Angreifer ungestört handeln können und sich Schäden an Werten und Informationen erheblich vergrößern.','TISAX','8.1.6-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.6-3','R-R3-0984','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0985','R3-2026-07','Werden Personen vor dem Zutritt zum Sicherheitsbereich nicht nachweislich zur Geheimhaltung verpflichtet, fehlt Ihnen die rechtliche Grundlage, um sie bei Weitergabe vertraulicher Informationen zur Verantwortung zu ziehen. Informationen können unbemerkt abfließen, und im Streitfall stehen Sie ohne durchsetzbare Handhabe da.','TISAX','8.1.7-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.7-2','R-R3-0985','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0986','R3-2026-07','Werden geltende Sicherheits- und Besucherregelungen nicht veröffentlicht und den Betroffenen zugänglich gemacht, kennen Mitarbeiter und Besucher die geforderten Verhaltensregeln nicht. Verstöße geschehen unwissentlich, Sicherheitsmaßnahmen laufen ins Leere, und im Ereignisfall können Sie sich nicht auf verbindlich kommunizierte Vorgaben berufen.','TISAX','8.1.7-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.7-3','R-R3-0986','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0987','R3-2026-07','Werden bei Zutrittsregelungen die länderspezifischen Datenschutzbestimmungen nicht eingehalten, verarbeiten Sie Zutritts- und Personendaten unrechtmäßig. Das führt zu Datenschutzverstößen, Bußgeldern und Beschwerden Betroffener, und Ihre eigentlich sinnvolle Sicherheitsmaßnahme wird selbst zur rechtlichen Angriffsfläche gegenüber Aufsichtsbehörden.','TISAX','8.1.7-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.7-4','R-R3-0987','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0988','R3-2026-07','Ist die räumliche Situation nicht geeignet, bei schutzbedürftigen Fahrzeugen eine Mandantentrennung durchzuführen, könnten Vertreter eines Auftraggebers Prototypen eines Wettbewerbers einsehen. Dieser Vertraulichkeitsbruch führt zu Vertragsstrafen, dem Verlust von Kundenaufträgen und einem schwerwiegenden Schaden für Ihre Reputation als neutraler Dienstleister.','TISAX','8.1.8-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.1.8-2','R-R3-0988','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0989','R3-2026-07','Besteht zwischen Auftragnehmer und Auftraggeber keine vertragsrechtlich gültige Geheimhaltungsvereinbarung auf Firmenebene, fehlt die rechtliche Grundlage für den Schutz ausgetauschter vertraulicher Informationen. Bei einer Weitergabe haben Sie keine durchsetzbaren Ansprüche, und schützenswerte Projektdaten können ohne Konsequenzen offengelegt werden.','TISAX','8.2.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.1-2','R-R3-0989','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0990','R3-2026-07','Sind nicht alle Mitarbeiter und Projektbeteiligten persönlich zur Geheimhaltung verpflichtet, fehlt Ihnen gegenüber dem Einzelnen die rechtliche Handhabe bei Verstößen. Vertrauliche Informationen können unbemerkt weitergegeben werden, ohne dass Sie den Verursacher belangen können, was Geheimhaltungspflichten gegenüber Ihren Auftraggebern gefährdet.','TISAX','8.2.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.1-3','R-R3-0990','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0991','R3-2026-07','Werden bei Geheimhaltungsvereinbarungen die länderspezifischen Datenschutzbestimmungen nicht eingehalten, können einzelne Klauseln oder die gesamte Vereinbarung unwirksam sein. Sie verlieren dadurch den rechtlichen Schutz für vertrauliche Informationen und riskieren gleichzeitig Bußgelder und Beanstandungen wegen datenschutzwidriger Verarbeitung personenbezogener Daten.','TISAX','8.2.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.1-4','R-R3-0991','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0992','R3-2026-07','Liegt keine vertragsrechtlich gültige Geheimhaltungsvereinbarung vor, die das Verhältnis zu beauftragten Unterauftragnehmern absichert, sind die an diese weitergegebenen vertraulichen Informationen rechtlich ungeschützt. Ein Datenabfluss über die Lieferkette bleibt folgenlos, und Sie haften gegenüber Ihrem Auftraggeber für Verstöße, die Sie nicht durchsetzen können.','TISAX','8.2.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.2-2','R-R3-0992','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0993','R3-2026-07','Besteht zwischen Auftragnehmer und Unterauftragnehmer keine gültige Geheimhaltungsvereinbarung auf Firmenebene, geben Sie schützenswerte Informationen ohne vertragliche Absicherung in die Lieferkette weiter. Bei einer unbefugten Offenlegung fehlt Ihnen jede Handhabe, und die Verantwortung für den Schaden fällt auf Sie zurück.','TISAX','8.2.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.2-3','R-R3-0993','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0994','R3-2026-07','Sind nicht alle Mitarbeiter und Projektbeteiligten des Unterauftragnehmers persönlich zur Geheimhaltung verpflichtet, können vertrauliche Informationen dort unbemerkt und folgenlos abfließen. Sie verlieren die Kontrolle über die Vertraulichkeit in der Lieferkette und haften gegenüber Ihrem Auftraggeber für Verstöße, die Sie nicht ahnden können.','TISAX','8.2.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.2-4','R-R3-0994','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0995','R3-2026-07','Ist die Einhaltung der Sicherheitsvorgaben des eigentlichen Kunden beim Unterauftragnehmer nicht sichergestellt und nicht nachgewiesen, entstehen unkontrollierte Sicherheitslücken in Ihrer Lieferkette. Vertrauliche Kundeninformationen sind dort ungeschützt, und Verstöße fallen auf Sie zurück, mit Vertragsstrafen und dem Verlust des Kundenvertrauens.','TISAX','8.2.2-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.2-5','R-R3-0995','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0996','R3-2026-07','Liegt kein Nachweis vor, dass der Unterauftragnehmer die Mindestanforderungen zum Prototypenschutz einhält, arbeiten Sie mit einem unbekannten Sicherheitsniveau in der Lieferkette. Prototypen und geheime Entwicklungsdaten sind dort möglicherweise ungeschützt, was zu Geheimnisverrat, Vertragsstrafen und dem Verlust Ihrer eigenen TISAX-Konformität führen kann.','TISAX','8.2.2-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.2-6','R-R3-0996','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0997','R3-2026-07','Werden Mitarbeiter und Projektbeteiligte bei Projekteinstieg nicht im richtigen Umgang mit Prototypen geschult, kennen sie die geltenden Schutz- und Tarnvorgaben nicht. Sie riskieren unbeabsichtigte Enthüllungen, etwa durch Fotos oder unbedeckte Prototypen, was zu Geheimnisverrat, Vertragsstrafen und schwerem Reputationsschaden gegenüber dem Auftraggeber führt.','TISAX','8.2.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.3-2','R-R3-0997','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0998','R3-2026-07','Werden Mitarbeiter nicht mindestens jährlich zum Umgang mit Prototypen geschult, veralten ihr Wissen und ihr Risikobewusstsein. Neue Vorgaben und Bedrohungen bleiben unbekannt, alte Fehler schleichen sich wieder ein, und die Wahrscheinlichkeit unbeabsichtigter Geheimnisverletzungen mit entsprechenden Vertragsstrafen steigt spürbar an.','TISAX','8.2.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.3-3','R-R3-0998','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-0999','R3-2026-07','Ist nicht sichergestellt, dass Mitarbeiter und Projektbeteiligte den jeweiligen Schutzbedarf und die daraus folgenden Maßnahmen kennen, behandeln sie schützenswerte Informationen unangemessen. Hochsensible Daten werden möglicherweise wie gewöhnliche behandelt, was zu vermeidbaren Sicherheitslücken, Geheimnisverlust und Verstößen gegen Auftraggebervorgaben führt.','TISAX','8.2.3-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.3-4','R-R3-0999','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1000','R3-2026-07','Ist die Teilnahme an Schulungen und Sensibilisierungsmaßnahmen nicht verpflichtend geregelt und wird sie nicht tatsächlich eingefordert, bleiben Teile der Belegschaft ungeschult. Diese Wissenslücken führen zu Fehlverhalten im Umgang mit schützenswerten Informationen und untergraben die Wirksamkeit Ihres gesamten Sicherheits- und Prototypenschutzkonzepts.','TISAX','8.2.3-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.3-5','R-R3-1000','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1001','R3-2026-07','Werden durchgeführte Schulungen nicht nachvollziehbar dokumentiert, können Sie nicht belegen, wer wann sensibilisiert wurde. Bei Audits oder Sicherheitsvorfällen fehlt Ihnen der Nachweis erfüllter Schulungspflichten, was zu Beanstandungen, dem Verlust der TISAX-Konformität und rechtlichen Nachteilen gegenüber Auftraggebern führen kann.','TISAX','8.2.3-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.3-6','R-R3-1001','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1002','R3-2026-07','Ist das Schulungskonzept für den Prototypenschutz nicht fest in das allgemeine Informationssicherheits-Schulungskonzept eingebunden, sondern nur separat vorhanden, drohen Lücken, Doppelungen und Inkonsistenzen. Themen werden übersehen oder widersprüchlich vermittelt, wodurch das Sicherheitsbewusstsein der Mitarbeiter unvollständig bleibt und Schutzmaßnahmen an Wirksamkeit verlieren.','TISAX','8.2.3-7') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.3-7','R-R3-1002','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1003','R3-2026-07','Werden bei der Projektplanung Stufenpläne, Geheimhaltungs- und Tarnmaßnahmen sowie geltende Entwicklungsrichtlinien nicht systematisch berücksichtigt, entstehen Schutzlücken bereits in der Planungsphase. Diese lassen sich später nur mühsam oder gar nicht schließen, sodass Prototypen früh gefährdet sind und Geheimhaltungsvorgaben des Auftraggebers verletzt werden.','TISAX','8.2.4-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.4-2','R-R3-1003','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1004','R3-2026-07','Werden Prototypenschutz-Anforderungen nicht ausdrücklich als Informationssicherheitsanforderungen des Projektes aufgenommen, gehen sie im Projektverlauf leicht unter. Schutzmaßnahmen werden nicht eingeplant, budgetiert oder umgesetzt, wodurch schützenswerte Entwicklungen ungeschützt bleiben und Sie Vertragsstrafen sowie den Verlust des Auftraggebervertrauens riskieren.','TISAX','8.2.4-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.4-3','R-R3-1004','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1005','R3-2026-07','Fehlt ein geregelter Prozess für das Vergeben, Ändern und Löschen von Zutrittsberechtigungen zu geschützten Bereichen, sammeln sich unberechtigte oder veraltete Zugänge an. Ausgeschiedene Mitarbeiter oder Fremde behalten möglicherweise Zutritt, wodurch schützenswerte Bereiche unbemerkt kompromittiert und Diebstahl oder Sabotage begünstigt werden.','TISAX','8.2.5-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.5-2','R-R3-1005','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1006','R3-2026-07','Sind keine verbindlichen Verhaltensregeln bei Verlust oder Diebstahl von Schlüsseln oder Zutrittskarten festgelegt, bleiben Vorfälle unbehandelt und Schließmittel im Umlauf. Unbefugte können damit Zutritt zu geschützten Bereichen erlangen, was Diebstahl, Spionage und Sabotage ermöglicht und die gesamte Zutrittssicherung wirkungslos macht.','TISAX','8.2.5-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.5-3','R-R3-1006','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1007','R3-2026-07','Gibt es keine verbindliche Festlegung, wie Bildmaterial hinsichtlich seines Schutzbedarfs klassifiziert wird, behandeln Mitarbeiter hochsensible Aufnahmen wie gewöhnliche Bilder. Schützenswerte Aufnahmen von Prototypen werden dann unzureichend gesichert oder unbedacht weitergegeben, was zu Geheimnisverrat, Vertragsstrafen und erheblichen Wettbewerbsnachteilen führt.','TISAX','8.2.6-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.6-2','R-R3-1007','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1008','R3-2026-07','Wird schützenswertes Bildmaterial nicht sicher gelagert und gespeichert, können Unbefugte darauf zugreifen und sensible Aufnahmen von Prototypen entwenden oder kopieren. Solche Bilder gelangen an Wettbewerber oder in die Öffentlichkeit, wodurch Sie Geheimhaltungspflichten verletzen und mit Vertragsstrafen sowie Reputationsschäden rechnen müssen.','TISAX','8.2.6-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.6-3','R-R3-1008','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1009','R3-2026-07','Wird nicht mehr benötigtes Bildmaterial nicht sicher gelöscht oder entsorgt, lässt es sich später wiederherstellen und auswerten. Vermeintlich vernichtete Aufnahmen von Prototypen können so nachträglich in falsche Hände geraten, was zu Geheimnisverrat, Vertragsstrafen und dem Verlust Ihres Wettbewerbsvorsprungs führt.','TISAX','8.2.6-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.6-4','R-R3-1009','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1010','R3-2026-07','Erfolgt die Weitergabe und der Versand von Bildmaterial nicht abgesichert und nicht ausschließlich an empfangsberechtigte Personen, können sensible Aufnahmen an unbefugte Empfänger gelangen. Bereits ein falscher Verteiler oder ein ungeschützter Übertragungsweg genügt, damit vertrauliche Prototypenbilder abfließen und Geheimhaltungspflichten verletzt werden.','TISAX','8.2.6-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.6-5','R-R3-1010','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1011','R3-2026-07','Ist nicht verbindlich festgelegt, wie mobile Geräte etwa hinsichtlich Telefonieren und Fotografieren genutzt werden dürfen, können in Sicherheitsbereichen unbemerkt Aufnahmen entstehen. Fotos von Prototypen gelangen dann leicht nach außen, wodurch Sie Geheimhaltungspflichten verletzen und erhebliche Vertrags- und Reputationsschäden riskieren.','TISAX','8.2.7-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.2.7-2','R-R3-1011','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1012','R3-2026-07','Sind die vom Auftraggeber definierten Sicherheitsvorgaben nicht bekannt oder werden sie in der Zusammenarbeit nicht eingehalten, verletzen Sie vertragliche Pflichten möglicherweise unwissentlich. Das gefährdet schützenswerte Informationen, führt zu Vertragsstrafen und kann die Geschäftsbeziehung sowie Ihre Anerkennung als vertrauenswürdiger Partner dauerhaft beschädigen.','TISAX','8.3.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.3.1-2','R-R3-1012','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1013','R3-2026-07','Setzen Sie für den Transport auch nicht freigegebene Logistikunternehmen ein, entziehen sich schützenswerte Bauteile und Prototypen der Kontrolle des Auftraggebers. Ungeprüfte Dienstleister bieten weder vertragliche Sicherheitsgarantien noch nachvollziehbare Lieferketten, sodass Diebstahl, unbefugte Weitergabe und Geheimnisverrat drohen. In der Folge riskieren Sie Vertragsstrafen, den Verlust des Auftraggebers und erhebliche Reputationsschäden.','TISAX','8.3.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.3.1-3','R-R3-1013','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1014','R3-2026-07','Fehlt ein gelebter Prozess zur Meldung sicherheitsrelevanter Ereignisse an den Auftraggeber, bleiben Vorfälle wie Diebstahl oder Manipulation unbemerkt oder werden zu spät kommuniziert. Der Auftraggeber kann dann keine Gegenmaßnahmen einleiten, wodurch sich Schäden ausweiten. Sie verletzen vertragliche Pflichten und gefährden das Vertrauensverhältnis sowie die weitere Zusammenarbeit.','TISAX','8.3.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.3.1-4','R-R3-1014','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1015','R3-2026-07','Nehmen Sie Veränderungen an der Tarnung ohne dokumentierte Abstimmung mit dem Auftraggeber vor, können Schutzkonzepte unbeabsichtigt ausgehebelt und geheimhaltungsbedürftige Fahrzeuge oder Bauteile vorzeitig erkennbar werden. Wettbewerber und Öffentlichkeit erhalten so Einblicke in Entwicklungsprojekte. Dies führt zu Wissensverlust, Vertragsverletzungen und dem Entzug künftiger Aufträge.','TISAX','8.4.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.4.1-2','R-R3-1015','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1016','R3-2026-07','Ohne einen implementierten Prozess zur unverzüglichen Meldung von Tarnungsbeschädigungen bleiben freigelegte Konturen und Details unentdeckt und ungeschützt. So können Unbefugte geheime Merkmale fotografieren oder ausspähen, bevor Sie reagieren. Der Auftraggeber verliert die Kontrolle über seine Geheimhaltungsstrategie, und Sie haften für den entstehenden Wissensabfluss und Imageschaden.','TISAX','8.4.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.4.1-3','R-R3-1016','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1017','R3-2026-07','Kennen die Nutzer von Test- und Erprobungsgeländen die freigegebene Geländeliste, die Verhaltensregeln und die Schutzmaßnahmen nicht, drohen unbefugte Aufenthalte, gestörte Versuchsabläufe und ungewollte Beobachtung durch Dritte. Vertrauliche Erprobungsdaten und Prototypen werden dadurch offengelegt. Sie riskieren Vertragsverstöße, Schadensersatzforderungen und den Verlust der Zulassung für weitere Erprobungen.','TISAX','8.4.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.4.2-2','R-R3-1017','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1018','R3-2026-07','Sind die vom Auftraggeber definierten Schutzmaßnahmen nicht bekannt oder werden sie in der Praxis nicht eingehalten, entstehen Sicherheitslücken bei der Nutzung geheimhaltungsbedürftiger Objekte. Unbefugte können dann Zugriff erlangen oder vertrauliche Informationen abschöpfen. Die Folge sind Geheimnisverrat, Vertragsstrafen und ein nachhaltiger Verlust des Vertrauens Ihres Auftraggebers.','TISAX','8.4.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.4.3-2','R-R3-1018','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1019','R3-2026-07','Sind die Verhaltensregeln bei besonderen Vorfällen wie Panne, Unfall oder Diebstahl nicht bekannt oder werden sie missachtet, reagieren Ihre Mitarbeiter in kritischen Situationen unkoordiniert. Geheime Fahrzeuge oder Unterlagen können dabei unbeaufsichtigt bleiben und ausgespäht werden. Dies führt zu Informationsabfluss, erweiterten Schäden und der Verletzung Ihrer vertraglichen Schutzpflichten.','TISAX','8.4.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.4.3-3','R-R3-1019','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1020','R3-2026-07','Liegen keine erstellten und vom Auftraggeber freigegebenen Sicherheitskonzepte für organisatorische, technische und personelle Aspekte vor, bleiben Schutzmaßnahmen lückenhaft und unabgestimmt. Risiken werden weder systematisch erkannt noch verbindlich adressiert. In der Folge drohen Sicherheitsvorfälle, mangelnde Nachweisbarkeit gegenüber dem Auftraggeber und der Verlust von Aufträgen sowie Zertifizierungen.','TISAX','8.5.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.5.1-2','R-R3-1020','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1021','R3-2026-07','Fehlen verbindliche und bekannte Verhaltensregeln für den Umgang mit besonderen Vorfällen, handeln Beteiligte im Ernstfall uneinheitlich und unvorbereitet. Wichtige Sofortmaßnahmen unterbleiben, und Schäden können sich unkontrolliert ausweiten. Sie verlieren die Kontrolle über die Lage und riskieren Informationsabfluss, Haftungsansprüche und den Bruch vertraglicher Vereinbarungen.','TISAX','8.5.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.5.1-3','R-R3-1021','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1022','R3-2026-07','Fehlt ein Nachweis über die Freigabe der genutzten Örtlichkeiten durch den Auftraggeber, nutzen Sie möglicherweise Standorte ohne geprüftes Schutzniveau. Solche Örtlichkeiten bieten unzureichenden Schutz gegen Zutritt, Einsicht und Ausspähung. Dadurch gefährden Sie vertrauliche Informationen, verstoßen gegen vertragliche Vorgaben und setzen sich Haftungs- und Reputationsrisiken aus.','TISAX','8.5.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.5.2-2','R-R3-1022','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1023','R3-2026-07','Ohne erstellte und vom Auftraggeber freigegebene Sicherheitskonzepte für organisatorische, technische und personelle Aspekte bleiben die Schutzmaßnahmen an genutzten Örtlichkeiten unvollständig und unkoordiniert. Bedrohungen werden nicht systematisch abgedeckt, sodass Sicherheitslücken entstehen. Die Folge sind Vorfälle mit Informationsabfluss, fehlende Nachweise gegenüber dem Auftraggeber und der drohende Auftragsverlust.','TISAX','8.5.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.5.2-3','R-R3-1023','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1024','R3-2026-07','Sind verbindliche Verhaltensregeln für besondere Vorfälle nicht festgelegt oder den Beteiligten nicht bekannt, fehlt in kritischen Momenten die notwendige Handlungssicherheit. Ihre Mitarbeiter reagieren dann verzögert oder falsch, wodurch sich Schäden ausweiten und Beweise verloren gehen. Sie riskieren Geheimnisverrat, Vertragsverletzungen und erhebliche wirtschaftliche wie rechtliche Nachteile.','TISAX','8.5.2-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','8.5.2-4','R-R3-1024','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1025','R3-2026-07','Veröffentlichen Sie die Kontaktdaten des Datenschutzbeauftragten nicht, können Betroffene ihre Rechte nicht wahrnehmen und die Aufsichtsbehörde Sie nicht erreichen. Damit verstoßen Sie gegen die Veröffentlichungspflicht aus der DSGVO. Die Folge sind Beschwerden, aufsichtsbehördliche Beanstandungen, mögliche Bußgelder und ein Vertrauensverlust bei Kunden und Partnern.','TISAX','9.2.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.2.1-2','R-R3-1025','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1026','R3-2026-07','Ist der Datenschutzbeauftragte nicht klar in die Unternehmensstruktur eingegliedert und seine Stellung nicht eindeutig festgelegt, kann er seine Aufgaben nicht wirksam und unabhängig wahrnehmen. Weisungsbindungen und Interessenkonflikte behindern seine Kontrollfunktion. Dadurch bleiben Datenschutzverstöße unentdeckt, und Sie riskieren aufsichtsbehördliche Maßnahmen, Bußgelder und Haftungsrisiken.','TISAX','9.2.1-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.2.1-3','R-R3-1026','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1027','R3-2026-07','Werden die Kontrollpflichten aus Art. 39 Abs. 1 lit. b DSGVO nicht tatsächlich ausgeübt und dokumentiert, bleibt die Überwachung der Datenschutz-Einhaltung wirkungslos und nicht nachweisbar. Verstöße gegen gesetzliche und interne Vorgaben werden so nicht erkannt. Sie können Ihre Rechenschaftspflicht nicht belegen und riskieren Bußgelder sowie erhebliche Reputationsschäden.','TISAX','9.2.1-4') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.2.1-4','R-R3-1027','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1028','R3-2026-07','Wird der datenschutzrechtliche Status nicht dokumentiert und regelmäßig an die oberste Managementebene berichtet, fehlt der Leitung die Grundlage für fundierte Entscheidungen und die Steuerung von Risiken. Datenschutzdefizite bleiben unbeachtet und werden nicht behoben. Dadurch verletzen Sie Ihre Rechenschaftspflicht und setzen sich Bußgeldern, Haftung und Vertrauensverlust aus.','TISAX','9.2.1-5') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.2.1-5','R-R3-1028','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1029','R3-2026-07','Ist der Datenschutzbeauftragte nicht mit ausreichenden Kapazitäten, Qualifikation, Fortbildungen und Unterstützung ausgestattet, kann er seine gesetzlichen Aufgaben nicht sachgerecht erfüllen. Fehlendes Fachwissen und Zeitmangel führen zu übersehenen Risiken und falschen Einschätzungen. In der Folge drohen unentdeckte Datenschutzverstöße, aufsichtsbehördliche Beanstandungen und Bußgelder.','TISAX','9.2.1-6') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.2.1-6','R-R3-1029','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1030','R3-2026-07','Werden Datenschutzfolgenabschätzungen nicht durchgeführt oder sind Verantwortlichkeiten, Aufgaben und Unterstützung dabei nicht festgelegt, bleiben hohe Risiken für die Rechte Betroffener unerkannt. Riskante Verarbeitungen starten ohne angemessene Schutzmaßnahmen. Dadurch verstoßen Sie gegen die DSGVO und riskieren Datenschutzvorfälle, Bußgelder und Schadensersatzansprüche der Betroffenen.','TISAX','9.4.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.4.1-2','R-R3-1030','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1031','R3-2026-07','Überprüfen Sie die Einhaltung vertraglicher Vereinbarungen mit Unterauftragnehmern nicht und fehlen aktuelle Kontaktdaten sowie nachverfolgte Maßnahmen, verlieren Sie die Kontrolle über die Auftragsverarbeitung in der Kette. Verstöße der Unterauftragnehmer bleiben unbemerkt. Als Verantwortlicher haften Sie dennoch und riskieren Datenschutzvorfälle, Bußgelder und den Verlust der Nachweisfähigkeit.','TISAX','9.5.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.5.2-2','R-R3-1031','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1032','R3-2026-07','Liegen für Datenübermittlungen keine geeigneten Garantien nach Kapitel V DSGVO einschließlich EuGH-Rechtsprechung und, wo nötig, kein Transfer Impact Assessment vor, übermitteln Sie personenbezogene Daten möglicherweise unrechtmäßig in Drittländer. Betroffene sind dort keinem angemessenen Schutzniveau ausgesetzt. Die Folge sind Untersagungen durch die Aufsicht, hohe Bußgelder und Schadensersatzforderungen.','TISAX','9.5.3-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.5.3-2','R-R3-1032','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1033','R3-2026-07','Prüfen Sie bei Übermittlungen an Drittstaaten nicht, ob für jede einzelne Übermittlung die Zustimmung des Verantwortlichen einzuholen ist, handeln Sie möglicherweise ohne die erforderliche Weisungsgrundlage. Daten gelangen dann unbefugt ins Ausland. Sie verletzen Ihre Pflichten als Auftragsverarbeiter und riskieren Vertragsverstöße, aufsichtsbehördliche Maßnahmen und Bußgelder.','TISAX','9.5.3-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.5.3-3','R-R3-1033','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1034','R3-2026-07','Berücksichtigen Ihre Maßnahmen zum Sicherheitsvorfallmanagement keine Datenschutzvorfälle und fehlt auch ein eigener Notfallplan, bleiben Datenpannen unbehandelt und die gesetzlichen Meldefristen werden versäumt. Betroffene und Behörden erfahren zu spät von Verletzungen ihres Schutzes. Dadurch drohen Bußgelder, Schadensersatzansprüche und ein erheblicher Vertrauens- und Reputationsverlust.','TISAX','9.6.2-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.6.2-2','R-R3-1034','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1035','R3-2026-07','Sind keine Verfahren etabliert und dokumentiert, die eine unverzügliche Meldung an den Verantwortlichen, eine Prozessdokumentation und Mitarbeiterschulungen sicherstellen, reagieren Sie bei Datenschutzvorfällen verspätet und unkoordiniert. Meldefristen werden versäumt und Ursachen nicht aufgeklärt. Die Folge sind sich ausweitende Schäden, Bußgelder und der Verlust der Nachweisfähigkeit gegenüber Aufsicht und Auftraggeber.','TISAX','9.6.2-3') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.6.2-3','R-R3-1035','direkt') ON CONFLICT DO NOTHING;
INSERT INTO public.risks(risk_id,quelle,text_de,primary_control_framework,primary_control_id) VALUES ('R-R3-1036','R3-2026-07','Fehlen Verfahren, die dokumentierte und umsetzbare Weisungen etwa zum Berichtigen und Löschen sowie eine Trennung der Daten nach Auftraggeber und Auftrag sicherstellen, können Sie Betroffenenrechte nicht zuverlässig erfüllen und riskieren Datenvermischungen. Personenbezogene Daten werden unbefugt verknüpft oder nicht fristgerecht gelöscht. Dies führt zu DSGVO-Verstößen, Bußgeldern und Haftungsansprüchen.','TISAX','9.8.1-2') ON CONFLICT (risk_id) DO UPDATE SET text_de=EXCLUDED.text_de;
INSERT INTO public.control_risk(framework,control_id,risk_id,link_typ) VALUES ('TISAX','9.8.1-2','R-R3-1036','direkt') ON CONFLICT DO NOTHING;

-- ============================================================

-- ============================================================
-- RG-* Risikogruppen (Fuehrung/Unterstuetzung/Betrieb/Bewertung): erklaerender Fliesstext statt ID-Platzhalter. 2026-07-16
-- Idempotent (nur wenn Platzhalter). ============================================================
UPDATE public.risks SET text_de='Fehlt es an sichtbarer Führung für die Informationssicherheit, bleiben Verantwortlichkeiten, Ziele und Ressourcen unklar. Wenn die Leitung Sicherheit nicht aktiv vorlebt, priorisiert und einfordert, wird sie im Tagesgeschäft nachrangig behandelt: Zuständigkeiten überschneiden sich oder bleiben unbesetzt, notwendige Mittel werden nicht bereitgestellt und Sicherheitsregeln verlieren an Verbindlichkeit. In der Folge entstehen Lücken, die im Ernstfall zu Vorfällen, Haftungsfragen und dem Verlust von Vertrauen führen.' WHERE risk_id='RG-FUE' AND text_de=risk_id;
UPDATE public.risks SET text_de='Ohne ausreichende Unterstützung — geschultes Personal, klare Kompetenzen, gepflegte Dokumentation und passende Werkzeuge — können Sicherheitsvorgaben in der Praxis nicht zuverlässig umgesetzt werden. Wenn Mitarbeitende ihre Pflichten nicht kennen oder ihnen die Mittel fehlen, entstehen Fehler, Umgehungen und ungeschützte Abläufe. Das erhöht die Wahrscheinlichkeit von Sicherheitsvorfällen und erschwert es, deren Einhaltung gegenüber Prüfern und Aufsicht nachzuweisen.' WHERE risk_id='RG-UNT' AND text_de=risk_id;
UPDATE public.risks SET text_de='Werden Sicherheitsmaßnahmen im laufenden Betrieb nicht konsequent geplant, durchgeführt und gesteuert, klaffen Anspruch und Wirklichkeit auseinander. Wenn Prozesse für Änderungen, Zugriffe, Protokollierung oder Notfälle nur auf dem Papier bestehen, greifen sie im Ernstfall nicht. Die Folge sind ausnutzbare Schwachstellen, unbemerkte Angriffe und Betriebsunterbrechungen, die den Geschäftsbetrieb und die Erfüllung gesetzlicher Pflichten gefährden.' WHERE risk_id='RG-BTR' AND text_de=risk_id;
UPDATE public.risks SET text_de='Ohne regelmäßige Bewertung — Überwachung, interne Audits und Managementbewertung — bleibt unklar, ob die Sicherheitsmaßnahmen tatsächlich wirken. Wenn Kennzahlen, Prüfungen und Rückmeldungen fehlen, werden Mängel und neue Risiken zu spät oder gar nicht erkannt und Korrekturen unterbleiben. Dadurch verschlechtert sich das Sicherheitsniveau schleichend, und im Prüfungs- oder Schadensfall fehlt der Nachweis eines funktionierenden, kontinuierlich verbesserten Managementsystems.' WHERE risk_id='RG-BEW' AND text_de=risk_id;


-- ============================================================
-- Fable5-Risikoaudit: 71 mangelhafte Risikotexte (61 SOC2-Schablonen mit Englisch-Fragment + 10 einzelne) -> erklaerender deutscher Fliesstext. 2026-07-16
-- ============================================================
UPDATE public.risks SET text_de='Wenn die Verarbeitungskapazität nicht laufend überwacht und am tatsächlichen Bedarf ausgerichtet wird, bleiben Engpässe bei Rechenleistung, Speicher oder Bandbreite unbemerkt, bis Systeme unter Last spürbar langsamer werden oder ganz ausfallen. Gerade bei Lastspitzen, etwa zu Stoßzeiten oder nach neuen Diensten, reagiert die Organisation dann nur noch im Nachhinein und muss Ausfälle improvisiert beheben. Anwendungen brechen ab, Bürgerdienste stehen still und Vorgänge stauen sich. In der Folge leidet der Betrieb, es drohen Terminversäumnisse, Nacharbeit und ein erheblicher Vertrauensverlust bei Bürgern und Partnern.' WHERE risk_id='DR-SOC2-A1_1';
UPDATE public.risks SET text_de='Ohne verlässliche, regelmäßig geschützte Backups sowie grundlegenden Umgebungsschutz wie Notstromversorgung, Kühlung und Brandschutz genügt ein einziger Zwischenfall, um wichtige Daten und Systeme zu verlieren. Ein Stromausfall, ein Wasser- oder Brandschaden im Serverraum oder ein Ransomware-Angriff kann dann Fachverfahren tage- oder wochenlang lahmlegen, weil sich nichts sauber zurückspielen lässt. Fehlt der Schutz vor unbefugtem Zugriff auf die Sicherungen, greifen Angreifer die Kopien gleich mit an. Das führt zu unwiederbringlichem Datenverlust, Betriebsunterbrechung, hohen Wiederherstellungskosten und je nach betroffenen Daten auch zu meldepflichtigen Datenschutzverstößen.' WHERE risk_id='DR-SOC2-A1_2';
UPDATE public.risks SET text_de='Werden die Wiederanlauf- und Wiederherstellungsverfahren nicht regelmäßig getestet, weiß niemand wirklich, ob Backups im Ernstfall vollständig und rechtzeitig zurückzuspielen sind. Oft zeigt sich erst im Notfall, dass Sicherungen unbrauchbar, Anleitungen veraltet oder die Wiederherstellzeiten viel zu lang sind. Ein vermeintlich vorhandener Notfallplan versagt dann genau in dem Moment, in dem er gebraucht wird. Die Folge sind ungeplant lange Ausfallzeiten, dauerhafter Datenverlust und ein Betrieb, der wesentlich länger stillsteht als eingeplant.' WHERE risk_id='DR-SOC2-A1_3';
UPDATE public.risks SET text_de='Wenn vertrauliche Informationen nicht systematisch nach ihrem Schutzbedarf klassifiziert und gekennzeichnet werden, behandeln Mitarbeiter sensible und harmlose Daten unbewusst gleich. Besonders schützenswerte Unterlagen landen dann in offenen Ablagen, werden per unverschlüsselter Mail versendet oder zu großzügig freigegeben, weil ihr Schutzbedarf nicht erkennbar ist. Angreifer und neugierige Insider greifen genau solche ungeschützten Bestände ab. Das führt zu Datenschutzverletzungen, dem Verlust vertraulicher Informationen, Bußgeldern und einem nachhaltigen Vertrauensschaden.' WHERE risk_id='DR-SOC2-C1_1';
UPDATE public.risks SET text_de='Werden nicht mehr benötigte vertrauliche Informationen und Datenträger nicht sicher und unwiederbringlich vernichtet, bleiben sensible Daten auf Altgeräten, in Papierkörben oder auf ausgemusterten Festplatten erhalten. Ausrangierte Hardware, Ausdrucke oder verkaufte Rechner geben dann personenbezogene Daten an Dritte preis, die sich mit einfachen Mitteln wiederherstellen lassen. Was eigentlich gelöscht sein sollte, taucht so unkontrolliert wieder auf. Die Folge sind meldepflichtige Datenpannen, Bußgelder nach der Datenschutz-Grundverordnung und ein erheblicher Reputationsschaden.' WHERE risk_id='DR-SOC2-C1_2';
UPDATE public.risks SET text_de='Fehlt ein gelebtes Bekenntnis zu Integrität und ethischen Werten mit einem klaren, kommunizierten Verhaltenskodex, entsteht ein Klima, in dem Regelverstöße als normal gelten und niemand mit Konsequenzen rechnet. Wenn zudem die Leitung nicht mit gutem Beispiel vorangeht, orientieren sich Mitarbeiter an dieser Nachlässigkeit und umgehen Sicherheits- und Compliance-Vorgaben. Missbrauch, Datenweitergabe und Manipulationen bleiben so lange unentdeckt. Das begünstigt interne Betrugsfälle, Sicherheitsvorfälle und rechtliche Verstöße, die den Betrieb und den Ruf der Organisation schwer beschädigen.' WHERE risk_id='DR-SOC2-CC1_1';
UPDATE public.risks SET text_de='Ist kein hinreichend unabhängiges Aufsichtsorgan eingerichtet, das Gestaltung und Wirksamkeit des internen Kontrollsystems überwacht, kontrolliert sich die Geschäftsführung faktisch selbst. Fehlentscheidungen, verschleppte Risiken und unwirksame Kontrollen fallen dann niemandem auf, der eingreifen dürfte. Warnsignale werden intern kleingeredet statt unabhängig hinterfragt. Das führt dazu, dass gravierende Mängel erst bei einem Schadensfall oder einer externen Prüfung sichtbar werden, mit entsprechenden Haftungs-, Bußgeld- und Reputationsfolgen.' WHERE risk_id='DR-SOC2-CC1_2';
UPDATE public.risks SET text_de='Sind Organisationsstruktur, Berichtswege und Verantwortlichkeiten nicht klar dokumentiert und sauber abgegrenzt, weiß im entscheidenden Moment niemand, wer wofür zuständig ist und wer entscheiden darf. Sicherheitsaufgaben bleiben liegen, weil jeder sie beim anderen vermutet, oder mehrere greifen unkoordiniert ein. Gerade bei Vorfällen kostet diese Unklarheit wertvolle Zeit und führt zu Fehlentscheidungen. Die Folge sind ungeregelte Zuständigkeiten, verschleppte Reaktionen auf Bedrohungen und Kontrolllücken, die Angreifer und Fehler ungehindert wirken lassen.' WHERE risk_id='DR-SOC2-CC1_3';
UPDATE public.risks SET text_de='Wenn für sicherheitsrelevante Rollen keine Kompetenzanforderungen definiert sind und Schulungen weder bereitgestellt noch nachgehalten werden, übernehmen Aufgaben oft Personen ohne das nötige Fachwissen. Falsch konfigurierte Systeme, übersehene Warnungen und fehlerhaft umgesetzte Maßnahmen sind dann die Regel und nicht die Ausnahme. Neue Bedrohungen werden nicht erkannt, weil das aktuelle Wissen fehlt. Das führt zu vermeidbaren Sicherheitsvorfällen, instabilem Betrieb und einer Organisation, die auf Angriffe und Störungen schlecht vorbereitet ist.' WHERE risk_id='DR-SOC2-CC1_4';
UPDATE public.risks SET text_de='Werden Personen nicht an ihren Kontrollpflichten gemessen und gibt es keine Konsequenzen bei Verstößen, verkommen Sicherheitsvorgaben zu unverbindlichen Empfehlungen. Wenn klar ist, dass Nachlässigkeit folgenlos bleibt, werden Kontrollen aus Bequemlichkeit übergangen und Zuständigkeiten schleifen gelassen. Vorschriften stehen dann nur auf dem Papier. Die Folge sind unwirksame Kontrollen, wiederkehrende Verstöße und Sicherheitslücken, die niemand mehr ernsthaft schließt.' WHERE risk_id='DR-SOC2-CC1_5';
UPDATE public.risks SET text_de='Werden Informationswerte nicht inventarisiert, klassifiziert und mit Eigentümern belegt und ist der Informationsbedarf für die Steuerung der Kontrollen unklar, steuert die Organisation ihre Sicherheit im Blindflug. Man kann nur schützen, was man kennt, doch unbekannte oder herrenlose Systeme und Datenbestände fallen durch jedes Raster. Entscheidungen beruhen dann auf lückenhaften oder veralteten Angaben. Das führt zu übersehenen Risiken, ungeschützten Datenbeständen und Fehlsteuerungen, die erst bei einem Vorfall auffallen.' WHERE risk_id='DR-SOC2-CC2_1';
UPDATE public.risks SET text_de='Werden Sicherheitsziele, -pflichten und -richtlinien nicht intern kommuniziert und fehlt ein klarer Meldeweg für Sicherheits- und Datenschutzvorfälle, wissen Mitarbeiter nicht, was von ihnen erwartet wird und an wen sie sich im Ernstfall wenden. Verdächtige Vorgänge werden dann verschwiegen oder zu spät gemeldet, weil niemand den Kanal kennt. Bedrohungen können sich ungestört ausbreiten, bevor jemand reagiert. Die Folge sind unentdeckte Vorfälle, verzögerte Reaktion und ein deutlich größerer Schaden als bei früher Meldung.' WHERE risk_id='DR-SOC2-CC2_2';
UPDATE public.risks SET text_de='Sind keine Kanäle für die Kommunikation mit Kunden, Dienstleistern und Behörden definiert und werden Sicherheitsanforderungen nicht an externe Parteien weitergegeben, entstehen Lücken genau an den Schnittstellen nach außen. Dienstleister kennen dann die geforderten Schutzstandards nicht und halten sie folglich nicht ein, während gesetzliche Meldepflichten an Aufsichtsbehörden im Ernstfall verpasst werden. Wichtige Warnungen erreichen die richtigen Stellen zu spät oder gar nicht. Das führt zu Vertragsverstößen, unsicheren Lieferketten, Bußgeldern wegen versäumter Meldungen und einem Vertrauensverlust bei Partnern.' WHERE risk_id='DR-SOC2-CC2_3';
UPDATE public.risks SET text_de='Sind die Ziele für Informationssicherheit, Verfügbarkeit und Compliance nicht klar und verbindlich dokumentiert, fehlt der Maßstab, an dem sich Risiken überhaupt erst erkennen und bewerten lassen. Ohne dieses Fundament bleibt unklar, was geschützt werden muss und welches Risiko noch akzeptabel ist. Maßnahmen werden dann willkürlich und ohne roten Faden gewählt. Die Folge sind blinde Flecken in der Risikosteuerung, falsch gesetzte Prioritäten und Kontrollen, die an den eigentlichen Gefahren vorbeigehen.' WHERE risk_id='DR-SOC2-CC3_1';
UPDATE public.risks SET text_de='Werden Risiken über Systeme, Prozesse und Dienstleister nicht systematisch identifiziert und Schwachstellen nicht in ihrer Bedeutung bewertet, bleiben Gefahren so lange verborgen, bis sie sich als Schaden zeigen. Angreifer finden ungepatchte Systeme und übersehene Einfallstore oft schneller als die eigene Organisation. Ohne saubere Analyse fließen Schutzmaßnahmen in die falschen Stellen. Das führt zu ausnutzbaren Sicherheitslücken, unvorbereiteten Vorfällen und Schäden, die mit einer geordneten Risikoanalyse vermeidbar gewesen wären.' WHERE risk_id='DR-SOC2-CC3_2';
UPDATE public.risks SET text_de='Wird das Betrugspotenzial in der Risikoanalyse nicht berücksichtigt, bleiben interne wie externe Betrugsszenarien blinde Flecken. Manipulierte Zahlungsanweisungen, gefälschte Rechnungen oder Vorgänge, die eine einzelne Person unkontrolliert ausführt, werden dann weder erwartet noch durch gezielte Kontrollen abgesichert. Täter nutzen genau diese ungeprüften Wege aus. Die Folge sind finanzielle Verluste, unterschlagene Mittel und Betrugsfälle, die lange unentdeckt bleiben und Vertrauen wie Haushalt schwer belasten.' WHERE risk_id='DR-SOC2-CC3_3';
UPDATE public.risks SET text_de='Wird die interne und externe Bedrohungs- und Schwachstellenlage nicht laufend neu bewertet, veralten die Schutzmaßnahmen still und heimlich. Neue Angriffsmethoden, geänderte Prozesse, neue Dienstleister oder Technikwechsel schaffen fortlaufend Risiken, die ein einmal erstelltes Sicherheitskonzept nicht mehr abdeckt. Die Organisation verteidigt sich dann gegen die Gefahren von gestern. Das führt zu Schutzlücken gegenüber aktuellen Bedrohungen und zu Vorfällen, die eine zeitnahe Neubewertung verhindert hätte.' WHERE risk_id='DR-SOC2-CC3_4';
UPDATE public.risks SET text_de='Wird die Wirksamkeit des internen Kontrollsystems nicht durch regelmäßige interne Prüfungen und eine risikoorientierte Revision überprüft, verlässt sich die Organisation blind darauf, dass Kontrollen tun, was sie sollen. Ob sie tatsächlich vorhanden und wirksam sind, weiß dann niemand, und unwirksame oder umgangene Kontrollen bleiben über lange Zeit unbemerkt. Erst ein Schadensfall oder eine externe Prüfung deckt die Lücke auf. Die Folge sind unentdeckte Kontrollmängel, Sicherheitsvorfälle und Beanstandungen von Aufsicht oder Prüfern mit entsprechenden rechtlichen Folgen.' WHERE risk_id='DR-SOC2-CC4_1';
UPDATE public.risks SET text_de='Werden festgestellte Kontrollmängel nicht erfasst und zeitnah an Management und Aufsicht berichtet, versanden erkannte Schwächen, statt behoben zu werden. Wer die Probleme abstellen könnte, erfährt zu spät oder gar nichts davon, sodass dieselben Lücken über Monate offen bleiben. Angreifer und Fehler nutzen genau diese ungeschlossenen Schwachstellen aus. Das führt zu wiederkehrenden Vorfällen, sich anhäufenden Risiken und einem Kontrollsystem, das seine Mängel nicht mehr aus eigener Kraft korrigiert.' WHERE risk_id='DR-SOC2-CC4_2';
UPDATE public.risks SET text_de='Werden Kontrollen nicht risikoorientiert ausgewählt und dem tatsächlichen Risiko angemessen gestaltet, entsteht ein Ungleichgewicht zwischen Aufwand und Schutz. Für harmlose Vorgänge werden dann aufwendige Kontrollen aufgebaut, während echte Hochrisikobereiche kaum abgesichert bleiben. Die begrenzten Ressourcen fließen an den gefährlichsten Stellen vorbei. Die Folge sind ungeschützte kritische Prozesse, vermeidbare Sicherheitsvorfälle und ein Kontrollsystem, das viel kostet, aber die wesentlichen Risiken nicht senkt.' WHERE risk_id='DR-SOC2-CC5_1';
UPDATE public.risks SET text_de='Sind keine allgemeinen IT-Kontrollen für Zugriff, Betrieb und Änderungen etabliert, fehlt das technische Fundament, auf dem alle fachlichen Kontrollen aufbauen. Ohne geregelte Zugriffssteuerung, überwachten Betrieb und kontrollierte Änderungen können sich Fehler und unbefugte Eingriffe ungehindert durch die gesamte Systemlandschaft ziehen. Selbst gut gemeinte Einzelmaßnahmen laufen auf unsicherem Untergrund ins Leere. Das führt zu manipulierbaren Systemen, unbemerkten Fehlkonfigurationen und Sicherheitsvorfällen mit breiter Wirkung.' WHERE risk_id='DR-SOC2-CC5_2';
UPDATE public.risks SET text_de='Werden Kontrollen nicht durch verbindliche Richtlinien und dokumentierte Betriebsverfahren im Alltag verankert, bleiben gute Absichten in der Praxis wirkungslos. Ohne klare Handlungsanweisungen macht jeder es nach eigenem Ermessen, Wissen geht mit Personalwechseln verloren und Abläufe werden uneinheitlich und fehleranfällig. Kontrollen, die niemand konkret ausführt, existieren nur auf dem Papier. Die Folge sind inkonsistente Umsetzung, Kontrolllücken im Tagesgeschäft und Sicherheitsvorfälle durch schlicht nicht gelebte Vorgaben.' WHERE risk_id='DR-SOC2-CC5_3';
UPDATE public.risks SET text_de='Fehlt eine umgesetzte Richtlinie zur logischen Zugriffssteuerung nach dem Prinzip der minimalen Berechtigung und einem rollenbasierten Modell, sammeln Nutzer im Lauf der Zeit weit mehr Rechte an, als ihre Aufgaben erfordern. Ein einziges kompromittiertes Konto öffnet dann Angreifern den Zugang zu weit mehr Systemen und Daten als nötig. Auch Insider können unkontrolliert auf Fremdbereiche zugreifen. Das führt zu großflächigem Datenabfluss, Missbrauch von Berechtigungen und Sicherheitsvorfällen, deren Schaden durch Least Privilege deutlich kleiner ausgefallen wäre.' WHERE risk_id='DR-SOC2-CC6_1';
UPDATE public.risks SET text_de='Ist kein geregelter Registrierungs- und Genehmigungsprozess für neue Nutzer etabliert und werden Zugänge bei Austritt oder Rollenwechsel nicht zeitnah entzogen, sammeln sich verwaiste und überflüssige Konten an. Ehemalige Mitarbeiter oder Dienstleister behalten dann Zugriff auf interne Systeme, lange nachdem ihre Berechtigung entfallen ist. Genau solche vergessenen Konten sind ein beliebtes Einfallstor für Angriffe. Die Folge sind unbefugte Zugriffe, Datenabfluss über Altkonten und Sicherheitsvorfälle, die sich schwer einer verantwortlichen Person zuordnen lassen.' WHERE risk_id='DR-SOC2-CC6_2';
UPDATE public.risks SET text_de='Werden Zugriffsrechte nicht regelmäßig überprüft und rezertifiziert und fehlt eine wirksame Funktionstrennung, häufen einzelne Personen mit der Zeit zu viele und unangemessene Berechtigungen an. Ohne Aufgabentrennung kann dann eine einzige Person einen sicherheitskritischen Vorgang allein und unkontrolliert vollständig durchführen, etwa Zahlungen selbst anlegen und freigeben. Fehler und Manipulationen fallen niemandem auf. Das führt zu Betrug, unbemerktem Missbrauch und schleichend wachsenden Berechtigungen, die das gesamte Kontrollsystem aushöhlen.' WHERE risk_id='DR-SOC2-CC6_3';
UPDATE public.risks SET text_de='Ist der physische Zutritt zu Rechenzentrum, Backup-Lager und sensiblen Bereichen nicht beschränkt und protokolliert und der Umgang mit Geräten ungeregelt, kann sich unbefugtes Personal direkten Zugang zur Technik verschaffen. Wer physisch an Server, Netzwerktechnik oder Sicherungsmedien gelangt, umgeht viele digitale Schutzmaßnahmen mühelos und kann Geräte manipulieren, stehlen oder Daten direkt kopieren. Ohne Protokoll bleibt zudem unklar, wer wann vor Ort war. Die Folge sind Diebstahl, Sabotage, Datenverlust und Sicherheitsvorfälle, die sich kaum aufklären lassen.' WHERE risk_id='DR-SOC2-CC6_4';
UPDATE public.risks SET text_de='Werden Datenträger vor Entsorgung oder Wiederverwendung nicht sicher gelöscht oder physisch vernichtet, bleiben auf ausgemusterten oder weitergegebenen Geräten sensible Daten zurück. Alte Festplatten, USB-Sticks oder wiederverwendete Rechner geben dann personenbezogene und vertrauliche Informationen an Dritte preis, die sich mit frei verfügbaren Werkzeugen wiederherstellen lassen. Was als gelöscht galt, ist in Wahrheit weiterhin lesbar. Das führt zu Datenschutzverletzungen, unkontrolliertem Abfluss vertraulicher Daten, Bußgeldern und Reputationsschaden.' WHERE risk_id='DR-SOC2-CC6_5';
UPDATE public.risks SET text_de='Fehlen technische Schutzmaßnahmen wie Firewalls, Netzwerksegmentierung und Perimeterschutz und ist für Fernzugriffe aus dem Internet keine Mehr-Faktor-Authentifizierung vorgeschrieben, steht das interne Netz Angreifern von außen weit offen. Ein erbeutetes Passwort genügt dann für die Anmeldung, und ohne Segmentierung breitet sich ein Eindringling ungehindert von System zu System aus. Automatisierte Angriffe aus dem Internet finden schnell die ungeschützte Angriffsfläche. Die Folge sind Kontenübernahmen, weiträumige Netzwerkkompromittierungen, Ransomware-Befall und massiver Datenabfluss.' WHERE risk_id='DR-SOC2-CC6_6';
UPDATE public.risks SET text_de='Werden Datenübertragungen über Netzwerke nicht verschlüsselt und Datenexport sowie Wechselmedien nicht kontrolliert, lassen sich Informationen auf ihrem Weg abhören, manipulieren oder unbemerkt aus der Organisation heraustragen. Unverschlüsselte Verbindungen geben vertrauliche Inhalte an jeden preis, der den Datenverkehr mitliest, und ungeprüfte USB-Sticks oder Exporte werden zum bequemen Kanal für Datenabfluss. Sensible Daten verlassen so kontrolllos das Haus. Das führt zu abgehörten oder verfälschten Übertragungen, Datenschutzverletzungen, Datendiebstahl und entsprechenden Bußgeldern.' WHERE risk_id='DR-SOC2-CC6_7';
UPDATE public.risks SET text_de='Ist kein wirksamer Schutz gegen unbefugte oder schädliche Software vorhanden, also kein aktiver Malware-Schutz auf Endgeräten und Servern und keine Kontrolle installierter Software, kann sich Schadcode ungehindert einnisten und ausbreiten. Ein unbedachter Klick oder ein manipuliertes Programm reicht dann, um Systeme zu verschlüsseln, Daten abzugreifen oder als Sprungbrett für weitere Angriffe zu dienen. Ohne Kontrolle installiert jeder beliebige und unsichere Anwendungen. Die Folge sind Ransomware-Ausfälle, Datenverlust, kompromittierte Systeme und ein erheblicher Betriebs- und Wiederherstellungsaufwand.' WHERE risk_id='DR-SOC2-CC6_8';
UPDATE public.risks SET text_de='Fehlen regelmäßiges Schwachstellen-Scanning und eine fortlaufende Überwachung der Systemkonfigurationen, bleiben Sicherheitslücken und unzulässige Änderungen so lange verborgen, bis sie ausgenutzt werden. Neue Verwundbarkeiten und schleichende Fehlkonfigurationen entstehen fortlaufend, doch ohne aktive Erkennung merkt die Organisation davon nichts. Angreifer scannen dieselben Systeme oft gründlicher als der Betreiber selbst. Das führt zu offen stehenden, längst bekannten Einfallstoren, unbemerkten Konfigurationsfehlern und Vorfällen, die rechtzeitiges Erkennen verhindert hätte.' WHERE risk_id='DR-SOC2-CC7_1';
UPDATE public.risks SET text_de='Sind keine sicherheitsrelevante Protokollierung und keine Angriffs- oder Anomalieerkennung wie ein SIEM oder IDS im Einsatz und werden Auffälligkeiten nicht bewertet, laufen Angriffe unbemerkt im Hintergrund. Verdächtige Anmeldungen, ungewöhnliche Datenzugriffe oder die Ausbreitung von Schadsoftware fallen dann tage- oder wochenlang niemandem auf. Ohne Protokolle lässt sich ein Vorfall später auch nicht mehr rekonstruieren. Die Folge ist, dass Angreifer lange ungestört agieren, der Schaden ungebremst wächst und die Aufklärung nach dem Vorfall kaum möglich ist.' WHERE risk_id='DR-SOC2-CC7_2';
UPDATE public.risks SET text_de='Werden Sicherheitsereignisse nicht bewertet und im Zweifel als Vorfall eingestuft, gehen echte Angriffe im Rauschen alltäglicher Meldungen unter. Ohne diese Einordnung bleibt unklar, welches Ereignis harmlos ist und welches sofortiges Handeln erfordert, sodass ernste Vorfälle als Fehlalarm abgetan werden. Wertvolle Zeit für eine frühe Reaktion verstreicht ungenutzt. Das führt zu verschleppten Reaktionen, einem sich ausweitenden Schaden und Vorfällen, die erst erkannt werden, wenn der Betrieb bereits spürbar betroffen ist.' WHERE risk_id='DR-SOC2-CC7_3';
UPDATE public.risks SET text_de='Fehlt ein eingeübter Incident-Response-Plan mit klaren Rollen, Eskalationswegen und Kommunikationsregeln sowie definierten Eindämmungs- und Behebungsschritten, herrscht bei einem Sicherheitsvorfall Chaos statt geordneter Reaktion. Niemand weiß dann, wer entscheidet, wen man informiert und wie ein Angriff gestoppt wird, während sich der Schaden mit jeder Minute ausbreitet. Improvisierte Einzelmaßnahmen kosten wertvolle Zeit und verschlimmern die Lage oft noch. Die Folge sind unnötig lange Ausfälle, größerer Datenverlust und versäumte gesetzliche Meldefristen mit rechtlichen Konsequenzen.' WHERE risk_id='DR-SOC2-CC7_4';
UPDATE public.risks SET text_de='Sind keine Wiederanlauf- und Wiederherstellungsmaßnahmen für die Zeit nach einem Sicherheitsvorfall definiert und werden keine Lessons Learned umgesetzt, gerät die Rückkehr zum Normalbetrieb zum ungeplanten Kraftakt. Ohne klaren Ablauf werden Systeme unkoordiniert und womöglich noch kompromittiert wieder hochgefahren, was den Vorfall verlängert oder gleich den nächsten auslöst. Ohne Aufarbeitung wiederholen sich zudem dieselben Fehler. Das führt zu verlängerten Ausfallzeiten, wiederkehrenden Vorfällen und einem Betrieb, der aus Schäden nicht dazulernt.' WHERE risk_id='DR-SOC2-CC7_5';
UPDATE public.risks SET text_de='Werden wesentliche Änderungen an Infrastruktur, Software, Daten und Verfahren nicht über einen formalen Change-Prozess mit vorheriger Risikobewertung, Test, Genehmigung und Freigabe abgewickelt, gelangen ungeprüfte und unautorisierte Änderungen direkt in den Produktivbetrieb. Eine übereilte Anpassung kann dann unbemerkt Sicherheitslücken öffnen, Fachverfahren zum Absturz bringen oder Daten beschädigen. Da niemand die Auswirkungen vorab bewertet hat, trifft die Störung den laufenden Betrieb völlig unvorbereitet. Die Folge sind Ausfälle, neu eingeschleppte Schwachstellen, Datenverlust und Vorfälle, deren Ursache sich mangels Dokumentation kaum zurückverfolgen lässt.' WHERE risk_id='DR-SOC2-CC8_1';
UPDATE public.risks SET text_de='Wenn die Organisation keine Maßnahmen entwickelt, um Risiken aus Geschäftsunterbrechungen zu mindern, trifft sie eine Störung wie ein Brand, ein Stromausfall oder ein Cyberangriff völlig unvorbereitet. Kritische Prozesse fallen dann tage- oder wochenlang aus, weil niemand weiß, wie der Betrieb notdürftig weiterlaufen oder wiederhergestellt werden soll. Restrisiken, die man hätte versichern oder anderweitig absichern können, schlagen unvermittelt als voller finanzieller Verlust durch. Am Ende drohen Umsatzeinbrüche, Vertragsstrafen und ein nachhaltiger Vertrauensverlust bei Bürgern und Partnern.' WHERE risk_id='DR-SOC2-CC9_1';
UPDATE public.risks SET text_de='Werden Risiken aus der Zusammenarbeit mit Lieferanten und Dienstleistern nicht bewertet und gesteuert, holt man sich Schwachstellen unbemerkt über die Hintertür ins Haus. Ein schlecht abgesicherter Zulieferer oder ein Dienstleister ohne vertragliche Sicherheitspflichten wird schnell zum Einfallstor für Angreifer oder zum Grund für einen Datenabfluss. Ohne Auditrechte kann die Organisation zudem gar nicht überprüfen, ob die Partner ihre Zusagen tatsächlich einhalten. So entstehen Abhängigkeiten und Sicherheitslücken, für die am Ende die Organisation selbst haftet, obwohl sie den Fehler nicht verursacht hat.' WHERE risk_id='DR-SOC2-CC9_2';
UPDATE public.risks SET text_de='Wenn betroffene Personen nicht klar und verständlich über die Datenschutzpraktiken informiert werden, bleibt für sie im Dunkeln, wozu ihre Daten erhoben, genutzt und wie lange sie gespeichert werden. Sie können ihre Rechte gar nicht wahrnehmen, weil sie schlicht nicht wissen, was mit ihren Daten geschieht. Das untergräbt das Vertrauen und verstößt gegen die Transparenzpflichten der DSGVO. In der Folge drohen Beschwerden bei der Aufsichtsbehörde, Bußgelder und ein erheblicher Ansehensverlust.' WHERE risk_id='DR-SOC2-P1_1';
UPDATE public.risks SET text_de='Werden Wahlmöglichkeiten und Einwilligungen nicht sauber eingeholt und dokumentiert, verarbeitet die Organisation personenbezogene Daten ohne belastbare Rechtsgrundlage. Kommt es später zum Streit, kann niemand nachweisen, wer wann und wozu eingewilligt hat, und die gesamte Verarbeitung steht auf wackligen Beinen. Betroffene fühlen sich übergangen, weil sie nie eine echte Wahl hatten. Das führt zu Beschwerden, aufsichtsbehördlichen Prüfungen und im Ernstfall zu empfindlichen Bußgeldern.' WHERE risk_id='DR-SOC2-P2_1';
UPDATE public.risks SET text_de='Wenn personenbezogene Daten nicht auf festgelegte, legitime Zwecke und das notwendige Minimum beschränkt erhoben werden, sammelt die Organisation mehr an, als sie überhaupt braucht. Jeder überflüssige Datensatz vergrößert die Angriffsfläche und den Schaden, falls es zu einem Leck kommt. Zugleich wird gegen die Grundsätze der Zweckbindung und Datenminimierung verstoßen. So entstehen unnötige Haftungsrisiken, und im Prüfungsfall drohen Beanstandungen und Sanktionen der Aufsichtsbehörde.' WHERE risk_id='DR-SOC2-P3_1';
UPDATE public.risks SET text_de='Wird bei einwilligungspflichtigen, sensiblen Daten die ausdrückliche Einwilligung nicht vor der Erhebung eingeholt, verarbeitet die Organisation besonders schützenswerte Informationen wie Gesundheits- oder Religionsdaten schlicht unrechtmäßig. Betroffene verlieren die Kontrolle über hochsensible Angaben, die im Missbrauchsfall besonders großen Schaden anrichten. Ein solcher Verstoß wiegt schwer, weil das Gesetz gerade hier ein hohes Schutzniveau verlangt. Die Folge sind erhebliche Bußgelder, Schadenersatzforderungen und ein schwerer Vertrauensbruch.' WHERE risk_id='DR-SOC2-P3_2';
UPDATE public.risks SET text_de='Ist die Nutzung personenbezogener Daten nicht auf die ursprünglich festgelegten Zwecke begrenzt, werden einmal erhobene Daten nach und nach für ganz andere Dinge weiterverwendet. Betroffene haben in diese schleichende Zweckentfremdung nie eingewilligt und verlieren die Kontrolle über ihre Informationen. Damit wird der Grundsatz der Zweckbindung ausgehebelt, der im Zentrum des Datenschutzes steht. Das zieht Beschwerden, aufsichtsbehördliche Maßnahmen und Bußgelder nach sich.' WHERE risk_id='DR-SOC2-P4_1';
UPDATE public.risks SET text_de='Sind keine Aufbewahrungs- und Löschfristen definiert oder werden sie nicht eingehalten, sammeln sich personenbezogene Daten zeitlich unbegrenzt an, obwohl der ursprüngliche Zweck längst entfallen ist. Diese Datenberge sind ein attraktives Ziel für Angreifer und vergrößern den Schaden bei jedem Vorfall. Zugleich verstößt das dauerhafte Speichern gegen die gesetzliche Pflicht zur Speicherbegrenzung. Im Prüfungsfall drohen Beanstandungen, Bußgelder und aufwendige Nachbesserungen.' WHERE risk_id='DR-SOC2-P4_2';
UPDATE public.risks SET text_de='Werden personenbezogene Daten nach Fristablauf oder Wegfall des Zwecks nicht sicher und unwiederherstellbar gelöscht, bleiben sie auf Datenträgern, in Backups und Altsystemen erhalten und können jederzeit wieder auftauchen. Angreifer oder Unbefugte können auf diese vermeintlich entsorgten Daten zugreifen und sie missbrauchen. Damit wird das Recht der Betroffenen auf Löschung verletzt. Die Folge sind Datenschutzverstöße, Bußgelder und ein konkretes Risiko für die betroffenen Personen.' WHERE risk_id='DR-SOC2-P4_3';
UPDATE public.risks SET text_de='Gibt es keinen funktionierenden Prozess für Auskunftsersuchen, können Betroffene nicht erfahren, welche Daten die Organisation über sie gespeichert hat. Anfragen bleiben liegen, werden verspätet oder gar nicht beantwortet, und die Betroffenen können ihre Rechte nicht ausüben. Das verstößt gegen das Auskunftsrecht der DSGVO, das innerhalb enger Fristen zu erfüllen ist. In der Folge drohen Beschwerden bei der Aufsichtsbehörde und Bußgelder wegen verweigerter Auskunft.' WHERE risk_id='DR-SOC2-P5_1';
UPDATE public.risks SET text_de='Ist kein Verfahren zur Berichtigung und Ergänzung von Daten vorhanden, bleiben falsche oder veraltete Angaben über Betroffene dauerhaft im System stehen. Auf Basis dieser fehlerhaften Daten werden dann Entscheidungen getroffen, die den Betroffenen schaden können. Die Personen können ihr Recht auf Berichtigung nicht durchsetzen, weil es keinen geregelten Weg dafür gibt. Das führt zu Beschwerden, falschen Sachbearbeitungen und Datenschutzverstößen.' WHERE risk_id='DR-SOC2-P5_2';
UPDATE public.risks SET text_de='Werden personenbezogene Daten ohne Rechtsgrundlage oder Einwilligung und ohne Zweckbindung an Dritte weitergegeben, verlieren die Betroffenen jede Kontrolle darüber, wer ihre Informationen erhält. Daten gelangen an Empfänger, die sie nie hätten bekommen dürfen, und werden dort womöglich für ganz andere Zwecke verwendet. Ein solcher unrechtmäßiger Datenfluss lässt sich im Nachhinein kaum noch rückgängig machen. Die Folge sind schwerwiegende Datenschutzverstöße, Bußgelder und Schadenersatzforderungen.' WHERE risk_id='DR-SOC2-P6_1';
UPDATE public.risks SET text_de='Führt die Organisation kein aktuelles Verzeichnis über autorisierte Datenweitergaben, kann sie nicht mehr nachvollziehen, welche Daten wann an wen weitergegeben wurden. Kommt es zu einer Beschwerde oder einem Vorfall, fehlt jeder Nachweis, dass die Offenlegung rechtmäßig war. Auch Auskunftsersuchen der Betroffenen lassen sich ohne dieses Verzeichnis nicht korrekt beantworten. Das führt zu Kontrollverlust, Beanstandungen der Aufsichtsbehörde und einer erschwerten Aufklärung im Schadensfall.' WHERE risk_id='DR-SOC2-P6_2';
UPDATE public.risks SET text_de='Werden erkannte oder gemeldete unbefugte Offenlegungen nicht nachvollziehbar erfasst und dokumentiert, bleiben Datenschutzverletzungen im Verborgenen und werden weder aufgearbeitet noch gemeldet. Ohne diese Aufzeichnungen kann die Organisation das Ausmaß eines Vorfalls nicht einschätzen und Betroffene nicht rechtzeitig warnen. Wiederkehrende Schwachstellen werden nicht erkannt und ziehen weitere Vorfälle nach sich. Am Ende drohen verspätete Meldungen, Bußgelder und ein vermeidbar großer Schaden.' WHERE risk_id='DR-SOC2-P6_3';
UPDATE public.risks SET text_de='Sind Dienstleister und Auftragsverarbeiter mit Zugriff auf personenbezogene Daten nicht vertraglich zu Datenschutz und Vertraulichkeit verpflichtet, gibt die Organisation Daten aus der Hand, ohne deren Schutz sicherzustellen. Der Dienstleister kann die Daten dann unkontrolliert weiterverwenden, unzureichend absichern oder sogar weitergeben. Ohne Auftragsverarbeitungsvertrag fehlt jede rechtliche Handhabe, um im Ernstfall Ansprüche durchzusetzen. Die Verantwortung und Haftung bleibt dabei vollständig bei der Organisation.' WHERE risk_id='DR-SOC2-P6_4';
UPDATE public.risks SET text_de='Sind Dienstleister nicht zur Meldung von Datenpannen an die Organisation verpflichtet, erfährt diese von einem Vorfall beim Dienstleister oft gar nicht oder viel zu spät. Dadurch verstreichen die engen gesetzlichen Meldefristen ungenutzt, und Betroffene können nicht rechtzeitig gewarnt werden. Der Schaden weitet sich aus, weil niemand gegensteuert. In der Folge drohen der Organisation Bußgelder wegen verspäteter Meldung, obwohl der Fehler beim Dienstleister lag.' WHERE risk_id='DR-SOC2-P6_5';
UPDATE public.risks SET text_de='Ist kein Prozess zur Meldung von Datenpannen an Betroffene und Behörden etabliert, verstreichen im Ernstfall die knappen gesetzlichen Fristen, weil niemand weiß, wer was bis wann tun muss. Betroffene werden nicht gewarnt und können sich nicht vor Folgeschäden wie Identitätsdiebstahl schützen. Die Aufsichtsbehörde erfährt zu spät oder gar nicht von dem Vorfall. Das führt zu erheblichen Bußgeldern, Haftungsrisiken und einem massiven Vertrauensverlust.' WHERE risk_id='DR-SOC2-P6_6';
UPDATE public.risks SET text_de='Erhalten Betroffene auf Wunsch keine Aufstellung ihrer gespeicherten und offengelegten Daten, können sie nicht überprüfen, was mit ihren Informationen tatsächlich geschieht und an wen sie weitergegeben wurden. Ihnen wird damit die Möglichkeit genommen, unrechtmäßige Verarbeitungen zu erkennen und dagegen vorzugehen. Das verstößt gegen die Auskunfts- und Transparenzpflichten der DSGVO. In der Folge drohen Beschwerden bei der Aufsichtsbehörde und Bußgelder.' WHERE risk_id='DR-SOC2-P6_7';
UPDATE public.risks SET text_de='Werden personenbezogene Daten nicht aktuell, richtig und vollständig gehalten und bei Bedarf berichtigt, arbeitet die Organisation mit fehlerhaften Informationen weiter. Auf dieser Grundlage getroffene Entscheidungen können Betroffene benachteiligen, etwa durch falsche Bescheide oder Zuordnungen. Fehler pflanzen sich fort und lassen sich später nur mühsam korrigieren. Das führt zu Fehlentscheidungen, Beschwerden und Verstößen gegen den Grundsatz der Datenrichtigkeit.' WHERE risk_id='DR-SOC2-P7_1';
UPDATE public.risks SET text_de='Ist kein Prozess für Anfragen, Beschwerden und Streitfälle der Betroffenen etabliert, laufen berechtigte Anliegen ins Leere und bleiben unbeantwortet. Die Betroffenen fühlen sich nicht ernst genommen und wenden sich frustriert direkt an die Aufsichtsbehörde. Konflikte, die man intern hätte klären können, eskalieren so unnötig. Das führt zu behördlichen Prüfungen, einem Ansehensverlust und im Ernstfall zu Sanktionen.' WHERE risk_id='DR-SOC2-P8_1';
UPDATE public.risks SET text_de='Sind die Definitionen der verarbeiteten Daten und die Service-Spezifikationen nicht dokumentiert, arbeiten die Beteiligten mit unterschiedlichen Vorstellungen davon, was das System eigentlich leisten und verarbeiten soll. Fehler und Missverständnisse schleichen sich ein, weil eine verbindliche Grundlage fehlt. Ob die Verarbeitung tatsächlich vollständig und korrekt abläuft, lässt sich ohne diese Vorgaben gar nicht beurteilen. Das führt zu fehlerhaften Ergebnissen, Nacharbeit und unzuverlässigen Diensten.' WHERE risk_id='DR-SOC2-PI1_1';
UPDATE public.risks SET text_de='Werden Eingaben nicht auf Vollständigkeit und Richtigkeit validiert, gelangen fehlerhafte, unvollständige oder manipulierte Daten ungeprüft ins System. Diese Fehler pflanzen sich durch die gesamte Verarbeitung fort und führen zu falschen Ergebnissen, die niemand mehr auf ihre Ursache zurückführen kann. Angreifer können zudem gezielt schädliche Eingaben einschleusen. So entstehen Datenqualitätsprobleme, Fehlentscheidungen und ein hoher Korrekturaufwand.' WHERE risk_id='DR-SOC2-PI1_2';
UPDATE public.risks SET text_de='Werden die einzelnen Verarbeitungsschritte nicht kontrolliert und aufeinander abgestimmt, können Daten unterwegs verloren gehen, doppelt oder unvollständig verarbeitet werden, ohne dass es jemand bemerkt. Die Ergebnisse sind dann unzuverlässig, obwohl die Eingaben korrekt waren. Fehler in der Kette bleiben unentdeckt und summieren sich. Das führt zu falschen Auswertungen, fehlerhaften Vorgängen und einem Vertrauensverlust in die Systeme.' WHERE risk_id='DR-SOC2-PI1_3';
UPDATE public.risks SET text_de='Werden Ausgaben nicht auf Vollständigkeit, Richtigkeit und Zeitgerechtigkeit kontrolliert, verlassen fehlerhafte oder verspätete Ergebnisse das System und werden für Entscheidungen oder Bescheide genutzt. Empfänger verlassen sich auf Daten, die unvollständig oder schlicht falsch sein können. Fehler fallen erst auf, wenn bereits Schaden entstanden ist. Das führt zu Fehlentscheidungen, Reklamationen und einem Verlust an Verlässlichkeit.' WHERE risk_id='DR-SOC2-PI1_4';
UPDATE public.risks SET text_de='Werden Eingaben, Zwischenstände und Ausgaben nicht so gespeichert und archiviert, dass ihre Integrität dauerhaft gewahrt bleibt, können Daten unbemerkt verändert, beschädigt oder verloren gehen. Später lässt sich nicht mehr feststellen, ob die gespeicherten Werte noch dem Original entsprechen. Manipulationen bleiben unentdeckt und untergraben die Verlässlichkeit der gesamten Verarbeitung. Das führt zu fehlerhaften Nachweisen, Beweisproblemen und einem Verlust der Datenintegrität.' WHERE risk_id='DR-SOC2-PI1_5';
UPDATE public.risks SET text_de='Werden Sicherheitsbereiche nicht regelmäßig inspiziert und der Einsatz von Aufnahmegeräten nicht kontrolliert, können Unbefugte Serverräume und kritische Infrastruktur ungehindert betreten oder heimlich Fotos und Aufnahmen anfertigen. Ohne dokumentierte Besucherkontrolle lässt sich später nicht mehr nachvollziehen, wer sich wann in sensiblen Bereichen aufgehalten hat. So können Geräte manipuliert, Daten abgegriffen oder Sicherheitsvorkehrungen ausgespäht werden. Die Folge sind physische Angriffe, Datenabfluss und der Ausfall kritischer Systeme.' WHERE risk_id='R-0153';
UPDATE public.risks SET text_de='Sind keine Behebungsfristen je nach Schwere der Schwachstelle definiert und fehlt ein geordneter Patch-Prozess mit vorheriger Prüfung, bleiben bekannte Sicherheitslücken lange offen oder Patches werden ungetestet eingespielt. Angreifer nutzen ungepatchte Schwachstellen gezielt aus, um in Systeme einzudringen. Ohne Integritätssicherung während der Auslieferung können Komponenten zudem unterwegs manipuliert werden. Das führt zu erfolgreichen Angriffen, kompromittierten Systemen und Betriebsstörungen.' WHERE risk_id='R-0161';
UPDATE public.risks SET text_de='Gibt es keinen Prozess, um Sicherheitsereignisse nach ihrer Auswirkung zu bewerten, zu klassifizieren und zu priorisieren, gehen kritische Vorfälle in der Masse der Meldungen unter oder werden zu spät bearbeitet. Ohne klare Kriterien, wann eine Störung erheblich ist, und ohne abgestimmte Kommunikationspläne herrscht im Ernstfall Chaos, und wichtige Stellen werden nicht rechtzeitig informiert. Angreifer gewinnen wertvolle Zeit, weil niemand koordiniert reagiert. Das führt zu ausufernden Schäden, Meldeverstößen und regulatorischen Konsequenzen.' WHERE risk_id='R-0171';
UPDATE public.risks SET text_de='Fehlt eine Richtlinie für das Netzwerk-Sicherheitsmanagement mit geregelter Aktualisierung von Betriebssystem- und Netzwerk-Patches, bleiben Systeme verwundbar und werden zum leichten Ziel für Angreifer. Bietet man Kunden zudem keine starke Authentifizierung über Benutzername und Passwort hinaus an, lassen sich Zugänge leicht übernehmen. Werden Kunden nicht über Internet-Risiken und Schadsoftware aufgeklärt, fallen sie häufiger auf Angriffe herein. Das führt zu kompromittierten Konten, Schadsoftware-Ausbreitung und finanziellen Schäden.' WHERE risk_id='R-0358';
UPDATE public.risks SET text_de='Sind Informationssicherheitsrollen und -verantwortlichkeiten nicht klar definiert und den Mitarbeitern erläutert, weiß im Ernstfall niemand, wer zuständig ist und handeln muss. Besonders außerhalb der regulären Geschäftszeiten bleiben Alarme und Vorfälle dann liegen, weil keine verbindliche Zuständigkeit geregelt ist. Sicherheitsaufgaben fallen zwischen die Stühle, und Schwachstellen bleiben unbearbeitet. Das führt zu verzögerter Reaktion, unbemerkten Vorfällen und vermeidbar großen Schäden.' WHERE risk_id='R-0359';
UPDATE public.risks SET text_de='Wird die zu diesem MaRisk-Prüfpunkt gehörende Anforderung nicht nachweislich erfüllt und angemessen dokumentiert, fehlt im Prüfungsfall der Beleg, dass die Organisation die aufsichtsrechtlichen Vorgaben tatsächlich einhält. Was nicht dokumentiert ist, gilt gegenüber der Aufsicht als nicht umgesetzt, selbst wenn die Maßnahme in der Praxis existiert. Prüfer beanstanden solche Lücken regelmäßig und verlangen aufwendige Nachweise. Das führt zu Prüfungsfeststellungen, aufsichtsrechtlichen Auflagen und einem erhöhten Haftungsrisiko.' WHERE risk_id='R-N-0081';
UPDATE public.risks SET text_de='Wird die zu diesem MaRisk-Prüfpunkt gehörende Anforderung nicht nachweislich erfüllt und angemessen dokumentiert, kann die Organisation gegenüber der Aufsicht nicht belegen, dass die geforderten Vorkehrungen greifen. Fehlende Nachweise werden in der Prüfung wie fehlende Maßnahmen gewertet und ziehen Beanstandungen nach sich. Ohne saubere Dokumentation lassen sich Verantwortlichkeiten und Abläufe im Ernstfall zudem nicht nachvollziehen. Das führt zu Prüfungsfeststellungen, Auflagen und einem geschwächten Kontrollsystem.' WHERE risk_id='R-N-0082';
UPDATE public.risks SET text_de='Wird die zu diesem MaRisk-Prüfpunkt gehörende Anforderung nicht nachweislich erfüllt und angemessen dokumentiert, entsteht eine Lücke im aufsichtsrechtlichen Nachweis, die bei der nächsten Prüfung sofort auffällt. Die Aufsicht geht bei fehlender Dokumentation davon aus, dass die Anforderung nicht umgesetzt ist. Das schwächt das interne Kontrollsystem und erschwert die Aufarbeitung im Schadensfall. Die Folge sind Prüfungsfeststellungen, aufsichtsrechtliche Auflagen und ein erhöhtes Risiko für die Organisation.' WHERE risk_id='R-N-0083';
UPDATE public.risks SET text_de='Sind für die stabsleitende Person keine mehreren Stellvertretenden benannt, steht und fällt die Krisenbewältigung mit der Verfügbarkeit einer einzigen Person. Fällt diese im Notfall aus, weil sie krank, im Urlaub oder selbst betroffen ist, bleibt der Krisenstab führungslos. Entscheidungen werden dann nicht getroffen oder verzögern sich, während die Lage eskaliert. Das führt zu Handlungsunfähigkeit im entscheidenden Moment und einem deutlich größeren Schaden.' WHERE risk_id='R-R3-0321';
UPDATE public.risks SET text_de='Sind die relevanten Meldequellen und die zuständigen Meldestellen nicht im Notfallhandbuch dokumentiert, weiß im Ernstfall niemand, wer welche Stelle wann informieren muss. Wichtige Meldungen an Behörden, Partner oder interne Stellen unterbleiben oder erfolgen zu spät. Dadurch verstreichen Fristen, und die koordinierte Reaktion auf den Notfall gerät ins Stocken. Das führt zu Meldeverstößen, verzögerter Hilfe und einem vermeidbar größeren Schaden.' WHERE risk_id='R-R3-0339';


