-- ==================================================================
-- BSIG-Neunummerierung (NIS2UmsuCG, BSIG in Kraft seit 06.12.2025) — 19.09.2026
-- Die Texte unten stammen aus dem Grundkatalog (schema.sql) und nannten noch
-- das alte BSIG: § 8a Abs. 1a (SzA) -> § 31 Abs. 2, § 8b (Meldung) -> § 32,
-- § 8b/§ 8c (Kontaktstelle/Registrierung) -> § 33, § 8a Abs. 1 -> §§ 30, 31.
-- Energie: § 11 Abs. 1a-1g EnWG ist entfallen (jetzt §§ 5c-5e EnWG). Meldung an
-- das BSI nach § 5d Abs. 3 EnWG (§ 32 BSIG gilt fuer Energiebetreiber nicht,
-- § 28 Abs. 5 BSIG); Registrierung nach § 33 BSIG bzw. — fuer Netzbetreiber, die
-- keine (besonders) wichtige Einrichtung sind — nach § 5d Abs. 4 EnWG.
-- DORA/MaRisk: § 8a BSIG entfernt — §§ 30, 31 BSIG gelten fuer
-- Finanzunternehmen nach DORA nicht (§ 28 Abs. 6 BSIG).
-- replace() ist idempotent: nach dem ersten Lauf trifft das alte Muster nicht mehr.
-- ==================================================================
UPDATE public.controls SET
  req_de = replace(req_de, '(§8a Abs.1a BSIG)', '(§ 31 Abs. 2 BSIG)'),
  req_en = replace(COALESCE(req_en,''), '(§8a(1a) BSIG)', '(§ 31(2) BSIG)')
 WHERE framework='KRITIS' AND id='FDH-07';
UPDATE public.controls SET
  req_de = replace(req_de, '(Pflicht seit Mai 2023, §8a Abs.1a BSIG)', '(Pflicht seit Mai 2023, heute § 31 Abs. 2 BSIG)'),
  req_en = replace(COALESCE(req_en,''), '(mandatory since May 2023, §8a(1a) BSIG)', '(mandatory since May 2023, now § 31(2) BSIG)')
 WHERE framework='KRITIS' AND id='FDP-02';
UPDATE public.controls SET
  req_de = replace(req_de, 'nach §8a Abs.1 BSIG', 'nach §§ 30, 31 BSIG'),
  req_en = replace(COALESCE(req_en,''), 'per §8a(1) BSIG', 'per §§ 30, 31 BSIG')
 WHERE framework='KRITIS' AND id='TRA-01';
UPDATE public.controls SET
  req_de = replace(req_de, '(Systeme zur Angriffserkennung, §8a Abs.1a BSIG)', '(Systeme zur Angriffserkennung, § 31 Abs. 2 BSIG)'),
  req_en = replace(COALESCE(req_en,''), '(attack detection systems, §8a(1a) BSIG)', '(attack detection systems, § 31(2) BSIG)')
 WHERE framework='KRITIS' AND id='TRA-23';
UPDATE public.controls SET
  req_de = replace(req_de, 'an das BSI (§8b BSIG)', 'an das BSI (§ 32 BSIG)'),
  req_en = replace(COALESCE(req_en,''), 'to the BSI (§8b BSIG)', 'to the BSI (§ 32 BSIG)')
 WHERE framework='KRITIS' AND id='TRA-24';
UPDATE public.controls SET
  req_de = replace(replace(req_de,
             'Ist eine Kontaktstelle gegenüber dem BSI (§8b/§8c BSIG) registriert und werden IT-Störungen (§11 Abs.1c EnWG) gemeldet?',
             'Ist das Unternehmen beim BSI registriert (§ 33 BSIG bzw. § 5d Abs. 4 EnWG) und werden erhebliche Sicherheitsvorfälle an das BSI gemeldet (§ 5d Abs. 3 EnWG)?'),
             'Ist das Unternehmen beim BSI registriert (§ 5d Abs. 4 EnWG, § 33 BSIG) und werden erhebliche Sicherheitsvorfälle gemeldet (§ 5d Abs. 3 EnWG, § 32 BSIG)?',
             'Ist das Unternehmen beim BSI registriert (§ 33 BSIG bzw. § 5d Abs. 4 EnWG) und werden erhebliche Sicherheitsvorfälle an das BSI gemeldet (§ 5d Abs. 3 EnWG)?'),
  req_en = replace(replace(COALESCE(req_en,''),
             'Is a contact point to the BSI (§8b/§8c BSIG) registered and are IT disruptions (§11(1c) EnWG) reported?',
             'Is the company registered with the BSI (§ 33 BSIG or § 5d(4) EnWG) and are significant security incidents reported to the BSI (§ 5d(3) EnWG)?'),
             'Is the company registered with the BSI (§ 5d(4) EnWG, § 33 BSIG) and are significant security incidents reported (§ 5d(3) EnWG, § 32 BSIG)?',
             'Is the company registered with the BSI (§ 33 BSIG or § 5d(4) EnWG) and are significant security incidents reported to the BSI (§ 5d(3) EnWG)?')
 WHERE framework='KRITIS' AND id='ENE-12';
UPDATE public.controls SET
  req_en = replace(COALESCE(req_en,''), '(required per Art. 3c RTS RMF, §8a(1) BSIG)', '(required per Art. 3c RTS RMF)')
 WHERE (framework='DORA' AND id='DORA-006') OR (framework='MaRisk' AND id='MR-013');
